export default [{"id":211,"question":"هل الأذان إعلامٌ وإلزامٌ؟","title":"ما معنى أن الأذان هو إعلان وإلزام؟","answer":"الجواب: نعم، نعم، الأذان إعلامٌ بالوقت، ودعوة إلى الصلاة، ويلزم أن يجاب.\nحي على الصلاة، حي على الفلاح، هذه دعوة، ومعنى \"حيَّ\": أقبلوا إلى الصلاة، أقبلوا إلى الفلاح.\nولهذا لما جاء رجلٌ أعمى إلى النبيِّ الكريم عليه الصلاة والسلام فقال: يا رسول الله، إنه ليس قائدٌ يُلائمني إلى المسجد، فهل لي من رخصةٍ أن أُصلي في بيتي؟ فرخَّص له، ثم قال: هل تسمع النِّداء بالصلاة؟ قال: نعم، قال: فأجب، فالإجابة واجبةٌ على جميع المُكلفين من الرجال، إلا من عذرٍ: كالمريض ونحوه ممن له عذرٌ، كالخائف، والحارس على مالٍ يخشى ضياعه لو أجاب، ونحو ذلك مما بيَّن العلماء في أعذار ترك الجمعة والجماعة.","link":"https://binbaz.org.sa/fatwas/3992/ما-معنى-ان-الاذان-هو-اعلان-والزام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0218.mp3","categories":["الأذان والإقامة"]},{"id":212,"question":"أذان الجمعة الأول انقضت الحكمةُ منه الآن، فهل يُعتبر بدعةً؟","title":"ما حكم الأذان الأول يوم الجمعة؟","answer":"الجواب: ليس ببدعةٍ، ولم تنقضِ الحكمة، ومَن قال هذا فقد غلط، إذا كان الأوَّلون من أصحاب النبيِّ ﷺ قد يُشغلون عن الجمعة، وقد لا ينتبهون لها؛ فكيف بحالنا أيّها الموجودون الآن؟ هل نحن أكثر انتباهًا منهم للعبادة، وأكثر حفظًا منهم للعبادة؟ كلا، هم أحفظ منا، وخيرٌ منا، فإذا فعله عثمانُ الخليفة الراشد للتَّنبيه، فمَن بعد الصحابة أشد حاجةٍ إلى التَّنبيه، وأكثر شغلًا، وأكثر غفلةً، فلم تنقضِ الحاجة، هو تنبيهٌ على أنَّ اليوم يوم جمعة؛ ليستعدَّ المؤمنُ ويُبادر بالتوجه إلى المساجد.\nوقد استمرَّ عليه المسلمون من عهد الخليفة الراشد عثمان إلى يومنا هذا في غالب الأمصار والأعصار، وقلَّ أن يوجد بلدٌ أو دولةٌ تركت ذلك.","link":"https://binbaz.org.sa/fatwas/3993/ما-حكم-الاذان-الاول-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0219.mp3","categories":["الأذان والإقامة","صلاة الجمعة"]},{"id":1383,"question":"إذا خُيِّر أحدهم بين الأذان والإمامة فأيهما خير؟","title":"أيهما أفضل الأذان أم الإمامة؟","answer":"الجواب:\nيختار الذي هو أقوى عليه:  إن كان يقوى على الإمامة فالإمامة أفضل.  وإن كان ما يقوى عليها يختار الأذان.  لأن الناس يختلفون في هذا، إذا كان مؤهلاً للإمامة ومؤهلاً للأذان يختار ما هو الذي يعتقد أو يغلب على ظنه أنه يقوى عليه ويقوم به على الوجه الأكمل.\nس: وعند الأجر: أعظمها أجرًا الأذان أم الإقامة؟\nج: الله أعلم.","link":"https://binbaz.org.sa/fatwas/21476/ايهما-افضل-الاذان-ام-الامامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أيهما خير الأذان أم الإمامة.mp3","categories":["الأذان والإقامة"]},{"id":2082,"question":"بعض المشايخ ينكرون أذان الحرم؛ لأن النبي ﷺ يقول: إذا أذَّنْتَ فترسَّل، وإذا أقمت فاحدر، وبعضهم يجعل الأذان كالإقامة، يعني: ما يترسل فيه؟","title":"هل السُّنة في الأذان التَّرَسُّل أم الحَدْر؟","answer":"الجواب:\nلا، السُّنة التَّرَسُّل في الأذان، والسرعة في الإقامة، هذه السنة، والمؤذنون في الحرم يُطيلون ولا يُخففون، فخطرهم على الطول.","link":"https://binbaz.org.sa/fatwas/22200/هل-السنة-في-الاذان-الترسل-ام-الحدر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا أذَّنْتَ فترسَّل، وإذا أقمت فاحدر.mp3","categories":["الأذان والإقامة"]},{"id":2371,"question":"بالنسبة للأذان حكمه للمنفرد؟","title":"حكم الأذان للمنفرد وحكم التنويع والتمطيط","answer":"الجواب:\nفيه خلاف، بعض أهل العلم يراه واجبًا، وبعضهم يراه سنة، والأقرب أنه سنة مؤكدة، والقول بالوجوب قول قوي؛ لأن قول النبي ﷺ لمالك بن الحويرث: إذا حضرت فأذنا وأقيما وهما شخصان..... الواحد كذلك، ولأنه إظهار لشعائر الصلاة وإظهار للوقت وإعلام به، والقول بالوجوب قول قوي، أما على الجماعة اثنين فأكثر؛ الكفاية.\nس: ولو تركه الجماعة؟\nج: يأثمون، لو تركوه الجماعة يأثمون.\nس: يؤثر على الصلاة؟\nج: لا، الصلاة صحيحة؛ لأنه واجب خارج الصلاة، الأذان والإقامة لو تُركا يأثمون، ولكن الصلاة صحيحة.\nس: أي أفضل المؤذنون أم الأئمة؟\nج: أتقاهم لله، إنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ [الحجرات:13] أتقاهم لله هو أفضلهم.\nس: من ينوّع في الأذان يعني تارة مثل  أذان أبي محذورة وتارة مثل أذان بلال، بالترجيع؟\nج: ما في بأس ما في حرج، لكن أذان بلال أفضل؛ لأنه الذي كان يؤذن بين يدي النبي ﷺ، وإذا أتى بهذا تارة وهذا تارة فالأمر واسع والحمد لله.\nس: حكم التَّغَنِّي بالأذان؟\nج: لا يُطَوِّل يكون وسطًا، التلحين مكروه، أقل أحواله الكراهة، يكون وسطًا لا خفيف ولا تمطيط زائد، يكون بين ذلك حتى يسمع الناس بسهولة، ويؤديه بسهولة؛ فلا يعجل يفوت الناس، ولا يمطط،  ولكن بين ذلك.\nس: فيه يمطط إلى أربع وعشرين حركة؟ ج: لا....\nس: هذا سؤال من أحد الناس، يقول السائل: إنني رجل مؤذن ولي أولاد فأذهب إلى الأذان وبعد الأذان أرجع وأوقظ أولادي من النوم، وسألت إمام المسجد الذي أذن فيه فأجاب: لا يجوز ذلك؟\nج: لا بأس، إذا أذّنت ثم خرجت توقظهم وترجع؛ لا بأس ولا حرج، والإمام غلط، ما في بأس، وإن تيسر يخرجون معك طيب، وإلا أذن وعُدْ توقظهم، والحمد لله بين الأذان والإقامة فرصة.","link":"https://binbaz.org.sa/fatwas/22496/حكم-الاذان-للمنفرد-وحكم-التنويع-والتمطيط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الأذان وفضله وحكمه للمنفرد.mp3","categories":["الأذان والإقامة"]},{"id":2374,"question":"الإقامة مثل الأذان؛ يقول مثل ما يقول المؤذن؟","title":"هل يردّد في الإقامة مثل ما يردّد في الأذان؟","answer":"الجواب:\nالإقامة مثل الأذان، هي الأذان الثاني، لكن يقول عند الإقامة: قد قامت الصلاة، وعند الحيعلة يقول: لا حول ولا قوة إلا بالله، لا يقول مثلما يقول عند الحيعلة، يقول: لا حول ولا قوة إلا بالله، وعند الإقامة يقول: قد قامت الصلاة، جاء في بعض الأحاديث: أقامها وأدامها، وهو ضعيف، والصواب أن يقول: قد قامت الصلاة قد قامت الصلاة، مثل ما يقول المؤذن.","link":"https://binbaz.org.sa/fatwas/22499/هل-يردد-في-الاقامة-مثل-ما-يردد-في-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في إقامة الصلاة.mp3","categories":["الأذان والإقامة"]},{"id":2391,"question":"تمطيط الأذان والتلحين الزائد؟","title":"حكم تمطيط الأذان والتلحين الزائد","answer":"الجواب:\nلا، السنة خلاف ذلك، مكروه، السنة أن يكون الأذان سَمْحًا ليس فيه عجلة، وليس فيه تمطيط، بين ذلك.\nس: يُردّ وراءه؟\nالشيخ: يُرَدّ، يُجاب.\nس: أحيانًا يكون المؤذن يستعجل بالأذان ما يكفي الواحد يَرُدّ وراءه؟\nالشيخ: يتابعه والحمد لله، مُيَسّر، ولو استعجل، المتابعة متيسرة، لكن العَجِل يُعِلّم؛ يَتَرَسَّل، لا يكون مُلَحِّنًا ولا يكون مُعَجِّلًا، ولكن يكون بين ذلك.\nس: ولو ما استجاب المؤذن؟\nالشيخ: ولو يجاب، يجاب المؤذن مطلقًا، وإذا كان فيه خلل يرفع أمره إلى الجهة المسؤولة إذا ما استجاب، الإمام يرفع أمره إلى الجهة المسؤولة حتى يُبَدّل أو يستجيب.","link":"https://binbaz.org.sa/fatwas/22516/حكم-تمطيط-الاذان-والتلحين-الزاىد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تمطيط الأذان والتلحين الزائد.mp3","categories":["الأذان والإقامة"]},{"id":2419,"question":"هل الأذان فرض كفاية على الجماعات أو على أهل البلد عمومًا؟","title":"هل الأذان فرض على كل بلد أم كل مسجد؟","answer":"الجواب:\nفرض كفاية، على كل ناحية ما تسمع الأذان الآخر، كل ناحية لها مسجد فرض كفاية عليها، لكن إذا كان المؤذن يُسْمِع الجميع كفى، صار في حق الباقين سُنَّة، إذا كان المؤذن صيتًا يُسْمِع الجميع صار في حق الباقين سُنَّة.","link":"https://binbaz.org.sa/fatwas/22547/هل-الاذان-فرض-على-كل-بلد-ام-كل-مسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الأذان على أهل البلد أو على الجماعات.mp3","categories":["الأذان والإقامة"]},{"id":3400,"question":"من نام عن الصلاة وهو داخل المدينة: يؤذن ويقيم؟","title":"هل يؤذن ويقيم مَنْ نام وفاتته الصلاة؟","answer":"الجواب: كذلك يصليها كما كان يصليها، لكن يقيم، الأذان خلاص، وإن أذن فلا بأس، لكن يؤذن أذانًا لا يشوش على الناس، إذا أذّن فأفضل.\nس: لكن لو اكتفى بالإقامة؛ لأن المساجد داخل المدينة تؤذن يا شيخ فيُكتفى بالإقامة فقط؟\nالشيخ: إذا كان في الوقت كفى، أما إذا كان ما استيقظ إلا بعد الشمس: إذا أذن أذانًا لا يسمعه الناس أذانًا خفيفًا تأسيًا بالنبي ﷺ؛ لا بأس طيب، ويقيم أيضًا، أما إذا كان استيقظ في وقت وقد صلى الناس يكفيه الإقامة؛ لأنه قد حصل الأذان، والحمد لله.","link":"https://binbaz.org.sa/fatwas/23571/هل-يوذن-ويقيم-من-نام-وفاتته-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/نام عن الصلاة فهل يؤذن، ويقيم إذا أراد الصلاة.mp3","categories":["الأذان والإقامة"]},{"id":3495,"question":"قول \"صدق وبررت\" عند قول المؤذن \"الصلاة خير من النوم\"؟","title":"حكم قول \"صدقت وبررت\" في إجابة المؤذن","answer":"الجواب: لا، الصواب أن يقول مثل قوله: الصلاة خير من النوم.  صدقت وبررت، هذه ما لها أصل، ما هو صحيح. يقول مثل ما يقول المؤذن: الصلاة خير من النوم.  وعند الإقامة يقول: قد قامت الصلاة، مثل المؤذن، هذا هو الصواب.","link":"https://binbaz.org.sa/fatwas/23673/حكم-قول-صدقت-وبررت-في-اجابة-الموذن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قول صدق وبررت عند قول المؤذن الصلاة خير من النوم.mp3","categories":["الأذان والإقامة"]},{"id":3496,"question":"يُؤخّر الأذان (في حال الإبراد بالظهر)؟","title":"هل يُؤخّر الأذان في حال الإبراد بالظهر؟","answer":"الجواب: لا مانع حتى لو قدّمه لا يعجّل بالإقامة، لكن تأخير الأذان أوْلى مثل ما أمر النبي ﷺ المؤذن في حديث أبي ذر قال: أبرد أبرد؛ لأن الناس إذا سمعوا الأذان جاءوا، ما كلٌّ يعلم أنه سيُبْرِد الإمام، فإذا أبرد بالأذان أرفق في الناس.","link":"https://binbaz.org.sa/fatwas/23674/هل-يوخر-الاذان-في-حال-الابراد-بالظهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث فأبردوا عن الصّلاة...، هل يؤخر الأذان.mp3","categories":["شروح الحديث","الأذان والإقامة"]},{"id":3512,"question":"هل يُؤذّن القارئ على الممسوس عند القراءة؟","title":"حكم الأذان عند القراءة على الممسوس","answer":"الجواب: ما أعلم فيه بأسًا، يرجو أنه يذهب... لكن المهم توعيده وتحذيره، وبيان تحريم الظلم عليه، وأنه إن كان مسلمًا يخاف الله، وإن كان ما هو مسلم يجب عليه التوبة إلى الله... بالمواعظ بالتذكير والتخويف.","link":"https://binbaz.org.sa/fatwas/23692/حكم-الاذان-عند-القراءة-على-الممسوس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الأذان عند القراءة على الممسوس.mp3","categories":["الأذان والإقامة"]},{"id":3513,"question":"لماذا يفر الشيطان من الأذان ولا يفر من قراءة القرآن؟","title":"هل يَفِرُّ الشيطان مِن القرآن مثل الأذان؟","answer":"الجواب: جاء في الحديث أنه يفر من قراءة القرآن أيضًا: إن الشيطان يفر من البيت الذي تُقرأ فيه سورة البقرة.\nس: يعود بعد الأذان ليسمع الصلاة مع المصلين..؟\nالشيخ: للتشويش عليهم قاتله الله.","link":"https://binbaz.org.sa/fatwas/23693/هل-يفر-الشيطان-من-القران-مثل-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/لماذا يفر الشيطان من الأذان ولا يفر من قراءة القرآن.mp3","categories":["الأذان والإقامة","القرآن وعلومه"]},{"id":3514,"question":"الذي يسمع الأذان وفاته كثير من ألفاظ الأذان فهل له أن يأتي بها جُملةً ويُكمل مع المؤذن؟","title":"هل يُقْضَى ما يفوت مِنْ ألفاظ الأذان؟","answer":"الجواب: يأتي بما فاته، ويُكمل.","link":"https://binbaz.org.sa/fatwas/23694/هل-يقضى-ما-يفوت-من-الفاظ-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسائل في ترديد الأذان بعد المؤذن.mp3","categories":["الأذان والإقامة"]},{"id":3515,"question":"عند الدعاء اللهم رب هذه الدعوة التامة.. هل يرفع يديه؟","title":"حكم رفع اليدين في \"اللهم رب هذه الدعوة..\"","answer":"الجواب: ما ورد، ما نعرف أنه ورد في هذا شيء.\nس: هل يقال إن الأوْلى تَرْكُه؟\nالشيخ: هو الظاهر، لم يرد في هذا الدعاء رفع.","link":"https://binbaz.org.sa/fatwas/23695/حكم-رفع-اليدين-في-اللهم-رب-هذه-الدعوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/رفع اليدين عند الدعاء باللهم رب هذه الدعوة التامّة..mp3","categories":["الأذان والإقامة","الأدعية والأذكار"]},{"id":3518,"question":"النداء الأول (للفجر) هل يُخَصّ في رمضان دون غيره؟","title":"هل أذان الفجر الأول عام لرمضان وغيره؟","answer":"الجواب: لا، عام؛ لأنه مثل ما قال ﷺ: ليرجع قائمكم ويوقظ نائمكم.","link":"https://binbaz.org.sa/fatwas/23699/هل-اذان-الفجر-الاول-عام-لرمضان-وغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/النداء الأول عام في رمضان وغيره.mp3","categories":["الأذان والإقامة"]},{"id":3519,"question":"هل ثبت \"الصلاة خير من النوم\" في الأذان الثاني؟","title":"هل \"الصلاة خير من النوم\" في الأذان الثاني؟","answer":"الجواب: الصلاة خير من النوم في الأذان الثاني؛ لأنه هو الذي ينادي بالصبح.","link":"https://binbaz.org.sa/fatwas/23700/هل-الصلاة-خير-من-النوم-في-الاذان-الثاني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الصلاة خير من النوم في الأذان الثاني.mp3","categories":["الأذان والإقامة"]},{"id":3520,"question":"أذّن المؤذن لصلاة الفجر ثم نُبّه أنه باق على الفجر نصف ساعة: هل يقطع الأذان ويسكت أم يكمل الأذان؟","title":"حكم مَنْ تنبّه وهو يؤذّن للفجر أنه قبل الوقت","answer":"الجواب: يقطعه، يقطع الأذان، إذا كان ما له عادة الأذان الأول؛ لئلا يُوهِم الناس.","link":"https://binbaz.org.sa/fatwas/23701/حكم-من-تنبه-وهو-يوذن-للفجر-انه-قبل-الوقت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أذن لصلاة الفجر قبل الوقت، فهل يقطعه.mp3","categories":["الأذان والإقامة"]},{"id":3522,"question":"بين كل أذانين: العصر والمغرب ما هو بوقت نهي؟","title":"ما معنى حديث \"بين كل أذانين صلاة\"؟","answer":"الجواب: بين كل أذانين يعني الإقامة، هذا هو المقصود: الأذان والإقامة. العصر ما هو بداخل.","link":"https://binbaz.org.sa/fatwas/23703/ما-معنى-حديث-بين-كل-اذانين-صلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بحديث بين كل أذانين صلاة.mp3","categories":["الأذان والإقامة","شروح الحديث"]},{"id":3525,"question":"إمام يقول \"أرحنا بها\" بدل \"أقم الصلاة\"؟","title":"حكم قول \"أرحنا بها\" بدل \"أقم الصلاة\"","answer":"الجواب: قالها النبي ﷺ في بعض الأحيان: أرحنا بالصلاة يعني: إذا دخلنا بها استرحنا، ما هو أرحنا منها، أرحنا بها، فالصلاة مريحة.\nس: يستريح فيها ؟\nالشيخ: يستريح فيها المؤمن.\nس: يقولُها أو يُنكر عليه؟\nالشيخ: ما في بأس، قالها النبي ﷺ في بعض الصلوات، قال: أرحنا بها يا بلال.","link":"https://binbaz.org.sa/fatwas/23706/حكم-قول-ارحنا-بها-بدل-اقم-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم قول أرحنا بها بدل أقم الصلاة.mp3","categories":["الأذان والإقامة"]},{"id":3529,"question":"يقوم المأمومون أول ما يرون الإمام داخلًا من باب المسجد؟","title":"حكم قيام المأمومين عند دخول الإمام المسجد","answer":"الجواب: إذا كان عادة الإمام أنه إذا دخل أقيمت الصلاة فلا يقومون حتى تُقام الصلاة ويرونه قد دخل؛ لأن بلالًا كان إذا رآه ﷺ قد دخل أقام الصلاة، وقد يقيم قبل أن يدخل الإمام على الموعد الذي بينه وبين النبي ﷺ. قوله: حتى يرى الإمام قد دخل.","link":"https://binbaz.org.sa/fatwas/23710/حكم-قيام-المامومين-عند-دخول-الامام-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قيام المأموم للصلاة.mp3","categories":["الأذان والإقامة"]},{"id":3531,"question":"الفصل بين الإقامة والصلاة (هل له حَدّ)؟","title":"ما مدة الفَصْل بين الإقامة والصلاة؟","answer":"الجواب: ما في حد محدود، الشيء الذي لا يضر الناس، فلا يعجل حتى يتلاحق الناس، إلا في الظهر في شدة الحر الأفضل التأخير، والعشاء إذا لم يجتمعوا الأفضل التأخير، والبقية يراعي الوقت المناسب ربع ساعة، عشر دقائق، ثلث ساعة؛ حتى يتلاحق الناس، فما في حد محدود، يرفق بهم.","link":"https://binbaz.org.sa/fatwas/23712/ما-مدة-الفصل-بين-الاقامة-والصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الفصل بين الإقامة والصلاة.mp3","categories":["الأذان والإقامة"]},{"id":3535,"question":"مؤذن يقيم الصلاة وهو جالس، وأنكر عليه المصلون؛ فهل معهم دليل؟","title":"حكم إقامة المؤذن الصلاة جالسًا","answer":"الجواب: السنة القيام، كان بلال يقيم وهو واقف.","link":"https://binbaz.org.sa/fatwas/23717/حكم-اقامة-الموذن-الصلاة-جالسا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إقامة الصلاة جالسا.mp3","categories":["الأذان والإقامة"]},{"id":3553,"question":"الصواب في قوله: ألا صلوا في رحالكم، إذا بلغ حي على الصلاة، أو بعد؟","title":"متى تُقال \"صلوا في رحالكم\" في الأذان؟","answer":"الجواب: الظاهر أن فعلها عند \"حي على الصلاة\"، أو بعدها، في الرواية الأخرى أنه أمر بعد الأذان؛ حتى لا يستنكر الناس تغيير الأذان حتى يبقى الأذان على حاله، ثم يقول لهم: صلوا في بيوتكم.","link":"https://binbaz.org.sa/fatwas/23735/متى-تقال-صلوا-في-رحالكم-في-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الصواب في قوله ألا صلوا في رحالكم.mp3","categories":["الأذان والإقامة","شروح الحديث"]},{"id":3618,"question":"إذا دخل وقت الأذان فهل الأفضل له أن ينتظر الأذان ثم يصلي تحية المسجد أم يشرع في تحية المسجد؟","title":"هل تُؤجل تحية المسجد للترديد مع المؤذن؟","answer":"الجواب: الأفضل يجمع بين الأمرين: يجيب المؤذن ثم يصلي.","link":"https://binbaz.org.sa/fatwas/23800/هل-توجل-تحية-المسجد-للترديد-مع-الموذن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يصلي تحية المسجد أو يردد الأذان.mp3","categories":["المساجد ومواضع السجود","الأذان والإقامة"]},{"id":4234,"question":"من شرع في الوضوء وسمع المؤذن هل له أن يتابع المؤذن أو يقطع الوضوء؟","title":"هل يُشرع ترديد الأذان أثناء الوضوء؟","answer":"الجواب: يمكن، يتابع ويتوضأ، الأمر واسع إذا كان خارج الحمام.","link":"https://binbaz.org.sa/fatwas/24501/هل-يشرع-ترديد-الاذان-اثناء-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متابعة المؤذن حال الوضوء.mp3","categories":["الأذان والإقامة"]},{"id":4431,"question":"الأذان ياشيخ، يُردد الأذان إذا كان في الخلاء؟","title":"هل يقضي ترديد الأذان مَنْ سمعه في الخلاء؟","answer":"الجواب: لا يُجيبه، لا.\nس: يجوز التَّرديد بعد الخروج؟\nج: بعض أهل العلم يقول: يقضي، ولكن ما عليه دليلٌ واضح.\nس: لو أجاب الأذانَ بقلبه؟\nج: القلب ما في مانع، القلب في أي مكان، لكن ما يُسمَّى: جوابًا.","link":"https://binbaz.org.sa/fatwas/24709/هل-يقضي-ترديد-الاذان-من-سمعه-في-الخلاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم ترديد الأذان في الخلاء.mp3","categories":["قضاء الحاجة","الأذان والإقامة"]},{"id":4470,"question":"الجنب يُجيب المُؤذن أو يفعل التيمم...؟","title":"هل يُجيب الجُنُب المُؤذن؟","answer":"الجواب: مثل بقية الأذكار ... يجيب المؤذن؛ لأنه من ذكر الله ، وليس من قراءة القرآن.","link":"https://binbaz.org.sa/fatwas/24748/هل-يجيب-الجنب-الموذن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يُجيب الجنب المُؤذن.mp3","categories":["الأذان والإقامة"]},{"id":4498,"question":"الأذان الأول في الفجر: بعضهم قبل ساعة، وبعضهم ساعتين، وبعضهم نصف ساعة، هل له وقت؟","title":"متى وقت الأذان الأول لصلاة الفجر؟","answer":"الجواب: السنة أن يكون قبل الفجر بقليلٍ، ما يكون بعيدًا، كما فعل بلال مع ابن أم مكتوم، كان يُؤذن قريبًا، فإذا كان قبل الأذان بنصف ساعة، بثلث ساعة، بربع ساعة، يكون أولى؛ لأنَّ المقصود تنبيه الناس على أن الفجر قد قرب، بعض الناس أجاز أن يكون من نصف الليل، ولكن ليس عليه دليل، فالأولى أن يكون قريبًا من الفجر.","link":"https://binbaz.org.sa/fatwas/24778/متى-وقت-الاذان-الاول-لصلاة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل للأذان الأول في الفجر وقتٌ.mp3","categories":["الأذان والإقامة"]},{"id":4499,"question":"الأذان للصبح قبل دخول الوقت؟","title":"حكم الأذان للصبح قبل دخول الوقت","answer":"الجواب: الصواب أنه لا يجوز، إلا إذا كان هناك مَن يُؤذن على الوقت، مثل: ابن أم مكتوم مع بلال، وإذا كان ما في إلا واحد فالواجب أن لا يُؤذن إلا بعد دخول الوقت.","link":"https://binbaz.org.sa/fatwas/24779/حكم-الاذان-للصبح-قبل-دخول-الوقت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الأذان للصبح قبل دخول الوقت.mp3","categories":["الأذان والإقامة"]},{"id":4500,"question":"الأذان للفائتة؟","title":"ما حكم الأذان للفائتة؟","answer":"الجواب: لهذا الحديث - عن أبي قتادة  في قصة نومهم عن صلاة الفجر قال: \"ثم أذّن بلال بالصلاة، فصلى رسول الله ﷺ ركعتين، ثم صلّى الغداة، فصنع كما كان يصنع كلّ يوم\". رواه أحمد، ومسلم- نعم، تُصلَّى جماعة، ويُؤذّن لها، ويُقام لكل واحدةٍ، لكن أذان لا يُشوش على الناس، إذا كان في الحضر.  وقد يُقال في الحضر: إن الأذان حصل؛ لأنَّ الناس أذَّنوا، فتكفيه الإقامة، بخلاف الصَّحراء فإنه لا أذانَ عندهم، فيُؤذِّنون، ولهذا أمرهم بالأذان عليه الصلاة والسلام، أما الحضر فالأمر فيه أوسع؛ لأنَّ الناس قد أذَّنوا وفرغوا، إنما هو للذي فاتته الصلاةُ فيُقيم.","link":"https://binbaz.org.sa/fatwas/24780/ما-حكم-الاذان-للفاىتة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الأذان للفائتة.mp3","categories":["الأذان والإقامة"]},{"id":4504,"question":"الأذان واجبٌ في السفر؟","title":"حكم الأذان في السفر","answer":"الجواب: نعم، واجب في السفر على الجماعة، خلاف الواحد: هل يجب أم لا؟ يُسنُّ للواحد، واختلفوا هل يجب عليه أم لا؟ ولكن الجماعة يجب، قال: فليُؤذّن لكم هذا أمر، والأمر للوجوب.","link":"https://binbaz.org.sa/fatwas/24784/حكم-الاذان-في-السفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الأذان في السفر.mp3","categories":["الأذان والإقامة"]},{"id":4505,"question":"الالتفات في الحيعلتين: يكون في كلِّ حيعلةٍ التفات أو التفاتان؟","title":"كيف يكون الالتفات في الحيعلتين؟","answer":"الجواب: التفاتان يمين وشمال.\nس: يعني \"حي على الصلاة\" هل يلتفت فيها عن اليمين والشمال أو عن اليمين؟\nج: يعني \"حي على الصلاة\" يمين، و\"حي على الفلاح\" شمال، في الحيعلتين.","link":"https://binbaz.org.sa/fatwas/24785/كيف-يكون-الالتفات-في-الحيعلتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كيفية الالتفات في الحيعلتين.mp3","categories":["الأذان والإقامة"]},{"id":4506,"question":"إذا تنازع قومٌ الأذان يُقدّم الأحسن صوتًا أم .....؟","title":"من يُقدّم للأذان عند التنازع؟","answer":"الجواب: يُقرع بينهم إذا استووا، وإذا ما استووا يُقدّم مَن هو أفضل وأندى صوتًا، وأحسن صوتًا، وأندى صوتًا، وأطيب صوتًا، يُقدّم مَن هو أفضل في رفع الصوت، في حُسن الصوت، ويُطابقه في إقامة الألفاظ، فإن استووا فيُقرع.","link":"https://binbaz.org.sa/fatwas/24786/من-يقدم-للاذان-عند-التنازع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من يُقدّم للأذان.mp3","categories":["الأذان والإقامة"]},{"id":4507,"question":"حكم أذان الفاسق؟","title":"حكم أذان الفاسق","answer":"الجواب: المشهور عند العلماء أنه لا يصح، لا بدّ من العدالة .....؛ لأنه يُخبر عن الوقت، وأخبار الفاسقين لا تُقبل، فلا بد أن يكون عدلًا، لكن إذا كان معه مُؤذنون فالأمر أسهل، لو كان معه مؤذنون في البلد يُسمعون ويُكتفى بهم عنه فالأمر واسع، وجوده كعدمه، لكن لا ينبغي أن يولى في محلٍّ يُعتمد عليه، وبكل حال لا يجوز أن يُولى مَن ظهر فسقه، لا يجوز أن يُولّى.","link":"https://binbaz.org.sa/fatwas/24787/حكم-اذان-الفاسق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم أذان الفاسق.mp3","categories":["الأذان والإقامة"]},{"id":4509,"question":"الفرق بين الأذانين حوالي كم؟ السنة؟","title":"كم الفرق بين الأذان الأول والثاني في الفجر؟","answer":"الجواب: يكون ليس ببعيد، أما قوله: \"يرقى هذا، وينزل هذا\" هذا مبالغة في القرب، وبينهما مسافة تحصل بها الفائدة لردِّ القائم، وإيقاظ النائم، ليست طويلةً، يعني: نصف ساعة أو حولها، أو ساعة، يعني: يحصل به المقصود للمُستيقظ حتى يتوضَّأ ويكمل وتره، يختم صلاته التي صلَّاها من أول الليل، وحتى يتمكَّن أيضًا القائم من إتمام صلاته.","link":"https://binbaz.org.sa/fatwas/24789/كم-الفرق-بين-الاذان-الاول-والثاني-في-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كم يكون الفرق بين الأذان الأول والثاني في الفجر.mp3","categories":["الأذان والإقامة"]},{"id":4511,"question":"في (بعض) البلاد الإسلامية يقرأ المُؤذن آيات من القرآن بدون تلحين؟","title":"حكم قراءة المُؤذن آيات من القرآن قبل الأذان","answer":"الجواب: هذا بدعة، السُّنة ألا يكون قبله شيء ولا بعده شيء، أذان فقط مجرد، لا يسبق بشيءٍ، ولا يلحق به شيء، حتى الصلاة على النبي ﷺ لا يرفع بها الصوت مع الأذان، بل إذا قال: \"لا إله إلا الله\" قفل المكبِّر وانتهى الأذان، ثم يُصلي على النبي ﷺ بينه وبين نفسه، فيُسمعه لمن حوله؛ حتى لا يكون زائدًا في الأذان.","link":"https://binbaz.org.sa/fatwas/24791/حكم-قراءة-الموذن-ايات-من-القران-قبل-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يشرع قراءة المُؤذن آيات من القرآن قبل الأذان.mp3","categories":["الأذان والإقامة","البدع والمحدثات"]},{"id":4512,"question":"بعد الإقامة يدعو؟","title":"هل يُشرع الدعاء بعد إقامة الصلاة؟","answer":"الجواب: ما ورد شيء، مَن دعا فلا بأس، ومَن ترك فلا بأس، ما هو مشروع، لكن مباح، مَن فعله فلا بأس، لم يرد فيه شيء.\nس: حديث سعد في مسلم...؟\nج: يقول: رضيتُ بالله ربًّا، وبالإسلام دينًا، وبمحمدٍ رسولًا. رواه مسلم في \"الصحيح\" عن سعدٍ، قال: إذا قال المؤذن: أشهد أن لا إله إلا الله، وأشهد أن محمدًا رسول الله، مثله، غفر له ذنبه... إذا قال: رضيتُ بالله ربًّا، وبالإسلام دينًا، وبمحمد رسولًا عليه الصلاة والسلام غفر له ذنبه، يقول عند الشَّهادتين: رضيتُ بالله ربًّا، وبالإسلام دينًا، وبمحمدٍ رسولًا عند الشَّهادتين.","link":"https://binbaz.org.sa/fatwas/24792/هل-يشرع-الدعاء-بعد-اقامة-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الدعاء بعد الإقامة.mp3","categories":["الأذان والإقامة","الأدعية والأذكار"]},{"id":4934,"question":"إذا تقدَّم بعضُ المُؤذنين قبل الوقت يُعيد الأذان؟","title":"هل يعيد المؤذن لو ثبت أنه أذن قبل الوقت؟","answer":"الجواب: يُعيد الأذان، إلا إذا كان حوله مُؤذنون... الأمر واسع.","link":"https://binbaz.org.sa/fatwas/27025/هل-يعيد-الموذن-لو-ثبت-انه-اذن-قبل-الوقت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يعيد المؤذن لو ثبت أنه أذن قبل الوقت.mp3","categories":["الأذان والإقامة"]},{"id":4941,"question":"قول الفقهاء أحسن الله إليك: يسن القيام عند \"قد\" من إقامتها؟","title":"متى يقوم المأمومون عند إقامة الصلاة؟","answer":"الجواب: ما أعلم فيه دليلًا، سواء قام في أولها أو في وسطها أو في آخرها.","link":"https://binbaz.org.sa/fatwas/27328/متى-يقوم-المامومون-عند-اقامة-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يقوم المأمومون عند إقامة الصلاة.mp3","categories":["الأذان والإقامة"]},{"id":4942,"question":"بعد الشهادتين ما ورد أنه يقول: \"وأنا أشهد أن لا إله الله، رضيت بالله ربًّا...\"؟","title":"متى يُقال \"وأنا أشهد..\" في ترديد الأذان؟","answer":"الجواب: هذا عند الشهادتين يقول مثله: \"من قال حين يقول المؤذن: أشهد أن لا إله إلا الله..... رضيت بالله ربًا وبالإسلام دينًا وبمحمد رسولاً؛ غفر له ذنبه\" من حديث سعد بن أبي وقاص.\nس: أحسن الله إليك، رواية: وأنا أشهد ألا إله إلا الله؟\nالشيخ: المعنى واحد، سواء قال أنا، أو ما قال أنا، لأن الروايات مختلفة.\nس: من حيث الرواية صحيحة؟\nالشيخ: الذي يظهر أنها صحيحة، إذا قال أشهد ألا إله إلا الله، أو قال وأنا أشهد ألا إله إلا الله، فقد قال مثله.","link":"https://binbaz.org.sa/fatwas/27329/متى-يقال-وانا-اشهد-في-ترديد-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يقال وأنا أشهد.. في ترديد الأذان.mp3","categories":["الأذان والإقامة"]},{"id":4991,"question":"إذا دخل المؤذن المسجد وبقي على الأذان خمس دقائق أو دقيقتين يقف وبعدين يؤذن؟","title":"ما يفعل المؤذن لو دخل قبل وقت الأذان؟","answer":"الجواب: إن صلى فهو أفضل، إن صلى ركعتين فهو أفضل؛ تحية المسجد.","link":"https://binbaz.org.sa/fatwas/28512/ما-يفعل-الموذن-لو-دخل-قبل-وقت-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما يفعل المؤذن لو دخل قبل وقت الأذان؟.mp3","categories":["الأذان والإقامة"]},{"id":5435,"question":"الوسيلة ما هي؟","title":"ما معنى الوسيلة والمقام المحمود؟","answer":"الجواب: منزلة في الجنة. س: هل هي المقام المحمود؟ ج: لا، المقام المحمود: الشفاعة يوم القيامة، شفاعته لأهل الموقف يوم القيامة، هذا المقام المحمود.[1]","link":"https://binbaz.org.sa/fatwas/31228/ما-معنى-الوسيلة-والمقام-المحمود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 051.mp3","categories":["الأذان والإقامة"]},{"id":5436,"question":"بعض المُؤذنين يرفعون في مُكبرات الصوت، يقول: أريد أن يبلغ صوتي أقصى مدى؛ للأجر، فهل يُشرع هذا؟","title":"حكم رفع صوت الأذان في مُكبرات الصوت","answer":"الجواب: الأصل رفع الصوت مثلما قال أبو سعيد: \"إذا كنتَ في غنمك فارفع صوتَك بالنِّداء، فإنه لا يسمع صوتَ المؤذن جنٌّ ولا إنسٌ ولا حجرٌ ولا شجرٌ إلا شهد له يوم القيامة سمعتُه من نبيكم عليه الصلاة والسلام\". س: ما يقال: هذا مخصوص بالصوت المفرد دون المكبرات؛ لأن بالمكبر لا يجتهد المؤذن برفع صوته، بل قد يؤذن بصوتٍ منخفضٍ ويكون الصوت مسموعًا بواسطة المكبر؟ ج: فضل الله واسع.[1]","link":"https://binbaz.org.sa/fatwas/31231/حكم-رفع-صوت-الاذان-في-مكبرات-الصوت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 053.mp3","categories":["الأذان والإقامة"]},{"id":5437,"question":"أيهما أفضل: الأذان أم الإمامة؟","title":"هل الأفضل الأذان أم الإمامة؟","answer":"الجواب: فيه خلاف بين العلماء: فمنهم مَن فضَّل هذا، ومنهم مَن فضَّل هذا، وكلاهما له فضل، لكن ظاهر النصوص أنَّ المؤذن له فضلٌ خاصٌّ؛ لأنه يُنادي الناس، ويدعوهم إلى الله، يدعوهم إلى توحيد الله، وطاعة الله، وإقامة هذه الصلاة، فهذا فضلٌ خاصٌّ لم يجئ مثله فيما نعلم في الإمامة. والإمامة لها فضلٌ خاصٌّ؛ لأنَّ الإمام يُعلِّم الناسَ صلاةَ النبي ﷺ، ويعظهم، ويُذكِّرهم، فالإمام إذا كان عنده علمٌ وعنده بصيرةٌ فله خيرٌ عظيمٌ: إذا ذكَّر الناس، واجتهد في إيصال الحقِّ إليهم.[1]","link":"https://binbaz.org.sa/fatwas/31229/هل-الافضل-الاذان-ام-الامامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 052.mp3","categories":["الأذان والإقامة"]},{"id":5578,"question":"إذا كان المؤذن جنبًا فهل يدخل المسجد ليُؤذن وهو واقف ثم يخرج؟","title":"هل يجوز دخول الجُنُب المسجد للأذان؟","answer":"الجواب: ما ينبغي الوقوف، هذا يُشبه الجلوس، وقوف طويل، فالأحوط ألا يدخل إلا بوضوءٍ، لكن لو فعل صحَّ؛ لأنه ليس بجالسٍ، لا يجلس، قد يُشبه العابر من بعض الوجوه، لكن طول قيامه يُشبه الجلوس، فالأحوط له أن يتأهَّب قبل الأذان، يغتسل، هذا هو الأحوط. س: ليس شرطًا الوضوء في الأذان؟ ج: ليس بشرطٍ، الصحيح ليس بشرطٍ؛ لأنَّ الحديث ضعيف، ليس بشرطٍ.[1]","link":"https://binbaz.org.sa/fatwas/31531/هل-يجوز-دخول-الجنب-المسجد-للاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 019.mp3","categories":["الأذان والإقامة","المساجد ومواضع السجود"]},{"id":5588,"question":"أقام الصلاة بعد الأذان مباشرةً؟","title":"ما حكم عدم الفصل بين الأذان والإقامة؟","answer":"الجواب: السنة أن تكون الإقامةُ بعد الأذان بوقتٍ حتى يتمكن الناسُ من أداء الراتبة في الفجر والظهر، وركعات قبل العصر، وركعتين قبل المغرب، لا يعجل، يكون بينهما فصلٌ حتى يتمكن الحاضرون من الصلاة: سنة الفجر، وسنة الظهر، وركعتين قبل المغرب، وركعتين قبل العشاء، فالسُّنة عدم العجلة. س: تحديد الفصل؟ ج: ما في تحديد، تحديد قليل، القريب يكفي: ربع ساعة، ثلث ساعة، مُقارب.[1]","link":"https://binbaz.org.sa/fatwas/31549/ما-حكم-عدم-الفصل-بين-الاذان-والاقامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 029.mp3","categories":["الأذان والإقامة"]},{"id":5589,"question":"(الأذان) فرض على كل مسجدٍ، أو يكفي البلد إذا أُدِّيَ في البلد؟","title":"هل الأذان فرض على كل مسجد؟","answer":"الجواب: في كل مسجدٍ، نعم.\nس: وإذا تركوه اكتفاءً بالمُؤذنين الآخرين؟\nج: لا، الواجب في كل مسجدٍ؛ لأنَّ كل مسجدٍ له جماعة ينتظرون مُؤذنهم، بينهم تباعد في الغالب، قد لا يسمعون المؤذن الآخر.[1]","link":"https://binbaz.org.sa/fatwas/31547/هل-الاذان-فرض-على-كل-مسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 028.mp3","categories":["الأذان والإقامة"]},{"id":5590,"question":"صلاة الكسوف والخسوف والعيدين هل يُنادى لها بالصلاة جامعة؟","title":"حكم قول \"الصلاة جامعة\" في الكسوف والعيدين؟","answer":"الجواب: الكسوف صلاة جامعة، الكسوف فقط. أما العيدان لا، لا إقامة ولا أذان لها، فقط الكسوف يُنادى لها: الصلاة جامعة، أما العيد ما لها نداء، لا الصلاة جامعة ولا غيره، كان النبي ﷺ يُصلي بلا أذانٍ ولا إقامةٍ، صلاة العيد والاستسقاء معروفة ما تحتاج لأذان.[1]","link":"https://binbaz.org.sa/fatwas/31550/حكم-قول-الصلاة-جامعة-في-الكسوف-والعيدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 030.mp3","categories":["الأذان والإقامة"]},{"id":5592,"question":"إذا كان حليقًا المُؤذن؟","title":"ما حكم أذان حليق اللحية والمدخن والمُسبل؟","answer":"الجواب: هذا ما هو بظاهر، هذا عاصٍ، ظاهر، هذه معصية ظاهرة، نسأل الله العافية. س: ما يُؤذن؟ ج: ما يُعتدّ به، ينبغي أن يولَّى غيره؛ لأن هذا ما هو بمستور، هذا مفضوح. س: إذا سمع الأذان من حليقٍ فلا يُفطر على أذانه؟ ج: لا يُعتمد عليه إلا إذا كان أذان غيره، أو يعرف أنها غابت الشمس، دخل الوقت أو على أذان غيره. س: أقول: في بعض البلدان الذي يتولى الأذان ظاهر الفسق: حالق للحية، ويشرب الدخان، ومُسبل؟ ج: الله يهديهم، تدعو لهم بالهداية وتنصحهم، وتقول للمسؤولين يُبدلونهم. س: ويُجزئ أذانهم؟ ج: فيه نظر، إجزاؤه فيه نظر، إلا إذا عرفت أنه دخل الوقت أو أذَّن غيره، أما عند الضرورة فقد يُقال عند الضَّرورة، بَلْوَى حلق اللحى بعضهم يعتقد أنها جائزة، وأنه لا بأس، قد يقال عند الضَّرورة: إذا كان في نفسه لا بأس به، لا يتّهم بالتساهل بالأذان، قد يقال: يُعتمد عليه عند الضرورة في صلاته وفطره وغيره، لكن مهما أمكن إزالته وتنبيه المسؤولين فيُعين غيره، لا بأس الضَّرورات لها أحكامها: وَقَدْ فَصَّلَ لَكُمْ مَا حَرَّمَ عَلَيْكُمْ إِلَّا مَا اضْطُرِرْتُمْ إِلَيْهِ [الأنعام:119]، قد يقال في هذا من باب الضَّرورة: يُعتمد عليه للضرورة أو الشبهة؛ لأنَّ بعض الناس قد يرى أنها مباحة، وأن حلقها مباح، وأن تقصيرها مباح، يُلبس عليه، فهذا قد يكون عذرًا في اعتماد أذانه؛ لأن كثيرًا من الناس الآن يُجادل في هذا ويُقلد أناسًا فعلوا هذا الشيء، يرى أنهم أهلًا لأن يُقلدوا، يغتر بهم الناس، نسأل الله السلامة.[1]","link":"https://binbaz.org.sa/fatwas/31554/ما-حكم-اذان-حليق-اللحية-والمدخن-والمسبل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 032.mp3","categories":["الأذان والإقامة"]},{"id":5593,"question":"كم يكون بين الأذان الأول والأذان الثاني في الفجر؟","title":"ما مقدار الفصل بين الأذانين في الفجر والجمعة؟","answer":"الجواب: مثلما قال ﷺ: ليرجع قائمكم، ويوقظ نائمكم، لا يكون بالكثير، قبل الفجر بقليل؛ حتى يتنبه الناس: الذي يتوضأ، والذي عليه غسل، لا يُبكر بالكثير بعد نصف الليل، لكن يكون قريبًا من الفجر حتى لا تذهب الفائدة، فإنه إذا بكَّر به ذهبت الفائدة وتركوه ولم يُبالوا به وناموا، لكن إذا كان قريبًا من الفجر أوقظ النائم، ورد القائم عن طول القيام؛ لأنه عرف بذلك أنَّ الفجر قريب، السنة أن يكون الأذان الأول ليس ببعيدٍ عن الأذان الأخير؛ ولهذا في بعض الروايات في حديث بلال: \"ليس بينهما إلا أن يصعد هذا وينزل هذا\" يعني قريب. س: بعض المُؤذنين يجعل بين الأذان الأول والأذان الثاني ساعة؟ ج: هذا من اجتهاده، ما عليه دليل واضح، ساعة أو نصف ساعة كلها مقاربة، يمديه يوتر. س: ورد في بعض الروايات أنها بمقدار خمسين آية؟ ج: لا، هذا بين أذان الفجر وبين الإقامة. س: وأذانا الجمعة؟ ج: فعله الصحابة في عهد عثمان  وما بعده؛ أمر بالأذان الأول تنبيهًا للناس على أنَّ اليوم يوم الجمعة، ووافقه الصحابة ، والرسول عليه الصلاة والسلام قال: عليكم بسنتي وسنة الخلفاء الراشدين.[1]","link":"https://binbaz.org.sa/fatwas/31555/ما-مقدار-الفصل-بين-الاذانين-في-الفجر-والجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 033.mp3","categories":["الأذان والإقامة"]},{"id":5594,"question":"بعضهم يرى أن الصلاة خير من النوم تُقال في الأذان الأول؟","title":"متى ُيقال \"الصلاة خير من النوم\" في الأذان؟","answer":"الجواب: لا، الأفضل في الأذان الثاني، هذا الأفضل؛ لأنه جاء في حديث عائشة ما يدل على ذلك أنه يُقال في الأذان الثاني. س: القول لمَن يرى أن \"الصلاة خير من النوم\" في الأذان الأول؟ ج: المقصود إذا كانت في واحدٍ منهما كفى، لكن كونه في الأذان الثاني أوْلى. س: السؤال لمَن يرى أنها تُقال في الأذان الأول: هل فعلها في هذا الوقت يكون فتنةً؟ ج: لا، فقط لا يختلف أهل القرية، لا يختلفون، إما أن يجعله في الأذان الأول، وإلا في الأذان الثاني، لا يختلفون حتى لا يُشوشوا على الناس، والأفضل أن يكون في الأذان الثاني؛ لأن الصلاة خير من النوم في الأذان الثاني، الفريضة خير من النوم، أما في الأذان الأول فقد يكون النوم أفضل، إذا قام وهو تعبان ما يُحسن الصلاة، نومه أحسن، لكن الصلاة خير من النوم هذا في الفريضة قطعًا، الصلاة خير من النوم كونها في الأذان الثاني كما دلَّ عليه حديث عائشة رضي الله عنها، ودلَّ عليه المعنى أيضًا، يكون في الأذان الثاني أوْلى.[1]","link":"https://binbaz.org.sa/fatwas/31556/متى-يقال-الصلاة-خير-من-النوم-في-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 034.mp3","categories":["الأذان والإقامة"]},{"id":5595,"question":"ما يُقال أنَّ الحاجة انتفت لوجود الأذان الأول يوم الجمعة مع المُكبرات؟","title":"هل تكفي المكبّرات عن الأذان الأول يوم الجمعة؟","answer":"الجواب: لا، يعترض على الصحابة؟! الذي فعله الصحابة فيه خير وبركة ، وهو تنبيه للناس حتى يستعدوا للجمعة؛ لأنهم إذا سمعوا الأذان الأول استعدوا، الذي يبغي أن يغتسل، والذي ينظر في الأمر. س: في بعض البلدان يُؤذن المُؤذن الأول والمُؤذن الآخر بينهم أقل من خمس دقائق في نفس المسجد؟ ج: لا، الأولى أن يكون مبكرًا بشيءٍ قبل الزوال، وما يُفعل في الحرمين وبعض... ليس بجيدٍ، ما يحصل به المقصود، الأفضل أن يتقدم بعض الشيء قبل الزوال.[1]","link":"https://binbaz.org.sa/fatwas/31558/هل-تكفي-المكبرات-عن-الاذان-الاول-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 035.mp3","categories":["الأذان والإقامة"]},{"id":5603,"question":"متى يقول: \"رضيتُ بالله ربًّا\" بعد الشهادتين؟","title":"ما الصيغ الصحيحة لأدعية الأذان والترديد معه؟","answer":"الجواب: عند الشهادتين يقول: \"رضيتُ بالله ربًّا، وبالإسلام دينًا، وبمحمدٍ رسولًا\" عند الشهادتين، في حديث سعد بن أبي وقاص ، عن النبي عليه الصلاة والسلام أنه قال: مَن قال حين يقول المؤذن أشهد أن لا إله إلا الله: رضيتُ بالله ربًّا، وبالإسلام دينًا، وبمحمد رسولًا؛ غُفر له ذنبه، عند الشهادتين في الأذان والإقامة. س: الصلاة على النبي قبل دعاء: \"اللهم ربَّ هذه الدعوة التامة\"؟ ج: هذه السنة؛ يُصلي عليه ثم يدعو. س: لعموم الأدلة أو في دليل خاصّ لهذا؟ ج: للحديث الذي سمعت؛ حديث عبدالله بن عمرو، رواه مسلم في الصحيح، يقول ﷺ: إذا سمعتُم المؤذن فقولوا مثلما يقول، ثم صلوا عليَّ، فإنه مَن صلى عليَّ صلاةً صلَّى الله عليه بها عشرًا، ثم سلوا الله لي الوسيلة، فيُصلي على النبي أولًا ثم يقول: \"اللهم ربَّ هذه الدعوة التامة\". س: هل الأولى أن يُصلي على النبي عليه الصلاة والسلام كما يُصلي عليه في التَّشهد؟ ج: هذا أولى؛ لأن صلّوا عليَّ يعني الصلاة التي أمر بها: \"اللهم صلِّ على محمد وعلى آل محمد كما صليتَ على آل إبراهيم، وبارك على محمدٍ وعلى آل محمد كما باركتَ على آل إبراهيم إنك حميد مجيد\"، وإن اختصر وقال: \"اللهم صلِّ وسلم على رسول الله\" لأسبابٍ نرجو أن يكون لا بأس، لكن كونه يأتي بالصلاة كاملة هذا هو الأفضل. وبعض الناس يزيد \"الدرجة الرفيعة\" وهذا غلط، ما هي في الرواية، هي ليست في الرواية، الدرجة الرفيعة هي الوسيلة، هي نفسها، آته الوسيلة والفضيلة هي المنزلة في الجنة الرفيعة، وليس في الرواية الدرجة الرفيعة، بل هذا من غلط بعض الناس في كتابتها يقول: \"اللهم ربّ هذه الدعوة التامة والصلاة القائمة آتِ محمدًا الوسيلة والفضيلة والدرجة الرفيعة\" لا، الدرجة هي نفسها الوسيلة، فليست في الرواية، ولكن في الرواية: \"اللهم آتِ محمدًا الوسيلة والفضيلة وابعثه المقام المحمود الذي وعدته\". س: في بعض الروايات وردت بارك الله فيك؟ ج: غلط، غلط، غلط من بعض الكتاب والنُّساخ، ما هي في الرواية. س: مَن قال: إن المؤذن إذا قال في أذان الفجر: الصلاة خير من النوم، فإنك تقول: لا حول ولا قوة إلا بالله؟ ج: لا، ما له أصل، تقول: الصلاة خير من النوم، الحوقلة عند قوله: حي على الصلاة، حي على الفلاح، يقول: لا حول ولا قوة إلا بالله، أما عند الصلاة خير من النوم يقول: الصلاة خير من النوم مثله. س: زيادة \"إنك لا تخلف الميعاد\"؟ ج: لا بأس بها.[1]","link":"https://binbaz.org.sa/fatwas/31569/ما-الصيغ-الصحيحة-لادعية-الاذان-والترديد-معه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 042.mp3","categories":["الأذان والإقامة","الأدعية والأذكار"]},{"id":5672,"question":"هل يُردد خلف (المقيم) كالأذان؟","title":"هل يجوز ترديد إقامة الصلاة مثل الأذان؟","answer":"الجواب: نعم، يُستحبّ أن يُجيب المقيم كما أجاب المؤذن.[1]","link":"https://binbaz.org.sa/fatwas/31709/هل-يجوز-ترديد-اقامة-الصلاة-مثل-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aldurus almuhima 018.mp3.mp3","categories":["الأذان والإقامة"]},{"id":5779,"question":"جاء في مجلة التوحيد في أحد أعدادها الصادرة العام الماضي بأن وقت صلاة الفجر لا تحين إلا بعد عشرين دقيقة من الأذان، وعليه لا يجوز صلاة السنة قبل هذا الوقت، كما أباح البعض لنفسه الطعام، والشراب حتى ذلك الوقت؟","title":"ماذا يترتب على الأذان قبل دخول وقته؟","answer":"الجواب: هذا يختلف بحسب البلدان، إذا عرف أن الأذان يبكر في البلد، وأن صاحب الأذان يؤذن قبل الصبح، فهذا غلط، ولا يحرم الطعام على الصائم إذا عرف أن المؤذن بكر، وأنه يؤذن قبل الصبح، فلا يحرم الطعام، ولا تحل الصلاة، ولكن هذا ما هو بخاص بمصر، ولا بغير مصر، هذا في كل بلد. إذا عرف الإنسان في بلده، في قريته، أو في مكانه، أو في قبيلته، أو في الصحراء التي هو فيها، إذا عرف أن هذا المؤذن أذن قبل الصبح فإن الطعام لا يحرم على من أراد الصوم، يأكل ويشرب حتى يطلع الفجر، ولا تحل له الصلاة، لا الفريضة، ولا الراتبة، الراتبة ما تجزئ قبل طلوع الفجر. وأما إذا كان عرف أنه طلع الفجر؛ وجب عليه الإمساك عن الطعام والشراب، وحلت صلاة الفجر، وراتبتها أيضًا، فهذا ليس خاصًا بمصر، ولا بغير مصر، بل جميع البلاد على هذا النمط، على المؤذن أن يتحرى الفجر، ويؤذن على طلوع الفجر، وليس للمسلم أن يأكل بعد طلوع الفجر، ولو ما أذن، ولو ما سمع الأذان، إذا عرف أن الفجر طلع فليس له أن يأكل وهو يريد الصوم، لاسيما صوم الفريضة كرمضان، فليس له أن يأكل بعدما علم طلوع الفجر، ولو ما أذن المؤذن، ولو كان المؤذن نائمًا ما أذن.  العمدة على الصبح فإذا أذن قبل الفجر، وعرف أنه أذن قبل الفجر فإن أذانه لا يحرم الأكل والشرب على الصائم، ولا يحل الصلاة؛ بل أذانه يكون غلط، وفي غير محله، فلا يحرم الطعام على الصائم، ولا يبيح صلاة الفجر، فإن صلاة الفجر بعد طلوع الفجر، وإنما يصام في النهار، لا في الليل، إذا كان أذانه مبكرًا فإن أذانه ليس في محله إلا إذا أراد الأذان الأول؛ فلا بأس، أما أنه يكتفي به لا، لا يكتفي به، بل يؤذن بعد طلوع الفجر.  السؤال: هل يعرف الفجر بقول الله : حَتَّى يَتَبَيَّنَ لَكُمُ الْخَيْطُ الْأَبْيَضُ مِنَ الْخَيْطِ الْأَسْوَدِ مِنَ الْفَجْرِ [البقرة:187] هل يكتفي المسلم بهذا أم يكتفي بأذان المؤذن؟","link":"https://binbaz.org.sa/fatwas/1105/ماذا-يترتب-على-الاذان-قبل-دخول-وقته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_111.mp3","categories":["الحكم على الأحاديث","الأذان والإقامة"]},{"id":5794,"question":"للفجر أذانان، فهل ذلك سنة واجبة، أم مستحبة؟ وهل ذلك في رمضان، أم في جميع شهور العام، وما توقيتهما؟","title":"هل النداء بأذانين في صلاة الفجر مشروع؟","answer":"الجواب:  الواجب الأذان فقط، أذان واحد، أما الأذان الثاني فهو مستحب إذا دعت الحاجة إليه، ولا يحفظ أن النبي فعله إلا في رمضان، كان بلال يؤذن حتى يوقظ النائم، وينبه القائم قبل الفجر بقليل، ولا يحفظ عنه ﷺ في غير رمضان. ولكن بعض أهل العلم استحبه مطلقًا للتنبيه؛ لأنه ينبه طلوع الفجر حتى يستعد الناس للفجر، والذي يصوم يصوم، وإلا فالأمر فيه واسع، الواجب أذان الفجر فقط، أما الأول فليس بواجب؛ بل هو مستحب إذا دعت الحاجة إليه.","link":"https://binbaz.org.sa/fatwas/1108/هل-النداء-باذانين-في-صلاة-الفجر-مشروع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_114.mp3","categories":["الحكم على الأحاديث","الأذان والإقامة"]},{"id":5801,"question":"جاء في كتب السنة: أن مؤذن رسول الله كان يؤذن خارج المسجد على الباب، فهل هذه سنة واجبة، أم مستحبة؟","title":"هل صح أنه كان يُؤذَّن خارج المسجد؟","answer":"الجواب: لا، هذا حديث ضعيف رواه أبو داود بإسناد ضعيف؛ لأنه من طريق ابن إسحاق، وقد عنعن وهو مدلس، فحديثه ضعيف إذا دلس، وليس بثابت. والسنة في الأذان أن يكون على محل مرتفع، كما كان بلال يؤذن على السطح، حتى يكون أندى للصوت، وإذا كانت منارة كما صنع الناس المنارات فهو أندى، والآن جاءت المكبرات هذه؛ فاكتفى بها الناس؛ لأن تكبير الصوت يبلغ البعيد، ولهذا اكتفى بعضهم بها عن المنارة؛ لعدم الحاجة إلى المنارة.","link":"https://binbaz.org.sa/fatwas/1123/هل-صح-انه-كان-يوذن-خارج-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_129.mp3","categories":["الأدعية والأذكار","فضائل الأعمال","الأذان والإقامة"]},{"id":5896,"question":"ورد قول السامع للمؤذن هذا الدعاء: رضيت بالله ربًا، وبمحمد رسولًا، وبالإسلام دينًا، فهل هذا بعد الأذان مباشرة؟","title":"بيان الدعاء الوارد بعد الأذان","answer":"الجواب: ثبت عن رسول الله -عليه الصلاة والسلام- أنه أمر بإجابة المؤذن في الصحيحين عن أبي سعيد عن النبي ﷺ أنه قال: إذا سمعتم المؤذن؛ فقولوا مثل ما يقول.  وفي صحيح مسلم عن عبدالله بن عمرو بن العاص -رضي الله تعالى عنهما- أن النبي -عليه الصلاة والسلام- قال: إذا سمعتم المؤذن؛ فقولوا مثل ما يقول، ثم صلوا عليّ فإنه من صلى علي صلاة واحدة؛ صلى الله عليه بها عشرًا، ثم سلوا الله لي الوسيلة، فإنها منزلة في الجنة لا تنبغي إلا لعبد من عباد الله، وأرجو أن أكون أنا هو، ومن سأل الله لي الوسيلة؛ حلت له الشفاعة.  وفي حديث جابر بن عبدالله عند البخاري -رحمه الله- عن النبي ﷺ أنه قال: من قال حين يسمع النداء: اللهم رب هذه الدعوة التامة، والصلاة القائمة، آت محمدًا الوسيلة، والفضيلة، وابعثه مقامًا محمودًا الذي وعدته إلا حلت له شفاعتي يوم القيامة رواه البخاري في الصحيح. وبعض الناس قد يزيد فيها \"والدرجة الرفيعة\" وهذا لا أصل، له ليست في الرواية، وقد توجد في بعض الكتب \"والدرجة الرفيعة\" وهي لا أصل لها، ليست في الرواية، والدرجة الرفيعة هي الوسيلة، والوسيلة هي الدرجة الرفيعة، وهو تفسير لها، والحديث إنما فيه الوسيلة، والفضيلة، وليس فيها الدرجة الرفيعة كما قد تقع في ألسنة بعض الناس، أو في كتابة بعض الناس.  فالسنة أن يقول هكذا، ويقول عند الشهادتين عندما يقول المؤذن: أشهد أن لا إله إلا الله، أشهد أن محمدًا رسول الله، يقول المجيب مثله: أشهد أن لا إله إلا الله، أشهد أن محمدًا رسول الله، ويقول: أشهد أن لا إله إلا الله وحده لا شريك له وأشهد أن محمدًا عبده ورسوله، ويقول عند هذا: رضيت بالله ربًا، وبالإسلام دينًا، وبمحمد رسولًا. هكذا جاء عنه -عليه الصلاة والسلام- عند الشهادة، رواه مسلم في الصحيح عن سعد بن أبي وقاص -رضي الله تعالى عنه- أن النبي -عليه الصلاة والسلام- قال: من قال حين يقول المؤذن: أشهد أن لا إله إلا الله، أشهد أن محمدًا رسول الله، وأنا أشهد، رضيت بالله ربًا، وبالإسلام دينًا، وبمحمد رسولًا؛ غفر له ذنبه. وفي لفظ قال: عندما يقول الشهادة: أشهد أن لا إله إلا الله وحده لا شريك له، وأشهد أن محمدًا عبده، ورسوله يقول عند ذلك: رضيت بالله ربًا وبالإسلام دينًا وبمحمد رسولًا؛ غفرت له ذنوبه أو قال: غفر له ذنبه. فهذا يدل على أنه يستحب عند الشهادتين أن يقول هذا الكلام، يقول: رضيت بالله ربًا، وبالإسلام دينًا، وبمحمد رسولًا، عند الشهادتين يجيب المؤذن بقوله: أشهد أن لا إله إلا الله، أشهد أن لا إله إلا الله، أشهد أن محمدًا رسول الله، أشهد أن محمدًا رسول الله، أو يقول: وأنا أشهد أن لا إله إلا الله، وأشهد أن محمدًا رسول الله، ثم يقول بعد هذا: رضيت بالله ربًا، وبالإسلام دينًا، وبمحمد رسولًا، عليه الصلاة والسلام.  وعند الحيعلتين يقول: لا حول ولا قوة إلا بالله، لا حول ولا قوة إلا بالله، لا حول ولا قوة إلا بالله، لا حول ولا قوة إلا بالله، لكل واحدة هذا هو المشروع، وفي حديث عمر عند مسلم من قالها من قلبه؛ دخل الجنة من قال هذا الذكر من قلبه؛ دخل الجنة، فهذا فضل عظيم؛ فينبغي العناية بسماع الأذان، بعض الناس لا يبالي  يسمعه، ولا يبالي، فهذا حرمان من هذا الخير.  فإن الأفضل لك إذا سمعته أن تمسك عن الكلام، وعن القراءة، وتجيب هذا المؤذن بأن تقول ما تقول، وتقول عند الشهادتين: رضيت بالله ربًا، مع الشهادتين، تشهد وتقول مع الشهادتين: رضيت بالله ربًا، وبالإسلام دينًا، وبمحمد رسولًا، وتقول عند الحيعلة: لا حول ولا قوة إلا بالله، وإذا كمل تصلي على النبي ﷺ ثم تقول: اللهم رب هذه الدعوة التامة، والصلاة القائمة، آت محمدًا الوسيلة، والفضيلة، وابعثه المقام المحمود الذي وعدته، كما أرشد النبي -عليه الصلاة والسلام- إلى هذا.","link":"https://binbaz.org.sa/fatwas/1257/بيان-الدعاء-الوارد-بعد-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_253.mp3","categories":["الأذان والإقامة","الأدعية والأذكار"]},{"id":5905,"question":"ورد قول السامع للمؤذن هذا الدعاء: رضيت بالله ربًا، وبمحمد رسولًا، وبالإسلام دينًا، فهل هذا بعد الأذان مباشرة؟","title":"بيان الدعاء الوارد بعد الأذان","answer":"الجواب: ثبت عن رسول الله -عليه الصلاة والسلام- أنه أمر بإجابة المؤذن في الصحيحين عن أبي سعيد عن النبي ﷺ أنه قال: إذا سمعتم المؤذن؛ فقولوا مثل ما يقول.  وفي صحيح مسلم عن عبدالله بن عمرو بن العاص -رضي الله تعالى عنهما- أن النبي -عليه الصلاة والسلام- قال: إذا سمعتم المؤذن؛ فقولوا مثل ما يقول، ثم صلوا عليّ فإنه من صلى علي صلاة واحدة؛ صلى الله عليه بها عشرًا، ثم سلوا الله لي الوسيلة، فإنها منزلة في الجنة لا تنبغي إلا لعبد من عباد الله، وأرجو أن أكون أنا هو، ومن سأل الله لي الوسيلة؛ حلت له الشفاعة.  وفي حديث جابر بن عبدالله عند البخاري -رحمه الله- عن النبي ﷺ أنه قال: من قال حين يسمع النداء: اللهم رب هذه الدعوة التامة، والصلاة القائمة، آت محمدًا الوسيلة، والفضيلة، وابعثه مقامًا محمودًا الذي وعدته إلا حلت له شفاعتي يوم القيامة رواه البخاري في الصحيح. وبعض الناس قد يزيد فيها \"والدرجة الرفيعة\" وهذا لا أصل، له ليست في الرواية، وقد توجد في بعض الكتب \"والدرجة الرفيعة\" وهي لا أصل لها، ليست في الرواية، والدرجة الرفيعة هي الوسيلة، والوسيلة هي الدرجة الرفيعة، وهو تفسير لها، والحديث إنما فيه الوسيلة، والفضيلة، وليس فيها الدرجة الرفيعة كما قد تقع في ألسنة بعض الناس، أو في كتابة بعض الناس.  فالسنة أن يقول هكذا، ويقول عند الشهادتين عندما يقول المؤذن: أشهد أن لا إله إلا الله، أشهد أن محمدًا رسول الله، يقول المجيب مثله: أشهد أن لا إله إلا الله، أشهد أن محمدًا رسول الله، ويقول: أشهد أن لا إله إلا الله وحده لا شريك له وأشهد أن محمدًا عبده ورسوله، ويقول عند هذا: رضيت بالله ربًا، وبالإسلام دينًا، وبمحمد رسولًا. هكذا جاء عنه -عليه الصلاة والسلام- عند الشهادة، رواه مسلم في الصحيح عن سعد بن أبي وقاص -رضي الله تعالى عنه- أن النبي -عليه الصلاة والسلام- قال: من قال حين يقول المؤذن: أشهد أن لا إله إلا الله، أشهد أن محمدًا رسول الله، وأنا أشهد، رضيت بالله ربًا، وبالإسلام دينًا، وبمحمد رسولًا؛ غفر له ذنبه. وفي لفظ قال: عندما يقول الشهادة: أشهد أن لا إله إلا الله وحده لا شريك له، وأشهد أن محمدًا عبده، ورسوله يقول عند ذلك: رضيت بالله ربًا وبالإسلام دينًا وبمحمد رسولًا؛ غفرت له ذنوبه أو قال: غفر له ذنبه. فهذا يدل على أنه يستحب عند الشهادتين أن يقول هذا الكلام، يقول: رضيت بالله ربًا، وبالإسلام دينًا، وبمحمد رسولًا، عند الشهادتين يجيب المؤذن بقوله: أشهد أن لا إله إلا الله، أشهد أن لا إله إلا الله، أشهد أن محمدًا رسول الله، أشهد أن محمدًا رسول الله، أو يقول: وأنا أشهد أن لا إله إلا الله، وأشهد أن محمدًا رسول الله، ثم يقول بعد هذا: رضيت بالله ربًا، وبالإسلام دينًا، وبمحمد رسولًا، عليه الصلاة والسلام.  وعند الحيعلتين يقول: لا حول ولا قوة إلا بالله، لا حول ولا قوة إلا بالله، لا حول ولا قوة إلا بالله، لا حول ولا قوة إلا بالله، لكل واحدة هذا هو المشروع، وفي حديث عمر عند مسلم من قالها من قلبه؛ دخل الجنة من قال هذا الذكر من قلبه؛ دخل الجنة، فهذا فضل عظيم؛ فينبغي العناية بسماع الأذان، بعض الناس لا يبالي  يسمعه، ولا يبالي، فهذا حرمان من هذا الخير.  فإن الأفضل لك إذا سمعته أن تمسك عن الكلام، وعن القراءة، وتجيب هذا المؤذن بأن تقول ما تقول، وتقول عند الشهادتين: رضيت بالله ربًا، مع الشهادتين، تشهد وتقول مع الشهادتين: رضيت بالله ربًا، وبالإسلام دينًا، وبمحمد رسولًا، وتقول عند الحيعلة: لا حول ولا قوة إلا بالله، وإذا كمل تصلي على النبي ﷺ ثم تقول: اللهم رب هذه الدعوة التامة، والصلاة القائمة، آت محمدًا الوسيلة، والفضيلة، وابعثه المقام المحمود الذي وعدته، كما أرشد النبي -عليه الصلاة والسلام- إلى هذا.","link":"https://binbaz.org.sa/fatwas/1257/بيان-الدعاء-الوارد-بعد-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_253.mp3","categories":["الأذان والإقامة","الأدعية والأذكار"]},{"id":5916,"question":"ورد قول السامع للمؤذن هذا الدعاء: رضيت بالله ربًا، وبمحمد رسولًا، وبالإسلام دينًا، فهل هذا بعد الأذان مباشرة؟","title":"بيان الدعاء الوارد بعد الأذان","answer":"الجواب: ثبت عن رسول الله -عليه الصلاة والسلام- أنه أمر بإجابة المؤذن في الصحيحين عن أبي سعيد عن النبي ﷺ أنه قال: إذا سمعتم المؤذن؛ فقولوا مثل ما يقول.  وفي صحيح مسلم عن عبدالله بن عمرو بن العاص -رضي الله تعالى عنهما- أن النبي -عليه الصلاة والسلام- قال: إذا سمعتم المؤذن؛ فقولوا مثل ما يقول، ثم صلوا عليّ فإنه من صلى علي صلاة واحدة؛ صلى الله عليه بها عشرًا، ثم سلوا الله لي الوسيلة، فإنها منزلة في الجنة لا تنبغي إلا لعبد من عباد الله، وأرجو أن أكون أنا هو، ومن سأل الله لي الوسيلة؛ حلت له الشفاعة.  وفي حديث جابر بن عبدالله عند البخاري -رحمه الله- عن النبي ﷺ أنه قال: من قال حين يسمع النداء: اللهم رب هذه الدعوة التامة، والصلاة القائمة، آت محمدًا الوسيلة، والفضيلة، وابعثه مقامًا محمودًا الذي وعدته إلا حلت له شفاعتي يوم القيامة رواه البخاري في الصحيح. وبعض الناس قد يزيد فيها \"والدرجة الرفيعة\" وهذا لا أصل، له ليست في الرواية، وقد توجد في بعض الكتب \"والدرجة الرفيعة\" وهي لا أصل لها، ليست في الرواية، والدرجة الرفيعة هي الوسيلة، والوسيلة هي الدرجة الرفيعة، وهو تفسير لها، والحديث إنما فيه الوسيلة، والفضيلة، وليس فيها الدرجة الرفيعة كما قد تقع في ألسنة بعض الناس، أو في كتابة بعض الناس.  فالسنة أن يقول هكذا، ويقول عند الشهادتين عندما يقول المؤذن: أشهد أن لا إله إلا الله، أشهد أن محمدًا رسول الله، يقول المجيب مثله: أشهد أن لا إله إلا الله، أشهد أن محمدًا رسول الله، ويقول: أشهد أن لا إله إلا الله وحده لا شريك له وأشهد أن محمدًا عبده ورسوله، ويقول عند هذا: رضيت بالله ربًا، وبالإسلام دينًا، وبمحمد رسولًا. هكذا جاء عنه -عليه الصلاة والسلام- عند الشهادة، رواه مسلم في الصحيح عن سعد بن أبي وقاص -رضي الله تعالى عنه- أن النبي -عليه الصلاة والسلام- قال: من قال حين يقول المؤذن: أشهد أن لا إله إلا الله، أشهد أن محمدًا رسول الله، وأنا أشهد، رضيت بالله ربًا، وبالإسلام دينًا، وبمحمد رسولًا؛ غفر له ذنبه. وفي لفظ قال: عندما يقول الشهادة: أشهد أن لا إله إلا الله وحده لا شريك له، وأشهد أن محمدًا عبده، ورسوله يقول عند ذلك: رضيت بالله ربًا وبالإسلام دينًا وبمحمد رسولًا؛ غفرت له ذنوبه أو قال: غفر له ذنبه. فهذا يدل على أنه يستحب عند الشهادتين أن يقول هذا الكلام، يقول: رضيت بالله ربًا، وبالإسلام دينًا، وبمحمد رسولًا، عند الشهادتين يجيب المؤذن بقوله: أشهد أن لا إله إلا الله، أشهد أن لا إله إلا الله، أشهد أن محمدًا رسول الله، أشهد أن محمدًا رسول الله، أو يقول: وأنا أشهد أن لا إله إلا الله، وأشهد أن محمدًا رسول الله، ثم يقول بعد هذا: رضيت بالله ربًا، وبالإسلام دينًا، وبمحمد رسولًا، عليه الصلاة والسلام.  وعند الحيعلتين يقول: لا حول ولا قوة إلا بالله، لا حول ولا قوة إلا بالله، لا حول ولا قوة إلا بالله، لا حول ولا قوة إلا بالله، لكل واحدة هذا هو المشروع، وفي حديث عمر عند مسلم من قالها من قلبه؛ دخل الجنة من قال هذا الذكر من قلبه؛ دخل الجنة، فهذا فضل عظيم؛ فينبغي العناية بسماع الأذان، بعض الناس لا يبالي  يسمعه، ولا يبالي، فهذا حرمان من هذا الخير.  فإن الأفضل لك إذا سمعته أن تمسك عن الكلام، وعن القراءة، وتجيب هذا المؤذن بأن تقول ما تقول، وتقول عند الشهادتين: رضيت بالله ربًا، مع الشهادتين، تشهد وتقول مع الشهادتين: رضيت بالله ربًا، وبالإسلام دينًا، وبمحمد رسولًا، وتقول عند الحيعلة: لا حول ولا قوة إلا بالله، وإذا كمل تصلي على النبي ﷺ ثم تقول: اللهم رب هذه الدعوة التامة، والصلاة القائمة، آت محمدًا الوسيلة، والفضيلة، وابعثه المقام المحمود الذي وعدته، كما أرشد النبي -عليه الصلاة والسلام- إلى هذا.","link":"https://binbaz.org.sa/fatwas/1257/بيان-الدعاء-الوارد-بعد-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_253.mp3","categories":["الأذان والإقامة","الأدعية والأذكار"]},{"id":5972,"question":"هل تقرأ المرأة في الصلاة الجهرية جهرًا كما يقرأ الرجل حيث حدث خلاف بين أناس من طلبة العلم، وقال بعضهم: صلوا كما رأيتموني أصلي فهذه للمرأة، والرجل نرجو بيان الحق في ذلك؟","title":"هل تصلي المرأة جهرا كالرجل؟","answer":"الجواب: الذي يظهر لنا أنه لا مانع، تصلي، وتجهر في صلاة المغرب، والعشاء، والفجر كالرجل؛ لأن النبي -عليه الصلاة والسلام- قال: صلوا كما رأيتموني أصلي والأحكام على السواء، أحكام الرجال، والنساء على السواء إلا ما جاء الدليل يخصه إن جاء الدليل بتخصيص الرجل، أو المرأة، وإلا فالأصل أنهما في الأحكام، سواء صلاتهما واحدة، زكاتهما واحدة، حجهما واحد.","link":"https://binbaz.org.sa/fatwas/1353/هل-تصلي-المراة-جهرا-كالرجل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_310.mp3","categories":["الأذان والإقامة","القراءة في الصلاة","قضايا المرأة"]},{"id":6076,"question":"إذا نادى المنادي صلوا في رحالكم فهل يؤذن قبل هذا النداء، أو بعده؟","title":"أين يقول المؤذن صلوا في رحالكم؟","answer":"الجواب: جاء عن ابن عباس في الصحيح هذا، وهذا جاء أنه إذا أراد الإمام أن يخبر الناس بأن يصلوا في رحالهم إن شاء أذن أذانًا كاملاً، ثم قال: صلوا في رحالكم، وإن شاء قال ذلك عند حي على الصلاة، حي على الفلاح، بدل ما يقول: حي على الصلاة، يقول: صلوا في رحالكم، كل هذا ثبت عن ابن عباس، عن النبي ﷺ فإذا كمّل الأذان، ثم قال ذلك حسن، وإن قاله في محل حي على الصلاة، حي على الفلاح؛ فلا بأس، كما جاء عن ابن عباس أيضًا، فالمقصود أنه مخير.","link":"https://binbaz.org.sa/fatwas/1489/اين-يقول-الموذن-صلوا-في-رحالكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_419.mp3","categories":["الأذان والإقامة"]},{"id":6085,"question":"إذا نادى المنادي صلوا في رحالكم فهل يؤذن قبل هذا النداء، أو بعده؟","title":"أين يقول المؤذن صلوا في رحالكم؟","answer":"الجواب: جاء عن ابن عباس في الصحيح هذا، وهذا جاء أنه إذا أراد الإمام أن يخبر الناس بأن يصلوا في رحالهم إن شاء أذن أذانًا كاملاً، ثم قال: صلوا في رحالكم، وإن شاء قال ذلك عند حي على الصلاة، حي على الفلاح، بدل ما يقول: حي على الصلاة، يقول: صلوا في رحالكم، كل هذا ثبت عن ابن عباس، عن النبي ﷺ فإذا كمّل الأذان، ثم قال ذلك حسن، وإن قاله في محل حي على الصلاة، حي على الفلاح؛ فلا بأس، كما جاء عن ابن عباس أيضًا، فالمقصود أنه مخير.","link":"https://binbaz.org.sa/fatwas/1489/اين-يقول-الموذن-صلوا-في-رحالكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_419.mp3","categories":["الأذان والإقامة"]},{"id":6166,"question":"هل التوقيت المعمول به الآن في الدول العربية بأوقات الصلاة هل يجب الاعتماد عليه، أم الاجتهاد الشخصي لكل إنسان حسب ما يراه؟","title":"حكم الاعتماد في الأذان على تواقيت التقاويم","answer":"الجواب: الذي يظهر لنا أنه ظني، التوقيتات هذه الموجودة في التقاويم ظني حسب اجتهاد المقوم حتى يخطئ  كثيرًا وقد يتقدم بدقائق، وقد يتأخر بدقائق، لكن إذا تمكن الإنسان من الأوقات التي هي واضحة مثل غروب الشمس، ومثل طلوع الفجر، ومثل زوال الشمس في المحلات المناسبة، إذا تمكن أن ينظر في الأمر، وأن يحتاط فهذا طيب، وإلا فهي تقريبية.  الغالب عليهم حسب ما جربنا وجرب غيرنا الغالب عليها أنها تقريبية قد يتقدم المقوم مثل الفجر، أو غيرها قد يتقدم بخمس دقائق، أو عشر دقائق، قد يتأخر قليلًا، قد يقارب على كل حال هي ظنية، اجتهادية حسب علمهم بالفلك. ... السؤال: إذا قال بعض الأشخاص: إنهم رأوا أن الفجر يحين بعد الفجر هذا بربع ساعة مثلًا، فهل يؤخذ برأيهم؟ الجواب: إذا كانوا ثقات في محل معين، وفي وقت معين وهم ثقات، قالوا :أن الفجر يطلع في الوقت المعتاد يعتد بهذا، أو أن الشمس ما غابت حتى الآن، وهو ما يشوف، أو في محل ما يتمكن من رؤية الشمس، ينتظر، ويأخذ بقول الثقة، ولا يأخذ بالتقويم، إذا كان في محل ما يمكن أن يروا فيه الشمس، أو ... إلى طلوع الفجر. أما بعض المسائل ما يستطيعون مع الكهرباء في بعض البلدان مع نور الكهرباء العظيم، لا يستطيع أن يرى الفجر في بيته، أو في سطحه، أو في سوقه، ولا يتمكن من ذلك، كما في بعض المحلات عند وجود الغبرة، أو الغيم، قد لا يتمكن  من رؤية الشمس بسبب الغبرة الشديدة، أو بسبب الغيم الواضح، فهذا ما عنده إلا الظن فقط، والاجتهاد، والتحري.","link":"https://binbaz.org.sa/fatwas/1620/حكم-الاعتماد-في-الاذان-على-تواقيت-التقاويم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_511.mp3","categories":["الأذان والإقامة"]},{"id":6185,"question":"النداء إلى الصلاة في هذا العصر يسمع من مسافات بعيدة جدًا بواسطة الميكرفونات، فكم كانت المسافة التي كان الأذان التي يسمع منها في وقت الرسول ﷺ؟","title":"ما المسافة التي كان الأذان يسمع منها في عهد النبي؟","answer":"الجواب: ذكر بعض أهل العلم أنه يقدر بفرسخ، وأن الأذان عند وجود السلامة في الأجواء من الرعود، والأشياء التي تغير الصوت، كالرياح أنه يسمع الأذان في مقدار فرسخ، مقدار تقريبًا ساعة، ونصف من الرِّجْل القَدَم يسمع الأذان. وإذا كان في البلد لا يتحدد بشيء؛ يلزمه أن يسعى إلى المساجد -طالما سمع الأذان- يلزمه إذا حضر الوقت أن يسعى إلى المساجد، أن يصلي مع الناس. لكن إذا كان في بلد، وهو يقيم في ضواحيها، إذا سمع الأذان، مشى وسار، وإذا كان قد لا يسمع لأجل أصوات، وحركات، فإذا تحرى الوقت يمشي ولو قبل الأذان؛ حتى يحضر الجماعة، ويلزمه ذلك، أما صوت المكبر؛ فلا عبرة به؛ لأنه يجوز مسافات كبيرة.","link":"https://binbaz.org.sa/fatwas/1645/ما-المسافة-التي-كان-الاذان-يسمع-منها-في-عهد-النبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_533.mp3","categories":["الأذان والإقامة"]},{"id":6187,"question":"النداء إلى الصلاة في هذا العصر يسمع من مسافات بعيدة جدًا بواسطة الميكرفونات، فكم كانت المسافة التي كان الأذان التي يسمع منها في وقت الرسول ﷺ؟","title":"ما المسافة التي كان الأذان يسمع منها في عهد النبي؟","answer":"الجواب: ذكر بعض أهل العلم أنه يقدر بفرسخ، وأن الأذان عند وجود السلامة في الأجواء من الرعود، والأشياء التي تغير الصوت، كالرياح أنه يسمع الأذان في مقدار فرسخ، مقدار تقريبًا ساعة، ونصف من الرِّجْل القَدَم يسمع الأذان. وإذا كان في البلد لا يتحدد بشيء؛ يلزمه أن يسعى إلى المساجد -طالما سمع الأذان- يلزمه إذا حضر الوقت أن يسعى إلى المساجد، أن يصلي مع الناس. لكن إذا كان في بلد، وهو يقيم في ضواحيها، إذا سمع الأذان، مشى وسار، وإذا كان قد لا يسمع لأجل أصوات، وحركات، فإذا تحرى الوقت يمشي ولو قبل الأذان؛ حتى يحضر الجماعة، ويلزمه ذلك، أما صوت المكبر؛ فلا عبرة به؛ لأنه يجوز مسافات كبيرة.","link":"https://binbaz.org.sa/fatwas/1645/ما-المسافة-التي-كان-الاذان-يسمع-منها-في-عهد-النبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_533.mp3","categories":["الأذان والإقامة"]},{"id":6210,"question":"هل هناك وقت محدد بين الأذان والإقامة لكل صلاة؟","title":"ما الوقت بين الأذان والإقامة في كل فريضة؟","answer":"الجواب: لا نعلم فيه وقتًا محددًا بين الأذان والإقامة، ما في وقت محدد، لكن يتحرى الإمام الوقت المناسب، ربع ساعة، أو ما يقارب ذلك؛ حتى يتجمع الناس، إلا في العشاء كان النبي ﷺ إذا رآهم اجتمعوا؛ عجل، وإذا رآهم أبطؤوا؛ آخر -عليه الصلاة والسلام- وإلا المغرب فإنه يبادر بها -عليه الصلاة والسلام- كان لا يبقى بعد الأذان إلا قليلًا، يصلي ركعتين بعد الأذان، ثم يقيم ﷺ.  وأخبر الصحابة أنه كان في المغرب لا يؤخر الإقامة، ولا يبقى بعد الأذان إلا مدة قليلة، ثم يقيم بعدما يصلي الناس ركعتين بعد أذان المغرب، وأما الظهر، والعصر، والفجر، والعشاء فيتحرى الإمام في ذلك الوقت المناسب الذي يجمع الناس، ويرفق بهم، إذا أذن ذهب يتوضأ، وقد يكون عليه غسل؛ فلا يعجل إلا العشاء بزيادة، فإنه لا يعجل إذا رآهم ما اجتمعوا، فيتأنى حتى يجتمعوا، وإلا الظهر في شدة الحر، إذا اشتد الحر في الظهر؛ فله الإبراد؛ لقول النبي ﷺ: إذا اشتد الحر؛ فأبردوا بالصلاة، فإن شدة الحر من فيح جهنم.","link":"https://binbaz.org.sa/fatwas/1718/ما-الوقت-بين-الاذان-والاقامة-في-كل-فريضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_570.mp3","categories":["الأذان والإقامة"]},{"id":6220,"question":"هل هناك وقت محدد بين الأذان والإقامة لكل صلاة؟","title":"ما الوقت بين الأذان والإقامة في كل فريضة؟","answer":"الجواب: لا نعلم فيه وقتًا محددًا بين الأذان والإقامة، ما في وقت محدد، لكن يتحرى الإمام الوقت المناسب، ربع ساعة، أو ما يقارب ذلك؛ حتى يتجمع الناس، إلا في العشاء كان النبي ﷺ إذا رآهم اجتمعوا؛ عجل، وإذا رآهم أبطؤوا؛ آخر -عليه الصلاة والسلام- وإلا المغرب فإنه يبادر بها -عليه الصلاة والسلام- كان لا يبقى بعد الأذان إلا قليلًا، يصلي ركعتين بعد الأذان، ثم يقيم ﷺ.  وأخبر الصحابة أنه كان في المغرب لا يؤخر الإقامة، ولا يبقى بعد الأذان إلا مدة قليلة، ثم يقيم بعدما يصلي الناس ركعتين بعد أذان المغرب، وأما الظهر، والعصر، والفجر، والعشاء فيتحرى الإمام في ذلك الوقت المناسب الذي يجمع الناس، ويرفق بهم، إذا أذن ذهب يتوضأ، وقد يكون عليه غسل؛ فلا يعجل إلا العشاء بزيادة، فإنه لا يعجل إذا رآهم ما اجتمعوا، فيتأنى حتى يجتمعوا، وإلا الظهر في شدة الحر، إذا اشتد الحر في الظهر؛ فله الإبراد؛ لقول النبي ﷺ: إذا اشتد الحر؛ فأبردوا بالصلاة، فإن شدة الحر من فيح جهنم.","link":"https://binbaz.org.sa/fatwas/1718/ما-الوقت-بين-الاذان-والاقامة-في-كل-فريضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_570.mp3","categories":["الأذان والإقامة"]},{"id":6298,"question":"ما هي المدة المناسبة بين الأذان، والإقامة؟","title":"بيان المدة المناسبة بين الأذان والإقامة","answer":"الجواب: ليس فيها حد محدود بين الأذان، والإقامة، ولكن يتحرى الإمام، لا أعلم حدًا محدودًا عن النبي ﷺ إلا أنه يتحرى ربع ساعة، ثلث ساعة، قريب من ذلك على حسب قرب المأمومين، ومسارعتهم.  فإذا كانوا يسارعون إلى الصلاة، ويجتمعون بكّر، وإذا كان هناك عندهم شيء من التأخر، يراعي أحوالهم، ولاسيما في العشاء، فإن النبي كان يراعيهم في صلاة العشاء أحيانًا، وأحيانًا، إذا رآهم عجلوا عجلها، وإذا أبطؤوا أخرها.  أما الظهر، والعصر، والمغرب، والفجر فهذه ينبغي للإمام أن يراعي فيها حالهم، ولا يتأخر كثيرًا، بل يكون يعني متحريًا للصلاة في أول وقتها، لكن من غير عجلة، إلا المغرب فإن الأولى تعجيلها بعد الأذان بقليل، كان النبي يعجلها بعد الأذان بقليل، وكان الصحابة يصلون بعد الأذان ركعتين، ثم يأتي النبي، ويقيم، عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/1802/بيان-المدة-المناسبة-بين-الاذان-والاقامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_643.mp3","categories":["الأذان والإقامة"]},{"id":6941,"question":"من المعلوم أنه يشرع للمؤذن أن يلتفت يمينًا، وشمالًا عند قوله: حي على الصلاة، وحي على الفلاح؛ ليكون أبلغ في وصول صوته إلى ما يمكن أن يصل إليه، والآن بعد وجود المكبرات الصوتية، هل يشرع له الالتفات، لو التفت؛ لأبعد عن لاقط الصوت؟","title":"حكم الالتفات يميناً وشمالاً عند الأذان بالمكبّرات","answer":"الجواب: الالتفات له حكمة عن يمينه، وعن شماله؛ حتى يسمع الجهتين الشمالية، والجنوبية، أما بعد وجود المكبر؛ فلا حاجة إلى الالتفات، لو كان الالتفات ينفع ما يخالف، لكن لا ينفع، قد يخل بالصوت. فالمقصود: أنه يستقبل، وينادي، ولا حاجة إلى الالتفات؛ إذ المقصود البلاغ، البلاغ بمقابلته أنفع، وأكمل.","link":"https://binbaz.org.sa/fatwas/2871/حكم-الالتفات-يمينا-وشمالا-عند-الاذان-بالمكبرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1319.mp3","categories":["الأذان والإقامة"]},{"id":7024,"question":"إمام المسجد حينما تقام الصلاة يقف في المحراب، ويقول: أقامها الله وأدامها، اللهم رب هذه الدعوة التامة، والصلاة القائمة، آت محمدًا الوسيلة والفضيلة، وابعثه اللهم مقامًا محمودًا الذي وعدته، إنك لا تخلف الميعاد، فهل هذا دعاء مأثور، أو هناك غيره، أو هذا أفضل؟","title":"حكم قول (أقامها الله وأدامها) عند إقامة الصلاة","answer":"الجواب:\n\nالأذان يقال فيه هذا، إذا فرغ من الأذان؛ يصلي على النبي ﷺ ويقول: اللهم رب هذه الدعوة التامة، والصلاة القائمة، آت محمدًا الوسيلة والفضيلة، وابعثه المقام المحمود الذي وعدته هكذا جاء الحديث عن رسول الله ﷺ، فيما رواه البيهقي وزيادة: إنك لا تخلف الميعاد هذا سنة بعد الأذان، والإقامة أذان ثانٍ يقال بعدها.\n\nأما (أقامها الله وأدامها) جاء فيه حديث ضعيف، والأفضل أن يقول: قد قامت الصلاة مثل المؤذن، يقول: قد قامت الصلاة، قد قامت الصلاة، بدلا من (أقامها الله وأدامها) لأن لفظة أقامها الله وأدامها جاء فيه خبر ضعيف، لا يصح عن النبي ﷺ وإنما يقال مثل ما قال النبي ﷺ: إذا سمعتم المؤذن فقولوا مثلما يقول يعني يقول: قد قامت الصلاة، قد قامت الصلاة، في أذان الفجر إذا قال: الصلاة خير من النوم، يقول: الصلاة خير من النوم مثلها.\n\nأما في حي على الصلاة، حي على الفلاح، فيقول: لا حول ولا قوة إلا بالله؛ لأنه صح به الخبر عن النبي ﷺ أنه كان يقول عند حي على الصلاة: لا حول ولا قوة إلا بالله وعند حي على الفلاح يقول: لا حول ولا قوة إلا بالله هذا في الأذان، والإقامة.\n\nالسؤال: يعني ما سمعنا يقول: اللهم رب هذه الدعوة ما كان؟\n\nالجواب: لا، لا، بعد الأذان وبعد الإقامة طبيعي؛ لأنها كلها أذان.\n\nالسؤال: بالنسبة في عمان إقامتهم مثل الأذان طبق الأصل؟\n\nالجواب: قول ثانٍ للعلماء، رواه أبو جحيفة، الأذان له أنواع، والإقامة لها أنواع، فلا بأس إذا كانوا يطبقون حديث أبي جحيفة، لا بأس مثل الأذان، نعم، لكن أذان بلال أفضل، الذي كان بين يدي النبي ﷺ إقامتنا، وأذاننا الآن.","link":"https://binbaz.org.sa/fatwas/2952/حكم-قول-اقامها-الله-وادامها-عند-اقامة-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1403.mp3","categories":["الأدعية والأذكار","فضائل الأعمال","الأذان والإقامة"]},{"id":7432,"question":"ما حكم من صلوا بدون أذان ولا إقامة؟ وهل الأذان واجب والإقامة؟ لأن شيخ الإسلام ابن تيمية قال: إذا أقيم في بلد؛ سقط عن الباقين. وما حكم العزائم التي فيها زعفران يشربها المريض، إلى آخره؟","title":"حكم الصلاة بلا أذان ولا إقامة وكتابة الآيات للرُّقية","answer":"الجواب: الأذان والإقامة فرض كفاية، إذا كان في القرية أو في المدينة عليهم أن يؤذنوا ويقيموا، وهكذا في السفر عليهم أن يؤذنوا ويقيموا إذا كان المسجد واحدًا؛ فأذان واحد، وإن كان مسجدان أذانان، ثلاثة ثلاث، وهكذا على حسب المساجد، والإقامة فرض كفاية، إذا أقام المؤذن أو غيره؛ كفى، ولو صلوا ولم يؤذنوا ولم يقيموا؛ صحت صلاتهم، لكن يأثمون بترك الأذان والإقامة، يكونون قد أخطأوا وصلاتهم صحيحة؛ لأن هذا واجب خارج الصلاة فلا يضر الصلاة تركه من جهة عدم الصحة، بل صلاتهم صحيحة وهم آثمون وعليهم التوبة والاستغفار وعدم العود إلى ترك الأذان والإقامة. وكذلك كتابة الآيات القرآنية والدعوات بالزعفران في إناء أو في أوراق ثم يغسل ويشرب لا بأس به، وقد فعله كثير من السلف، ولكن كونه يقرأ على المريض، ينفث على يد المريض أو رجله، أو بماء يشربه؛ يكون هذا أفضل وأكمل.","link":"https://binbaz.org.sa/fatwas/3520/حكم-الصلاة-بلا-اذان-ولا-اقامة-وكتابة-الايات-للرقية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1824.mp3","categories":["الأدعية والأذكار","فضائل الأعمال","الأذان والإقامة"]},{"id":7459,"question":"سماحة الشيخ السؤال الأول من السائل يقول: أخوكم في الله يحيى محمد جابر زيداني يقول: إنسان في جماعة وسمع الأذان هل يجب عليه أن يؤذن أو يكفيه الأذان الذي سمعه من مؤذن أخر؟","title":"هل يجب الأذان على من سمعوه من مكان آخر؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه. أما بعد: فالإنسان الذي في جماعة وسمع الأذان من أي مسجد فإن الواجب عليه وعلى الجماعة أن يجيبوا الأذان وأن يتوجهوا إلى المسجد ولا يصلون في محلهم، ولا حاجة إلى أذان ولا غيره، بل يتوجهون إلى المسجد الذي سمعوا أذانه وهو قريب منهم، بحيث يمكنهم الوصول إليه والصلاة معهم، إذا كان الأذان بالصوت الطبيعي فإن الغالب يكون المسجد قريب، أما إذا كان بالمكبر فقد يكون بعيداً ووصلهم الصوت من بعد. \nفالحاصل: أن الواجب عليهم التوجه إلى المسجد إذا أمكن، أما إن كان بعيداً لا يتيسر الوصول إليه إلا بعد فوات الصلاة لبعده؛ ولأن الصوت سمعوه بواسطة المكبر وهو يأتي من بعيد، فإنهم يكتفون بالأذان هذا وتكفي الإقامة؛ لأن المقصود سماع الأذان ووجود ما يدعو الناس إلى الصلاة ويعلمهم بالوقت، وقد حصل. \n\nالمقدم: لا، وهو يقول أيضاً في الرسالة: هل يجب عليه أن يؤذن أم يقيم على الأذان الذي يسمعه من حوله؟ أفيدونا. \nالشيخ: يكفي هذا.  \nالمقدم: هذا يعني قريباً منه. \nالشيخ: المقصود يكفيه الإقامة، إذا كان ما يتيسر له أن يصلي مع الناس لمرض أو كونه حارساً أو ما أشبه ذلك، يكفيه الأذان ويقيم، يعني يأتي بالإقامة فقط، أما إذا كان في محل قريب بحيث يستطيع الوصول إلى محل الأذان ويصلي مع الناس، فإن الواجب على هؤلاء السامعين للأذان أن يجيبوا، للحديث من سمع النداء فلم يجب فلا صلاة له إلا من عذر هكذا قال النبي عليه الصلاة والسلام. فالواجب على من سمع الأذان أن يجيب المؤذن، ويتوجه إلى المسجد أو محل المسجد ومحل إقامة الجماعة حتى يكثروا السواد، وحتى يحصل الاجتماع على طاعة الله ، وحتى يحصل الامتثال لأمر النبي ﷺ في حضور الجماعة. لكن إذا كان هناك مانع من مرض أو خوف، أو كونه حارساً لمال عنده لا يستطيع التوجه، أو لأن المكان بعيد وسمعوا الصوت من بعيد بسبب المكبر، ولا يستطيعون الوصول إليه إلا وقد فاتتهم الصلاة، فليصلوا في مكانهم ويكتفون بالأذان، فإن أذنوا فلا بأس، إن أذنوا أذاناً ثانياً فلا حرج؛ لأنه خير بلا شر، ولاسيما مع البعد، وإن اكتفوا بالأذان فإنه كافٍ، وعليهم أن يقيموا فقط، على هذا المتخلف لمرض أو خوف أو ما أشبه ذلك أن يقيم الصلاة ويكتفي بالأذان. نعم.","link":"https://binbaz.org.sa/fatwas/4177/هل-يجب-الاذان-على-من-سمعوه-من-مكان-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_001/00101.mp3","categories":["الأذان والإقامة","قضايا المرأة"]},{"id":7540,"question":"هذه الرسالة وردت في البرنامج من جمهورية السودان الديمقراطية - مدينة عطبرة، يقول: أخوكم في الله تاج الدين إبراهيم أحمد ، يقول: والدتي الحاجة توفت بالأراضي المقدسة بعد أداء فريضة الحج وتوفت بجدة وهي في طريقها للسودان يوم ثلاثة وعشرين ذو الحجة، وأنا منذ ذلك التاريخ لي النية الصادقة لزيارة الأراضي المقدسة لأداء فريضة الحج والوقوف على قبر والدتي والترحم عليها، ولكن الحائل دون ذلك هو أن والدي رجل شيخ كبير، وهو طريح الفراش لا يستطيع الحركة، ويأكل ويشرب جيداً جداً، وهو معي بالمنزل، وهو دائماً يقف عقبة دون حضوري للأراضي المقدسة، فهل يحق لي من ناحية شرعية تركه والحضور للأراضي المقدسة، مع العلم بأنني سوف أمكث بعض الزمن بعد قضاء الفريضة بالأرض المقدسة، فما رأي الشرع والعلماء، أفيدوني زادنا الله وإياكم علماً، ودمتم في حفظ الله ورعايته؟","title":"تقديم بر الوالدين على الحج","answer":"الجواب: ينبغي أن تعلم أيها السائل أن بر الوالدين من أهم الواجبات، ومن أعظم الفرائض، كما قال الله جل وعلا: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا [الإسراء:23]، وقال سبحانه: أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ [لقمان:14].\nوقال النبي ﷺ لما سئل: أي العمل أفضل؟ قال: إيمان بالله وجهاد في سبيله؟ قيل: ثم أي؟ قال: بر الوالدين، قيل: ثم أي؟ قال: الجهاد في سبيل الله، فبر الوالدين من أهم المهمات حتى قدم على الجهاد، فكونك تقيم على والدك، وتحسن إليه، وترعاه، وتتلطف به، وتقضي حاجاته، هذا أعظم وأفضل من حجك ومجيئك إلى الأرض المقدسة، فنوصيك أيها الأخ بلزوم أبيك، والإحسان إليه، والاستمرار في بره حتى يشفيه الله أو يتوفاه الله، وبعد ذلك في إمكانك التوجه للحج أو العمرة، رزقنا الله وإياك التوفيق، وتقبل منا ومنك.","link":"https://binbaz.org.sa/fatwas/4526/تقديم-بر-الوالدين-على-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_011/01110.mp3","categories":["الأذان والإقامة"]},{"id":7595,"question":"ثانياً يقول: إن أبي المتوفى مطلوب بدين سبعة دنانير ونصف حسب ما يقول لي الناس وأمي، هل أوفي بمكانه ذلك الدين، أرشدوني رحمكم الله؟","title":"قضاء دين الوالد","answer":"الجواب: أحسن، أحسن يوفى عنه؛ لأن هذا يخفف عنه، فأحسن يوفى عنه، إذا كان عليه دين وتيسر لك أن توفي عنه أو خلف مالاً يوفى عنه. نعم.","link":"https://binbaz.org.sa/fatwas/4648/قضاء-دين-الوالد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_020/02003.mp3","categories":["الأذان والإقامة"]},{"id":7596,"question":"هذه الرسالة وردت من مهدي عيال أيضاً هذه من نفس المرسل، رسالة من نفس المرسل لكن ما دمنا استعرضنا رسالته الأولى نستعرض رسالته الثانية، يقول: سؤالي هو: هل أن الأذان هو واجب في الصلاة، وهل تركه ينقص الصلاة، وهل على الفرد المصلي أن يؤذن للصلاة وهو منفرد؟","title":"حكم الصلاة دون أذان وإقامة","answer":"الجواب: الأذان فرض كفاية في الصلاة، ويجب على الجماعة في الحضر والسفر أن يؤذنوا يؤذن واحد منهم ويقيم هذا هو الصواب أنهما فرض كفاية، الأذان والإقامة فرض كفاية، إذا قام بها واحد من الجماعة في القرية أو في السفر كفى عن الباقين، ولكن ليسا شرطاً للصلاة بل واجبان وجوب كفاية خارج الصلاة، فمن فعلهما فقد أحسن ويؤجر، ومن تركهما أثم والصلاة صحيحة، فصحتها لا تتوقف على الأذان والإقامة بل الصلاة صحيحة لكنها تكون ناقصة، بدون أذان وبدون إقامة عمداً تكون ناقصة، الأجر ينقص وتكون صلاة لمن صلى بأذان وإقامة أكمل وأفضل. \nولا يجوز للمسلمين تعمد ترك الأذان والإقامة بل الواجب أداء الأذان والإقامة من أحد الجماعة الحاضرين ممن هو أهل لذلك، ممن هو ظاهر في العدالة ويقيم الأذان يؤذن واحد منهم إذا كان بهذه الصفة يعني يقيم الأذان بألفاظه وظاهره العدالة، فإنه يعتمد عليه في الأذان فينبغي أن يكون معروفاً بالعدالة الظاهرة وأن يكون يقيم الأذان، فهو الذي يؤذن، سواء كان في الحضر أو في السفر. \nأما إذا كان فرداً واحداً في السفر فالأولى له أن يؤذن أيضاً، أما الوجوب عليه ففيه خلاف ونظر، لكن الأفضل والأولى في كل حال والسنة في حقه أن يؤذن، لما جاء في حديث أبي سعيد الخدري : أنه قال: «..... رجل إذا كنت في غنمك ..... فارفع صوتك بالنداء، فإنه لا يسمع صوت المؤذن حجر ولا شجر إلا شهد له يوم القيامة، سمعته من نبيكم عليه الصلاة والسلام»، فأمره بالأذان وهو واحد، فدل ذلك على تأكده في حق الواحد، أما الوجوب كونه يجب عليه أم لا يجب، فهو محل خلاف ومحل نظر، ولكن ينبغي له أن لا يدع الأذان، أما إذا كانوا جماعة فالواجب عليهم أن يؤذنوا يؤذن واحد منهم ويقيموا كذلك. نعم.","link":"https://binbaz.org.sa/fatwas/4649/حكم-الصلاة-دون-اذان-واقامة ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_020/02004.mp3","categories":["الأذان والإقامة","قضايا المرأة"]},{"id":7635,"question":"أيضاً هذه الرسالة من فاطمة محمد من مدينة أبها، تقول: السلام عليكم ورحمة الله وبركاته، إلى فضيلة الشيخ عبد العزيز بن باز المكرم، مشكلتي هذه أعرضها عليكم، راجين من الله ثم منكم أن تجدوا لي حلاً فيها، تقول: في الواقع أفيدكم أن لي أخت من الأم، وقد تزوجت من رجل، فأنجبت منه بنتاً ثم طلقها، ثم تزوجت من رجل آخر لا تريده ولا نحن أيضاً نريده خاصة والدتي، ولكن إخوانها من الأب هم الذين أجبروها، فعندما حضر زوجها رفضت والدتي أن تذهب إليها وأن تشير على أختي، وبعد ذلك سكن بجوارنا ولم يخبرنا، فعندما علمت والدتي أتت إليهم لكي ترى أختي، فقالت أختي لوالدتي: أنت ليس والدتي؛ لأنك لم تأتيني في الزواج، فقالت والدتي: أنا لم آتيك إلا لأراك ولزيارة الرحم، وبعد وقت قصير سافر بها زوجها إلى مدينة بعيدة منا، وقد حرم والدتي من رؤية ابنتها ومن رؤيتنا إليها نحن أيضاً، ولم يخبرنا بالعمل الذي هو فيه، ولم يخبرنا بالتلفون لكي نتصل أو تتصل والدتي وتطمئن إليها، علماً بأن أختي قد قالت لوالدتي: عندما أسافر أجعلك تبكين علي، وأنت التي ترسلين علي، فنرجو من فضيلتكم أن تخبرونا ماذا تفعل والدتي؟ هل والدتي حقاً لها أن ترسل إليها؟ علماً بأن للوالدين حقاً علينا نحن الأبناء، وأن الرسول ﷺ قد خص بالأم أحق من الأب، نرجو الإفادة وفقكم الله؟","title":"الحكم الشرعي في بنت هجرت أمها","answer":"الجواب: على كل حال الوالدة لها حق كبير، وبرها واجب، وبرها أعظم من بر الأب، النبي ﷺ لما سئل قال له رجل: يا رسول الله! من أبر؟ قال: أمك، قال: ثم من؟ قال: أمك، قال: ثم من؟ قال: أمك، قال: ثم من؟ قال: أباك، فلها ثلاثة الأرباع وله الربع، لكن هذه البنت يعني أساءت التصرف، ذهبت ولم تقابلها ولم توادعها، ولم تخبرها بمكانها، فلا حرج على الوالدة في هذه الحال إذا لم تكتب إليها؛ لأنها لا تعلم مكانها، فلا حرج عليها في هذه الحال، والواجب على البنت التي سافرت أن تكتب لأمها وأن تسأل عن حالها وأن تدعو لها كثيراً وأن تصلها؛ لأن هذا من البر، فالإثم على البنت التي قصرت في حق والدتها إذا لم تكتب إليها ولم تراسلها ولم تصلها، أما الأم فلا شيء عليها في هذه الحال؛ لأنها لا تعلم مكانها وحقها أكبر، فإن احتسبت هي الأم وسألت عنها حتى تعرف مكانها وكتبت إليها أو كلمتها بالهاتف تسأل عن حالها هذا عمل طيب ومن صلة الرحم، ولها أجر كبير في ذلك، وإن قصرت بنتها فهي لا تقصر، وتفعل ما هو الأحسن؛ لأن الرسول عليه السلام قال: ليس الواصل بالمكافي، ولكن الواصل الذي إذا قطعت رحمه وصلها هذا الواصل يعني: في الحقيقة، الواصل على الكمال: هو الذي يصل من قطعه، ولهذا قال عليه الصلاة والسلام: ليس الواصل بالمكافي، ولكن الواصل الذي إذا قطعت رحمه وصلها. نعم.","link":"https://binbaz.org.sa/fatwas/4689/الحكم-الشرعي-في-بنت-هجرت-امها ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_026/02602.mp3","categories":["الأذان والإقامة"]},{"id":7686,"question":"يقول في سؤاله التالي: إن المؤذنين لا يتقيدون بتوقيت واحد في الصلوات الخمس وخاصة صلاة الفجر، بالرغم من أن هناك توقيت معمول لكل مدينة، فماذا تنصحونهم به، وفقكم الله؟","title":"ما النصيحة للمؤذنين في تحري وقت الأذان؟","answer":"الجواب: ننصح المؤذنين بأن يتقيدوا بالوقت دائماً، الظهر والعصر والمغرب والعشاء والفجر، هذا الواجب عليهم، الواجب عليهم أن يتقيدوا بالوقت وأن يتحروا دخول الوقت، ولا يقلدوا التقويمات؛ لأن فيها الأخطاء والأغلاط، وينبغي لهم العناية والحرص على ضبط الوقت، الزوال يعرف في الشمس، والغروب بغروب الشمس في المغرب، والعشاء بغيبوبة الشفق، والفجر بطلوع الفجر، ينبغي أن يتحروا، إذا أمكنهم ذلك يتحروا، فإذا ما أمكنهم ذلك فيضبطوا التقويم ويتحروا يعني: صحة التقويم، وإذا كان التقويم مبكر أخروا عنه زيادة خمس دقائق.. عشر دقائق، حسب ما يتضح لهم بالتجارب، وهكذا حتى يضبطوا الأمر بشيء واضح، إن كان التقويم يتأخر ضبطوا التأخر وتقدموا عليه، وإن كان التقويم يعني يبكر قبل الوقت ضبطوا النقص الذي في التقويم، فزادوه بعد تقويمهم ثم أذنوا على البصيرة، فالحاصل أن الواجب عليهم التحري في الوقت بكل عناية؛ لأن الناس في ذمتهم، وهم أمناء في الصلاة وفي الفطر من رمضان، فالواجب عليهم التحري للوقت والعناية، وهو في الظهر وفي العصر وفي المغرب والعشاء والفجر بين بحمد الله إذا اعتنوا، فالظهر بزوال الشمس بعد فيء الزوال، إذا زالت الشمس دخل وقت الظهر، والعصر إذا صار ظل كل شيء مثله، بعد فيء الزوال دخل وقت العصر، والمغرب بغروب الشمس، والعشاء إذا غاب الشفق الأحمر الذي في جهة المغرب، والفجر بطلوع الفجر المستطيل في الأفق المعترض الصادق المنتشر، هذا هو الفجر الصادق، فالواجب عليهم التحري في هذه الأشياء بالعين أو بالتقويم المضبوط الذي قد درس وأعتني به وعرف مطابقته للواقع. نعم.","link":"https://binbaz.org.sa/fatwas/4885/ما-النصيحة-للموذنين-في-تحري-وقت-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_027/02705.mp3","categories":["الأذان والإقامة","قضايا المرأة"]},{"id":7692,"question":"من الجمهورية العراقية بعث بهذه الرسالة المستمع مهدي أبو صالح العايذي يقول في رسالته: لي والد متوفى، وتقول لي والدتي: إنه يسرق الناس أموالهم، هل أقوم بذبح الضحايا له، وهل أوفي الدين الذي مطلوب منه وهو سبعة دنانير، أفيدونا وفقكم الله؟","title":"حكم الإحسان إلى الوالدين بعد الموت ولو كانا فاسقين","answer":"الجواب: الوالد له حق كبير، وكونه إذا كان يسرق هذه معصية، والمعاصي لا تمنع الإحسان للوالدين، فإذا كان في قول والدته (إنه يسرق) لا يمنع هذا من التضحية عنه ووفاء الدين الذي عليه، وأنت مأجور في التضحية عنه وفي الإحسان إليه بالصدقة والدعاء ولو كان ينهب بعض الناس؛ لأن هذه من المعاصي، لا تخرجه من دائرة الإسلام، ما دام معروفاً بالاستقامة في المسائل الأخرى يصلي ويوحد الله، ولكن قد يقع منه نهب بعض الأموال، هذا لا يمنع من الضحية له، ولا يمنع من الصدقة عنه بالمال، من النقود ونحو ذلك، ولا يمنع من الدعاء له، كل هذا لا بأس به؛ لأن الميت يدعى له ويتصدق عنه ولو كان فيه فسق، ولو كان عنده معاصي. \nأما الكافر فلا، المعروف بالكفر الذي مثل.. اليهودي والنصاري والوثني، مثل الذي يدعو الأموات ويستغيث بالأموات وينذر لهم، هذا لا يدعى له إذا مات، ولا يضحى عنه ولا يتصدق عنه، وإنما الضحية والصدقة والدعاء للمسلم وإن كان عنده معاصي، ينبغي التفطن لهذا. نعم.","link":"https://binbaz.org.sa/fatwas/4891/حكم-الاحسان-الى-الوالدين-بعد-الموت-ولو-كانا-فاسقين ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_028/02803.mp3","categories":["الأذان والإقامة"]},{"id":7694,"question":"أيضاً يقول: لي والدة حنون وعطوف ومحبة لي، وهي لا تصلي، هل يمكنني الإنفاق عليها وخدمتها أم لا؟","title":"حكم الإحسان إلى الوالدة التي لا تصلي","answer":"الجواب: نعم، وإن كانت لا تصلي، الواجب عليك الإحسان إليها، وبرها ومصاحبتها بالمعروف حتى يتوفاها الله، ولكن مع هذا تنصحها كثيراً وتوصيها بالصلاة، وتعلمها أن الصلاة أمرها عظيم وأنها عمود الإسلام، وأن من تركها كفر، لعلها تهتدي تحسن إليها بالمعروف.. بالكلام الطيب.. بالمواساة.. بالمال، هكذا ينبغي؛ لأن الله جل وعلا أوصى بالوالدين وإن كانا كافرين، أوصى بهما خيراً وإحساناً، والإحسان قد يكون سبباً لهدايتها وقيامها بالصلاة، فعليك بالإحسان إليها والصبر عليها ومخاطبتها بالتي هي أحسن ونصيحتها لعل الله يهديها. نعم.","link":"https://binbaz.org.sa/fatwas/4893/حكم-الاحسان-الى-الوالدة-التي-لا-تصلي ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_028/02805.mp3","categories":["الأذان والإقامة"]},{"id":7765,"question":"يقول سليمان راشد: هل على المرأة المسلمة أذان أو إقامة عند الصلاة؟ وما حكم صلاتها لو فعلت ذلك؟","title":"حكم الأذان والإقامة على النساء","answer":"الجواب: بسم الله الرحمن الرحيم.\nالحمد لله، والصلاة والسلام على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: ليس على النساء أذان ولا إقامة، هذا للرجال، والسنة أن تصلي بدون أذان ولا إقامة، فلو صلت بأذان وإقامة أساءت وفعلت شيء غير مشروع، وصلاتها صحيحة.","link":"https://binbaz.org.sa/fatwas/4965/حكم-الاذان-والاقامة-على-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_045/04501.mp3","categories":["الأذان والإقامة","قضايا المرأة"]},{"id":7782,"question":"يقول ثالثاً: أنا أسكن إحدى القرى بالمملكة، والحمد لله محافظ على أداء الصلوات في المسجد، وبعد حضوري إلى هذه المنطقة في المملكة وهي منطقة اللسيب بالقصيم توجهت إلى المسجد لأداء الصلاة، وبعد أن جلست في المسجد مدة طلب مني أحد المواطنين بأن أؤذن؛ لأن المسجد ليس به مؤذن، فقمت على الفور وأديت الأذان، وظللت مدة أؤذن حين لم يحضر المؤذن، وفي يوم من الأيام أذنت لصلاة العشاء فحضر الإمام وقال: من أذن؟ فقلت له: أنا، فقال: لا نريد أحد أن يؤذن، فمن ذلك اليوم لم أؤذن، حتى ولو طلب مني، علماً بأنني متعلم والحمد لله، ولا أشك في أداء الأذان، أرجو أن تفيدوني؛ لأن هذا الإمام حرمني أجراً عظيم، علماً بأنني لا أتقاضى شيء مقابل هذا الأذان، وما فضل الأذان، وما حكم هذا الإمام بالنسبة لي؟","title":"ما حكم الأذان؟","answer":"الجواب: الأذان فرض كفاية، والواجب على أهل المسجد أن يؤذن أحدهم، إذا لم يكن هناك مؤذن من جهة وزارة الأوقاف فالواجب أن يؤذن أحدهم، فإذا أذن أحدهم كفى؛ لأنه فرض كفاية وهو يقيم أيضاً، فالإقامة والأذان فرضا كفاية، إذا قام به واحد منهم كفى، أما تركهم المسجد دون أذان هذا لا يجوز، اللهم إلا أن يكون قربه مسجد آخر يكتفى بأذانه لأنه يعم؛ لأن المؤذن الذي بقربه يعني: يعم جيران المسجد هذا ويسمعونه، فهذا قد يقال بإجزائه، ولكن لابد أن يقيم أحدهم، الإمام أو غيره يقيم للصلاة، وبكل حال فلا ينبغي ترك الأذان، بل ينبغي للمسجد أن يؤذن فيه من الجماعة، وإذا كان السائل يتبرع بذلك ويقيم الأذان فلا ينبغي للإمام ولا غيره أن يمنعه من ذلك إلا إذا وجدوا من يقوم مقامه، إن وجدوا من يقوم مقامه فلهم النظر في ذلك، الإمام ينظر في ذلك هو وجماعة، فيعينون من يحصل به المقصود من أداء هذه الفريضة، أما أن يعطلوا الأذان بالكلية فهذا لا يجوز ويأثمون بذلك، فالواجب أن يؤذن واحد منهم، يقيم الأذان، يحسن الأذان، فإن لم يتيسر واحد منهم سمحوا لهذا السائل هذا المتبرع وجزاه الله خيراً، يجب أن يسمحوا له أن يؤذن أو يقوموا بالأذان هم، أما تعطيل المسجد بدون أذان فهذا لا يجوز. نعم.","link":"https://binbaz.org.sa/fatwas/5122/ما-حكم-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_048/04804.mp3","categories":["الأذان والإقامة"]},{"id":7814,"question":"هذا سائل أرسل بمجموعة من الأسئلة يقول: سؤالي الأول: إذا دخلت المسجد والمؤذن ينادي للصلاة هل أصلي ركعتين تحيةً للمسجد أم أنتظر حتى ينتهي المؤذن من الأذان؟","title":"حكم من دخل المسجد والمؤذن يؤذن للصلاة","answer":"الجواب: الأفضل أن .... المؤذن، تنتظر تجيب المؤذن ثم تصلي ركعتين حتى تجمع بين الحسنيين وبين الفضيلتين وبين الأمر المشروع، تبدأ بالأذان تجيب المؤذن ثم تصلي ركعتين. نعم.","link":"https://binbaz.org.sa/fatwas/5204/حكم-من-دخل-المسجد-والموذن-يوذن-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_051/05122.mp3","categories":["المساجد ومواضع السجود","الأذان والإقامة"]},{"id":7833,"question":"سؤاله الثاني يقول فيه: هل يجوز مواصلة زيارة الأقارب ولديهم نساء سافرات؟","title":"حكم صلة الرحم إذا خشي منها فتنة","answer":"الجواب: أما الزيارة للأقارب فهذا من صلة الرحم، لكن بشرط أن لا يكون في ذلك فتنة ولا أذى، فإذا كانت النساء لا يتحجبن فهو بين أمرين، إما أن يزور ويأمر بالمعروف وينهى عن المنكر ويعلمهن أن هذا لا يجوز وأن عليهن التستر والحجاب، فإن فعلن ذلك فالحمد لله حصل بذلك صلة الرحم وإزالة المنكر.\nأما إن كانت زيارته يترتب عليها رؤية النساء والاستمتاع بالنساء هذا لا يجوز، أو أمرهن بالمعروف ولكن لم يمتثلن ولم يبالين كذلك، لا يزورهن لأن هذا قد يسبب فتنة عليه وشراً عليه، لكن يحسن إليهن من جهة أخرى بالمال إن كن فقراء، بالنصيحة ولو بالمكاتبة، ولو بالهاتف، ولو بوصية إخوتهن أو أبيهن أو جدهن أو أعمامهن بالنصيحة الواجبة؛ لأن حضوره إليهن ومشاهدته لهن قد يترتب عليها شر وفتنة، نعم.\nالمقدم: جزاكم الله خيرا ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/5225/حكم-صلة-الرحم-اذا-خشي-منها-فتنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_052/05206.mp3","categories":["الأذان والإقامة"]},{"id":8012,"question":"سؤال المستمعة فاطمة صالح صقر فارس من الأردن من مدينة أربد تقول: هو أنني مصابة بداء الشك، فهو ينتابني دائماً ومسيطر علي، أي: عندما يتكلم شخص فإنني أشك فيه أنه تكلم وهو لم يتكلم، وهذا الشك ينتابني من غير قصد مني ولا نية، أحاول التخلص منه فلم أقدر، والمشكلة أنني أخشى أن يصيبني إثم في اتهام الناس بالكلام وهو لم يقع منهم، أرجو إفتائي في ذلك وتوجيهي لما ينفع؟","title":"علاج مرض الشك بالغير","answer":"الجواب: لا إثم عليك إن شاء الله، لكن تتعالجين من هذا الأمر والتثبت في الأمور وعدم العجلة في الأمور، والتعوذ بالله من الشيطان، فإن هذا قد يفضي إلى الوساوس، فينبغي التعوذ بالله من الشيطان الرجيم عند وجود هذه الشكوك، وأيضاً عدم العجلة في الأمور وعدم الحكم على الناس إلا بعد التثبت، فلا تعجلي في شيء، وتثبتي في الأمور حتى تجزمي جزماً يقيناً أن هذا تكلم أو هذا قال كذا أو كذا، ودعي الشكوك والأوهام؛ لأن هذا قد يجر إلى شر كثير، وعليك بالإكثار من ذكر الله والتعوذ بالله من الشيطان حتى يزول هذا التوهم. نعم.","link":"https://binbaz.org.sa/fatwas/5576/علاج-مرض-الشك-بالغير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_076/07603.mp3","categories":["الأذان والإقامة"]},{"id":8014,"question":"سؤال المستمعة فاطمة صالح صقر فارس من الأردن من مدينة أربد تقول: هو أنني مصابة بداء الشك، فهو ينتابني دائماً ومسيطر علي، أي: عندما يتكلم شخص فإنني أشك فيه أنه تكلم وهو لم يتكلم، وهذا الشك ينتابني من غير قصد مني ولا نية، أحاول التخلص منه فلم أقدر، والمشكلة أنني أخشى أن يصيبني إثم في اتهام الناس بالكلام وهو لم يقع منهم، أرجو إفتائي في ذلك وتوجيهي لما ينفع؟","title":"علاج مرض الشك بالغير","answer":"الجواب: لا إثم عليك إن شاء الله، لكن تتعالجين من هذا الأمر والتثبت في الأمور وعدم العجلة في الأمور، والتعوذ بالله من الشيطان، فإن هذا قد يفضي إلى الوساوس، فينبغي التعوذ بالله من الشيطان الرجيم عند وجود هذه الشكوك، وأيضاً عدم العجلة في الأمور وعدم الحكم على الناس إلا بعد التثبت، فلا تعجلي في شيء، وتثبتي في الأمور حتى تجزمي جزماً يقيناً أن هذا تكلم أو هذا قال كذا أو كذا، ودعي الشكوك والأوهام؛ لأن هذا قد يجر إلى شر كثير، وعليك بالإكثار من ذكر الله والتعوذ بالله من الشيطان حتى يزول هذا التوهم. نعم.","link":"https://binbaz.org.sa/fatwas/5576/علاج-مرض-الشك-بالغير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_076/07603.mp3","categories":["الأذان والإقامة"]},{"id":8034,"question":"هذه الرسالة بعث بها المواطن حسن محمد ، يقول فيها: السلام عليكم ورحمة الله وبركاته، وبعد: أطرح بين أيديكم هذا السؤال وأرجو الإجابة على ذلك:أنا رجل أشغل وظيفة مؤذن بمسجد ولي مرتب من الأوقاف ويقال لي: إنك استلمت راتب فليس لك أجر. وأنا لا أرغب ذلك، وإنما أرغب الأجر أحسن من الراتب، يقول: علماً أني أنا في حاجة إلى هذا الراتب حيث ليس لي أي دخل آخر ولكن أفضل أجر الآخرة على أجر الدنيا والله يحفظكم ويرعاكم؟","title":"حكم أخذ الأجرة على الأذان","answer":"الجواب: ثبت عن النبي صلى الله عليه وسلم أنه قال لـعثمان بن أبي العاص لما سأله أن يكون إمام قومه قال: أنت إمامهم، واقتد بأضعفهم، واتخذ مؤذناً لا يأخذ على أذانه أجراً.\nفدل ذلك على أن المؤذن الذي يتبرع بالأذان ويتطوع به يريد ما عند الله أنه أفضل وأولى من غيره، لكن ذكر العلماء أن الذي يعطى من بيت المال ما يعينه على ذلك لا حرج عليه في ذلك ولا بأس عليه؛ لأن بيت المال للمصالح مصالح المسلمين، وهكذا الأوقاف التي يوقفها المسلمون على المؤذنين والأئمة لا حرج عليهم إذا أخذوا منها ما يعينهم على العمل الصالح، فإذا أخذت -أيها السائل- من بيت المال من وزارة الأوقاف ما يعينك فلا حرج عليك ونرجو أن يكون لك الأجر كاملاً؛ لأنك تأخذ شيئاً يعينك على هذا الواجب وعلى هذا العمل الصالح وربما لو تركت ذلك لتركت هذا العمل لالتماس الرزق.\nفالحاصل: أن المؤذن إذا دفع إليه ما يعينه على أداء الأذان لحاجته إليه فلا حرج عليه في ذلك؛ لأن الأذان يحبسه يحتاج منه إلى أوقات، فإذا أخذ ما يعينه على ذلك فلا حرج عليه في ذلك.\nلكن من وسع الله عليه وأحب أن يعمل من دون شيء من بيت المال فذلك أفضل وأكمل لأنه حينئذٍ تكون قربته كاملة ليس فيها شيء من النقص بل عمل عمله لله كاملاً من دون شائبة، أما من أخذ من بيت المال فلا حرج عليه؛ لأن بيت المال للمسلمين عامة ولا سيما المصالح كالأذان والإمامة وأشباه ذلك، وهكذا الأوقاف التي توقف على المؤذنين والأئمة هذه كلها من باب التعاون على البر والتقوى، ومن باب تسهيل أمور الإمامة والأذان لأنه ليس كل واحد يتفرغ لهذا الشيء، فإذا أمنت حاجته كان هذا أدعى إلى أن يلتزم ويقوم بهذا الأمر العظيم الواجب. نعم.\nالمقدم: لكن هذا الأجر الذي يساق اليوم للمؤذنين هل يدخل فيه هذا الحث الذي حث عليه الرسول صلى الله عليه وسلم وهؤلاء يأخذون من بيت مال المسلمين الآن؟\nالشيخ: الذي يظهر أنه غير داخل في هذا وأن النبي ﷺ أراد الذي يعني يؤاجر يعطيه يقول: لا أؤذن إلا بأجر يأخذ أجراً على ذلك، يعني: مشارطة بينه وبين أهل المسجد أو بينه وبين بعض الناس الآخرين فهذا هو الأقرب في ظاهر النص، أما الذي يعطاه من بيت المال كما يعطى المدرس ويعطى الإمام ويعطى المجاهدون فهو غير داخل في هذا إن شاء الله، لكن لا شك أن الذي يريد يعني ألا يأخذ شيئاً بالكلية وأن يتفرغ لهذا الشيء من جهة نفسه لأن الله قد أعطاه مالاً ووسع عليه فهذا أكمل في الإخلاص. نعم.","link":"https://binbaz.org.sa/fatwas/5657/حكم-اخذ-الاجرة-على-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_080/08005.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":8296,"question":"فضيلة الشيخ، يعقد السائل مُقارنةً أو مُوازنةً بين العمال من المسلمين وغير المسلمين فيقول: إن غير المسلمين هم من أهل الأمانة، وأستطيع أن أثق فيهم، وطلباتهم قليلةٌ، وأعمالهم ناجحةٌ، أما أولئك فهم على العكس تمامًا. فما رأيكم سماحة الشيخ؟","title":"حكم استقدام عمالاً كفرة وترك المسلمين","answer":"الجواب:\n\nهؤلاء ليسوا بمسلمين على الحقيقة، هؤلاء يدَّعون الإسلام، أما المسلمون في الحقيقة فهم أولى وأحق، وهم أكثر أمانةً، وأكثر صدقًا من الكفار.\n\nوهذا الذي قلتَه غلطٌ، لا ينبغي أن تقوله، والكفار إذا صدقوا عندكم وأدوا الأمانة حتى يُدركوا مصلحتهم معكم، وحتى يأخذوا الأموال عن إخواننا المسلمين، فهذه لمصلحتهم، فهم ما أظهروا هذا لمصلحتكم، ولكن لمصلحتهم هم؛ حتى يأخذوا الأموال، وحتى ترغبوا فيهم.\n\nفالواجب عليكم ألا تستقدموا إلا الطيبين من المسلمين، وإذا رأيتم مسلمين غير مُستقيمين فانصحوهم ووجِّهوهم، فإن استقاموا وإلا فردُّوهم إلى بلادهم، واستقدموا غيرهم، وطالبوا الوكيل الذي يختار لكم أن يختار الناس الطيبين المعروفين بالأمانة، المعروفين بالصلاة، المعروفين بالاستقامة، لا يستقدم مَن هبَّ ودَبَّ.\n\nوكثيرٌ من الناس يدَّعي الإسلام وهو كافرٌ، ليس بمسلمٍ: كالمنافقين، ولكن أنتم أرباب الأعمال عليكم أن تستقدموا الطيبين، ولا تغتروا بهؤلاء الكفرة الذين يتصنعون عندكم ويُظهرون عندكم ما يُرغِّبكم فيهم من أمانةٍ، وصدقٍ، ونحو ذلك.\n\nفهذا لا ينبغي منكم، بل إخوانكم المسلمون أولى بأموالكم، وأولى بخدمتكم، وإذا حصل منهم نقصٌ فوجِّهوهم، وعلِّموهم، ولاحظوهم حتى يستقيموا.\n\nوهذا لا شك أنه من خداع الشيطان أن يقول لكم: إن هؤلاء الكفار أحسن من المسلمين، أو أكثر أمانةً، أو كذا، أو كذا. كله لما يعلمه عدو الله وجنوده من الشر العظيم في استقدام الكفرة واستخدامهم بدل المسلمين؛ فلهذا يُرغِّب فيهم، ويُزين لكم استقدامهم؛ حتى تدعوا المسلمين، وحتى تستقدموا أعداء الله؛ إيثارًا للدنيا على الآخرة، ولا حول ولا قوة إلا بالله.\n\nوقد بلغني عن بعضهم أنه يقول: إن المسلمين يُصلون ويُعطلون الأعمال بالصلاة، والكفار لا يُصلون؛ حتى يأتوا بأعمالٍ أكثر.\n\nوهذا أيضًا من جنس ما قبله، ومن البلاء العظيم أن يعيب المسلمين بالصلاة، ويستقدم الكفار؛ لأنهم لا يُصلون، فأين الإيمان؟! وأين التقوى؟! وأين خوف الله؟! أن تعيب إخوانك المسلمين بالصلاة!\n\nنسأل الله السلامة والعافية.","link":"https://binbaz.org.sa/fatwas/6109/حكم-استقدام-عمالا-كفرة-وترك-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_108/10804.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":8390,"question":"كثيراً أقوم بتلاوة بعض الآيات أثناء عملي، أو أثناء النزهة من جانب الترفيه عن النفس، هل يصح ذلك؟","title":"حكم تلاوة القرآن أثناء العمل للترويح عن النفس","answer":"الجواب: لا بأس أن يقرأ المؤمن بعض الآيات، يريح به نفسه، يريح بذلك نفسه، ويتلذذ بكلام الله، ويستفيد ويتدبر ويتعقل، فآيات الله فيها الهدى والنور، وفيها جلاء النفس، وجلاء القلب، وبها التبصير والدعوة إلى كل خير، والتحذير من كل شر، فينبغي الإكثار من ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/6256/حكم-تلاوة-القران-اثناء-العمل-للترويح-عن-النفس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_116/11609.mp3","categories":["الأذان والإقامة"]},{"id":8457,"question":"هنا رسالة اشترك في وضع أسئلتها مجموعة من إخواننا المصريين المقيمين في العراق وهم:أخونا: حسن مصري الجنسية، وأيضاً أحد الإخوة من هناك: ورمز إلى اسمه (م. أ. ع) والثالث: أيضاً يقول: (ع. ب. س) يسألون سماحة الشيخ! كما قلت مجموعة من الأسئلة ومن بينها سؤال عن أخذ الأجرة على تحفيظ القرآن الكريم حيث أن لديهم إمام في قريتهم في مصر ويأخذ أجراً على تحفيظ الصبيان للقرآن الكريم فبم توجهونهم لو سمحتم سماحة الشيخ؟","title":"حكم أخذ الأجرة على تحفيظ الصبيان القرآن؟","answer":"الجواب: لا حرج في ذلك، الصحيح أنه لا حرج في أخذ الأجرة على تعليم القرآن وتعليم العلم؛ لأن الناس في حاجة إلى التعليم؛ ولأن المعلم قد يشق عليه ذلك ويعطله التعليم عن الكسب، فإذا أخذ أجرة على تعليم القرآن أو تحفيظ القرآن أو تعليم العلم، فالصحيح: أنه لا حرج في ذلك، وقد ثبت عنه ﷺ أن جماعة من الصحابة جاءهم بعض العرب وأخبرهم أن سيدهم يعني: رئيسهم لديغ وأنهم فعلوا كل شيء لا ينفعه، وطلبوا منهم أن يرقوه فتقدم أحد الصحابة ورقاه بفاتحة الكتاب، فشفاه الله وعافاه وكانوا اشترطوا عليهم قطيعاً من الغنم، فأوفوا لهم بشرطهم، فتوقفوا عن قسمه بينهم حتى سألوا النبي ﷺ فقال: أحسنتم واضربوا لي معكم بسهمم  ولم ينكر عليهم ذلك، وقال: إن أحق ما أخذتم عليه أجراً كتاب الله رواه البخاري في الصحيح.\nفهذا يدل على أنه لا بأس بأخذ الأجرة على التعليم إذا كان التطبب وقراءة الفاتحة ونحوها على اللديغ والمريض لا بأس أن يؤخذ عنه أجرة، فالتعليم أنفع للناس وأكثر حاجة، فلا بأس أن يؤخذ عنه الأجرة في تعليم العلم تعليم القرآن وتحفيظه ولا حرج في هذا والحمد لله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6463/حكم-اخذ-الاجرة-على-تحفيظ-الصبيان-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_123/12304.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":8494,"question":"هنا رسالة بعثها أحد الإخوة من مكة المكرمة -الزاهر- يقول فضل محمد أحمد السوداني أخونا يسأل ويقول: لي أرض بالسودان أرض زراعية ولم أستطع إصلاحها، ففكرت في إيجارها لمن يستطيع إصلاحها وعندما شرعت في ذلك بلغني من أحد الفقهاء هناك بأن إيجار الأرض لا يجوز، يجوز أن تعطيها بجزء من المحصول ولا يجوز إيجارها فهل هذا صحيح؟","title":"حكم إيجار الأرض","answer":"الجواب: ليس هذا بصحيح يجوز تأجير الأرض بشيء معلوم كالدراهم والأصواع المعلومة كما قال رافع بن خديج عن النبي ﷺ أنه قال: فأما شيء معلوم مضمون فلا بأس به فتأجير الأرض بشيء معلوم من دراهم أو دنانير أو أصوع معلومة من جنس ما يخرج منها أو غيره لا بأس بذلك، هذا هو الذي عليه أهل العلم وهو الحق وإن كان بعض الناس قد خالف في ذلك لكن خلاف لا وجه له، والصواب أنه يجوز تأجيرها بجزء مشاع مما يخرج منها كالربع والثلث ونحو ذلك، ويجوز تأجيرها بشيء مضمون معلوم كمائة درهم ألف درهم ألف صاع ألف كيلو من الحنطة من الأرز من الشعير كل هذا لا بأس به.\nأما الذي ينهى عنه فهو أن يؤجرها ببقعة منها، فيقول: لك ما نبت هنا ولي ما نبت هنا، فهذا يفضي إلى الغرر فقد تنبت هذه ولا تنبت هذه، قد تكون هذه أطيب من هذه فإذا أجره الأرض على أن له ما نبت في الجناح الشمالي أو في الجناح الغربي أو الجنوبي أو نحو ذلك هذا ليس بصحيح، أو قال لك أو لي ما نبت على السواقي -على الجداول مثلاً- وأما ما سوى ذلك فللآخر فهذا كذلك لا يصلح، وقد نص على ذلك في رواية رافع بن خديج ، عن النبي ﷺ وهذا يكون فيه جهالة، وإنما يجوز تأجيرها بشيء معلوم مضمون من آصع أو دراهم أو دنانير أو نحو ذلك، أو بجزء مشاع معلوم كالربع والثلث والنصف ونحو ذلك، هذا هو الذي يجوز. نعم.","link":"https://binbaz.org.sa/fatwas/6554/حكم-ايجار-الارض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_126/12608.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":8516,"question":"له سؤال ثانٍ أيضاً يقول فيه: كانت لي أخت قد ماتت من خمسة وعشرين سنة، وكانت مريضة ومرضها شديد، ولا يوجد عندنا أطباء، ولا يوجد ما يفيدها إلا أن الناس وصفوا لي بأن أعطيها شربة لتخفيف الألم الذي في بطنها، ثم أعطيتها الشربة، وبعد أيام توفيت من نفس المرض، وبعد سنين طائلة أخذت أوسوس ألا تكون هذه الشربة قد أثرت عليها وماتت بسببها، فهل علي ذنب، وهل علي كفارة؟","title":"حكم من شك أن قريبه مات بسبب العلاج الذي أعطاه","answer":"الجواب: دع عنك هذه الوساوس، هذه من الشيطان، مادامت الشربة في مصلحتها وقد وصفت لك، ووصفها من له خبرة بهذه المسائل، فهذه شربة أنت فيها محسن، ولا شيء عليك ولا حرج عليك وأنت مأجور، ودع عنك وساوس الشيطان التي يأتي بها إلى الناس فلا حرج عليك ولا إثم عليك وأنت محسن، ولا حول ولا قوة إلا بالله. نعم.","link":"https://binbaz.org.sa/fatwas/6595/حكم-من-شك-ان-قريبه-مات-بسبب-العلاج-الذي-اعطاه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_203/20312.mp3","categories":["الأذان والإقامة"]},{"id":8563,"question":"وأولى رسائل هذه الحلقة وردتنا من المستمع عبد الرحمن بن عبد الله بن سبتان من الدرعية، يقول في رسالته: أسمع كثيراً من المؤذنين في بعض إذاعات الدول الإسلامية يؤذنون أذاناً مختلفاً كالآتي، في بداية الأذان يكبر تكبيرتين فقط، بعد قوله: (حي على الفلاح، يقول: حي على خير العمل) مرتين فما حكم هذا الأذان؟ وهل ثبت عن أحد من الصحابة رضي الله عنهم؟","title":"حكم قول: (حي على خير العمل) في الأذان","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله أصحابه ومن اهتدى بهداه.\nأما بعد: فقد ثبت في الأحاديث الصحيحة عن رسول الله عليه الصلاة والسلام أن الأذان أربع تكبيرات في أوله، ولم يثبت عنه ﷺ أنه يقال فيه: حي على خير العمل، لم يقل هذا بلال ، ولا عبد الله بن أم مكتوم ، ولا أبو محذورة ولا غيره من مؤذنيه عليه الصلاة والسلام، وإنما هو مروي عن علي بن الحسين ويرويه بعضهم عن عبد الله بن عمر ولكنه ليس بثابت عن النبي ﷺ ولا عن مؤذنيه؛ ولهذا فالصواب في هذا أنه بدعة لا يجوز فعله؛ لأنه مخالف للأحاديث الصحيحة الثابتة عن رسول الله عليه الصلاة والسلام، وإنما الثابت أن يقول بعد حي على الصلاة حي على الفلاح: الله أكبر الله أكبر لا إله إلا الله.\nفالأذان خمسة عشر جملة: أربع تكبيرات في أوله، ثم الشهادتان أربع، ثم الحيعلة أربع، ثم الله أكبر الله أكبر، لا إله إلا الله، الجميع خمسة عشر، ومع الترجيع يكون تسعة عشر، والترجيع أن يأتي بالشهادتين بصوت منخفض ثم يأتي بهما بصوت مرتفع، كما في حديث أبي محذورة لما أذن بمكة حين علمه النبي ﷺ الأذان علمه فيه الترجيع، وفي الفجر يزاد فيه: الصلاة خير من النوم.. الصلاة خير من النوم أما (حي على خير العمل) فبدعة.\nالمقدم: ويقول الأخ عبد الرحمن بن سبتان في آخر رسالته، هل يبطل هذا الصلاة التي أذن لها هذا الأذان؟\nالشيخ: لا، لا يبطل الصلاة ولا يبطل الأذان، الأذان صحيح والكلمات الزائدة خطأ، فالأذان صحيح والصلاة صحيحة. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6640/حكم-قول-حي-على-خير-العمل-في-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_207/20701.mp3","categories":["الأذان والإقامة","البدع والمحدثات"]},{"id":8696,"question":"يلاحظ أن كثيراً من المؤذنين يمططون الأذان ويرجو التوجيه؟","title":"حكم التلحين والتمطيط في الأذان","answer":"الجواب: ينبغي للمؤمن في أذانه أن يكون سمحاً غير ممطط ولا متكلف، وهكذا في الإقامة، السنة في ذلك أن لا يلحن فيه وأن يحفظه أيضاً من اللحن لا يلحن ولا يلحن؛ اللحن: كونه يخل بالإعراب كأن يقول: أشهد أن محمداً رسول الله (بفتح اللام)، والمشروع أن يقول: أن محمداً رسول الله؛ لأن رسول الله خبر (أن) مرفوع، فهذا إذا نصب يكون من اللحن وإن كان لا يخل بالمعنى في الحقيقة؛ لأن مقصود المؤذن الإخبار بأنه رسول الله عليه الصلاة والسلام؛ ولأن بعض أهل اللغة ينصبون المعمولين، لكن هذا لحن عند جمهور أئمة اللغة وعند جمهور العرب، العرب ينصبون الاسم ويرفعون الخبر في (أن) كذلك من اللحن أن يقول مثلاً: (اهدنا الصراط المستقيم)؛ يكسرها، هذا غلط، لأنه مفعول منصوب (الصراط) لكن ما يخل بالمعنى، لا يخل بالمعنى، فلا يضر في الأذان أن يقول مثلاً: حي على الصلاة، أو حي على الصلاة ما يخل بالمعنى، لكن ينبغي له أن يكون فاهماً عربياً لا يلحن في الأذان، وأما التلحين هو تمطيطه كأنه يغني، هذا مكروه لا ينبغي. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6843/حكم-التلحين-والتمطيط-في-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_131/13103.mp3","categories":["الأذان والإقامة"]},{"id":8758,"question":"يقول: إنه يعمل خادم في مسجد ويستلم ألف وخمسين ريال، وهو لا يعمل في المسجد إلا أنه يعطي أحد الإخوة الباكستانيين مبلغ أربعمائة ريال؛ لينظف المسجد فما الحكم؟","title":"حكم من أوكل إليه عمل براتب واستأجر غيره ليقوم به","answer":"الجواب: لا بد من مراجعة الأوقاف، ومشاورة الأوقاف إذا سمحت لك الأوقاف بذلك فلا بأس، وإلا فالواجب عليك أن تباشر العمل وأن تتقي الله في ذلك حتى تستحل الأجرة؛ لأن الباكستاني قد لا يقوم بعملك وقد لا يحصل به المقصود، ولأن التساهل في هذا يفضي إلى شر كبير، من تعطيل المساجد وعدم تنظيفها وعدم العناية بها، أو تولية إنسان لا يصلح لسوء كلامه أو لسوء أعماله أو لعدم استقامته مع الإمام ومع أهل المسجد، فالحاصل أن هذا شيء فيه خطر فالواجب عليك أن تستشير مرجعك فإذا سمحوا لك بأن تستنيب فلان أو فلان بأجرة أو بغير أجرة فلا بأس.\nالمقدم: بارك الله فيكم وجزاكم الله خير!","link":"https://binbaz.org.sa/fatwas/6918/حكم-من-اوكل-اليه-عمل-براتب-واستاجر-غيره-ليقوم-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_217/21713.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":8866,"question":"أيضاً لاحظت عندما تقام الصلاة ويصل المؤذن إلى آخر كلمات الإقامة وهي: لا إله إلا الله أرى بعض المصلين يقبض أصابع يده اليمنى ويرفع السبابة، كذلك أثناء خطبة الجمعة أو أثناء حلقات العلم، إذا ردد الإمام أو الخطيب كلمة لا إله إلا الله أرى كثيراً من الناس يرفعون سبابة اليد اليمنى، فهل ورد ذلك عن الرسول ﷺ؟","title":"حكم رفع أصبع السبابة في آخر الأذان والإقامة","answer":"الجواب: لا أعلم شيئاً في هذا ولا أحفظ أنه ورد عنه شيئاً في هذا عليه الصلاة والسلام، وإنما ورد الإشارة بالسبابة في التشهدين؛ التشهد الأول والتشهد الأخير، كان يرفع سبابته عليه الصلاة والسلام إشارة للتوحيد، وأما بعد الفراغ من الذكر من الأذان أو من الإقامة فلا أحفظ شيئاً في هذا إلا أنه ﷺ شرع للناس أن يجيبوا المؤذن والمقيم وأن يقولوا بعد الأذان وبعد الإقامة يصلوا على النبي ﷺ، ثم يقول: اللهم رب هذه الدعوة التامة والصلاة والقائمة، آت محمداً الوسيلة والفضيلة وابعثه مقاماً محموداً الذي وعدتهوقال فيمن فرغ من الوضوء: من قال حين يفرغ من الوضوء: أشهد أن لا إله إلا الله وحده لا شريك له وأشهد أن محمداً عبده ورسوله، فتحت له أبواب الجنة الثمانية يدخل من أيها شاء زاد الترمذي رحمه الله: اللهم اجعلني من التوابين واجعلني من المتطهرين وهذا بإسناد صحيح، ويشرع أن يقول ذلك بعد الوضوء: أشهد أن لا إله إلا الله وحده لا شريك له وأشهد أن محمداً عبده ورسوله، اللهم اجعلني من التوابين واجعلني من المتطهرين.\nجاء في رواية: ثم يرفع نظره إلى السماء لكن لا أحفظ في شيء من الروايات الإشارة بالسبابة في هذا ولا بعد الإقامة ولا عند الدخول في الصلاة، إنما هذا في التشهدين، كان يشير بإصبعه السبابة في التشهد الأول والتشهد الأخير عليه الصلاة والسلام. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7021/حكم-رفع-اصبع-السبابة-في-اخر-الاذان-والاقامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_138/13804.mp3","categories":["الأذان والإقامة"]},{"id":8889,"question":"السؤال سماحة الشيخ عن الأذان في أذن المولود اليمنى والإقامة في أذنه اليسرى؟","title":"حكم الأذان والإقامة في أذني المولود","answer":"الجواب: هذا مشروع عند جمع من أهل العلم، وقد ورد فيه بعض الأحاديث وفي سندها مقال، فإذا فعله المؤمن فحسن؛ لأنه من باب السنن ومن باب التطوعات، والحديث في سنده عاصم بن عبيد الله بن عاصم بن عمر بن الخطاب وفيه ضعف وله شواهد، وقد فعل النبي ﷺ تسمية إبراهيم، ولم يحفظ عنه أنه أذن لما ولد له إبراهيم سماه إبراهيم، ولم يحفظ أنه أذن في أذنه اليمنى وأقام في اليسرى.\nوهكذا الأولاد الذين يؤتى بهم إليه من الأنصار ليحنكهم ويسميهم لم أقف على أنه أذن في أذن واحد منهم وأقام، ولكن إذا فعل ذلك المؤمن للأحاديث التي أشرنا إليها فلا بأس لأنه يشد بعضها بعضا، فالأمر في هذا واسع إن فعل فهو حسن لما جاء في الأحاديث التي يشد بعضها بعضًا وإن ترك فلا بأس. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7045/حكم-الاذان-والاقامة-في-اذني-المولود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_167/16705.mp3","categories":["الأذان والإقامة"]},{"id":8958,"question":"أخونا الطالب علي قاسم جبار غزوابي بمدرسة الجربة الابتدائية يقول: أرشدوني على طريقة أحفظ بها كتاب الله تعالى؟","title":"الطريقة المثلى لحفظ القرآن الكريم","answer":"الجواب: نوصيك بالعناية بالحفظ والإقبال على ذلك واختيار الأوقات المناسبة للتحفظ؛ كآخر الليل أو بعد صلاة الفجر، أو في أثناء الليل في الأوقات التي تكون فيها مرتاح النفس حتى تستطيع الحفظ.\nونوصيك أيضاً باختيار الزميل الطيب الذي يساعدك، الزميل الطيب يعينك على الحفظ والمذاكرة مع سؤال الله التوفيق والإعانة، تسأل ربك تضرع إليه أن يعينك وأن يوفقك، وأن يعيذك من أسباب قطع الطريق، ومن استعان بالله صادقاً أعانه الله ويسر أمره. نعم.","link":"https://binbaz.org.sa/fatwas/7116/الطريقة-المثلى-لحفظ-القران-الكريم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_145/14504.mp3","categories":["الأذان والإقامة"]},{"id":9038,"question":"تسأل أختنا وتقول: متى تكون ساعة الإجابة من يوم الجمعة، هل بين أذان الظهر الأول والثاني أم من صلاة العصر إلى أن يحين وقت أذان المغرب؟","title":"تحديد ساعة الإجابة في يوم الجمعة","answer":"الجواب: الجمعة كل ساعاتها مظنة الإجابة، كل ساعاتها مظنة الإجابة والنبي ﷺ أخبر أن فيها ساعة لا يرد فيها سائل وهي ساعة قليلة، فالمشروع للمؤمن والمؤمنة الإكثار من الدعاء يوم الجمعة من أوله إلى آخره، لكن أحرى الساعات وقتان، أحراها بالإجابة وقتان:\nأحدهما: حين يجلس الإمام يوم الجمعة للخطبة على المنبر إلى أن تقضى الصلاة، جاء فيها حديث رواه مسلم في الصحيح: أنها ما بين أن يجلس الإمام إلى أن تقضى الصلاة وقد أعله بعضهم بالوقف على أبي بردة ، والصواب: أنه متصل مرفوع، رواه مسلم في الصحيح.\nوالوقت الثاني: ما بين صلاة العصر إلى غروب الشمس جاء فيه أحاديث أيضًا، هذان الوقتان هما أرجى الساعات وأحراها بساعة الإجابة، ولكن مع ذلك يستحب الدعاء في جميع أوقات الجمعة حرصًا على هذه الساعة، نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7196/تحديد-ساعة-الاجابة-في-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_178/17803.mp3","categories":["الأذان والإقامة"]},{"id":9292,"question":"سؤاله الأخير، يقول: هل تجوز قراءة القرآن في السوق في الوقت الذي لا يكون لدي فيه عمل؟","title":"حكم قراءة القرآن في السوق","answer":"الجواب: لا بأس أن تقرأ القرآن في دكانك، أو في مبسطك أو في بقالتك إذا كنت فارغاً تقرأ ما تيسر من كتاب الله، أو تذكر الله، أو تصلي على رسول الله ﷺ، كل هذا طيب، عند وجود الفراغ تشتغل بذكر الله ، بقراءة القرآن، بالصلاة على الرسول ﷺ.. بمطالعة الكتب المفيدة، كل هذا طيب، كله طيب.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7462/حكم-قراءة-القران-في-السوق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_236/23606.mp3","categories":["الأذان والإقامة"]},{"id":9320,"question":"يسأل أيضاً ويقول: أنا رجل يغلب علي الوسواس في كثير من الأحيان، فعندما أريد أن أذهب من طريق يعارضني هذا الوسواس بأن الطريق من جهة أخرى، وعندما أريد أن آكل الطعام يوسوس لي الشيطان بأن هذا الطعام ليس بصالح، وأنه يضر مع أنني أخاف من النذر؛ لأنني أشك أن أنذر على نفسي، أرجو إرشادي وفقكم الله؟","title":"كيفية معالجة الوسواس","answer":"الجواب: الوساوس من الشيطان، كما قال الله جل وعلا: قُلْ أَعُوذُ بِرَبِّ النَّاسِ ۝ مَلِكِ النَّاسِ ۝ إِلَهِ النَّاسِ ۝ مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ [الناس:1-4] وهو الشيطان، فعليك -يا أخي- أن تتعوذ بالله منه، وأن تحذر مكائده، وتجزم في الأمور، إذا سلكت طريقاً فاجزم وامض فيه حتى تعلم يقيناً أن فيه شيئاً يضرك فاتركه، وهكذا الطعام إذا لم تعلم أنه محرم فكل ودع عنك الوساوس.\nوهكذا الوضوء إذا توضأت فاجزم ودع عنك أن توسوس فتقول: ما كملت، ما فعلت، امض، ما دام ترى أنك قد كملت فالحمد لله، وهكذا في صلاتك احذر الوساوس في كل شيء، واعلم أنها من الشيطان، وإذا وقع في نفسك شيء من ذلك فتعوذ بالله من الشيطان وامض في سبيلك واجزم على ذلك حتى ترغم عدوك الشيطان، وحتى لا يتمكن من التسلط عليك بسبب لينك معه، نعوذ بالله من شره ومكائده. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7482/كيفية-معالجة-الوسواس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_237/23702.mp3","categories":["الأذان والإقامة"]},{"id":9352,"question":"رسالة وصلت إلى البرنامج من الأخ جمال عبده أحمد صالح الشعبي أستاذ يمني في مدرسة الفوز بالشعابية ناحية الزهرة أخونا له خمسة أسئلة.سؤاله الأول: هل يسن الأذان في غير الصلاة كالأذان في أذن المولود وعند الحريق، وعند تزاحم الجيش، وعند المصروع، وعند الغضبان وغير ذلك، أفتونا جزاكم الله خير الجزاء؟","title":"ما المواضع التي يُشرع فيها الأذان؟","answer":"الجواب: أصل الأذان في الصلاة، الصلوات الخمس هذا هو الأصل والجمعة منها، ويشرع الأذان في أذن الصبي عند تسميته يوم السابع أو قبل أو بعد في اليمنى والإقامة في اليسرى، وإن سموه بدون ذلك فلا بأس ولكن الأفضل أن يؤذن في الأذن اليمنى ويقام في اليسرى.\nوهكذا الأذان عند رؤية الغيلان من الجن كما في الحديث: إذا تغولت الغيلان فبادروا بالأذان إذا رأى شيئًا من الجن فإنه يؤذن؛ لأن الأذان يطردها وذكر الله يطردها، والتكبير عند الحريق ما ورد الأذان إنما ورد التكبير عند الحريق، هذا هو الذي نعلم في هذا الأمر. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7517/ما-المواضع-التي-يشرع-فيها-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_185/18508.mp3","categories":["الأذان والإقامة"]},{"id":9444,"question":"يقول أيضاً في هذه الرسالة: أنا مستأجر لدكان، وقد اتفق معي رجل على أن أترك له الدكان مقابل خمسة آلاف جنيه برضا المالك، والذي زاده هذا المستأجر الجديد في الإيجار من مائة جنيه إلى مائة وخمسين شهرياً، فهل يجوز لي أن آخذ منه هذا المبلغ وهو يسمى عندنا: خلو رجل، أفيدونا أفادكم الله؟","title":"حكم اتفاق المستأجر الجديد مع القديم على ترك الدكان مقابل مبلغ","answer":"الجواب: هذا المبلغ لا أصل له ولا وجه له، ما دام المدة تمت فليس لك أخذها إلا إذا كانت هبة من المالك وسماحًا منه، أما أن تأخذها باسم أنها حق لك أو أنك يعني لا يمكن أن تدع الدكان إلا بهذا المبلغ، لا. لأنه لا حق لك فيه، إنما حقك في الدكان إذا بقيت المدة، فالمدة الباقية لك تؤجرها بما تشاء، أما بعد فراغ المدة فليس لك حق أن تأخذ شيئًا، وإنما التصرف لصاحب الملك هو الذي يتصرف يؤجره عليك أو على غيرك، ولو كانت الدولة جعلت هذا لك فالدولة لا تحل الحرام والناس أولى بأملاكهم، أصلح الله الجميع.\nالمقدم: بارك الله فيكم، يعني هذا المبلغ سماحة الشيخ لا يؤخذ من المالك؟\nالشيخ: لا يأخذه من المالك ولا من المستأجر.\nالمقدم: الجديد؟\nالشيخ: من الجديد، إذا كانت المدة قد تمت. نعم.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/7612/حكم-اتفاق-المستاجر-الجديد-مع-القديم-على-ترك-الدكان-مقابل-مبلغ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_255/25505.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":9472,"question":"يقول الأخ صالح أبو مروان: هل يجب أن يصلى على النبي ﷺ كل ما مر ذكره، أم أن ذلك سنة؟","title":"حكم الصلاة على النبي عليه الصلاة والسلام عند ذكره","answer":"الجواب: الواجب الصلاة عليه إذا مر ذكره عليه الصلاة والسلام؛ لما ثبت عنه عليه السلام قال: رغم أنف امرئ ذكرت عنده فلم يصل علي، فهذا يدل على أن الصلاة عليه واجبة عند ذكره عليه الصلاة والسلام. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7645/حكم-الصلاة-على-النبي-عليه-الصلاة-والسلام-عند-ذكره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_241/24108.mp3","categories":["الأذان والإقامة"]},{"id":9507,"question":"يقول أيضاً: ماذا عن الجهر بعد الأذان بالصلاة والسلام على رسول الله ﷺ بصوت كصوت الأذان، وإتباعه بقول المؤذن: يا أول خلق الله، وخاتم رسل الله، فهل يجوز رفع الصوت بهذا كما يرفع الصوت بالأذان، وهل الرسول ﷺ أول خلق الله؟","title":"حكم الجهر بالصلاة على النبي بعد الأذان وما يُقال معها","answer":"الجواب: وهذا أيضاً بدعة ومنكر، رفع الصوت بالصلاة على النبي صلى الله عليه وسلم مع الأذان منكر لا أصل له، ولم يفعله النبي ﷺ، ولا مؤذنوه، ولا الخلفاء الراشدون، ولا غيرهم من أهل العلم والإيمان، بل هذا مما ابتدعه الناس، وإنما السنة أن يصلي على النبي ﷺ بعد الأذان صلاة عادية بينه وبين نفسه يسمعها من حوله لا بأس، أما مع الأذان فلا، النبي ﷺ قال: إذا سمعتم المؤذن فقولوا مثلما يقول، ثم صلوا علي، فإن من صلى علي واحدة صلى الله عليه بها عشراً الحديث.\nفالسنة للمسلمين إذا سمعوا الأذان أن يجيبوا المؤذن، فإذا فرغوا من قول: (لا إله إلا الله) يصلون عليه عليه الصلاة والسلام، ثم يقول: اللهم رب هذه الدعوة التامة، والصلاة القائمة، آت محمداً الوسيلة والفضيلة، وابعثه مقاماً محموداً الذي وعدته، إنك لا تخلف الميعاد.\nأما أن يرفع الصوت بالصلاة على النبي ﷺ، أو بقراءة، أو بأي كلام مع الأذان فهذا بدعة، نهاية الأذان لا إله إلا الله، .... يغلق المكبر إن كان في مكبر، ثم يسكت المؤذن إن كان في غير مكبر، ثم يصلي على النبي ﷺصلاة عادية سراً بينه وبين نفسه، ولا مانع أن يسمعها من حوله.\nكذلك قوله: يا أول خلق الله، هذا لا أصل له، ليس الرسول أول خلق الله، بل قبله أمم، وأما حديث: (أنه أول خلق الله)، ما يروى (أنه أول خلق الله) فهو لا أصل له موضوع مكذوب على النبي صلى الله عليه وسلم، وهكذا قول بعضهم: إنه نور الله كذب، هو نور من النور الذي خلقه الله، جعله الله نوراً لتعليمه الناس وهدايته الناس وإرشاده الناس، لكن ليس من نور الله، وبعضهم يقول: يا نور عرش الله، كله باطل، ليس من نور الله، ولا من نور العرش، ولكن الله أعطاه نوراً بالوحي الذي جاءه، كما قال سبحانه: قَدْ جَاءَكُمْ مِنَ اللَّهِ نُورٌ وَكِتَابٌ مُبِينٌ [المائدة:15] وسماه جل وعلا سراجاً منيراً، فهو سراج منير وهو نور بما أعطاه الله من الوحي من القرآن والسنة، وليس من نور الله الذي هو وصفه سبحانه وتعالى، وليس من نور العرش، كل هذا باطل لا أصل له، وليس أول خلق الله، كله باطل. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7669/حكم-الجهر-بالصلاة-على-النبي-بعد-الاذان-وما-يقال-معها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_243/24303.mp3","categories":["الأذان والإقامة","البدع والمحدثات"]},{"id":9600,"question":"يسأل أيضاً ويقول: جملة: (الصلاة خير من النوم)، هل تقال في الأذان الأول قبل الفجر أم في الأذان الثاني؟ وما الدليل على قولها؟ وماذا يقول من سمعها بعد المؤذن أفيدونا بارك الله فيكم؟","title":"متى تُقال: (الصلاة خير من النوم)؟ وما جوابها؟","answer":"الجواب: السنة أن تقال في الأذان الأخير بعد طلوع الفجر؛ كما جاء ذلك في حديث أبي محذورة ، وجاء في حديث عائشة رضي الله عنها الدلالة على أن المؤذن كان يقولها في الأذان الأخير بعد طلوع الفجر، قالت: ثم يقوم النبي ﷺ فيصلي الركعتين ثم يخرج إلى الصلاة بعد الأذان الأول الذي هو الأذان الأخير بالنسبة إلى ما يسمى بالأذان الأول، فهو أذان أول بالنسبة إلى الإقامة؛ لأنه يقال لها: أذان، فالسنة أن يأتي بها في هذا الأذان الذي هو الأخير بعد طلوع الفجر وهو الأول بالنسبة إلى الإقامة، وأما الأول اللي في عرف الناس يسمونه: الأول فهذا للتنبيه، قال فيه النبي ﷺ: ليرجع قائمكم ويوقظ نائمكم فهو أذان للتنبيه، حتى يستيقظ النائم وحتى يرجع القائم، يعني: لا يطول الصلاة؛ لأن الفجر قد قرب.\nوقد صرح في حديث عائشة بتسمية الأذان الأخير أولاً مراعاةً للإقامة؛ لأنها أذان ثاني، وهو ثانٍ بالنسبة إلى الأول الذي يكون فيه التنبيه، وذهب بعض أهل العلم إلى أنه يقول هذا في الأول الذي هو محل التنبيه قبل طلوع الفجر، والأمر في هذا واسع إن شاء الله، لكن لا يقال فيهما جميعاً، فالأفضل أن يكون في الأخير الذي هو الأول بالنسبة إلى الإقامة، وهو الأذان الذي يكون بعد طلوع الفجر، (الصلاة خير من النوم)، والمراد بها الفريضة التي فرضها الله هي خير من النوم، والواجب على الناس أن يقوموا لها، أما النافلة في آخر الليل أو في أثناء الليل فليست واجبة، وقد يكون النوم أولى من الصلاة إذا كان نومه يغلبه في الصلاة، فإنه ينام حتى يأخذ حظه من النوم، وحتى يستطيع أن يصلي الصلاة على وجهها، ولكن صلاة الفرض أمر لازم وهي خير من النوم بكل حال، يجب عليه أن يقوم لها، وأن يتعاطى ما يعينه على ذلك حتى يؤديها بقلب حاضر وإتقان لها وإكمال لها، ويقول السامع له مثله: (الصلاة خير من النوم)؛ لقول النبي ﷺ: إذا سمعتم المؤذن فقولوا مثلما يقول فالمجيب يقول: الصلاة خير من النوم، مثلما يقول: الله أكبر، مثلما يقول: أشهد أن لا إله إلا الله، هذا مثله: الصلاة خير من النوم. أما حي على الصلاة حي على الفلاح، فإنه يقول: لا حول ولا قوة إلا بالله، هذا هو المشروع: كان النبي ﷺ إذا سمع المؤذن يقول: حي على الصلاة قال: لا حول ولا قوة إلا بالله، فإذا قال المؤذن: حي على الفلاح قال: لا حول ولا قوة إلا بالله لأن الإنسان ما يدري: هل يقوى أو ما يقوى؟ وهل ييسر له ذلك أم لا؟ فيقول: لا حول ولا قوة إلا بالله. فالمعنى: لا حول لي على إجابة المؤذن والحضور في المسجد وأداء الصلاة إلا بالله سبحانه وتعالى، ولا قوة على... إلا بالله سبحانه وتعالى، والمؤذن دعاه إلى الخير قال: حي على الصلاة حي على الفلاح، فعليه أن يجيب وعليه في هذا أن يقول: لا حول ولا قوة.. هذا المشروع له أن يقول: لا حول ولا قوة إلا بالله، يعني: لا حول لي ولا قوة لي على إجابة المؤذن، وعلى أداء الصلاة في وقتها مع الجماعة، وعلى كل شيء إلا بالله سبحانه وتعالى. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7775/متى-تقال-الصلاة-خير-من-النوم-وما-جوابها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_249/24905.mp3","categories":["الأذان والإقامة"]},{"id":9606,"question":"يسأل أيضاً ويقول: هل يكتفى بصلاة المرأة في بيتها بإقامة أو بأذان وإقامة؟ وكذلك الرجل إذا تأخر عن الصلاة وصلاها في بيته وفي غير وقتها أو في وقتها، هل تكفيه الإقامة أو لابد من الأذان والإقامة أفيدونا أفادكم الله؟","title":"حكم الأذان والإقامة للمنفرد من الرجال والنساء","answer":"الجواب: أما الرجل فتكفيه الإقامة؛ لأنه سمع النداء وأذن المسلمون فتكفيه الإقامة، وأما المرأة فليس عليها إقامة ولا أذان تصلي بدون إقامة ولا أذان. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7782/حكم-الاذان-والاقامة-للمنفرد-من-الرجال-والنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_249/24909.mp3","categories":["الأذان والإقامة"]},{"id":9624,"question":"لها سؤال آخر تقول فيه: أنا طالبة في المرحلة النهائية من الدراسة، وعندي انشغال بدروسي وأعمال البيت، لكن بنت الجيران تأتي إلي وتطلب مني أن أساعدها في الاستذكار فطردتها، فجاءت أمها فترجتني فطردتها أيضاً، وأخشى أن يكون علي إثم، أو أن هذا انتقاص من حقوق الجار، أفيدوني أفادكم الله؟","title":"الحث على الإحسان إلى الجار","answer":"الجواب: إذا استطعت أن تنفعي بنت جيرانك فذلك أفضل؛ لأن الجار له حق عظيم، يقول النبي ﷺ: ما زال جبريل يوصيني بالجار حتى ظننت أنه سيورثه ويقول عليه الصلاة والسلام: من كان يؤمن بالله واليوم الآخر فليحسن إلى جاره فالإحسان إليها بالتوجيه والتعليم والإرشاد من أكبر الإحسان ومن أعظم النعم، ومن أعظم الفوائد، فنوصيك بالإحسان إلى أخواتك في الله ولا سيما بنات الجيران في غير وقت الامتحان، ولكن في الوقت الذي يتيسر فيه التعليم والتوجيه في البيوت ونحوها، أما وقت الامتحان فهذا من باب الغش، ولكن في الأوقات الأخرى التي تستطيعين نفعهن فيها. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7790/الحث-على-الاحسان-الى-الجار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_250/25002.mp3","categories":["الأذان والإقامة"]},{"id":9674,"question":"الشيخ: السؤال الثاني؟ أما قول المؤذن قد قامت الصلاة؟","title":"ما المشروع في قول: (قد قامت الصلاة)؟","answer":"الجواب: أما قد قامت الصلاة فقد ثبت عن مؤذن النبي ﷺ وعن تعليمه قد قامت الصلاة مرتين، هذا هو الواجب (قد قامت الصلاة.. قد قامت الصلاة)؛ لأن الرسول ﷺ علم المؤذنين الأذان والإقامة، وكان في تعليمه ﷺ لهم أن تعاد الإقامة مرتين. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7847/ما-المشروع-في-قول-قد-قامت-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_252/25206.mp3","categories":["الأذان والإقامة"]},{"id":9746,"question":"أخيراً يقول: هل يؤذن لغير الصلوات الخمس المكتوبة كصلاة الضحى ونحوها؟","title":"حكم الأذان لغير الصلوات الخمس","answer":"الجواب: لا يؤذن إلا للخمس الصلوات فقط والجمعة، أما صلاة الضحى أو صلاة الاستسقاء أو صلاة العيد فليس لها أذان. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7915/حكم-الاذان-لغير-الصلوات-الخمس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_256/25606.mp3","categories":["الأذان والإقامة"]},{"id":9763,"question":"ما حكم الأذان والإقامة للنساء؟","title":"ما حكم الأذان والإقامة للنساء؟","answer":"الجواب: غير مشروعة لا يشرع للنساء الأذان ولا الإقامة؛ بل الأذان والإقامة مما يتعلق بالرجال، فالمرأة تصلي بدون أذان ولا إقامة هذا هو المشروع.\nالمقدم: جزاكم الله خيراً، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/7931/ما-حكم-الاذان-والاقامة-للنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_257/25705.mp3","categories":["الأذان والإقامة"]},{"id":9769,"question":"ما حكم الأذان والإقامة للنساء؟","title":"ما حكم الأذان والإقامة للنساء؟","answer":"الجواب: غير مشروعة لا يشرع للنساء الأذان ولا الإقامة؛ بل الأذان والإقامة مما يتعلق بالرجال، فالمرأة تصلي بدون أذان ولا إقامة هذا هو المشروع.\nالمقدم: جزاكم الله خيراً، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/7931/ما-حكم-الاذان-والاقامة-للنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_257/25705.mp3","categories":["الأذان والإقامة"]},{"id":9795,"question":"لها استفسار ثالث تقول فيه: في أيام الأعراس والأفراح يجتمع النساء ويعطون من يسمون بالدفافات نقودًا من أجل الرقص، هل هذا حرام أم لا؟","title":"حكم إعطاء النقود لمن يضربن على الدف","answer":"الجواب: لا حرج في هذا إن شاء الله لكن يكون قليل، ينبغي أن يكون قليلًا ليس فيه مباهاة ولا إسراف فلا حرج فيه؛ لأن هذا جرت به العادة والشعراء يعطون لكن ينبغي أن يكون قليلًا. نعم.","link":"https://binbaz.org.sa/fatwas/7962/حكم-اعطاء-النقود-لمن-يضربن-على-الدف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_196/19611.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":9817,"question":"يسأل ثانية ويقول: هل يجوز لرجل أن يذبح شاة ويجعل منها طعاماً ويتصدق منها وهو يريد بذلك براً لوالديه، أو ما يسمى بعشاء للوالدين، أفيدونا أفادكم الله؟","title":"حكم ذبح الشاة والتصدق بها عن الوالدين","answer":"الجواب: لا حرج في ذلك، إذا ذبح الإنسان شاة أو بقرة أو ناقة فأكل منها وتصدق عن نفسه وعن أهل بيته أو عن والديه أو عن غيرهما، كل هذا طيب لا بأس به، الصدقة باللحم والصدقة بالطعام والصدقة بالملابس والصدقة بالنقود كلها طيبة، كلها تنفع الميت بإجماع المسلمين، وتنفع الحي أيضاً، فإذا ذبح شاة أو بقرة أو بعيراً فأكل منه وادخر لبيته ما شاء الله، وعزم عليه من يحب من جيرانه وأقاربه، أو أعطاه الفقراء، كله طيب لا حرج في ذلك. نعم.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/7982/حكم-ذبح-الشاة-والتصدق-بها-عن-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_260/26003.mp3","categories":["الأذان والإقامة"]},{"id":9885,"question":"وهذه رسالة من عبدالله -عامل مصري الجنسية يعمل في الدرعية- يقول: عملت هنا سنة كاملة ثم سافرت إلى بلدي، فوجدت واحداً من إخواني مريض جداً فجلست بجواره وصرفت عليه جميع ما كان معي من مال، ما يقارب ثلاثة آلاف جنيه مصري، علماً بأن لي أخوان آخران طلبت منهم مساعدتي فرفضوا، وكذلك والدي متوفى ووالدتي على قيد الحياة وتملك قطعة أرض وبعض من المال وطلبت منها أن تساعدني فرفضت، مع العلم أن لي أولاد وزوجة وأصرف عليهم، فسؤالي: لو تركت المبلغ لأخي بدون مقابل: هل علي إثم، علماً بأن أولادي محتاجين لهذا المبلغ؟ أفيدوني بارك الله فيكم.","title":"فضائل الإنفاق على الأرحام","answer":"الجواب: أما إنفاقك على أخيك المريض وعنايتك به فهذا أمر طيب مشروع وصلة رحم، وأنت مأجور وأبشر بالخلف والأجر من الله ، لكن إذا كان أولادك في حاجة وزوجتك في حاجة فالواجب عليك أن تبدأ بهم وبحاجتهم، وأما أخوك المريض فعليك أنت والوالدة وإخوانك التعاون في هذا، في شأنه وفي الإنفاق عليه.\nأما إذا كنت تستطيع أن تنفق عليه وعلى أولادك فلك الأجر، وأنت حينئذ تكون غلبتهم في الأجر، وحصلت الخير العظيم، فعليك أن تنظر في الأمر، فإذا كنت تستطيع الإنفاق على أخيك المريض وعلى أولادك فافعل وأبشر بالخير، ولو تأخر إخوانك عن مساعدتك، ولو تأخرت أمك كذلك يكون لك الأجر كله، وأنت على خير عظيم، يقول النبي ﷺ: من أحب أن يبسط له في رزقه، وأن ينسأ له في أجله فليصل رحمه وهذا من صلة الرحم، وأنت في هذا مشكور على عملك، وسوف يعوضك الله عما فعلت خيراً كثيراً مع صلاح النية، فاستقم وأبشر بالخير، واجتهد في الإنفاق على أولادك حاجتهم، وعلى أخيك حسب الطاقة والإمكان، ولو بالقرض ولو بالدين، بالاستدانة من بعض المحبين وسوف يوفي الله عنك، يقول النبي ﷺ: من أخذ أموال الناس يريد أداءها أدى الله عنه، ومن أخذها يريد إتلافها الله فأنت إذا اقترضت من بعض إخوانك، أو استدنت من بعض إخوانك من أجل الإنفاق على أخيك المريض وعلى أولادك، فالله سبحانه سوف يعينك ويسهل أمرك، ويوفي عنك ، فاستقم وأحسن الظن بمولاك جل وعلا، وأنفق على أخيك وعلى أولادك، وادع الله للوالدة بالخير والتوفيق، وادع الله لأخويك بالتوفيق والهداية، واستعن بربك في كل خير.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8050/فضاىل-الانفاق-على-الارحام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_264/26407.mp3","categories":["الأذان والإقامة"]},{"id":9948,"question":"يسأل أيضاً صاحبنا هذا ويقول: هل يجوز للمرأة فعل الأذان والإقامة للصلاة أم لا؟","title":"هل يجوز للمرأة الأذان والإقامة للصلاة أم لا؟","answer":"الجواب: لا يشرع للمرأة أن تؤذن أو تقيم في صلاتها إنما هذا من شأن الرجال، أما النساء فلا يشرع لهن أذان ولا إقامة بل يصلين بدون أذان ولا إقامة، وعليهن العناية بالوقت والخشوع وعدم العبث في الصلاة، كالرجل، عليها أن تخشع وأن تطرح بصرها إلى موضع سجودها وأن تبتعد عن العبث لا بالأيدي ولا بغيرها، هكذا السنة للمؤمن في صلاته وللمؤمنة كذلك.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8113/هل-يجوز-للمراة-الاذان-والاقامة-للصلاة-ام-لا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_267/26705.mp3","categories":["الأذان والإقامة"]},{"id":10026,"question":"تقول أني أخيط الملابس النسائية والأقمشة المختلفة منها الشفاف الخفيف ومنها غير ذلك، والنساء التي يأتينني آراؤهن مختلفة في لبس الملابس، منهن من يلبس القصير ومنهن غير ذلك، وإنني أنصحهن على ذلك ومنهن من يستمع ومنهن من يصر، وإني أخاف أن يكون كسبي من خياطة هذه الملابس للناس الذين لا يخافون الله حرامًا، أرشدوني جزاكم الله خيرًا؟","title":"حكم خياطة الملابس النسائية التي ليست ساترة","answer":"الجواب: الذي يصر على لبس القصير لا تخيطين له شيء لا تعينه على المعصية والذي يقبل النصيحة ويقول: إنه يمتثل فلا مانع، والشفاف يبين لهن أن الشفاف لا يجوز لبسه وحده، لكن إذا كانت تلبسه فوق الساتر فلا بأس، فعليك أن تعينيهن على الخير وأن تنصحيهن وأن تمنعيهن من الشر، ولو بالكلام والنصيحة والذي لا يمتثل وتعلمين أنه يلبس القصير أو الشفاف الذي لا يستر وحده دون أن يكون تحته ساتر لا تعينينه على ذلك لا تعينيه ولا تخيطي له لأن الله يقول سبحانه: وَلا تَعَاوَنُوا عَلَى الإِثْمِ وَالْعُدْوَانِ [المائدة:2] فالواجب على المسلمين التعاون على البر والتقوى وأن لا يتعاونوا على الإثم والعدوان، فكل امرأة تعرفين عنها لبس القصير فلا تخيطين لها القصير، وكل امرأة تعرفين عنها أنه تلبس الشفاف وليس تحته ساتر لا تعينيها على ذلك وانصحيها وعلميها وامتنعي من مساعدتها وأبشري بالخير، سوف يعوضك الله خيرًا منهن وسوف يأتي الله لك برزق طيب تعويضًا لك عما فعلت من الخير، لأنه سبحانه يقول: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:2-3].\nويقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] فعليك أن تتقي الله وأن لا تساعدي النساء اللاتي يتعمدن المعصية لا في اللباس ولا في غيره. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8194/حكم-خياطة-الملابس-النساىية-التي-ليست-ساترة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_332/33206.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":10063,"question":"إحدى الأخوات المستمعات بعثت برسالة وقعت في نهايتها تقول: مقيمة في السعودية (ن. ع. د) أختنا لها جمع من الأسئلة في أحدها سؤال معناه: كيف أبر والدي حتى أدخل بسببهما الجنة؟","title":"كيفية بر الوالدين في حياتهما وبعد موتهما","answer":"الجواب: برهما بالإحسان إليهما في حياتهما بطاعتهما في المعروف والإحسان إليهما بالنفقة والكلام الطيب والسمع والطاعة في المعروف، وبعد الموت بالصدقة عنهما وبالدعاء لهما إذا كانا مسلمين. هذا من البر الذي يسبب الدخول إلى الجنة في حياتهما بالإحسان إليهما والرفق بهما والكلام الطيب معهما ومساعدتهما في حاجتهما والإنفاق عليهما إذا كانا محتاجين، وغير هذا من وجوه الخير حتى يرضيا عن ولدهما، والسمع والطاعة لهما في المعروف لا في المعاصي، وبعد الموت بالدعاء لهما والترحم عليهما وبالاستغفار لهما وصلاة الجنازة عليهما وإكرام صديقهما وصلة أرحامهما، سئل النبي ﷺ قال له رجل: يا رسول الله! هل بقي من بر أبوي شيء أبرهما به بعد الموت قال: نعم، الصلاة عليهما والاستغفار لهما وإنفاذ عهدهما من بعدهما -أي: وصيته الوصية الشرعية- وإكرام صديقهما وصلة الرحم التي لا توصل إلا بهما كل هذا من برهما بعد الموت، فإن فعل الولد هذا بعد الموت وفعل الفعل الطيب معهما في الحياة فهو على خير عظيم. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8217/كيفية-بر-الوالدين-في-حياتهما-وبعد-موتهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_303/30302.mp3","categories":["الأذان والإقامة"]},{"id":10086,"question":"مستمع رمز إلى اسمه بالحروف (م. ج) يسأل ويقول: هل للجمعة أذان واحد أم أذانان؟ وهل بينهما سنة قبلية للجمعة؟","title":"حكم الأذان الأول والثاني للجمعة","answer":"الجواب: الجمعة لها أذان واحد، هذا هو الأصل، وهذا هو المفترض عند دخول الخطيب وهو الواقع في عهد النبي ﷺ، كان إذا دخل الخطيب أذن بلال ، ثم زاد عثمان أذانًا ثانيًا مستحب لتنبيه الناس على أن اليوم يوم الجمعة قبل الأذان الأول، يعني قبل الأذان السابق الذي عند دخول الخطيب يأذن به قبل الوقت بنص ساعة أو نحوها أو ساعة؛ حتى يعلم الناس الجمعة، وحتى يستعدوا للمجيء، وقد درج السلف على هذا تأسيًا بـعثمان  في عهد عثمان وفي عهد علي وعهد الصحابة بعد عثمان ، ثم درج عليه السلف الصالح، فهذا مشروع من عمل الخلفاء الراشدين، والرسول عليه السلام قال: عليكم بسنتي وسنة الخلفاء الراشدين المهديين من بعدي، ومعلوم أن عثمان رضي الله عنه وعليًّا رضي الله عنه كلهم من الخلفاء الراشدين.\nفالسنة أن يؤتى بأذان أول للجمعة؛ للتنبيه، كما فعل عثمان ومن بعده ، أما الأذان الأول الذي عند دخول الخطيب فهذا هو الموجود في عهد النبي ﷺ وهو المفترض. نعم.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8255/حكم-الاذان-الاول-والثاني-للجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_276/27614.mp3","categories":["الأذان والإقامة","صلاة الجمعة"]},{"id":10118,"question":"المستمع (س. ع) بعث يسأل ويقول: هل لي أن أستلم مكافأة مقدارها ثلاثمائة ريال شهريًا مقابل كفالة أحد العمال ليبقى عاملًا في المملكة عند غيري؟","title":"حكم استقدام العمال وأخذ مبلغ شهري مقابل الكفالة","answer":"الجواب: ليس لك ذلك، وإنما تستقدمه بأجرة معلومة شهرية حتى يعمل عندك أو عند غيرك ممن اتفقت معهم بأجر معلوم تعطيه إياه كل شهر، وأما أن يعطيك دراهم عن كفالته فلا. وقد نظر مجلس هيئة كبار العلماء في ذلك وقرر أنه لا يجوز استقدامهم إلا على الطريقة التي رسمتها الدولة، الطريقة التي قررتها الدولة وأقرتها ولا يجوز استقدامهم على الطرق الأخرى لما في ذلك من الفساد والشر على الناس، فإذا أراد عاملًا يستقدمه على الطريقة التي رسمتها الدولة وبينتها الدولة وهو أن يستقدمه بأجر معلوم شهري أو يومي أو سنوي على أنه يعمل كذا بمزرعته في بناء في كذا..في عمل معلوم. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8288/حكم-استقدام-العمال-واخذ-مبلغ-شهري-مقابل-الكفالة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_334/33406.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":10129,"question":"المستمعة (ل. ع. ع) من جمهورية مصر العربية ومقيمة في الدمام، بعثت تسأل وتقول: هل يجوز الاستماع إلى القرآن الكريم وأنا أعمل في البيت في المطبخ مثلاً، مع العلم أنني أركز مع القراءة وأستمع جيداً؟","title":"حكم استماع القرآن أثناء تأدية أعمال البيت","answer":"الجواب: نعم لا بأس بل هذا طيب ما دمت تستمعين في المطبخ أو في أي مكان غير الحمام، لا بأس، جمعاً بين المصلحتين بين سماع القرآن الكريم وبين العمل الذي تقومين به مما شرع الله لك وأمرك به، فأنت على خير عظيم في المجلس عند القهوة في المطبخ لا بأس بذلك، بل هذا طيب ما دمت تستمعين له تنصتين له. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8299/حكم-استماع-القران-اثناء-تادية-اعمال-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_305/30505.mp3","categories":["الأذان والإقامة"]},{"id":10186,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول (و. ع. أ) هذه الرسالة مشتملة على جمع من الأسئلة من بينها سؤال يقول: أنا والحمد لله أحب أن أصلي الصلاة في وقتها، إذا أذن المؤذن ولم أتمكن من الذهاب إلى المسجد هل أصلي بعد الأذان مباشرة أم بعد الإقامة؟","title":"وقت الصلاة يدخل بالأذان لا الإقامة","answer":"الجواب: الواجب عليك الذهاب إلى المسجد إذا كنت سليماً، وأما إذا كان هناك علة لمرض أو ممنوع من الخروج من بيتك كالسجين أو ما أشبه ذلك فإنك تصلي بعد الأذان، وليس لك تعلق بالإمامة والإقامة، تصلي إذا دخل الوقت سواء قبل الناس أو بعد الناس، لست مربوطاً بإقامة الصلاة، بل تصلي قبلهم أو بعدهم، إذا كنت عاجزاً عن الذهاب إلى المسجد لمرض أو نحوه، أما إذا كنت قادراً فالواجب عليك أن تجيب المؤذن وأن تصلي مع المسلمين؛ لقول النبي ﷺ: من سمع النداء فلم يأت فلا صلاة له إلا من عذر ولأنه ﷺ لما جاءه رجل أعمى قال: يا رسول الله! ليس لي قائد يقودني إلى المسجد، فهل لي من رخصة أن أصلي في بيتي؟ أجابه ﷺ بقوله: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب رواه مسلم في صحيحه، وفي رواية أخرى لغير مسلم: لا أجد لك رخصة فإذا كان الأعمى الذي ليس له قائد يلائمه ليس له رخصة فكيف بغيره؟! فالواجب عليك يا أخي أن تحرص على الصلاة في الجماعة، وإذا كنت معذوراً عذراً شرعياً فأنت بحمد الله تصلي إن شئت قبلهم أو بعدهم لا حرج عليك.","link":"https://binbaz.org.sa/fatwas/8376/وقت-الصلاة-يدخل-بالاذان-لا-الاقامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_309/30915.mp3","categories":["الأذان والإقامة","وقت الصلاة"]},{"id":10189,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول (و. ع. أ) هذه الرسالة مشتملة على جمع من الأسئلة من بينها سؤال يقول: أنا والحمد لله أحب أن أصلي الصلاة في وقتها، إذا أذن المؤذن ولم أتمكن من الذهاب إلى المسجد هل أصلي بعد الأذان مباشرة أم بعد الإقامة؟","title":"وقت الصلاة يدخل بالأذان لا الإقامة","answer":"الجواب: الواجب عليك الذهاب إلى المسجد إذا كنت سليماً، وأما إذا كان هناك علة لمرض أو ممنوع من الخروج من بيتك كالسجين أو ما أشبه ذلك فإنك تصلي بعد الأذان، وليس لك تعلق بالإمامة والإقامة، تصلي إذا دخل الوقت سواء قبل الناس أو بعد الناس، لست مربوطاً بإقامة الصلاة، بل تصلي قبلهم أو بعدهم، إذا كنت عاجزاً عن الذهاب إلى المسجد لمرض أو نحوه، أما إذا كنت قادراً فالواجب عليك أن تجيب المؤذن وأن تصلي مع المسلمين؛ لقول النبي ﷺ: من سمع النداء فلم يأت فلا صلاة له إلا من عذر ولأنه ﷺ لما جاءه رجل أعمى قال: يا رسول الله! ليس لي قائد يقودني إلى المسجد، فهل لي من رخصة أن أصلي في بيتي؟ أجابه ﷺ بقوله: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب رواه مسلم في صحيحه، وفي رواية أخرى لغير مسلم: لا أجد لك رخصة فإذا كان الأعمى الذي ليس له قائد يلائمه ليس له رخصة فكيف بغيره؟! فالواجب عليك يا أخي أن تحرص على الصلاة في الجماعة، وإذا كنت معذوراً عذراً شرعياً فأنت بحمد الله تصلي إن شئت قبلهم أو بعدهم لا حرج عليك.","link":"https://binbaz.org.sa/fatwas/8376/وقت-الصلاة-يدخل-بالاذان-لا-الاقامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_309/30915.mp3","categories":["الأذان والإقامة","وقت الصلاة"]},{"id":10192,"question":"مستمع رمز إلى اسمه بالحروف (م. ض. ش) يقول: أنا مؤذن، والآن أنَبْتُ ابني عني في الأذان وأنا الذي أستلم الراتب، فهل يجوز هذا؟","title":"حكم الإنابة في الأذان","answer":"الجواب: إذا كانت الجهة المسئولة التي أنت ترجع إليها ترضى بهذا فلا مانع من ذلك، وكان ولدك يصلح لذلك، عدلاً يقيم الأذان، فإذا كان ولدك يقيم الأذان ويصلح لهذا الأمر، والجهة المسئولة التي وظفتك ترضى بذلك فلا بأس.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8372/حكم-الانابة-في-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_309/30912.mp3","categories":["الأذان والإقامة"]},{"id":10293,"question":"إحدى المستمعات بعثت برسالة من المكلا في حضرموت تقول: (خ. ح. العكبري )، ملاحظة: مقدمة في رسالتها تقول: نرجو منكم أن تبلغوا سماحة الشيخ عبد العزيز بن باز حبنا له في الله عز وجل، كما أرجو أن يدعو لنا بالهداية والثبات، ثم تسأل سماحة الشيخ وتقول: فتاة والدها مدين للناس، وهذه الفتاة أحياناً تعمل وتخيط وتحصل على بعض النقود وتنفقها في وجوه الخير، وتتصدق ببعضها للمساكين والمحتاجين، فهل لها الحق أن تتصدق بفلوسها وتتصرف بها كيف تشاء، أم أن هناك مانع من تصرفها بفلوسها؛ لأن والدها مدين وهي لا تستطيع أن تسدد دين والدها، نرجو الإفادة جزاكم الله خيراً؟","title":"هل قضاء دين الوالد أولى من بقية وجوه الخير؟","answer":"الجواب: أولاً نقول: أحبك الله الذي أحببتينا له سبحانه وتعالى، ونسأل الله أن يوفقنا جميعاً لما يرضيه، وأن يصلح أحوالنا جميعاً، وأن يجعلنا وإياكم من الهداة المهتدين، ومن الصالحين المصلحين، نسأله سبحانه أن يصلح أحوال المسلمين جميعاً في اليمن وغيره، وأن يثبتنا جميعاً على دينه، وأن يمنح المسلمين جميعاً في كل مكان الفقه في الدين والثبات عليه والاستقامة على ذلك.\nأما هذه الفتاة فإن عملها طيب، ولكن كونها تساعد أباها في قضاء دينه أولى وأنفع؛ لأن بره من أهم المهمات؛ ولأن مساعدته في قضاء دينه من أهم المهمات، فكونها تساعده في قضاء دينه مما كسبت يدها بالخياطة أو غيرها، هذا مقدم على الصدقة على غيره؛ لأنه يجمع بين البر وبين إعانته على قضاء الدين، فأنا أنصحها وأوصيها بأن تساعد أباها مما يسر الله لها في قضاء دينه؛ لأن في ذلك مصلحتين عظيمتين: إحداهما: برها لوالدها، والثانية: مساعدته في قضاء دينه الذي يشق عليه قضاؤه.\nأما إن كان والدها يستطيع قضاء الدين ولكنه متساهل فلا حاجة إلى ذلك تصدق وتحسن والحمد لله وهو يقضي دينه مما أعطاه الله من المال، لكن إذا كان معسراً ومحتاجاً فكونها تساعده وتعطيه من مالها أولى، كونك تساعدين والدك وتعطينه مما يسر الله لك هو أولى من غيره من الفقراء الأباعد، يسر الله أمرك وأمره، وأصلح حال الجميع.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8463/هل-قضاء-دين-الوالد-اولى-من-بقية-وجوه-الخير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_312/31203.mp3","categories":["الأذان والإقامة"]},{"id":10298,"question":"إحدى المستمعات بعثت برسالة من المكلا في حضرموت تقول: (خ. ح. العكبري )، ملاحظة: مقدمة في رسالتها تقول: نرجو منكم أن تبلغوا سماحة الشيخ عبد العزيز بن باز حبنا له في الله عز وجل، كما أرجو أن يدعو لنا بالهداية والثبات، ثم تسأل سماحة الشيخ وتقول: فتاة والدها مدين للناس، وهذه الفتاة أحياناً تعمل وتخيط وتحصل على بعض النقود وتنفقها في وجوه الخير، وتتصدق ببعضها للمساكين والمحتاجين، فهل لها الحق أن تتصدق بفلوسها وتتصرف بها كيف تشاء، أم أن هناك مانع من تصرفها بفلوسها؛ لأن والدها مدين وهي لا تستطيع أن تسدد دين والدها، نرجو الإفادة جزاكم الله خيراً؟","title":"هل قضاء دين الوالد أولى من بقية وجوه الخير؟","answer":"الجواب: أولاً نقول: أحبك الله الذي أحببتينا له سبحانه وتعالى، ونسأل الله أن يوفقنا جميعاً لما يرضيه، وأن يصلح أحوالنا جميعاً، وأن يجعلنا وإياكم من الهداة المهتدين، ومن الصالحين المصلحين، نسأله سبحانه أن يصلح أحوال المسلمين جميعاً في اليمن وغيره، وأن يثبتنا جميعاً على دينه، وأن يمنح المسلمين جميعاً في كل مكان الفقه في الدين والثبات عليه والاستقامة على ذلك.\nأما هذه الفتاة فإن عملها طيب، ولكن كونها تساعد أباها في قضاء دينه أولى وأنفع؛ لأن بره من أهم المهمات؛ ولأن مساعدته في قضاء دينه من أهم المهمات، فكونها تساعده في قضاء دينه مما كسبت يدها بالخياطة أو غيرها، هذا مقدم على الصدقة على غيره؛ لأنه يجمع بين البر وبين إعانته على قضاء الدين، فأنا أنصحها وأوصيها بأن تساعد أباها مما يسر الله لها في قضاء دينه؛ لأن في ذلك مصلحتين عظيمتين: إحداهما: برها لوالدها، والثانية: مساعدته في قضاء دينه الذي يشق عليه قضاؤه.\nأما إن كان والدها يستطيع قضاء الدين ولكنه متساهل فلا حاجة إلى ذلك تصدق وتحسن والحمد لله وهو يقضي دينه مما أعطاه الله من المال، لكن إذا كان معسراً ومحتاجاً فكونها تساعده وتعطيه من مالها أولى، كونك تساعدين والدك وتعطينه مما يسر الله لك هو أولى من غيره من الفقراء الأباعد، يسر الله أمرك وأمره، وأصلح حال الجميع.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8463/هل-قضاء-دين-الوالد-اولى-من-بقية-وجوه-الخير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_312/31203.mp3","categories":["الأذان والإقامة"]},{"id":10435,"question":"من المستمع علي حسين من العراق رسالة وضمنها جمعاً من الأسئلة في أحدها يقول: بالنسبة لقراءة القرآن ما هو الوقت المفضل لتلاوته؟ وما هو عدد الآيات التي تقرأ في كل مرة، جزاكم الله خيراً؟","title":"أفضل وقت لقراءة القرآن","answer":"الجواب: ليس لهذا حد محدود، بل الأنسب والأفضل للمؤمن أن يتحرى الأوقات التي تناسبه هو يكون فيها قلبه حاضراً ويكون فارغاً يستطيع التدبر والتعقل، وإذا تيسر له وقت يناسبه في الليل أو النهار فعل ذلك؛ لأن الناس يختلفون في هذه المسائل، فمن كان له وقت من النهار يناسبه فعل ذلك، ومن كان في الليل كذلك، والغالب أن الناس يختلفون في أوقاتهم، ومن كانت أوقاته ميسرة له فالليل أفضل؛ لأنه أجمع للقلوب، كما قال تعالى: إِنَّ نَاشِئَةَ اللَّيْلِ هِيَ أَشَدُّ وَطْئًا وَأَقْوَمُ قِيلًا [المزمل:6].\nفالليل أجمع للقلب إذا درس فيه أو تحفظ فيه، وهكذا بعد صلاة الفجر قبل أن يشتغل بأمور الدنيا وقت مناسب، لكن إذا كان له مشاغل فلينظر الوقت المناسب له الذي يكون فيه أفرغ من غيره ويكون فيه أجمع لقلبه حتى يقرأ قراءة قد أقبل عليها واستحضرها وجمع قلبه فيها لا في الحفظ ولا في القراءة التي تستمر ويتلوها لطلب الأجر، فليخص الوقت المناسب الذي يكون فيه قلبه حاضراً وشغله قليلاً. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8621/افضل-وقت-لقراءة-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_318/31812.mp3","categories":["الأذان والإقامة"]},{"id":10438,"question":"أسأل سماحة الشيخ لو تكرمتم: هل القراءة بين الأذان وبين الإقامة، أم يستحسن أن تسبق الأذان؟","title":"فضل الدعاء بين الأذان والإقامة والتبكير إلى المسجد","answer":"الجواب: كله خير كله طيب، فإن قرأ بين الأذان والإقامة فلا بأس وإن تحرى الدعاء وترك القراءة فلا بأس؛ لأن الدعاء بين الأذان والإقامة ترجى إجابته كما في الحديث: الدعاء بين الأذان والإقامة لا يرد، فإذا خص هذه الجلسة بالدعاء بين الأذان والإقامة دعوات جامعة فهذا طيب وترجى إجابته لقوله ﷺ: الدعاء بين الأذان والإقامة لا يرد، وإن اشتغل بالقراءة على وجه لا يؤذي من حوله من المصلين أو القراء قراءة هادئة لا يتأذى بها من حوله ولا يشوش على من حوله فكل ذلك حسن والحمد لله، وإن بكر وقرأ قبل الأذان حصل فضل له المسابقة والتبكير للصلاة، فيكون له أجر المسابقة وأجر التبكير ويحصل له مزيد من الفضل في انتظار الصلاة وفي قراءة القرآن، كل هذا لهو خير عظيم وفضل عظيم. نعم.","link":"https://binbaz.org.sa/fatwas/8622/فضل-الدعاء-بين-الاذان-والاقامة-والتبكير-الى-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_318/31813.mp3","categories":["الأذان والإقامة"]},{"id":10507,"question":"من جدة رسالة بعث بها مستمع رمز إلى اسمه بالحروف (ص. أ) يقول: هل هناك حديث عن فضل قراءة سورة الكهف؟","title":"فضل قراءة سورة الكهف","answer":"الجواب: فيه حديث موقوف كان بعض الصحابة يقرؤها يوم الجمعة، وأما المرفوع ضعيف، لكن فيها موقوف عن بعض الصحابة وهذا في حكم الرفع؛ لأن الصحابي إذا حافظ عليها يدل على أنه سمع فيها شيء عن النبي ﷺ. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8682/فضل-قراءة-سورة-الكهف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_282/28215.mp3","categories":["الأذان والإقامة"]},{"id":10544,"question":"هذا سائل أرسل بهذا السؤال لم يذكر الاسم في هذه الرسالة يقول سماحة الشيخ: أنا أعرف صاحب مؤسسة لديه الكثير من العمال قد يصل عددهم إلى خمسة عشر عامل، وهو لا يقوم بصرف المرتب لهم، مع العلم بأنه لم يصرف لهم المرتب منذ سبعة أشهر، وكذلك لا يعطيهم الإعاشة كاملة، وهم في حالة يرثى لها، فنرجو من سماحة الشيخ النصح لمثل هذا؟","title":"حكم من يستقدم عمالاً ولا يعطيهم حقوقهم أو يأخذ أموالاً لكفالتهم","answer":"الجواب: الواجب على المسلمين العناية بالعمال وإعطاؤهم حقوقهم وإعاشتهم ولا يجوز لهم التساهل في هذا، هذا منكر وظلم، بل يجب على صاحب العمال الذين استأجرهم أن يعطيهم حقوقهم حسب الشروط، إن كانت تقدم كل شهر وجب تقديمها كل شهر، وإن كان بينه وبينهم على شهرين شهرين وهكذا على الشروط اللي بينهم، مع الإعاشة المشروطة لا يخل بها، هذا هو الواجب: والظلم ظلمات يوم القيامة : كل المسلم على المسلم حرام دمه وماله وعرضه وفي الحديث الصحيح يقول النبي ﷺ: يقول الله جل وعلا: ثلاثة أنا خصمهم يوم القيامة: رجل أعطى بي ثم غدر، ورجل باع حرًا فأكل ثمنه، ورجل استأجر أجيرًا فاستوفى منه ولم يعطه أجره هذا من المنكرات العظيمة.\nفالواجب الحذر وألا يكلفهم ما لا يطيقون، وألا يؤجل حقوقهم، بل يجب أن يعطيهم حقوقهم حسب الشروط، نعم.\nالمقدم: سماحة الشيخ! أولئك الذين يأتون بالعمال ويأخذون منهم مبالغ مالية كل شهر ويتركونهم يسرحون ويمرحون، ما حكم هذه النقود التي يأخذونها، الذي يأخذها الكفيل وغيره؟\nالشيخ: لا يجوز هذا العمل، وقد صدر قرار من هيئة كبار العلماء بمنع هذا، وأن الواجب استقدامهم على الطريقة التي رسمتها الدولة، أما أن يستقدمهم ..... يجعلهم بين الناس يعملون، ويأخذ منهم كل شهر كذا وكذا من أجل كفالته فهذا لا يجوز، الواجب على المؤمن أن يستقدم حاجته فقط هو، على حسب الشروط التي نظرتها الدولة.","link":"https://binbaz.org.sa/fatwas/8719/حكم-من-يستقدم-عمالا-ولا-يعطيهم-حقوقهم-او-ياخذ-اموالا-لكفالتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_284/28416.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":10551,"question":"من اليمن المستمع صلاح محسن محمد بعث يسأل ويقول: هل يشرع للمرأة الأذان، وهل تشرع لها الإقامة؟ وضحوا لنا ذلك جزاكم الله خيرًا؟","title":"هل الأذان والإقامة من خصائص الرجال؟","answer":"الجواب: الأذان والإقامة من خصائص الرجال، أما المرأة فهي تصلي بدون أذان ولا إقامة ولم يرد في الشرع أنها تؤذن ولا تقيم، وإنما هذا للرجال فقط. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8722/هل-الاذان-والاقامة-من-خصاىص-الرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_321/32103.mp3","categories":["الأذان والإقامة"]},{"id":10567,"question":"من منطقة جيزان، المستمع ناصر أحمد هادي بعث برسالة وضمنها بعض الأسئلة، في أحد أسئلته يقول: لدي أرحام يسكنون بعيداً عن البلد الذي أسكن فيه، ولا أستطيع السفر إليهم لزيارتهم، فهل في ذلك إثم علي، وهل في الاتصال بهم عبر التلفون أو مراسلتهم عبر البريد وصل لهم، أفيدوني جزاكم الله خيراً.","title":"كيف تكون صلة الرحم؟","answer":"الجواب: لا يجب السفر إليهم، وفي الإمكان حصول الصلة بالمكاتبة وبالهاتف التلفون هذا كله ممكن بحمد الله، وليس من الواجب السفر، إلا إذا دعت الحاجة إلى ذلك أو الضرورة إلى ذلك فهذا شيء آخر.\nالمقصود: أن صلة الرحم تكون بالمكاتبة، وتكون بالزيارة إذا تيسرت من دون كلفة، وتكون بالهاتف بالتلفون، وتكون بتحميل الأصحاب السلام عليهم والدعاء لهم بالتوفيق والسؤال عن حاجاتهم، وتكون بالمال بهدية المال إذا كانوا محتاجين ومواساتهم بالمال كل هذا من الصلة.\nوالنبي عليه السلام يقول في الحديث الصحيح: من أحب أن يبسط له في رزقه، وأن ينسأ له في أجله فليصل رحمه، ويقول عليه الصلاة والسلام: ليس الواصل بالمكافئ، ولكن الواصل الذي إذا قطعت رحمه وصلها رواه البخاري في الصحيح، وقال له رجل: يا رسول الله! إن لي قرابة أصلهم ويقطعونني، وأحسن إليهم ويسيئون إلي، وأحلم عنهم ويجهلون علي. فقال له ﷺ: لئن كنت كما قلت فكأنما تسفهم المل -المل يعني: الرماد الحامي- ولا يزال معك من الله ظهير عليهم ما دمت على ذلك (ظهير) يعني: عون. فالمسألة فيها خير للإنسان إذا وصل واستقام وصبر ولو قابلوه بالإساءة، إذا صبر عليهم وأدى حقه فهو على خير عظيم، وله العاقبة الحميدة، وهذا هو عنوان الصلة الحقيقية، مثلما قال النبي ﷺ: ليس الواصل بالمكافئ الذي يصلهم إذا وصلوه ويقطعهم إذا قطعوه ليس هو الواصل على الحقيقة، ولكن الواصل على الحقيقة الذي يصلهم وإن قطعوه، ويحسن إليهم وإن أساءوا هذا هو الكمال وهذا هو المروءة، وهذا هو الخلق الكريم، وهذا الذي ينبغي للمؤمن أن يفعله حتى يحسن إلى من أساء إليه، ويحلم عمن جهل عليه، وبهذا يحصل له الفضل العظيم والأجر الكبير. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8744/كيف-تكون-صلة-الرحم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_323/32304.mp3","categories":["الأذان والإقامة"]},{"id":10607,"question":"يسأل في أحد أسئلته عن التكبير بعد الصلوات الخمس في أيام التشريق، هل هو واجب، أو مستحب، وإذا كان ذلك واجب، أو مستحب، فهل فعله رسول الله ﷺ، أو هو من فعل الصحابة رضوان الله تعالى عليهم؟","title":"حكم التكبير أيام عيد الأضحى وصيغته","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإن التكبير في أيام التشريق بعد الصلوات محفوظ من فعل الصحابة ، وعمر ، وجماعة من الصحابة، ويروى عن النبي ﷺ لكن في إسناده فيه ضعف، وهكذا التكبير في عشر ذي الحجة من أولها، كله مشروع، وهو مروي عن الصحابة رضي الله عنهم وأرضاهم، وكان ابن عمر وأبو هريرة رضي الله عنهما يخرجان إلى السوق في أيام العشر، فيكبران ويكبر الناس لتكبيرهما، وكان الصحابة وعمر، وجماعة يكبرون بعد الصلوات الخمس ابتداءً من يوم عرفة إلى نهاية أيام التشريق، وكان عمر  يكبر في خيمته في منى حتى يسمعه الناس ويكبرون بتكبيره، فالتكبير مشروع، وليس بواجب، ولكنه سنة في يوم عرفة، ويوم النحر، وأيام التشريق مطلق، ومقيد، بعد الصلوات، وفي بقية الزمان من الليل، أو النهار يشرع التكبير. أما في اليوم الثامن، وما قبله من ذي الحجة، فهو تكبير مطلق لا مقيد بالصلوات بل مطلق، من أول ذي الحجة إلى نهاية ليلة التاسعة من ذي الحجة هذا مطلق، يكبر الإنسان في الطريق، وفي بيته، وعلى فراشه، وهكذا في الأيام الأخيرة من يوم عرفة، وما بعده يكبر المسلمون في الطريق وفي المساجد، وفي الأسواق، وأدبار الصلوات الخمس في الخمسة الأخيرة يوم عرفة وما بعده، والذي عليه جمهور أهل العلم أنه سنة فقط.\nالمقدم: جزاكم الله خيراً، يسأل عن صيغته لو سمحتم؟\nالشيخ: الصيغة: الله أكبر الله أكبر لا إله إلا الله، الله أكبر الله أكبر ولله الحمد شفعاً، وكان بعض الصحابة يأتي بها وتراً: الله أكبر الله أكبر الله أكبر لا إله إلا الله، الله أكبر الله أكبر الله أكبر ولله الحمد، كله طيب سواء أتى ..... شفعاً أو وتراً، ومن ذلك: الله أكبر كبيراً، والحمد لله كثيراً، وسبحان الله بكرة وأصيلاً، كل هذا وارد في الآثار عن الصحابة وفي الأثر المروي عن النبي عليه الصلاة والسلام. نعم.\nالمقدم: جزاكم الله خيراً بالنسبة للتكبير في المساجد هل يكبر أحد الناس ويكبر الناس بعده؟\nالشيخ: كل يكبر على حسب حاله، ما في تكبير جماعي، هذا يكبر وهذا يكبر ولا يشرع التكبير الجماعي، الجماعي غير مشروع ولكن كل يكبر على حسب حاله وإذا صادف صوته صوت أخيه فلا يضر ذلك، أما عن تنظيم التكبير من أوله إلى آخره يشرعون جميعاً وينتهون جميعاً فهذا لا أصل له. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8774/حكم-التكبير-ايام-عيد-الاضحى-وصيغته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_326/32601.mp3","categories":["الأذان والإقامة"]},{"id":10642,"question":"سماحة الشيخ! يقول هذا السائل: يوجد عندنا بالحي الذي أقيم فيه إمام كبير في السن، وهو إمام للمسجد ومؤذن في نفس الوقت، يأتي بعض الأحيان للأذان في وقت متأخر، أي: بعد الأذان بخمس دقائق أو عشر دقائق تقريبًا أو أكثر.وثانياً: عندما يصلي يكون اتجاهه في الركعة الثانية قد بدأ يميل خارجًا عن القبلة إما شمال أو يمين، ولعلمكم نظره بسيط، وقد سألناه مرة في أجل ذلك من أجل الميول فأجاب: يا إخوان! بأن القبلة واسعة وعريضة ولا بأس في ذلك، فهل إجابته هذه تكفي أم بماذا تنصحوننا وتنصحونه سماحة الشيخ بارك الله فيكم؟","title":"حكم تأخر المؤذن عن الأذان في الوقت","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفإننا ننصح المذكور بأن يعتني بالأذان في وقته، وأن يؤذن مع الناس حتى لا يسبب تأخر جماعة مسجده عن الحضور في الوقت الذي ينبغي، وحتى لا يلبس على الناس، فالواجب عليه المحافظة على الوقت والعناية بالوقت هذا هو الواجب عليه؛ لأن هذه أمانة، والله يقول: إِنَّ اللَّهَ يَأْمُرُكُمْ أَنْ تُؤَدُّوا الأَمَانَاتِ إِلَى أَهْلِهَا [النساء:58].\nأما القبلة فأمرها واسع، كما قال ﷺ: ما بين المشرق والمغرب قبلة بالنسبة إلى الشمال والجنوب ما بين المشرق والمغرب قبلة، وبالنسبة إلى المشرق والمغرب ما بين الشمال والجنوب قبلة، لكن يشرع التحري والصمود الكامل إلى القبلة، هذا هو الأفضل، وإلا فلا يضر الميل اليسير يمين أو شمال، ما يضر، والحمد لله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8819/حكم-تاخر-الموذن-عن-الاذان-في-الوقت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_285/28504.mp3","categories":["الأذان والإقامة"]},{"id":10706,"question":"لعل هناك حداً فارقاً سماحة الشيخ بين طاعة الوالدين فيما هو طاعة لله، وطاعة الوالدين فيما هو معصية لله، حبذا لو تفضلتم وبينتم هذا الأمر؛ لأن كثيراً من الناس يقع فيه دون علم؟","title":"الضابط في طاعة الوالدين","answer":"الجواب: طاعة الوالدين مثلما تقدم، طاعة الوالدين من طاعة الله، وبرهما من الفرائض، وعقوقهما من الكبائر، وهذا يشمل الطاعات التي يحبها الله ويشمل المباحات حتى في المباح إذا طلبا منه أن يذهب بهما إلى كذا من المباحات أو يشتري لهما حاجة وهو يستطيع ذلك وجب عليه ذلك، إذا كان لا ضرر عليه في ذلك، وهكذا إذا أمراه أن يصلح لهما قهوة شاي يحضر لهما ماء للشرب ماء للوضوء وهو يستطيع ذلك، ولو في الشيء المباح وجب عليه طاعتهما في ذلك.\nالمقصود: أنه يجب عليه أن يطيعهما في المعروف الذي لا ضرر فيه ولا معصية فيه : إنما الطاعة في المعروف كما قال النبي ﷺ.\nأما إذا أمراه بمعاصي الله أمراه بأن لا يصلي في المسجد، أمراه بأن يشرب الخمر، أمراه أن يدخن، أمراه أن يعمل بالربا، أمراه بشيء آخر من معاصي الله لا يلزمه طاعتهم، أمراه أن يذهب إلى بلاد الشرك، أمراه بشيء آخر مما يضره فإنه لا يلزمه لقول النبي ﷺ: لا ضرر ولا ضرار، إنما الطاعة في المعروف.\nفإذا أمراه بمعروف وشيء مباح ينفعهما ولا يضره فلا بأس يطيعهما في ذلك، أما شيء يضره أو شيء من معاصي الله، فلا يلزمه طاعتهما في ذلك، لكن يرده بالكلام الطيب والأسلوب الحسن، والدعاء لهما بالتوفيق والهداية، ويبين لهما عذره من أن المعاصي ما يطاع فيها أحد، المعاصي لا يطاع فيها لا الوالد ولا الأمير ولا السلطان لا يطاع أحد في المعاصي، الرسول ﷺ يقول: إنما الطاعة في المعروف، لا طاعة لمخلوق في معصية الخالق.\nوالله قال لنبيه: وَلا يَعْصِينَكَ فِي مَعْرُوفٍ [الممتحنة:12] فإذا أبلغهما ذلك وفهمهما فإنهما إذا كانا عاقلين يرضيا منه بذلك؛ لأن العاقل يفهم العذر الشرعي، أما إذا كانا متعصبين لرأيهما بدون حجة فإنه لا يلزمه أن يطيعهما فيما يضره أو فيما هو من معاصي الله . نعم.\nالمقدم: جزاكم الله خيراً، لكن هل يصل هذا إلى درجة القطيعة بين الوالد ووالديه مثلاً؟\nالشيخ: لا، لا يقطعهما يحسن إليهما ويطيعهما في المعروف ويتصل بهما ويرفق بهما ولا يطيعهما في معاصي الله ، ولا فيما يضره، لو قالا: اهدم بيتك بدون حجة وبدون سبب أو طلق زوجتك بدون عذر ما يلزمه ذلك. نعم.\nالمقدم: جزاكم الله خيراً إذاً كون الولد يقطع والديه لخلاف بسيط بينهما وينهى أبناءه عن مواصلتهما؟\nالشيخ: لا يجوز لا يجوز لا يجوز عقوقهما ولا قطيعتهما لفعل شيء مما يضره بل يصلهما ويحسن إليهما ويمتنع من الشيء الذي يضره فقط، مع رفقه بهما ومع إحسانه إليهما، ومع الكلام الطيب معهما، ومع برهما بكل ما يستطيع، لكن ذاك الشيء الذي أمراه به وهو معصية الله لا يطيعهما فيه مع كونه يرفق بهما ويحسن إليهما، الله يقول جل وعلا في حق الكفرة: وَإِنْ جَاهَدَاكَ عَلى أَنْ تُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلا تُطِعْهُمَا وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15]، مع أنهما كافران.\nالمقدم: هذا وهما كفار.\nالشيخ: وَإِنْ جَاهَدَاكَ عَلى أَنْ تُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلا تُطِعْهُمَا وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15] فأمره أن يصاحبهما في الدنيا بالمعروف مع أنهما كافران، فكيف بالمسلمين.\nفالمقصود: أن الوالدين لو جاهداه على الشرك لو طلبوا منه الشرك لا يطيعهما في الشرك لكن لا يعقهما، بل يرفق بهما ويحسن إليهما وإن كانا قد أساءا إليه بأن أمراه بالشرك أو المعصية، لكن يبين العذر الشرعي ويرفق بهما ويدعو لهما بالهداية. نعم.\nالمقدم: جزاكم الله خيراً، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/8881/الضابط-في-طاعة-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_342/34205.mp3","categories":["الأذان والإقامة"]},{"id":10719,"question":"نعود مع مطلع هذه الحلقة إلى رسالة المستمع أحمد عز الدين حزام العماد من اليمن الشمالي قرية العسادي وصاب العالي، أخونا أحمد عرضنا بعض أسئلته في حلقة مضت، وفي هذه الحلقة يسأل ويقول: هل شرع الرسول ﷺ بعد إكمال الأذان أن يقول المؤذن بصوت عالٍ كالأذان: الحمد لله رب العالمين، إِنَّ اللَّهَ وَمَلائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ يَا أَيُّهَا الَّذِينَ آمَنُوا صَلُّوا عَلَيْهِ وَسَلِّمُوا تَسْلِيمًا [الأحزاب:56]، هل يجوز مثل هذا العمل، جزاكم الله خيرًا؟","title":"حكم قول المؤذن: (إن الله وملائكته يصلون على النبي...)","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فهذا العمل الذي ذكره السائل منكر بدعة، ليس للمؤذن أن يقول بعد الأذان: الحمد لله مع صوت الأذان في المكبر، أو صلوا على رسول الله، أو يقرأ الآية، كل هذا بدعة، بل متى قال: لا إله إلا الله فإنه يقفل المكبر، ولا يزيد شيئًا، وإذا كان بغير مكبر كذلك لا يزيد شيئًا، لا يبتدع، آخر الآذان (لا إله إلا الله)، هذا آخر الآذان، فمن زاد معها شيء الصلاة على النبي ﷺ أو حمداً لله فقد ابتدع، ولكن يشرع له بعد ذلك من غير رفع صوت مع الأذان، ولا بغير رفع صوت مع المكبر يشرع له أن يصلي على النبي صلى الله عليه وسلم بينه وبين نفسه، ولو سمعه من حوله، ثم يقول: اللهم رب هذه الدعوة التامة، والصلاة القائمة، آت محمداً الوسيلة والفضيلة، وابعثه مقاماً محموداً الذي وعدته إنك لا تخلف الميعاد يشرع له أن يقول هذا المؤذن، وهكذا الناس الذين سمعوا الأذان يستحب لهم أن يجيبوه، يعني: يقولون مثل قول المؤذن إلا في الحيعلة يقول: لا حول ولا قوة إلا بالله، فإذا قال في آخر الأذان: لا إله إلا الله صلى على النبي ﷺ صلاة خفية ليست مع الأذان، بل يصلي على النبي ﷺ مثل ما يصلي غيره، ثم يقول: اللهم رب هذه الدعوة التامة، والصلاة القائمة، آت محمداً الوسيلة والفضيلة، وابعثه مقاماً محموداً الذي وعدته إنك لا تخلف الميعاد .... فالمستمع يقول والمؤذن يقول، وليس لواحد منهم أن يجعلها مع الأذان لا المؤذن ولا غير المؤذن، بل الأذان ينتهي عند قول: لا إله إلا الله، انتهى، فمن أراد أن يصلي على النبي ﷺ يكون بصوت خفي ليس من جنس صوت الأذان، ولا مع الأذان، ولا في مكبر مع الأذان، بل يكون بينه وبين نفسه، أو يسمعه من حوله لا بأس؛ لأن الرسول ﷺ قال: إذا سمعتم المؤذن فقولوا مثل ما يقول ثم صلوا علي، فإنه من صلى علي واحدة صلى الله عليه بها عشراً، ثم سلوا الله لي الوسيلة فإنها منزلة في الجنة لا تنبغي إلا لعبد من عباد الله، وأرجو أن أكون أنا هو، فمن سأل لي الوسيلة حلت له الشفاعة، هذا فضل من الله جل وعلا.\nوقال أيضاً عليه الصلاة والسلام: من قال حين يسمع النداء: اللهم رب هذه الدعوة التامة، والصلاة القائمة، آت محمداً الوسيلة والفضيلة وابعثه مقاماً محموداً الذي وعدته، حلت له شفاعتي يوم القيامة، وهذا فضل من الله جل وعلا، فيشرع للمؤمن والمؤمنة إذا سمع الأذان أن يقول مثل قول المؤذن كل منهما، الرجل والمرأة، إذا قال: الله أكبر، يقول: الله أكبر، قال: أشهد أن لا إله إلا الله، يقول: أشهد أن لا إله إلا الله، إذا قال: أشهد أن محمداً رسول الله يقول: أشهد أن محمداً رسول الله، إذا قال: حي على الصلاة، يقول: لا حول ولا قوة إلا بالله، حي على الفلاح يقول: لا حول ولا قوة إلا بالله، هذا مستثنى لا يقول مثل المؤذن، بل يقول: لا حول ولا قوة إلا بالله، كما أرشد إليه النبي عليه الصلاة والسلام، فإذا قال: الله أكبر الله أكبر، قال: الله أكبر الله أكبر، فإذا قال: لا إله إلا الله، يقول: لا إله إلا الله، ثم يصلي على النبي ﷺ، يصلي على النبي ﷺ، صلاة ليست مع الأذان بل منفصلة عن الأذان، يخفضها ويقفل المكبر سواء كان مؤذناً وهكذا غير المؤذن لا يرفعها رفعاً زائداً كالأذان، بل يأتي بها بصوت عادي، ثم يقول: اللهم رب هذه الدعوة التامة، والصلاة والقائمة، آت محمداً الوسيلة والفضيلة، وابعثه مقاماً محموداً الذي وعدته إنك لا تخلف الميعاد هذا رواه البخاري في الصحيح، عن جابر إلا بعض كلمات إنك لا تخلف الميعاد فهذه زيادة رواها البيهقي بإسناد حسن.\nولما قيل للرسول ﷺ: يا رسول الله! المؤذنين يغبنوننا، قال: قولوا مثل ما يقولون، ثم صلوا علي فإن من صلى علي واحدة صلى الله عليه بها عشراً، ثم سلوا الله لي الوسيلة فإنها منزلة في الجنة، لا تنبغي إلا لعبد من عباد الله وأرجو أن أكون أنا هو، فمن سأل لي الوسيلة حلت له الشفاعة، هذا خير عظيم وفضل كبير ينبغي لكل مؤمن ولكل مؤمنة عدم التفريط في ذلك بل يحرص عليه. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8886/حكم-قول-الموذن-ان-الله-وملاىكته-يصلون-على-النبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_343/34301.mp3","categories":["الأذان والإقامة","البدع والمحدثات"]},{"id":10721,"question":"أيهما أفضل العشر الأواخر من رمضان، أم عشر ذو الحجة؟","title":"الأفضلية بين العشر الأواخر من رمضان وعشر ذي الحجة","answer":"الجواب: العشر الأواخر من رمضان أفضل من جهة الليل؛ لأن فيها ليلة القدر، والعشر الأول من ذي الحجة أفضل من جهة النهار؛ لأن فيها يوم عرفة، وفيها يوم النحر وهما أفضل أيام الدنيا، هذا هو المعتمد عند المحققين من أهل العلم، فعشر ذي الحجة أفضل من جهة النهار، وعشر رمضان أفضل من جهة الليل؛ لأن فيها ليلة القدر وهي أفضل الليالي، والله المستعان. نعم.\nالمقدم: الله المستعان، جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8908/الافضلية-بين-العشر-الاواخر-من-رمضان-وعشر-ذي-الحجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_344/34411.mp3","categories":["الأذان والإقامة"]},{"id":10904,"question":"هل سماع القرآن الكريم من خلال الراديو أفضل، أم التسبيح لله تعالى؟","title":"أفضلية سماع القرآن على غيره من الأذكار","answer":"الجواب: سماع القرآن أفضل، سماع القرآن والإنصات له، وتدبر معانيه أفضل من التسبيح، وإن سبح وهلل فلا بأس، كله خير -إن شاء الله- لكن سماع القرآن وتدبر معانيه من الإذاعة، أو غير الإذاعة أفضل، لما في سماع القرآن من الخير العظيم، والفائدة الكبيرة، والله يقول سبحانه وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنصِتُوا [الأعراف:204]، ففي ذلك الخير العظيم، والعلم العظيم لمن تدبر وتعقل وتفهم كلام ربه  وإن سمع تارة، وسبح تارة كله خير، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9085/افضلية-سماع-القران-على-غيره-من-الاذكار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_360/36012.mp3","categories":["الأذان والإقامة"]},{"id":10907,"question":"ما الحكم فيمن يسبح الله وهو يقضي أعماله في بيته، أو وهو ماش في الطريق؟","title":"حكم التسبيح أثناء العمل أو أثناء المشي في الطرق","answer":"الجواب:  هذا له خير عظيم، قد جمع خيرًا عظيمًا، فإن الله -جل وعلا- شرع لنا أن نذكره قيامًا وقعودًا وعلى جنوبنا، كما قال تعالى: فَإِذَا قَضَيْتُمُ الصَّلاةَ فَاذْكُرُوا اللَّهَ قِيَامًا وَقُعُودًا وَعَلَى جُنُوبِكُمْ [النساء:103]، فالمؤمن يذكر الله دائمًا، ويقول : إِنَّ فِي خَلْقِ السَّمَوَاتِ وَالأَرْضِ وَاخْتِلافِ اللَّيْلِ وَالنَّهَارِ لَآيَاتٍ لِأُولِي الأَلْبَابِ ۝ الَّذِينَ يَذْكُرُونَ اللَّهَ قِيَامًا وَقُعُودًا وَعَلَى جُنُوبِهِمْ [آل عمران:190-191]. فالمشروع للمؤمن أن يذكر الله في أعماله، سواءً كان في نسيج، أو في زراعة، أو في نجارة، أو في حدادة، أو يمشي في السوق، أو غير ذلك يذكر الله في كل أحيانه، تقول عائشة -رضي الله عنها-: كان النبي ﷺ يذكر الله في كل أحيانه -عليه الصلاة والسلام- نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9086/حكم-التسبيح-اثناء-العمل-او-اثناء-المشي-في-الطرق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_360/36013.mp3","categories":["الأذان والإقامة"]},{"id":11026,"question":"بعد هذا رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات، تقول أختكم في الله أم هاجر من الرياض، أم هاجر لها قضية تقول فيها: في بعض الأحيان أقول لأمي: إن زوجي يحبها بشدة، ويقول عنها أشياء طيبة، وهكذا.. حتى لو زوجي لم يقل هذا، ونفس الشيء أفعله مع زوجي ولا أقصد سوى أن أوفق بينهما؛ لأنهما كانا شديدي الخلاف مع بعض، وكذلك أقول لها: إنه يشتري لي أشياء، أو يفعل معي أشياء طيبة حتى لو لم يفعلها لنفس القصد، فهل أكون بذلك كاذبة؟","title":"حكم الكذب لإصلاح ذات البين","answer":"الجواب:  لا حرج في ذلك، هذا من باب الإصلاح، ولا حرج في ذلك، إذا كان لا يضر أحدًا، إنما يتعلق بكما فقط، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9204/حكم-الكذب-لاصلاح-ذات-البين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_367/36705.mp3","categories":["الأذان والإقامة"]},{"id":11089,"question":"هذا السائل رمز لاسمه بـ (أ. أ. م) من السودان يقول: لدينا مؤذن في المسجد كلما جاء ليؤذن وقتًا من الأوقات بدأ بالآية الكريمة، وَمَنْ أَحْسَنُ قَوْلًا مِمَّنْ دَعَا إِلَى اللَّهِ وَعَمِلَ صَالِحًا وَقَالَ إِنَّنِي مِنَ الْمُسْلِمِينَ [فصلت:33]، فما حكم ذلك سماحة الشيخ؟","title":"حكم قراءة: {وَمَنْ أَحْسَنُ قَوْلًا مِمَّنْ دَعَا إِلَى اللَّهِ} قبل الأذان","answer":"الجواب: هذا غير مشروع، أقول: غير مشروع، لم يفعله النبي ﷺ ولا أصحابه، يبدأ بـ (الله أكبر)، يبدأ الأذان بـ (الله أكبر). نعم.","link":"https://binbaz.org.sa/fatwas/9267/حكم-قراءة-ومن-احسن-قولا-ممن-دعا-الى-الله-قبل-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_289/28915.mp3","categories":["الأذان والإقامة","البدع والمحدثات"]},{"id":11124,"question":"هل يكتفى بالإقامة فقط بدون أذان عندما يكون قد اقترب انتهاء وقت الصلاة؟","title":"حكم الاكتفاء بالإقامة بدون أذان","answer":"الجواب: إذا كان قد أذن غيره، إذا كان قد أذن المؤذنون في البلد فلا بأس، أما إذا كان إلا هو فعليه أن يؤذن حتى يعلم الناس دخول الوقت، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9315/حكم-الاكتفاء-بالاقامة-بدون-اذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_369/36915.mp3","categories":["الأذان والإقامة"]},{"id":11141,"question":"هل يكتفى بالإقامة فقط بدون أذان عندما يكون قد اقترب انتهاء وقت الصلاة؟","title":"حكم الاكتفاء بالإقامة بدون أذان","answer":"الجواب: إذا كان قد أذن غيره، إذا كان قد أذن المؤذنون في البلد فلا بأس، أما إذا كان إلا هو فعليه أن يؤذن حتى يعلم الناس دخول الوقت، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9315/حكم-الاكتفاء-بالاقامة-بدون-اذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_369/36915.mp3","categories":["الأذان والإقامة"]},{"id":11147,"question":"ما المدة الزمنية التي يجب أن تكون فيها صلة الرحم أي: الآباء لبناتهم ولبنات أخواتهم، والنساء لعماتهم وخالاتهم، أهي ثلاثة أيام من كل شهر؟ أفيدونا جزاكم الله خيرًا، وهل يأثم المسلم الذي لا يزور عمات وخالات والدته ووالده؟","title":"المدة الزمنية التي تجب فيها صلة الأرحام","answer":"الجواب:  ليس لصلة الرحم مدة معلومة فيما نعلم، بل الواجب صلة الراحم دائمًا حتى يموت، الواجب على المؤمن والمؤمنة صلة الرحم مطلقًا، ولا تتحدد بيوم أو يومين أو ثلاثة أو أربعة في الشهر أو في السنة، لا؛ الواجب صلة الرحم دائمًا، وتحرم القطيعة دائمًا، لكن صلة الرحم تكون بالمعتاد بالزيارة، بالمكاتبة، بالهاتف -التلفون- بوصية الأقارب أو الأصدقاء يبلغونه السلام، بمواساة الفقير، بالهدية المناسبة، كل هذا من الصلة، نعم، جزاكم الله خيرًا. المقدم: في آخر سؤالها تسأل سماحتكم، هل يأثم المسلم الذي لا يزور عمات وخالات والدته ووالده؟ الشيخ: لا يأثم في ذلك إذا كانت الصلة موجودة بالمكاتبة، أو بالتلفون أو بالمكاتبة، لأن الزيارة بالأبدان قد تصعب في بعض الأحيان، والمقصود رضا أقاربه، وعدم قطيعته لهم، أن يكون بينه وبينهم الرضا والمحبة وعدم القطيعة بأي وسيلة بالمكاتبة أو بالزيارة، أو من طريق الهاتف -التلفون- أو من طريق وصية الأصدقاء والأحباب الذين يزورونهم، يبلغون عنه محبته لهم، ورغبته في زيارتهم لولا الموانع، وهكذا تكون بالهدية، بالصدقة على الفقير، بالشفاعة الحسنة إلى غير هذا من وجوه النفع.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9329/المدة-الزمنية-التي-تجب-فيها-صلة-الارحام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_370/37005.mp3","categories":["الأذان والإقامة"]},{"id":11150,"question":"ما المدة الزمنية التي يجب أن تكون فيها صلة الرحم أي: الآباء لبناتهم ولبنات أخواتهم، والنساء لعماتهم وخالاتهم، أهي ثلاثة أيام من كل شهر؟ أفيدونا جزاكم الله خيرًا، وهل يأثم المسلم الذي لا يزور عمات وخالات والدته ووالده؟","title":"المدة الزمنية التي تجب فيها صلة الأرحام","answer":"الجواب:  ليس لصلة الرحم مدة معلومة فيما نعلم، بل الواجب صلة الراحم دائمًا حتى يموت، الواجب على المؤمن والمؤمنة صلة الرحم مطلقًا، ولا تتحدد بيوم أو يومين أو ثلاثة أو أربعة في الشهر أو في السنة، لا؛ الواجب صلة الرحم دائمًا، وتحرم القطيعة دائمًا، لكن صلة الرحم تكون بالمعتاد بالزيارة، بالمكاتبة، بالهاتف -التلفون- بوصية الأقارب أو الأصدقاء يبلغونه السلام، بمواساة الفقير، بالهدية المناسبة، كل هذا من الصلة، نعم، جزاكم الله خيرًا. المقدم: في آخر سؤالها تسأل سماحتكم، هل يأثم المسلم الذي لا يزور عمات وخالات والدته ووالده؟ الشيخ: لا يأثم في ذلك إذا كانت الصلة موجودة بالمكاتبة، أو بالتلفون أو بالمكاتبة، لأن الزيارة بالأبدان قد تصعب في بعض الأحيان، والمقصود رضا أقاربه، وعدم قطيعته لهم، أن يكون بينه وبينهم الرضا والمحبة وعدم القطيعة بأي وسيلة بالمكاتبة أو بالزيارة، أو من طريق الهاتف -التلفون- أو من طريق وصية الأصدقاء والأحباب الذين يزورونهم، يبلغون عنه محبته لهم، ورغبته في زيارتهم لولا الموانع، وهكذا تكون بالهدية، بالصدقة على الفقير، بالشفاعة الحسنة إلى غير هذا من وجوه النفع.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9329/المدة-الزمنية-التي-تجب-فيها-صلة-الارحام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_370/37005.mp3","categories":["الأذان والإقامة"]},{"id":11164,"question":"بعد هذا رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول: أختكم في الله أم أحمد من العزيزية، أم أحمد لها جمع من الأسئلة في أحدها تقول: إذا توضأت قبل صلاة المغرب بنصف ساعة أو ربع ساعة، وصليت ركعتين للوضوء، وجلست لقراءة القرآن والاستغفار حتى يحين أذان المغرب فهل عملي ذلك صحيح؟","title":"حكم الوضوء قبل المغرب وصلاة ركعتين وقراءة القرآن والاستغفار","answer":"الجواب:  نعم، عمل طيب، لأن الوضوء عبادة عظيمة، وقد شرع الله لمن توضأ أن يصلي ركعتين سنة الوضوء، فإذا توضأتي ولو بعد العصر، وصليت ركعتين السنة سنة الوضوء فهذا كله طيب، فإذا انتظرت صلاة المغرب بالتسبيح والتحميد والتكبير فهذا خير عظيم، يقول الله سبحانه: وَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ الْغُرُوبِ [ق:39]، فالتسبيح في آخر النهار قربة عظيمة، وهكذا في أول النهار، فيبدأ النهار بالتسبيح والتحميد والتهليل والاستغفار ويختم كذلك، وفق الله الجميع، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9340/حكم-الوضوء-قبل-المغرب-وصلاة-ركعتين-وقراءة-القران-والاستغفار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_371/37107.mp3","categories":["الأذان والإقامة"]},{"id":11220,"question":"بعد هذا رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين رمز إلى اسمه بالحروف (ع. س. س) أخونا له عدد من الأسئلة في أحدها يقول: ما هو أفضل وقت لقراءة سورة الكهف يوم الجمعة، لما ورد في فضل قراءتها يوم الجمعة؟","title":"تحديد قراءة سورة الكهف يوم الجمعة","answer":"الجواب:  كل يوم الجمعة وقت، تقرؤها في أول النهار، أو في وسط النهار، أو في آخر النهار، ورد فيها أحاديث فيها ضعف، لكن الثابت عن بعض الصحابة، عن أبي سعيد الخدري كان يقرؤها، ويروى عن ابن عمر ذلك، فإذا قرأتها فهو حسن إن شاء الله، سواء في أول الوقت، في أول اليوم، أو في وسطه، أو في المسجد حين تذهب إلى الصلاة، أو بعد ذلك، الأمر واسع والحمد لله. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9398/تحديد-قراءة-سورة-الكهف-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_373/37304.mp3","categories":["الأذان والإقامة"]},{"id":11221,"question":"أخيرًا يسأل سماحتكم ويقول: هل لنا أن نستغفر لأهلنا وذرياتنا وأزواجنا وموتانا؟","title":"حكم الاستغفار للأهل والذرية والأزواج والأحياء والأموات","answer":"الجواب:  نعم يستحب لكم ذلك، أن تستغفروا لهم، وتدعوا لهم بالمغفرة والرحمة، الأحياء والأموات إذا كانوا مسلمين. تدعون لهم بالرحمة والمغفرة، ودخول الجنة، والنجاة من النار، أحياءً وأمواتًا، لأبيك وأمك وآبائك وأجدادك وعماتك وخالاتك، وجميع أقاربك المسلمين، تدعو لهم بالرحمة وبالمغفرة، بالعتق من النار، بقبول أعمالهم، كل هذا طيب، وأنت مأجور. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9403/حكم-الاستغفار-للاهل-والذرية-والازواج-والاحياء-والاموات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_373/37310.mp3","categories":["الأذان والإقامة"]},{"id":11225,"question":"بعد هذا رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين رمز إلى اسمه بالحروف (ع. س. س) أخونا له عدد من الأسئلة في أحدها يقول: ما هو أفضل وقت لقراءة سورة الكهف يوم الجمعة، لما ورد في فضل قراءتها يوم الجمعة؟","title":"تحديد قراءة سورة الكهف يوم الجمعة","answer":"الجواب:  كل يوم الجمعة وقت، تقرؤها في أول النهار، أو في وسط النهار، أو في آخر النهار، ورد فيها أحاديث فيها ضعف، لكن الثابت عن بعض الصحابة، عن أبي سعيد الخدري كان يقرؤها، ويروى عن ابن عمر ذلك، فإذا قرأتها فهو حسن إن شاء الله، سواء في أول الوقت، في أول اليوم، أو في وسطه، أو في المسجد حين تذهب إلى الصلاة، أو بعد ذلك، الأمر واسع والحمد لله. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9398/تحديد-قراءة-سورة-الكهف-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_373/37304.mp3","categories":["الأذان والإقامة"]},{"id":11226,"question":"أخيرًا يسأل سماحتكم ويقول: هل لنا أن نستغفر لأهلنا وذرياتنا وأزواجنا وموتانا؟","title":"حكم الاستغفار للأهل والذرية والأزواج والأحياء والأموات","answer":"الجواب:  نعم يستحب لكم ذلك، أن تستغفروا لهم، وتدعوا لهم بالمغفرة والرحمة، الأحياء والأموات إذا كانوا مسلمين. تدعون لهم بالرحمة والمغفرة، ودخول الجنة، والنجاة من النار، أحياءً وأمواتًا، لأبيك وأمك وآبائك وأجدادك وعماتك وخالاتك، وجميع أقاربك المسلمين، تدعو لهم بالرحمة وبالمغفرة، بالعتق من النار، بقبول أعمالهم، كل هذا طيب، وأنت مأجور. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9403/حكم-الاستغفار-للاهل-والذرية-والازواج-والاحياء-والاموات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_373/37310.mp3","categories":["الأذان والإقامة"]},{"id":11341,"question":"هذا السائل أبو أحمد رمز لاسمه بهذا الرمز (أبو أحمد أ. أ) من الرياض يقول: سماحة الشيخ! علمنا بأن من أوثق عرى الإيمان الحب في الله والبغض في الله، فما معنى الحب في الله وما معنى البغض في الله؟","title":"معنى الحب في الله والبغض في الله","answer":"الجواب: الحب في الله أن تحب من أجل الله -جل وعلا- لأنك رأيته ذا تقوى وإيمان فتحبه في الله، وتبغضه في الله؛ لأنك رأيته كافرًا عاصيًا لله فتبغضه في الله، أو عاصيًا وإن كان مسلمًا فتبغضه بقدر ما عنده من المعاصي، هكذا المؤمن، يتسع قلبه لهذا وهذا، يحب في الله أهل الإيمان والتقوى، ويبغض في الله أهل الكفر والشرور والمعاصي، ويكون قلبه متسعًا لهذا وهذا. وإذا كان الرجل فيه خير وشر كالمسلم العاصي أحبه من أجل إسلامه وأبغضه من أجل ما عنده من المعاصي، فيكون فيه الأمران الشعبتان شعبة الحب والبغض، فأهل الإيمان وأهل الاستقامة يحبهم حبًا كاملًا، وأهل الكفر يبغضهم بغضًا كاملًا، وصاحب الشائبتين صاحب المعاصي يحبه على قدر ما عنده من الإيمان والإسلام ويبغضه على قدر ما عنده من المعاصي والمخالفات. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9523/معنى-الحب-في-الله-والبغض-في-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_293/29304.mp3","categories":["الأذان والإقامة"]},{"id":11391,"question":"من المدينة المنورة رسالة بتوقيع إحدى الأخوات المستمعات تقول: المرسلة (ف. ع) أختنا تقول: لدي مؤسسة باسمي، لكن زوجي يتولى الأعمال، وقد استخرجنا عشرين فيزة، وبعد ذلك طلب من العمال مبلغ ثلاثمائة ريال شهرياً، ويعملوا على حسابهم الخاص، وأنا محتارة في ذلك، فهل ما قام به زوجي جائز أم لا؟ علمًا بأن زوجي يصر على أن ذلك جائز بعد أن ناقشته أكثر من مرة، أفيدوني جزاكم الله خيرًا.","title":"حكم أخذ مبالغ مالية ممن يتم استقدامهم للعمل","answer":"الجواب:  عليك وعليه السير على ما رسمت الدولة في استقدام العمال، وعدم الخروج عن ذلك، عليكما العمل بالتعليمات التي رسمتها الدولة فيما يتعلق بالعمال، وليس لكما الخروج عن ذلك؛ لأن عليكما السمع والطاعة في المعروف وهذا من المعروف. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9557/حكم-اخذ-مبالغ-مالية-ممن-يتم-استقدامهم-للعمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_379/37906.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":11406,"question":"رسالة بعث بها مستمع يقول: (أ. س. د) يقول: أعمل مهندسًا في مؤسسة في إحدى مناطق المملكة، وتعاقدت مع كفيلي، واتفق معي على اتفاقات مادية ومعنوية، ولكنه بعد مضي سنة أخلف بعض الاتفاقات المادية والمعنوية، أفتوني ماذا أفعل؟ جزاكم الله خيرًا.","title":"حكم من عقد مع كفيله اتفاقات ولم يف الكفيل بها","answer":"الجواب: عليك أن ترفع أمره إلى المحكمة، تطلب الشرع إلا إذا اصطلحت أنت وإياه، أو أصلح بينكما بعض الإخوان؛ طيب، الصلح خير، فإذا تيسر من يصلح بينكما بأن تسمح عن بعض حقك، أو يؤدي الحق كله هو. فالمقصود: الصلح طيب إذا تيسر، فإن لم يتيسر الصلح وأبى؛ فليس لك إلا المحكمة، ترفع أمرك إلى المحكمة، وفيما تراه المحكمة الكفاية، إن شاء الله. المقدم: بارك الله فيكم.  الشيخ: إذا كنت في بلاد تحكم بالشرع، إذا كنت في بلاد تحكم بالشرع. المقدم: يقول: إنه في إحدى مناطق المملكة، جزاكم الله خيرًا. الشيخ: ........ المحكمة والحمد لله، نعم. المقدم: الحمد لله، بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9586/حكم-من-عقد-مع-كفيله-اتفاقات-ولم-يف-الكفيل-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_380/38006.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":11554,"question":"يقول: أنا أعمل في محل بيع لملابس النساء، فبماذا تنصحونني؟ جزاكم الله خيرًا، ولا بد أنه وصلكم طريقة النساء في الأسواق؟","title":"حكم العمل في محلات بيع ملابس النساء","answer":"الجواب:  أنت أعلم بنفسك، إذا كان عملك هذا قد يجرك إلى شر وفتنة بالنساء؛ فاترك العمل، والتمس عملًا آخر، أما إذا كان لا يضرك، بل تستعمل طريقًا لا يضرك معه هذا العمل، ويمكن البيع والشراء من دون فتنة؛ فلا حرج عليك في ذلك، أنت أعلم بنفسك، وأنت أدرى بالواقع. والذي أنصحك به أن يكون عملك غير هذا العمل؛ لأن .... النساء في الغالب تجر إلى فتنة، ولاسيما قد يخلو بالواحدة منهن لتفتيش الملابس، والنظر في الملابس، فتكون الفتنة أكبر وأعظم، فالتماس عملًا آخر ليس فيه فتنة خير لك، وأولى. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9737/حكم-العمل-في-محلات-بيع-ملابس-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_297/29703.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":11575,"question":"بعد هذا رسالة بعثت بها إحدى الأخوات المستمعات، تقول عن نفسها: أمة الله من جيزان ضمد (ع. ف. ق) لها رسالة مطولة، في سؤالها الأول تشكو حالها مع أمها، وأبيها، إذ تقول: إن الأم والأب لم يعيناها على البر والطاعة، وحينئذ تتضايق من هذا الوضع سماحة الشيخ، وترجو منكم التوجيه والنصح، جزاكم الله خيرًا.","title":"الوصية بوجوب بر الوالدين","answer":"الجواب:  نوصيك أيها الأخت في الله نوصيك بالبر والإحسان إليهما، وإن أساءا إليك، الله -جل وعلا- أوصى بالوالدين، قال سبحانه: أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ [لقمان:14] وقال سبحانه: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا إِمَّا يَبْلُغَنَّ عِنْدَكَ الْكِبَرَ أَحَدُهُمَا أَوْ كِلاهُمَا فَلا تَقُلْ لَهُمَا أُفٍّ وَلا تَنْهَرْهُمَا وَقُلْ لَهُمَا قَوْلًا كَرِيمًا ۝ وَاخْفِضْ لَهُمَا جَنَاحَ الذُّلِّ مِنَ الرَّحْمَةِ وَقُلْ رَّبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا [الإسراء:23-24] وقال في حق الوالدين الكافرين: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا وَاتَّبِعْ سَبِيلَ مَنْ أَنَابَ إِلَيّ [لقمان:15] فإذا الوالدان الكافران يحسن إليهما، فالوالدان المسلمان من باب أولى. فالواجب عليك الصبر والاحتساب والإحسان إليهما، ولو أساءا إليك، ولو ساءت أخلاقهما، فعليك الصبر والاحتساب والبر فيهما بكل ما تستطيعين، نسأل الله لك العون والتوفيق والتسديد، ونسأل الله لهما الهداية والتوفيق. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9758/الوصية-بوجوب-بر-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_386/38608.mp3","categories":["الأذان والإقامة"]},{"id":11646,"question":"يقول: إذا كان الإنسان لديه والدته، وهي كبيرة، ولكنها تقدر والحمد لله على المشي مع أنها تتعبها مشاغل المنزل، وليس عندها من يساعدها، هل يجوز لي استقدام خادمة للقيام بأعمال البيت، وخدمة والدتي، وجهونا حول هذا الموضوع حيث أن بعض الناس استقدم منهن، ولكن بعض الناس أنكر عليه ذلك، وجهوا لنا هذا الموضوع جزاكم الله خيرًا.","title":"حكم استقدام خادمة للضرورة","answer":"الجواب:  لا حرج في ذلك، استقدام خادمة من المسلمين ما هو من الكفار، خادمة مسلمة لا يجوز استقدام الكفرة إلى هذه الجزيرة العربية، ولكن استقدام مسلمة حتى في غير الجزيرة، الأحوط للمؤمن ألا يستقدم إلا مسلمة، لكن في الجزيرة لا يجوز استقدام الكفرة؛ لأن الرسول أمر بإخراجهم من هذه الجزيرة -عليه الصلاة والسلام- وليس لك أن تخلو بها، تكون مع الوالدة، تبيت معها وتعاونها، وليس لك أن تخلو بها، وعليك غض البصر، والحذر من أسباب الشر، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9828/حكم-استقدام-خادمة-للضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_389/38915.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":11666,"question":"يسأل أخونا هذا السؤال ويقول: إذا كنت في دورة المياه، وسمعت المؤذن، هل أقول كما يقول؟ مع العلم أن ذلك في السر، وإذا كنت أذكر الله في سري في دورة المياه، هل هذا ممنوع؟ جزاكم الله خيرًا.","title":"حكم متابعة المؤذن داخل دورة المياه","answer":"الجواب:  لا يشرع لك ذلك في دورة المياه، ولكن في قلبك لا بأس من دون تلفظ، وكون الإنسان في قلبه يستحضر هذا الذكر العظيم، فلا بأس، وإن كان على حاجاته يستذكر حاجات دينية معاني القرآن، معاني الأحاديث، لا حرج، إنما المكروه التلفظ. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9849/حكم-متابعة-الموذن-داخل-دورة-المياه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_299/29902.mp3","categories":["قضاء الحاجة","الأذان والإقامة"]},{"id":11738,"question":"أخيرًا يسأل أخونا هل يصح الأذان بغير وضوء؟","title":"حكم الأذان بغير وضوء","answer":"الجواب:  نعم الصحيح أنه لا بأس، الأذان والإقامة جميعًا، ثم يتوضأ، لكن الأفضل أن يؤذن على وضوء، ويقيم على وضوء، لكن لو أذن على غير وضوء، وأقام على .. صح. المقدم: ما شاء الله، جزاكم الله خيرًا، لكنه إذا أقام، وذهب يتوضأ؛ يفوته كثير من فضل صلاة الجماعة. الشيخ: المقصود إقامته صحيحة، والنقص عليه هو. المقدم: النقص عليه. الشيخ: إقامته صحيحة. نعم. المقدم: الكلام الآن على الإقامة. الشيخ: نعم. المقدم: بارك الله فيكم، جزاكم الله خيرًا، لكن يبدو بأن سماحة الشيخ ينصح الأئمة ألا يفعلوا هذا. الشيخ: لا السنة أن يؤذن على وضوء، وأن يقيم على وضوء هذا السنة، جاء في حديث ضعيف لا يؤذن إلا متوضئ لكنه ضعيف. المقدم: طيب طيب، بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9938/حكم-الاذان-بغير-وضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_393/39319.mp3","categories":["الأذان والإقامة"]},{"id":11795,"question":"سماحة الشيخ! ما رأيكم في الذين يكثر نعاسهم، ونومهم إذا أقيمت حلقات الذكر؟","title":"توجيه لمن ينتابه النعاس في حلقات الذكر","answer":"الجواب:  عليه أن يجتهد، ويحاسب نفسه، ويتحرى أسباب يقظته وانتباهه، ولو بشيء يتعاطاه من قرنفل، أو غيره، أو سواك، يتعاطى الأسباب، يجتهد في الأسباب التي تعينه على الانتباه واليقظة، وسماع الفائدة، نعم. المقدم: جزاكم الله خيرًا، سماحة الشيخ يقولون: إن النوم والنعاس عدوى، ما هو رأيكم؟ الشيخ: ما سمعته، ما بلغني شيء في هذا. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9979/توجيه-لمن-ينتابه-النعاس-في-حلقات-الذكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_422/42212.mp3","categories":["الأذان والإقامة"]},{"id":11833,"question":"يسأل أخونا عن حكم الشرع في شخص لم يربه أبوه -كما قال- ولم يعطه أي نوع من العناية حتى أثناء طفولته، بالرغم من مقدرة الوالد على الإنفاق على الابن، فهل تجب حينئذ الصلة بين الأب وابنه؟ جزاكم الله خيرًا.","title":"حكم صلة الابن أباه الذي جفاه صغيراً وكبيراً","answer":"الجواب: نعم على الولد البر بوالده، ومعرفة حقه، والإحسان إليه ولو أساء الوالد، ولو قصر، فالوالد عليه التوبة إلى الله من تقصيره، عليه أن يتوب إلى الله من تقصيره في حق ولده وتربيته، ولكن هذا لا يبرر للولد العقوق، بل يجب على الولد أن يبر والديه، وإن قصرا في حقه، قال الله في حق الكافرين في قصة لقمان: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15] ولو كانا كافرين. فالواجب على الولد الإحسان إلى والديه، وبرهما، والرفق بهما، ومعاملتهما المعاملة الطيبة الحسنة، وإن قصرا في حقه. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10015/حكم-صلة-الابن-اباه-الذي-جفاه-صغيرا-وكبيرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_395/39518.mp3","categories":["الأذان والإقامة"]},{"id":11917,"question":"يقول: نلاحظ كثيرًا من الناس يعيشون على الدلالة، وكلما يفعله هؤلاء الدلالون هو أن يوفق بين البائع والمشتري على أن تكون عمولة للدلال كذا وكذا في المائة، فهل تجوز هذه المهنة؟ مع العلم بأن كثيرًا من الدلالين يحلفون للبائع، أو المشتري بالكذب حتى يوافق على تمام البيع، وبعض الدلالين يخفون العيب الذي يكون في الشيء المباع على المشتري؛ لكي يتم البيع وجهونا جزاكم الله خيرًا.","title":"حكم مهنة الدلالة وأخذ الأجرة عليها","answer":"الجواب:  الدلالة لا بأس بها كونه يأخذ نصيبًا، يبيع أرض فلان، بيت فلان، سيارة فلان، ويأخذ أجرة؛ لا بأس، لكن لا يجوز له أن يكذب، ولا أن يغش البائع، ولا أن يغش المشتري، حرام عليه ينصح لهؤلاء ولهؤلاء، ولا يكتم العيب، ولا يكذب على صاحب السلعة، ويقول: إنها هذا حدُّها، وهو يكذب لأجل مصلحة المشتري. المقصود أن عليه النصح، والحذر من الكذب، وإخفاء العيوب، وإذا فعل شيئًا من هذا؛ فقد أثم، وصار كسبه خبيثًا، لكن عليه أن يتقي الله، وأن ينصح لهذا وهذا، للبائع والمشتري، ويبرئ ذمته، ولا يجوز له كتمان العيوب، ولا الغش، ولا الخيانة، ولا الكذب لا على المشتري، ولا على البائع، هذا الواجب عليه أن ينصح لله، ولعباد الله، وبذلك تكون مهنته لا بأس بها، ويكون أجره لا بأس به، أما إن كان غش الناس، وخان الأمانة، وكذب؛ فقد تعاطى منكرًا عظيمًا، نسأل الله العافية، وصارت دلالته فيها الشر الكثير، ولم تجز له حلالًا؛ بسبب غشه وخيانته وكذبه، نسأل الله العافية. المقدم: اللهم آمين جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10101/حكم-مهنة-الدلالة-واخذ-الاجرة-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_426/42618.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":11928,"question":"ما حكم الأذان والإقامة للنساء؟","title":"ما حكم الأذان والإقامة للنساء؟","answer":"الجواب:  غير مشروعة، لا يشرع للنساء الأذان، ولا الإقامة، بل الأذان والإقامة مما يتعلق بالرجال، فالمرأة تصلي بدون أذان، ولا إقامة هذا هو المشروع. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10112/ما-حكم-الاذان-والاقامة-للنساء ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_427/42705.mp3","categories":["الأذان والإقامة"]},{"id":11985,"question":"يسأل سماحتكم: عندما تصلي المرأة في بيتها هل تؤذن وتقيم للصلاة سرًا، أم جهرًا؟ وهل يصح للرجل أن يصلي مع زوجته؟ إذا كان ذلك جائز، فأين تقف خلفه، أم عن يمينه؟ أفيدونا جزاكم الله خيرًا.","title":"هل تؤذن وتقيم المرأة للصلاة سرًا؟، وما موقفها إن صلت مع زوجها؟","answer":"الجواب:  النساء ليس عليهن أذان ولا إقامة، الأذان والإقامة من اختصاص الرجال، تصلي بلا أذان ولا إقامة، وإذا صلى هو وإياها في الليل صلاة الليل، أو كان مريضًا، وصلى هو وإياها؛ فلا بأس، وإلا هو يجب عليه أن يصلي في الجماعة، في المساجد، لكن إذا كان في صلاة الليل، أو مريضًا لا يستطيع الصلاة في المسجد، وصلى هو وإياها؛ لا بأس، لكن تكون خلفه، ما تكون عن يمينه، ولا عن شماله، موقفها خلفه في الفريضة والنافلة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10170/هل-توذن-وتقيم-المراة-للصلاة-سرا-وما-موقفها-ان-صلت-مع-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_430/43008.mp3","categories":["الأذان والإقامة","صلاة الجماعة"]},{"id":12059,"question":"يسأل عن المرأة والأذان والإقامة، هل لها أن تؤذن وتقيم في بيتها كالرجل، أم تصلي كحال النساء؟ جزاكم الله خيرًا.","title":"هل للمرأة أن تؤذن وتقيم الصلاة في بيتها؟","answer":"الجواب:  الأذان والإقامة للرجال، أما المرأة فهي تصلي بدون أذان، ولا إقامة، وإن صلت مع الناس؛ فلا بأس، إذا خرجت متحجبة متسترة، وصلت مع الناس؛ لا بأس، لكن بيتها خير لها وأفضل، ولا يشرع لها أذان ولا إقامة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10244/هل-للمراة-ان-توذن-وتقيم-الصلاة-في-بيتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_434/43408.mp3","categories":["الأذان والإقامة"]},{"id":12111,"question":"بعد هذا رسالة من إحدى الأخوات المستمعات من ليبيا تقول: أختكم في الله (أ. ب. أ) أختنا لها جمع من الأسئلة في أحدها تقول: إن أمي تقيم الصلاة فأخبرتها أن ذلك ليس واجبًا عليها، لكنها تجاهلت، فهل عليها شيء؟ جزاكم الله خيرًا.","title":"هل على المرأة إثم إن أقامت الصلاة قبل أن تصلي؟","answer":"الجواب:  ليس عليها شيء، لكن تخبر أنه غير مشروع لها الإقامة، الإقامة مشروعة في حق الرجال الأذان والإقامة للرجال، أما هي غير مشروع لها ذلك، ونخشى عليها من الإثم، وأن تكون أتت ببدعة، فالمقصود الذي ينبغي لها ترك الإقامة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10296/هل-على-المراة-اثم-ان-اقامت-الصلاة-قبل-ان-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_437/43714.mp3","categories":["الأذان والإقامة"]},{"id":12147,"question":"من جنوب الهند رسالة بعث بها المستمع: أحمد علي، الأخ أحمد يسأل جمعًا من الأسئلة من بينها سؤال يقول: أرجو إفادتي عن أصل الحجر الأسود.","title":"تحقيق الخلاف في أصل الحجر الأسود","answer":"الجواب:  الحجر الأسود جاء في حديث لا بأس به: أنه أصله من الجنة وهذا هو المعتمد، أن الله أنزله على إبراهيم، فجعله في مكانه. وقال جماعة: إنه من الدنيا، من جبل أبي قبيس. والصواب: أنه من الجنة كما جاءت به الأحاديث الصحيحة، هذا هو الصواب. نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10332/تحقيق-الخلاف-في-اصل-الحجر-الاسود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_440/44004.mp3","categories":["الأذان والإقامة"]},{"id":12304,"question":"المستمعة (ن. ن) من مكة المكرمة بعثت برسالة تقول فيها: قرأت كتابًا تحت عنوان: السيدة عائشة -رضي الله عنها- وفيه أن السيدة عائشة كانت تؤذن، وتقيم الصلاة لنفسها، أو لمن يصلي معها من النساء، فهل على المرأة أن تؤذن، وتقيم الصلاة لنفسها؟ نرجو الإفادة مأجورين جزاكم الله خيرًا.","title":"هل على المرأة أن تؤذن وتقيم الصلاة لنفسها؟","answer":"الجواب:  المشروع أن الأذان يكون للرجال، وهكذا الإقامة؛ لأن الأذان دعوة إلى حضور الصلاة، وإعلام بالوقت، فهو يكفي للنساء؛ لأنهن علمن بالوقت بالأذان، فليس هناك حاجة إلى أن يؤذن، والإقامة إنما تشرع للحاضرين حتى يعلموا حضور الصلاة وإقامتها، والنساء صلاتهن في البيوت، ولسن في حاجة إلى ذلك. فالمشروع هو أن تصلي بدون أذان وإقامة، أما ما يروى عن عائشة فلا نعلم صحته، لا نعلم أنه يصح عن عائشة، ولا عن غيرها في هذا شيء، من جهة الأذان والإقامة، فمن ادعى ذلك؛ فعليه الدليل، والأصل عدم ذلك، وإنما شرع الله الأذان والإقامة للرجال، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10504/هل-على-المراة-ان-توذن-وتقيم-الصلاة-لنفسها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_453/45310.mp3","categories":["الأذان والإقامة"]},{"id":12333,"question":"آخر سؤال له يقول: إذا دخلت المسجد، والمؤذن يؤذن، فهل أشرع في تحية المسجد، أم أتابع المؤذن حتى ينتهي، ثم أصلي؟ وإذا كنت أقرأ القرآن والمؤذن يؤذن هل أقف عن القراءة لأتابع المؤذن، أم كيف؟ جزاكم الله خيرًا.","title":"ما يفعله الداخل للمسجد عند الأذان ومن يقرأ القرآن","answer":"الجواب:  نعم نعم، الأفضل لك أن تتابع المؤذن، فإن كنت تقرأ؛ تمسك وإن كنت دخلت والمؤذن يؤذن؛ تقف حتى تكمل الإجابة، ثم تصلي، تجمع بين المصلحتين؛ لقول النبي ﷺ: إذا سمعتم المؤذن فقولوا مثلما يقول متفق على صحته، فالنبي ﷺ حين قال: إذا سمعتم المؤذن فقولوا مثلما يقول يعم القارئ، ويعم غير القارئ، فإذا دخلت والمؤذن يؤذن؛ فإنك تجيب أذانه في يوم الجمعة، وفي غير يوم الجمعة، تجيب الأذان، ثم تصلي ركعتين، ثم تنصت للخطيب إن كان في يوم الجمعة.  فالحاصل: أنك إذا دخلت المسجد، والمؤذن يؤذن، فالمشروع لك أن تجيب المؤذن، ثم تصلي تحية المسجد، وهكذا إذا كنت قارئًا تقرأ القرآن، أو تتحدث مع غيرك؛ تمسك حتى تجيب المؤذن، ثم تعود إلى القراءة، أو الحديث مع غيرك، عملًا بقول النبي ﷺ: إذا سمعتم المؤذن؛ فقولوا مثلما يقول، ثم صلوا علي، فإن من صلى علي واحدة؛ صلى الله عليه بها عشرًا، ثم سلوا الله لي الوسيلة، فإنها منزلة في الجنة، لا تنبغي إلا لعبد من عباد الله، وأرجو أن أكون أنا هو، فمن سأل لي الوسيلة؛ حلت له الشفاعة. هذا عمل عظيم، وفائدة كبيرة، وفي صحيح البخاري -رحمه الله- عن جابر بن عبدالله الأنصاري -رضي الله عنهما- عن النبي ﷺ أنه قال: من قال حين يسمع النداء:: اللهم رب هذه الدعوة التامة، والصلاة القائمة، آت محمدًا الوسيلة والفضيلة، وابعثه مقامًا محمودًا الذي وعدته حلت له شفاعتي يوم القيامة وهذا خير عظيم، وفضل كبير، فلا ينبغي للمؤمن أن يضيع هذا الخير العظيم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10533/ما-يفعله-الداخل-للمسجد-عند-الاذان-ومن-يقرا-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_454/45406.mp3","categories":["الأذان والإقامة"]},{"id":12638,"question":"تقول في سؤال آخر: هل المناداة للصلاة بدعة؟","title":"ما حكم المناداة للصلاة بعد الأذان؟","answer":"الجواب:  هذا من إنكار المنكر، ومن الأمر بالمعروف؛ لأن الله -جل وعلا- أمر بالأذان، بالنداء، قال: (حي على الصلاة، حي على الفلاح) فإذا مر المسلم على قوم جالسين لم يتحركوا إلى الصلاة، وناداهم قال: صلوا يا عباد الله! الصلاة الصلاة، فهذا من باب الأمر بالمعروف والنهي عن المنكر، ومن باب الدعوة إلى الله -عز وجل- صاحبه مأجور؛ لأنه آمر بالمعروف، وناهٍ عن منكر.  فالذي يمشي في الأسواق، ويرى من يتخلف عن الصلاة، فيقول له: صل يا عبدالله! اتق الله، بادر إلى الصلاة مأجور، وهذا من باب الأمر بالمعروف، والنهي عن المنكر، ومن باب الدعوة إلى الله .  وهكذا إذا قال لأهله: صلوا، لأولاده، لإخوته بعد الأذان، وقام عليهم واشتد عليهم في ذلك حتى يخرجوا إلى الصلاة؛ فهو مأجور، وهذا واجب عليه، يقول الله سبحانه: وَأْمُرْ أَهْلَكَ بِالصَّلاةِ وَاصْطَبِرْ عَلَيْهَا [طه:132] ويقول -جل وعلا-: يَا أَيُّهَا الَّذِينَ آمَنُوا قُوا أَنفُسَكُمْ وَأَهْلِيكُمْ نَارًا وَقُودُهَا النَّاسُ وَالْحِجَارَةُ [التحريم:6].  ولا شك أن الأمر بالصلاة من أسباب الوقاية من النار، وبعض الناس يسمع النداء، ولا يتحرك، يسمع الأذان، ولا يتحرك، فلابد أن يقوم عليه جاره وأخوه، ومن يشاهده، أو أبوه، أو غيرهم من باب التعاون على البر والتقوى، ومن باب الأمر بالمعروف والنهي عن المنكر، ومن باب الدعوة إلى الله  نسأل الله للجميع الهداية، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10848/ما-حكم-المناداة-للصلاة-بعد-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_415/41512.mp3","categories":["الأذان والإقامة"]},{"id":12785,"question":"بعد هذا رسالة بعث بها الأخ المستمع إبراهيم الأحمر يقول: أخبروني عن هذه الجملة في الأذان وهي: (الصلاة خير من النوم) هل هي في الأذان الأول، أم في الأذان الثاني؟ جزاكم الله خيرًا.","title":"ما الأذان الذي يقال فيه (الصلاة خير من النوم)؟","answer":"الجواب:  هذه الجملة في الأذان الثاني عند طلوع الفجر، كما بينته عائشة -رضي الله عنها- وجاء ذلك في عدة أحاديث، ويسمى الأذان الأول والإقامة هي الأذان الثاني. أما الأول الذي يأذن به بعض الناس في آخر الليل؛ فهذا لتنبيه القائم، وإيقاظ النائم كما في الحديث الصحيح في حديث بلال أمره ﷺ يؤذن بليل: إن بلالًا يؤذن بليل؛ فكلوا واشربوا حتى يؤذن ابن أم مكتوم فإن بلالًا يؤذن بليل؛ ليوقظ نائمكم، ويعلم قائمكم يعني: قرب الفجر؛ حتى يستعد للفجر، نعم.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10999/ما-الاذان-الذي-يقال-فيه-الصلاة-خير-من-النوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_420/42012.mp3","categories":["الأذان والإقامة"]},{"id":12809,"question":"المستمع عبدالله محمد الشهراني من جيزان بعث برسالة ضمنها جمعًا من الأسئلة، من بينها سؤال يقول فيه: ما رأي سماحتكم إذا حان وقت الصلاة، وتوجهت للمسجد، ووجدت الجماعة قد أدوا الصلاة، هل يجب علي الأذان والإقامة، أم أقيم فقط؟ وإذا صليت بدون ذلك هل صلاتي تعتبر صحيحة، سواءً سمعت الأذان، أو لم أسمع؟","title":"حكم من صلى بدون أذان ولا إقامة لمن فاتته الجماعة","answer":"الجواب:  السنة لك أن تقيم، أما الأذان فلا قد سبق الأذان والحمد لله، لكن السنة لك أن تقيم، فإن صليت بدون إقامة؛ فلا حرج، صلاتك صحيحة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11023/حكم-من-صلى-بدون-اذان-ولا-اقامة-لمن-فاتته-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_462/46214.mp3","categories":["الأذان والإقامة"]},{"id":12832,"question":"مستمع بعث إلى البرنامج يسأل جمعًا من الأسئلة من بينها سؤال عن الصلاة بدون إقامة، هل تصح أو لا؟","title":"حكم الصلاة بدون أذان ولا إقامة","answer":"الجواب:  نعم تصح، ولكنه يأثم إذا ترك الإقامة، الإقامة فرض كفاية، فإذا تركها يأثم، ولكن الصلاة صحيحة، وهكذا الأذان فرض كفاية، فلو صلوا بلا أذان ولا إقامة؛ صحت صلاتهم، ولكن يأثمون؛ لأن الرسول أمر بالأذان والإقامة -عليه الصلاة والسلام- نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11046/حكم-الصلاة-بدون-اذان-ولا-اقامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_463/46320.mp3","categories":["الأذان والإقامة"]},{"id":13027,"question":"السؤال الأخير يقول: لقد أحضرت خمسة عمال، وأخذت من كل واحد منهم مبلغًا من المال لقاء أتعابي، فهل المال الذي أخذته حلال، أم حرام؟","title":"حكم أخذ الإنسان مالًا من عامل استقدمه للعمل","answer":"الجواب:  إذا كان شيء مقابل ما أنفقته في تحصيل ما ينفعهم، أما إحضارهم لتأخذ مالًا منهم؛ فلا يصح، لا يجوز هذا. لكن إذا أحضرتهم، وأحسنت إليهم، وسعيت في طلب الإقامة لهم، وهم طيبون أخيار؛ فلا بأس، وليس لك أن تأخذ إلا بقدر ما صرفت عليهم في طعامهم، وشرابهم، أو في شراء حاجات لهم، أو غير هذا مما تصرفه في حاجاتهم، نعم.  المقدم: جزاكم الله خيرًا، الواقع سماحة الشيخ هناك ما يسمى بالاتجار بالعمال توجيهكم؟ الشيخ: هذا غلط، الاتجار بالعمال لا يجوز، وقد صدر قرار من هيئة كبار العلماء بمنع ذلك، وأن الواجب ألا يستقدموا إلا على الطريقة التي أوضحتها الدولة، وبينتها الدولة، فمن أراد أن يستقدم؛ فعليه أن يسلك الطرق التي رسمتها الدولة، نعم، حتى لا يضر نفسه، ولا يضر المسلمين.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11244/حكم-اخذ-الانسان-مالا-من-عامل-استقدمه-للعمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_472/47207.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":13028,"question":"من جمهورية مصر العربية المستمع: محمد الإمام عبدالرازق الشيخ، بعث يسأل عن حكم الصلاة على النبي ﷺ بعد الأذان؟","title":"حكم الصلاة على النبي ﷺ بعد الأذان","answer":"الجواب:  الصلاة على النبي ﷺ بعد الأذان سنة، يقول النبي ﷺ لما قالوا له: يا رسول الله! إن المؤذنين يفضلوننا قال: إذا سمعتم المؤذن فقولوا مثلما يقول، ثم صلوا علي فإنه من صلى علي صلاة؛ صلى الله عليه بها عشرًا، ثم سلوا الله لي الوسيلة، فإنها منزلة في الجنة، لا تنبغي إلا لعبد من عباد الله، فأرجو أن أكون أنا هو، فمن سأل لي الوسيلة؛ حلت له الشفاعة -عليه الصلاة والسلام- رواه مسلم في الصحيح. وفي صحيح البخاري -رحمه الله- عن جابر بن عبدالله الأنصاري -رضي الله تعالى عنهما- عن النبي ﷺ أنه قال: من قال حين يسمع النداء: اللهم رب هذه الدعوة التامة، والصلاة القائمة، آت محمدًا الوسيلة والفضيلة، وابعثه مقامًا محمودًا الذي وعدته؛ حلت له شفاعتي يوم القيامة وهذا فضل عظيم، زاد البيهقي بإسناد صحيح: إنك لا تخلف الميعاد. فالمقصود: أن الصلاة عليه في جميع الأوقات مستحبة، وفيها خير عظيم، قال الله -جل وعلا-: إِنَّ اللَّهَ وَمَلائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ يَا أَيُّهَا الَّذِينَ آمَنُوا صَلُّوا عَلَيْهِ وَسَلِّمُوا تَسْلِيمًا [الأحزاب:56] ويقول ﷺ: رغم أنف امرئ ذكرت عنده فلم يصل علي ﷺ ويصلى عليه في آخر الصلاة بعد التشهد الأول، وبعد التشهد الأخير، يقال: اللهم صل على محمد وعلى آل محمد، كما صليت على إبراهيم، وعلى آل إبراهيم، إنك حميد مجيد، اللهم بارك على محمد، وعلى آل محمد، كما باركت على إبراهيم، وعلى آل إبراهيم، إنك حميد مجيد في التشهد الأخير، وقد أوجب ذلك جمع من أهل العلم، وقال بعضهم: إن ذاك ركن، أما في التشهد الأول فيستحب على الصحيح فقط استحبابًا، ثم يقوم للثالثة. فالمقصود: أن الصلاة على النبي ﷺ عبادة مشروعة، بعد الأذان، وفي التشهد الأول، وفي التشهد الأخير، وعند ذكره -عليه الصلاة والسلام- وفي جميع الأوقات، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11245/حكم-الصلاة-على-النبي-ﷺ-بعد-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_472/47208.mp3","categories":["الأذان والإقامة","الأدعية والأذكار"]},{"id":13057,"question":"ننتقل إلى رسالة بعثت بها السائلة أم محمد من المنطقة الجنوبية، تقول في السؤال الأول: أيهما أفضل -يا سماحة الشيخ- صلاة النوافل، أم تلاوة القرآن الكريم، والمداومة على التلاوة يوميًا في كل يوم جزء؟ نرجو منكم الإفادة.","title":"استحباب التنويع من القربات","answer":"الجواب:  النبي ﷺ جمع بين هذا وهذا، السنة أن يكثر المسلم من التلاوة، والمسلمة مع الصلاة، مع صلاة النافلة، صلاة الضحى، التهجد بالليل، صلاة الرواتب، ويقرأ ما تيسر جزءًا، أو أكثر، أو أقل، الحمد لله، يجمع بين الخيرين. لا يقتصر على الصلاة وحدها، ولا على القراءة وحدها، بل يجمع بين الخيرين، ويجتهد في القراءة في الليل والنهار جزءًا، أو أكثر، أو أقل، ويصلي ما شرع الله من صلاة الضحى الرواتب، التهجد بالليل حتى يجمع بين الخيرين، وهكذا كان النبي ﷺ يفعل، والصحابة يجتهدون بالقراءة، وفي الصلاة جميعًا. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11274/استحباب-التنويع-من-القربات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_505/50517.mp3","categories":["الأذان والإقامة"]},{"id":13116,"question":"إذا دخلت المسجد، وكان المؤذن يؤذن، فهل أقف، أم أجلس؟","title":"ما المشروع لمن دخل المسجد والمؤذن يؤذن؟","answer":"الجواب:  تقف تستمع تجيب المؤذن، ثم تصلي ركعتين، هذا السنة، تجيب المؤذن، ثم تصلي ركعتين، تجمع بين السنتين، فإن شق عليك القيام؛ تبدأ بالصلاة، تصلي ركعتين، ولو هو يؤذن والحمد لله.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11333/ما-المشروع-لمن-دخل-المسجد-والموذن-يوذن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_473/47311.mp3","categories":["الأذان والإقامة"]},{"id":13244,"question":"هل يجب على المؤذن أن يكون مستقبلًا للقبلة حين الأذان؟","title":"حكم استقبال القبلة عند الأذان","answer":"الجواب:  هو السنة، وإلا ما هو بواجب، لكن هو السنة. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/11529/حكم-استقبال-القبلة-عند-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_513/51310.mp3","categories":["الأذان والإقامة"]},{"id":13276,"question":"هذا السائل -سماحة الشيخ- سلامة مسعد مصري، ويعمل بالأردن، يقول: أرجو معرفة وإدراك العائد من مهنة الحلاقة الرجالي من أموال، هل هذا العائد من المال حرام؟ نرجو بهذا إفادة.","title":"حكم أجرة الحلاقين من حلق اللحى","answer":"الجواب:  هذا فيه تفصيل: إذا كانت الحلاقة للرأس؛ فلا بأس، والعائد منها حلال طيب، لا بأس. أما إن كان الحلاق يحلق لحى الناس؛ فهذا منكر، والعائد منها خبيث لا يجوز. فالواجب على الحلاقين أن يتقوا الله، وألا يحلقوا اللحى، ولا يقصوها، ومن قال لهم يأبون وينصحونه، يقولون له: ما يجوز، الرسول ﷺ قال: قصوا الشوارب، وأعفوا اللحى، خالفوا المشركين وقال -عليه الصلاة والسلام-: قصوا الشوارب، ووفروا اللحى، خالفوا المشركين وقال -عليه الصلاة والسلام-: جزوا الشوارب، وأرخوا اللحى، خالفوا المجوس. فالحلاق لا يحلق اللحى، ولا يقصها، وينصح من يطلب ذلك، ويمتنع من موافقته، والكسب الذي يأتي من طريق حلق اللحى خبيث، ومحرم، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11561/حكم-اجرة-الحلاقين-من-حلق-اللحى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_514/51409.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":13290,"question":"ننتقل بعد ذلك إلى رسالة وصلت من الكويت من السائل أخوكم الذي رمز لاسمه بـ(ج . س . ش) الرشيدي يقول: ما هي ثمرات غض البصر في الدنيا والآخرة، وهل من كلمة -يا سماحة الشيخ- توجهونها للشباب بهذا الخصوص؟","title":"ثمرات غض البصر","answer":"الجواب:  غض البصر من أهم المهمات، ومن أفضل الطاعات، يقول الله -جل وعلا-: قُلْ لِلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ وَيَحْفَظُوا فُرُوجَهُمْ [النور:30] وفي الحديث يقول ﷺ: من غض بصره؛ أوجده الله حلاوة يجدها في قلبه. فالمقصود: غض البصر من القربات العظيمة، ومن الواجبات؛ لأن إطلاق البصر من أسباب استحسان ما قد يقع للبصر من نساء، أو مردان فيقع الفتنة.. تقع الفتنة، فغض البصر من أهم الواجبات، ومن أعظم أسباب النجاة والسعادة. فالواجب على أهل الإيمان غض البصر، والحذر من شر النظر، وهكذا المرأة، يجب عليها غض البصر، والحذر من شر إطلاق البصر؛ ولهذا قال ﷺ في الحديث الصحيح، لما سئل عن نظر الفجأة الذي ينظر المرأة فجأة، قال: اصرف بصرك وقال لعلي: لما سأل عن النظرة قال: إن لك الأولى، وليست لك الثانية الأولى الذي وقعت فجأة لك، ما هو بهواك -يعني- لم تخترها، لكن ليست لك الثانية، يعني: لك الأولى؛ لأنك لم تقصدها، وليست لك الثانية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11575/ثمرات-غض-البصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_509/50919.mp3","categories":["الأذان والإقامة"]},{"id":13377,"question":"بعد ذلك ننتقل إلى رسالة السائل (فهد . م) من الرياض يقول في هذا الحديث: سماحة الشيخ! حديث الرسول ﷺ الذي رواه أبو هريرة  وهو قول الرسول ﷺ: لو يعلم الناس ما في النداء، والصف الأول، ثم لم يجدوا إلا أن يستهموا عليه لاستهموا عليه ما المقصود بالنداء -جزاكم الله خيرًا- الوارد في الحديث؟","title":"«لو يعلم الناس ما في النداء» ما معنى النداء؟","answer":"الجواب: النداء: هو الأذان، يعني: لو يعلمون ما فيه من الفضل؛ لاستهموا عليه؛ لاقترعوا، يعني: كل واحد يقول: أنا الذي أؤذن، دعوني أؤذن؛ لما فيه من الفضل العظيم؛ لأنه ينادي على الناس بتوحيد الله، وتعظيمه، وتكبيره، ويدعو إلى الصلاة، ويقول النبي ﷺ: أطول الناس أعناقًا يوم القيامة المؤذنون فهم يشهدون لله بالوحدانية، ولنبيه بالرسالة، ويدعون الناس إلى الصلاة والفلاح، فهو ذكر عظيم على رؤوس الأشهاد. ويقول النبي ﷺ: لا يسمع مدى صوت المؤذن شجر، ولا حجر، ولا شيء إلا شهد له يوم القيامة فضل عظيم، فلو أن الناس ... هذا الفضل، واستحضروه؛ لاستهموا لاقترعوا، يعني: كل واحد يقول: أنا الذي أؤذن حتى يحتاجوا للقرعة حتى يؤذن من خرج له القرعة، من شدة الرغبة، لكن أكثر الخلق ما عنده بصيرة، ولا يحرص على الفضائل، لكن لو أن الناس عرفوا هذا الفضل، وتأكدوه، وصارت عندهم الرغبة في الخير؛ لاستهموا على ذلك. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ، ألا يدخل في ذلك -سماحة الشيخ- إجابة النداء وهو الذهاب إلى المصلى والتبكير، ألا يدخل في الأفضلية أيضًا؟ الشيخ: هذا من باب المسارعة إلى الصلاة، هذا من باب المسارعة إلى الصلاة والمسابقة إليها، مثلما في قوله -جل وعلا-: سَابِقُوا إِلَى مَغْفِرَةٍ مِنْ رَبِّكُمْ [الحديد:21] .. وَسَارِعُوا [آل عمران:133] .. فَاسْتَبِقُوا الْخَيْرَاتِ [المائدة:48] هذا من باب المسارعة إلى الخيرات، والمسابقة إلى..، لكن لو يعلم الناس ما في النداء، والصف الأول هذا مقصوده في النداء يسعى إلى النداء. أما الصف الأول معناه المسارعة إلى الصلاة؛ حتى يكون في الصف الأول، يعني: يبكر حتى يفوز بالصف الأول، أما إذا تأخر قد لا يحصل له إلا الصف الثاني، أو الثالث، أو .. إذا كان المسجد كبيرًا، فيه ناس كثير، لكن ما يتعلق بالأذان معناه أنهم يتنافسون فيه حتى كل واحد يقول: دعوني أنا الذي أؤذن، وقد يحتاجون إلى القرعة. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11667/لو-يعلم-الناس-ما-في-النداء-ما-معنى-النداء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_515/51507.mp3","categories":["الأذان والإقامة","شروح الحديث"]},{"id":13453,"question":"على بركة الله نبدأ هذا اللقاء برسالة وصلت من السائل: محمد الشرباصي، مصري ويعمل بالسعودية، يقول في هذا  هل تجوز التواشيح قبل أذان الفجر مثل قول: يا مليح الوجه .. يا كريم الأخلاق .. يا سيدي يا رسول الله؟ وجهونا في ضوء هذا السؤال سماحة الشيخ؟","title":"حكم التواشيح قبل أذان الفجر","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فهذه التواشيح التي ذكرها السائل بدعة لا تجوز، بل السنة للمؤذن في الصبح وغيره أن يبدأ بقوله: الله أكبر، ولا يكون قبله تواشيح ولا قراءة خاصة، ولا كلام خاص، بل الأذان مستقل، يبدؤه بقوله: الله أكبر، وينهيه بـلا إله إلا الله، ولا يكون قبله شيء خاص لا تواشيح، ولا غيرها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11753/حكم-التواشيح-قبل-اذان-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_517/51701.mp3","categories":["الأذان والإقامة","البدع والمحدثات"]},{"id":13454,"question":"يقول هذا السائل أيضًا: هل يجوز أن يكون الفجر بأذان واحد وهو الأخير؟","title":"حكم الاكتفاء بالأذان الأخير في الفجر","answer":"الجواب: لا بأس، وإن أذنوا للأول فلا حرج، نعم، وإن اكتفوا بأذان الفجر فلا حرج، وإن جعلوا أذانين الأول لتنبيه الناس حتى يعلموا أن الصبح قريب، كما قال ﷺ: إذا أذن بلال ليرجع قائمكم، ويوقظ نائمكم هذا أفضل حتى ينتبه الناس، ويستعدوا للفجر، وإن اكتفوا بأذان واحد؛ فلا حرج. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11756/حكم-الاكتفاء-بالاذان-الاخير-في-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_517/51702.mp3","categories":["الأذان والإقامة"]},{"id":13455,"question":"يقول في ثالث أسئلته: هل يجوز قول: وصلى الله وسلم على سيدنا محمد، وعلى آله وصحبه وسلم، وذلك بعد الانتهاء من الأذان؟","title":"ألفاظ الصلاة على النبي ﷺ بعد الأذان","answer":"الجواب: السنة أن يصلي على النبي ﷺ بعد الأذان: اللهم صل على سيدنا، أو اللهم صل على محمد، أو على نبينا محمد، وعلى آله.. وإن أتى بالصلاة المشروعة كاملة: اللهم صل على محمد وعلى آل محمد كما صليت على إبراهيم وعلى آل إبراهيم، إنك حميد مجيد، اللهم بارك على محمد وعلى آل محمد، كما باركت على إبراهيم، وعلى آل إبراهيم إنك حميد مجيد هذا أكمل، ثم يقول: اللهم رب هذه الدعوة التامة، والصلاة القائمة، آت محمدًا -أو آت نبينا محمدًا- الوسيلة والفضيلة وابعثه مقامًا محمودًا الذي وعدته إنك لا تخلف الميعاد هذا رواه البخاري في الصحيح دون قوله: إنك لا تخلف الميعاد لكن هذه الزيادة زادها البيهقي بإسناد صحيح. وإن قال: على سيدنا. فلا حرج، النبي ﷺ كرهه لما خوطب به، يعني: أنت سيدنا، والآن لا يخاطب بهذا، قد توفي -عليه الصلاة والسلام- فالآن إذا قال: سيدنا محمد لا حرج في ذلك، هو سيد ولد آدم، يقول ﷺ: أنا سيد ولد آدم يوم القيامة ولا فخر هو خير البرية -عليه الصلاة والسلام- نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11758/الفاظ-الصلاة-على-النبي-ﷺ-بعد-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_517/51703.mp3","categories":["الأدعية والأذكار","الأذان والإقامة"]},{"id":13643,"question":"ما حكم عدم زيارة الأقارب إذا كانوا بعيدين، ولكن تكون الصلة عن طريق الهاتف لبعد المسافة؟","title":"هل تكفي صلة الرحم عن طريق الهاتف؟","answer":"الجواب: يكفي والحمد لله، صلة الرحم تكفي من طريق الهاتف، من طريق المكاتبة، من طريق تحميل بعض الأقارب السلام، والسؤال لقريبه الثاني، إذا تيسرت الزيارة بالقدم فهذا أكمل، إذا تيسرت الصلة بالقدم والزيارة وبالمال وبالشفاعات الطيبة هذا أكمل، لكن إذا ما تيسر ذلك يكفي الصلة بالمكالمة الهاتفية، وبالمكاتبة وبإعانته على قضاء دينه، أو سد حاجته، ولو من طريق إرسالها من طريق البريد، أو مع بعض الرسل الذين يحملون الصدقة أو المساعدة. المقصود: أنه يتقي الله ما استطاع في صلة الرحم على حسب التيسير؛ لأن الله أطلقها، والرسول ﷺ أطلقها بحسب التيسير، يصل أرحامه بالقدم، أو بالمكاتبة، أو بالهاتف، أو بالوصية من زيد إلى عمرو، كل هذا الحمد لله فيه الخير الكثير، وأكملها الصلة بالقدم إذا كانت ممكنة بلا محذور شرعًا. نعم. المقدم: جزاكم الله خيرًا، سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11976/هل-تكفي-صلة-الرحم-عن-طريق-الهاتف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_542/54210.mp3","categories":["الأذان والإقامة"]},{"id":13648,"question":"يقول هذا السائل: ما حكم الاستماع للأذان، وما حكم البيع حين الأذان؟","title":"حكم الاستماع للأذان والبيع أثناء الأذان","answer":"الجواب: يقول النبي ﷺ: إذا سمعتم المؤذن فقولوا مثلما يقول السنة أن يستمع للأذان، إذا سمع الأذان يستمع، ويقول كمثل قوله، إلا في الحيعلة، فيقول: لا حول ولا قوة إلا بالله. وإذا أذن المؤذن؛ ينبغي له أن يبادر بالصلاة، يتوضأ ويذهب للمسجد، وإذا كان في الجمعة؛ وجب عليه ذلك؛ لقوله -جل وعلا-: يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا نُودِيَ لِلصَّلاةِ مِنْ يَوْمِ الْجُمُعَةِ فَاسْعَوْا إِلَى ذِكْرِ اللَّهِ وَذَرُوا الْبَيْعَ [الجمعة:9]. هذا واجب، وفي غير الجمعة كذلك يشرع له في غير الجمعة إذا سمع الأذان أن يدع البيع، ويشتغل بالوضوء إن كان ما هو على وضوء حتى يتوجه إلى المسجد، يصلي مع المسلمين، فإذا كان الذي بين الإقامة والأذان لا يتسع إلا لذهابه؛ وجب عليه ذلك وجوبًا، أما إذا كان لا، فيه سعة؛ فلا مانع أن يكمل ما في يده إن كان في يده سلعة، وباعها، أو شيء لا حرج، ثم يبادر إلى الصلاة، أما في الجمعة لا، لابد إذا سمع النداء لا يفعل شيئًا يبادر، ويسارع إلى الجمعة. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11983/حكم-الاستماع-للاذان-والبيع-اثناء-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_528/52819.mp3","categories":["الأذان والإقامة"]},{"id":13784,"question":"كيف يكون الأذان الصحيح؟ وما هو رأيكم في الزيادة التي تقال بعد لا إله إلا الله؟","title":"صفة الأذان الشرعي وحكم الزيادة فيه","answer":"الجواب: الأذان الصحيح هو الذي علمه النبي ﷺ أمته، وكان يؤذن به بلال بين يديه حتى توفي عليه الصلاة والسلام، وكان يؤذن به المؤذنون في حياته في مكة والمدينة وغيرهما، وهو الأذان المعروف الآن، وهو خمسة عشر جملة: الله أكبر.. الله أكبر، الله أكبر.. الله أكبر، أشهد أن لا إله إلا الله، أشهد أن لا إله إلا الله، أشهد أن محمدًا رسول الله، أشهد أن محمدًا رسول الله، حي على الصلاة، حي على الصلاة، حي على الفلاح، حي على الفلاح، الله أكبر، الله أكبر، لا إله إلا الله. هذا هو الأذان الذي كان يؤذن به بلال بين يدي رسول الله ﷺ حتى توفاه الله.\nوفي الفجر زيادة (الصلاة خير من النوم) في الأذان الذي ينادى به بعد طلوع الفجر وهو أذان الصبح، يقول بعد الحيعلة: الصلاة خير من النوم، الصلاة خير من النوم، ثم يقول بعدها، الله أكبر الله أكبر، لا إله إلا الله، هذا خاص بأذان الفجر الذي ينادى به عند طلوع الفجر: الصلاة خير من النوم، الصلاة خير من النوم. أما ما يزيد بعض الناس حي على خير العمل، أو أشهد أن عليًا ولي الله، كذلك ما يزيد بعض الناس من الصلاة على النبي ﷺ بعد الأذان عندما يقول: لا إله إلا الله يزيد الصلاة على النبي ﷺ رافعًا بها صوته مع الأذان، أو في المكبر هذا لا يجوز هذا بدعة، ولكن يصلي على النبي ﷺ بينه وبين نفسه لا في الأذان، إذا ختم الأذان مشروع للمسلم أن يصلي على النبي ﷺ ثم يقول: اللهم رب هذه الدعوة التامة والصلاة القائمة آت محمدًا الوسيلة والفضيلة، وابعثه مقامًا محمودًا الذي وعدته إنك لا تخلف الميعاد، هذا المشروع لكل مسلم ولكل مسلمة بعد الأذان، والمؤذن كذلك إذا قال: لا إله إلا الله شرع للجميع بعد الأذان الصلاة على النبي.. اللهم صل على محمد، اللهم صل على نبينا محمد وعلى آله وأصحابه، وإن قال: اللهم صل وسلم كان أكمل على نبينا وعلى وآله وأصحابه، ثم يقول: اللهم رب هذه الدعوة التامة.. إلى آخره، لكن لا مع الأذان، بل بصوت غير صوت الأذان، صوت منخفض يسمعه من حوله لا بأس، لكن ليس مع الأذان، الأذان ينتهي إذا قال: لا إله إلا الله يقفل الميكرفون انتهى، انتهى الأذان، وإن كان في غير ميكرفون كذلك انتهى لا يلحقه شيء، ثم يصلي على النبي ﷺ بينه وبين نفسه ولا مانع أن يسمعه من حوله ليقتدي به، لما ثبت عنه ﷺ أنه قال: إذا سمعتم المؤذن فقولوا مثلما يقول ثم صلوا علي، فإنه من صلى علي واحدة صلى الله عليه بها عشرًا، ثم سلوا الله لي الوسيلة فإنها منزلة في الجنة لا تنبغي إلا لعبد من عباد الله وأرجو أن أكون أنا هو، فمن سأل لي الوسيلة حلت له الشفاعة هكذا قال عليه الصلاة والسلام، رواه مسلم في الصحيح.\nهذه سنة للجميع؛ للمؤذن والمستمع من الرجال والنساء في الحاضرة والبادية في كل مكان بعد الفراغ من الأذان يقول: اللهم صل على محمد، أو اللهم صل وسلم على نبينا محمد وعلى آله وأصحابه.. بصوت غير صوت الأذان، صوت منخفض ليس مع الأذان، ثم بعد هذا يقول: اللهم رب هذه الدعوة التامة والصلاة القائمة آت محمدًا الوسيلة والفضيلة وابعثه مقامًا محمودًا الذي وعدته، لما روى البخاري في الصحيح رحمه الله عن جابر بن عبد الله الأنصاري رضي الله عنهما عن النبي ﷺ أنه قال: من قال حين يسمع النداء: اللهم رب هذه الدعوة التامة، والصلاة القائمة آت محمدًا الوسيلة والفضيلة وابعثه مقامًا محمودًا الذي وعدته حلت له شفاعتي يوم القيامة هكذا جاء الحديث عن رسول الله عليه الصلاة والسلام، زاد البيهقي في آخره: إنك لا تخلف الميعاد بإسناد حسن، هذا هو المشروع. أما الزيادة بالأذان حي على خير العمل، أو أشهد أن عليًا ولي الله، فهذا لا يجوز.. بدعة، وهكذا الزيادة مع الأذان: الصلاة على النبي ﷺ مع لا إله إلا الله بصوت الأذان، هذا لا يجوز بل هو من البدع، ولكن مثلما تقدم يصلي على النبي ﷺ المؤذن والمستمع بصوت غير صوت الأذانان؛ صوت منخفض غير صوت الأذان.\nوفي أذان أبي محذورة الترجيع؛ والترجيع: هو أن يأتي بالشهادتين بصوت منخفض ثم يأتي بهما بصوت مرتفع، فيكون على هذا تسعة عشر جملة، يقول: أشهد أن لا إله إلا الله، أشهد أن لا إله إلا الله، أشهد أن محمدًا رسول الله، أشهد أن محمدًا رسول الله، بصوت منخفض ثم يرفع صوته بهما ويعيدهما، هذا يقال له: الترجيع، وهذا علمه النبي ﷺ أبا محذورة وكان يؤذن به في مكة ، فإذا فعله فلا بأس، نوع من أنواع الأذان الشرعي، ولكن الأفضل هو أذان بلال الذي كان يؤذن بين يدي النبي عليه الصلاة والسلام، كان بلال يؤذن من دون ترجيع بين يدي النبي عليه الصلاة والسلام في المدينة حتى توفى الله نبيه عليه الصلاة والسلام، وكلا النوعين الحمد لله مشروع وجائز، إلا أن الأفضل هو ما كان يفعل بين يديه عليه الصلاة والسلام وهو عدم الترجيع ومن رجع فلا بأس. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12155/صفة-الاذان-الشرعي-وحكم-الزيادة-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_601/60106.mp3","categories":["الأذان والإقامة"]},{"id":13873,"question":"يقول السائل: هل من السنة قراءة القرآن من المصحف وأنا في انتظار الصلاة بالمسجد؟ نرجو منكم إفادة.","title":"هل من السنة قراءة القرآن عند انتظار الصلاة؟","answer":"الجواب: الأمر في هذا واسع، إن قرأ فلا بأس، وإن جلس ينتظر ويدعو فلا بأس، إن جلس بين الأذان والإقامة يدعو أو قرأ القرآن لكن من غير جهر يشوش على من حوله من المصلين والقراء، كله حسن إن شاء الله، الأمر واسع.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/12270/هل-من-السنة-قراءة-القران-عند-انتظار-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_506/50607.mp3","categories":["الأذان والإقامة"]},{"id":13887,"question":"يقول السائل: هل من السنة قراءة القرآن من المصحف وأنا في انتظار الصلاة بالمسجد؟ نرجو منكم إفادة.","title":"هل من السنة قراءة القرآن عند انتظار الصلاة؟","answer":"الجواب: الأمر في هذا واسع، إن قرأ فلا بأس، وإن جلس ينتظر ويدعو فلا بأس، إن جلس بين الأذان والإقامة يدعو أو قرأ القرآن لكن من غير جهر يشوش على من حوله من المصلين والقراء، كله حسن إن شاء الله، الأمر واسع.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/12270/هل-من-السنة-قراءة-القران-عند-انتظار-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_506/50607.mp3","categories":["الأذان والإقامة"]},{"id":14214,"question":"في سؤاله هذا يقول هذا السائل مصطفى عبد القادر سماحة الشيخ: تجديد الوضوء هل هو أفضل؟ أو الاعتكاف في مسجد؟ أو قراءة القرآن؟ أو تصلي السنة؟ أيهما أولى في هذه الأمور قبل إقامة الصلاة؟","title":"ما الأولى قبل الإقامة تجديد الوضوء أو قراءة القرآن؟","answer":"الجواب: تجديد الوضوء مستحب، إذا كان قد توضأ سابقًا إذا جدده فهو أفضل ولا يلزمه تجديد الوضوء، والسنة له أن يتقدم إلى الصلاة وجلوسه في المسجد ينتظر الصلاة فيه خير عظيم، وإذا سمي اعتكاف فلا بأس؛ لأن اللبث في المسجد يسمى اعتكاف إذا نواه اعتكافًا، فإن انتظاره الصلاة أو الجلوس في المسجد يقرأ هذه قربة إلى الله جل وعلا، فالمؤمن يتقرب إلى الله بما شرع، فإذا قصد المسجد ليقرأ فيه ويتعبد ويصلي ونواه اعتكافًا سواءً ساعة أو ساعتين أو يوم أو يومين كله لا بأس، ولكن عليه أن يحافظ على الصلاة في الجماعة في أوقاتها ويحذر التخلف عن ذلك، وإذا أراد تجديد الوضوء يعني توضأ للظهر ثم أراد أن يجدد للعصر أو المغرب فهذا أفضل، وإن صلى بالوضوء السابق فلا حرج، والحمد لله.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12664/ما-الاولى-قبل-الاقامة-تجديد-الوضوء-او-قراءة-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_548/54815.mp3","categories":["الأذان والإقامة"]},{"id":14223,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع عبد الله حسان الطاهر سوداني ويعمل في الخرج، الأخ عبد الله يسأل عن الكيفية الصحيحة للأذان إذ أنه سمع أن هناك طرقًا متعددة وقرأ عنها أيضًا ويرجو من سماحة الشيخ التوجيه. جزاكم الله خيرًا.","title":"ما الكيفية الصحيحة للأذان؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فقد ثبت عن النبي ﷺ الأذان على أنواع أفضلها ما كان يفعله بلال بين يدي النبي عليه الصلاة والسلام حتى توفاه الله وهو الأذان المعروف اليوم بين الناس وهو خمسة عشر جملة: الله أكبر الله أكبر الله أكبر الله أكبر، أشهد أن لا إله إلا الله، أشهد أن لا إله إلا الله، أشهد أن محمدًا رسول الله، أشهد أن محمدًا رسول الله، حي على الصلاة حي على الصلاة، حي على الفلاح حي على الفلاح، الله أكبر الله أكبر، لا إله إلا الله، هذا هو الأذان الذي كان يؤذن به بلال بين يدي النبي عليه الصلاة والسلام.\nوثبت في الصحيحين من حديث أنس  قال: أمر بلال أن يشفع الأذان ويوتر الإقامة يشفع الأذان: يعني ثنتين ثنتين هذا شفع الأذان ما عدا التكبير الأول فإنه أربع كما ثبت عنه عليه الصلاة والسلام أنه علَّم بلالاً ذلك بعدما رأى الرؤيا الصالحة المعروفة عبد الله بن زيد ، لكن في أذان الفجر يزيد جملتين: الصلاة خير من النوم، الصلاة خير من النوم، فيكون الأذان في الفجر سبعة عشر جملة، الأذان عند طلوع الفجر يقول فيه: الصلاة خير من النوم، الصلاة خير من النوم، بعد الحيعلة ثم بعدها يقول: الله أكبر الله أكبر، لا إله إلا الله، والأفضل أن يكون في الأذان الأخير ويسمى الأذان الأول بالنسبة إلى الإقامة، وأما الأذان الأول الذي يكون في آخر الليل هذاك ليس فيه الصلاة خير من النوم على الراجح، والأفضل يكون في الأخير وهذا الأخير يسمى الأذان الأول بالنسبة للإقامة؛ لأن الإقامة أذان ثاني والأذان بعد طلوع الفجر هو الأذان الأول وهو الذي جاء في الأحاديث أنه يقال فيه: الصلاة خير من النوم، الصلاة خير من النوم، كما في حديث بلال وحديث أبي محذورة، وقد ظن بعض الناس أن تسميته الأول أنه يراد به الأذان اللي في آخر الليل وليس كذلك، سمي أولاً؛ لأنه يكون قبل الإقامة والإقامة هي الأذان الثاني كما في الحديث الصحيح يقول عليه الصلاة والسلام: بين كل أذانين صلاة الأذانين يعني: الأذان والإقامة. وجاء في حديث أبي محذورة نوع آخر وهو تكرار الشهادة ..... الشهادتين مرة أخرى فيكون تسعة عشر جملة، يأتي بالشهادتين ثم يعيدها يأتي بها بصوت منخفض: أشهد أن لا إله إلا الله، أشهد أن لا إله إلا الله، أشهد أن محمدًا رسول الله، أشهد أن محمدًا رسول الله، ثم يعيدها بصوت أرفع حتى تكون الجمل تسعة عشر وهذا صحيح لا بأس به، علمه النبي ﷺ أبا محذورة وأذن به في مكة فلا حرج في ذلك، لكن الأفضل ما عليه العمل اليوم وهو الذي كان يؤذن به بلال بين يدي النبي عليه الصلاة والسلام. وهكذا الإقامة أفراد كما في حديث أنس المتقدم: أمر بلال أن يشفع الأذان ويوتر الإقامة يوتر أي: يفرد الإقامة إلا التكبير فإنه مثنى فيها كما في حديث عبد الله بن زيد وحديث بلال، يقول في أول الإقامة: الله أكبر الله أكبر، وفي آخرها: الله أكبر الله أكبر، والبقية أفراد: أشهد أن لا إله إلا الله، أشهد أن محمدًا رسول الله، حي على الصلاة حي على الفلاح؛ أفراد، والإقامة يكررها: قد قامت الصلاة قد قامت الصلاة، يثنيها في الإقامة كالتكبير في أولها وفي آخرها في المثنى التكبير مرتان في أولها وفي آخرها كذلك، وهكذا قوله: قد قامت الصلاة قد قامت الصلاة، يقولها مرتين، أما الشهادتان والحيعلة مرة مرة، وجاء في حديث أبي محذورة التكرار الشهادتين مرتين كالأذان ولا حرج في ذلك إنما هو أفضلية فقط، وهذا يقال له: اختلاف التنوع، ولكن الأفضل مثلما تقدم ما في حديث بلال . نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12679/ما-الكيفية-الصحيحة-للاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_617/61701.mp3","categories":["الأذان والإقامة"]},{"id":14226,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع عبد الله حسان الطاهر سوداني ويعمل في الخرج، الأخ عبد الله يسأل عن الكيفية الصحيحة للأذان إذ أنه سمع أن هناك طرقًا متعددة وقرأ عنها أيضًا ويرجو من سماحة الشيخ التوجيه. جزاكم الله خيرًا.","title":"ما الكيفية الصحيحة للأذان؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فقد ثبت عن النبي ﷺ الأذان على أنواع أفضلها ما كان يفعله بلال بين يدي النبي عليه الصلاة والسلام حتى توفاه الله وهو الأذان المعروف اليوم بين الناس وهو خمسة عشر جملة: الله أكبر الله أكبر الله أكبر الله أكبر، أشهد أن لا إله إلا الله، أشهد أن لا إله إلا الله، أشهد أن محمدًا رسول الله، أشهد أن محمدًا رسول الله، حي على الصلاة حي على الصلاة، حي على الفلاح حي على الفلاح، الله أكبر الله أكبر، لا إله إلا الله، هذا هو الأذان الذي كان يؤذن به بلال بين يدي النبي عليه الصلاة والسلام.\nوثبت في الصحيحين من حديث أنس  قال: أمر بلال أن يشفع الأذان ويوتر الإقامة يشفع الأذان: يعني ثنتين ثنتين هذا شفع الأذان ما عدا التكبير الأول فإنه أربع كما ثبت عنه عليه الصلاة والسلام أنه علَّم بلالاً ذلك بعدما رأى الرؤيا الصالحة المعروفة عبد الله بن زيد ، لكن في أذان الفجر يزيد جملتين: الصلاة خير من النوم، الصلاة خير من النوم، فيكون الأذان في الفجر سبعة عشر جملة، الأذان عند طلوع الفجر يقول فيه: الصلاة خير من النوم، الصلاة خير من النوم، بعد الحيعلة ثم بعدها يقول: الله أكبر الله أكبر، لا إله إلا الله، والأفضل أن يكون في الأذان الأخير ويسمى الأذان الأول بالنسبة إلى الإقامة، وأما الأذان الأول الذي يكون في آخر الليل هذاك ليس فيه الصلاة خير من النوم على الراجح، والأفضل يكون في الأخير وهذا الأخير يسمى الأذان الأول بالنسبة للإقامة؛ لأن الإقامة أذان ثاني والأذان بعد طلوع الفجر هو الأذان الأول وهو الذي جاء في الأحاديث أنه يقال فيه: الصلاة خير من النوم، الصلاة خير من النوم، كما في حديث بلال وحديث أبي محذورة، وقد ظن بعض الناس أن تسميته الأول أنه يراد به الأذان اللي في آخر الليل وليس كذلك، سمي أولاً؛ لأنه يكون قبل الإقامة والإقامة هي الأذان الثاني كما في الحديث الصحيح يقول عليه الصلاة والسلام: بين كل أذانين صلاة الأذانين يعني: الأذان والإقامة. وجاء في حديث أبي محذورة نوع آخر وهو تكرار الشهادة ..... الشهادتين مرة أخرى فيكون تسعة عشر جملة، يأتي بالشهادتين ثم يعيدها يأتي بها بصوت منخفض: أشهد أن لا إله إلا الله، أشهد أن لا إله إلا الله، أشهد أن محمدًا رسول الله، أشهد أن محمدًا رسول الله، ثم يعيدها بصوت أرفع حتى تكون الجمل تسعة عشر وهذا صحيح لا بأس به، علمه النبي ﷺ أبا محذورة وأذن به في مكة فلا حرج في ذلك، لكن الأفضل ما عليه العمل اليوم وهو الذي كان يؤذن به بلال بين يدي النبي عليه الصلاة والسلام. وهكذا الإقامة أفراد كما في حديث أنس المتقدم: أمر بلال أن يشفع الأذان ويوتر الإقامة يوتر أي: يفرد الإقامة إلا التكبير فإنه مثنى فيها كما في حديث عبد الله بن زيد وحديث بلال، يقول في أول الإقامة: الله أكبر الله أكبر، وفي آخرها: الله أكبر الله أكبر، والبقية أفراد: أشهد أن لا إله إلا الله، أشهد أن محمدًا رسول الله، حي على الصلاة حي على الفلاح؛ أفراد، والإقامة يكررها: قد قامت الصلاة قد قامت الصلاة، يثنيها في الإقامة كالتكبير في أولها وفي آخرها في المثنى التكبير مرتان في أولها وفي آخرها كذلك، وهكذا قوله: قد قامت الصلاة قد قامت الصلاة، يقولها مرتين، أما الشهادتان والحيعلة مرة مرة، وجاء في حديث أبي محذورة التكرار الشهادتين مرتين كالأذان ولا حرج في ذلك إنما هو أفضلية فقط، وهذا يقال له: اختلاف التنوع، ولكن الأفضل مثلما تقدم ما في حديث بلال . نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12679/ما-الكيفية-الصحيحة-للاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_617/61701.mp3","categories":["الأذان والإقامة"]},{"id":14228,"question":"يقول في سؤاله الثاني: نرجو من سماحة الشيخ توضيحًا مفصلًا لحدود حرم المدينة النبوية حيث اتسعت رقعة العمران ولا يدري بعض السكان -سكان المدينة- أهو داخل الحرم أم خارجه؟","title":"حدود حرم المدينة","answer":"الجواب: قد بلغني أنها وضعت حدود، والنبي ﷺ قال: ما بين عير إلى ثور عير في جهة وثور في جهة حول أحد، وفي بعضها: ما بين لابتيها وقد بلغني أنه وضعت حدود الآن توضح الحرم -حرم المدينة- وفي الإمكان سؤال العلماء في المدينة؛ لأن هناك حدود قد.. حين وجودي في المدينة في الجامعة هناك يعني اهتمام بوضع الحدود اللازمة ولعلها وضعت. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12685/حدود-حرم-المدينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_549/54902.mp3","categories":["الأذان والإقامة"]},{"id":14230,"question":"مسجد قباء هل هو داخل حدود حرم المدينة أم خارجها؟","title":"هل مسجد قباء داخل حدود الحرم؟","answer":"الجواب: الذي أذكر أنه داخل الحدود؛ داخل الحرم، الذي أذكر وغالب على ظني أنه داخل الحدود؛ حدود الحرم، هذا غالب ظني أنه داخل الحدود. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12688/هل-مسجد-قباء-داخل-حدود-الحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_549/54903.mp3","categories":["الأذان والإقامة"]},{"id":14300,"question":"تقول السائلة: هل جميع الأعمال التي يتعدى نفعها إلى الغير هي أفضل من الأعمال التي هي مقتصرة على النفع للنفس؟ أم أن هناك ميزانًا آخر للتفاضل؟ وهل هناك حالات تكون الأفضلية للأعمال المقتصرة على النفع للنفس دون الأعمال التي تتعدى للغير؟","title":"ما معيار التفاضل في الأعمال؟","answer":"الجواب: هذه مسائل تخضع للأدلة الشرعية، فإن الأعمال فيها المتعدي وفيها القاصر، فالصلاة أمرها قاصر وهي أفضل الأعمال بعد الشهادتين وأوجب الأعمال بعد الشهادتين، ومع ذلك هي عمل قاصر على صاحبه، وأجره لصاحبه ليس بمتعدي، والزكاة متعدية والصلاة أفضل منها، هذه أمور تخضع للأدلة الشرعية.","link":"https://binbaz.org.sa/fatwas/12769/ما-معيار-التفاضل-في-الاعمال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_550/55002.mp3","categories":["الأذان والإقامة"]},{"id":14356,"question":"ما معنى المواقيت في الحج؟ وهل للميقات حدود مكانية لا يجوز تجاوزها ولو بمسافة بسيطة جدًا؟","title":"معنى المواقيت في الحج","answer":"الجواب: المواقيت قسمان: مواقيت مكانية، ومواقيت زمانية؛ فالمواقيت المكانية للحج، المواضع التي أمر النبي ﷺ بالإحرام منها، يقال لها: مواقيت، هذا من أراد الحج أو العمرة إذا مر عليها أن يحرم منها، يقول ﷺ لما وقت المواقيت وقت لأهل المدينة ذا الحليفة، مكان معروف يسمى أبيار علي الآن، ووقت لأهل الشام وأهل مصر والمغرب ونحوهم الجحفة، وهي في رابغ، محل رابغ الذي يعرف برابغ، يحرم الناس من رابغ، يلي الجحفة، ووقت لأهل المشرق ذات عرق، ووقت لأهل نجد وادي قرن، يسمى السيل، ووقت لأهل اليمن يلملم، هذه مواقيت مكانية إذا مر عليها من يريد الحج والعمرة يحرم منها، الذي يأتي من المدينة يحرم من ذي الحليفة، من الشام من جحفة، من اليمن من يلملم، من العراق من ذات عرق، من نجد أو الطائف من السيل، من وادي قرن، هذه يقال لها: المواقيت المكانية. وإذا مر بها وهو ما أراد الحج ولا العمرة ما عليه شيء، مثل ذهب مكة للتجارة، ما أراد الحج ولا العمرة، لا بأس لا يحرم، لا يلزمه إحرام؛ لأنه ما ذهب لحج ولا عمرة، إنما ذهب إلى مكة للتجارة، أو ليزور قريبًا له، أو ما أشبه ذلك، لكن من أراد الحج والعمرة يحرم من هذه المواقيت؛ لقول ابن عباس -رضي الله عنهما-: «وقت النبي ﷺ لأهل المدينة الحليفة، ولأهل الشام الجحفة، ولأهل نجد قرن المنازل، ولأهل اليمن يلملم، قال: هن لهن، ولمن أتى عليهن، من غير أهلهن، ممن أراد الحج والعمرة، ومن كان دون ذلك فمهله من حيث أنشأ. الذي نازل في مكان دون هذه المواقيت مثل أهل جدة، إذا أرادوا الحج أو العمرة أحرموا من جدة، أو أهل.....، أو البحرة، يحرمون من مكانهم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12830/معنى-المواقيت-في-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_551/55105.mp3","categories":["الأذان والإقامة"]},{"id":14357,"question":"رسالة وصلت إلى البرنامج من المستمع عبدالله حامد عبود، ضمنها جمعًا من الأسئلة، في أحد أسئلته يقول: المتوفون في حوادث السيارات هل هم شهداء؟","title":"من مات بحادث سيارة يرجى له شهادة","answer":"الجواب: يرجى لهم الشهادة؛ لأنه من جنس صاحب الهدم، صاحب الهدم شهيد، صاحب الغرق شهيد، وصاحب الحادث بالسيارة الذي يصدم، أو تنقلب به السيارة حتى يموت هو من جنس صاحب الهدم، نرجو له الشهادة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12837/من-مات-بحادث-سيارة-يرجى-له-شهادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_623/62314.mp3","categories":["الأذان والإقامة"]},{"id":14740,"question":"ننتقل إلى مواضيع أخرى عبر رسائل من المستمعين الكرام، فهذه رسالة وصلت إلى البرناج من سلطنة عمان، وباعثها المستمع (س. ف. ح) أخونا يقول: استقدمت أحد العمال من الخارج للعمل لدي، وبعد مدة توفي، وتحملت نفقة تجهيزه، وترحيل جثمانه إلى بلده بما يزيد على خمسة آلاف ريال، هل علي شيء بعد ذلك تجاهه لتبرأ ذمتي؟","title":"ما يجب على صاحب العامل إذا توفي أحد عماله؟","answer":"الجواب: عليك أن تسلم لأهله الأجور التي عندك، إذا كان له أجور عندك بقايا أجور أو تركة عندك، عليك أن تسلم جميع أمواله التي عندك، من أجور، أو تركة له من نقود، أو متاع عليك أن تسلم ذلك.  أما ما أنفقته في تجهيزه فأنت أعلم بنيتك، إن كنت أنفقت ذلك تبرعًا منك، فجزاك الله خيرًا، وليس لك الرجوع بذلك، وإن كنت ما أنفقت بنية الرجوع فلك أن ترجع بما أنفقت في كفنه وحفر قبره، ونحو ذلك. أما تجهيزه إلى أهله فليس لك الرجوع، لأنه ليس واجبًا أن يرجع إلى أهله، لو دفنته مع المسلمين في بلدك، كفى، إلا إذا كان أهله طلبوا منك ذلك، ووافقوا على أن تأخذ قيمة تجهيز السفر من ماله فلا بأس، وإلا فليس عليك أن تجهزه إلى بلده، بل الواجب أن يدفن مع المسلمين في عمان، كما لو مات في مكة أو المدينة أو غير ذلك، يدفن مع المسلمين، ولا يرسل إلى بلاده، لكن لو طلب أهله إرساله إلى بلاده، والتزموا بالنفقة، أو سمحوا بأخذ النفقة من التركة فلا بأس، مع أن ترك ذلك أفضل، كونه يدفن مع المسلمين، ولا يسفر أولى من التكلف، هذا هو الأولى، إنما يتكلف في ذلك إذا كان في بلاد الكفار، في بلاد لا يدفن فيها المسلم هذا لا بأس في نقله إلى بلد مسلم، أو إلى أهله، أو سمح أهله بنقله إليهم لمصلحة رأوها يكون على حسابهم، على حساب من سمح بذلك من طلب نقله، والتزم بقيمة التذاكر، أما أنت فلا يلزمك ذلك لكن إذا تبرعت بذلك فليس لك الرجوع. المقدم: بارك الله فيكم.\nإذا كان ذلك العامل غير مسلم؟\nالشيخ: إذا كان العامل غير مسلم لا يكفن، ولا يصلى عليه، ولا يجهز إلى بلاد قومه يدفن مع الكفار إن كان في بلدك فيها كفار، أو يحفر له في محل بعيد عن المسلمين، ويدفن في محل بعيد في الصحراء، ويواسى قبره وانتهى الأمر، ولا يصلى عليه ولا يغسل ولا يكفن، بل يدفن فيما تيسر من الثياب الساترة. المقدم: يستر في ثياب، ويدفن بعيدًا عن مقابر المسلمين؟ الشيخ: هكذا هكذا، نعم. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/13258/ما-يجب-على-صاحب-العامل-اذا-توفي-احد-عماله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_630/nour_63008.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":14757,"question":"الأخت سلوى من جدة، بعثت برسالة تقول فيها:إذا سمع السامع الأذان أكثر من مرة لفرض واحد، فهل يردد ما يقول المؤذنون، أم يكتفي بالترديد خلف مؤذن واحد؟","title":"حكم إجابة أكثر من مؤذن في الفرض الواحد","answer":"الجواب: السنة أن يجيب الجميع، السنة أن يجيب الجميع؛ لقول النبي ﷺ: إذا سمعتم المؤذن فقولوا مثلما يقول فهذا عام يعم جميع المؤذنين، فيقول مثل قوله إلا عند الحيعلة عند (حي على الصلاة) يقول: (لا حول ولا قوة إلا بالله) وإذا ختم الأذان يصلي على النبي ﷺ ثم يقول: اللهم رب هذه الدعوة التامة، والصلاة القائمة، آت محمدًا الوسيلة والفضيلة، وابعثه مقامًا محمودًا الذي وعدته، إنك لا تخلف الميعاد رواه البخاري في الصحيح، لكن بغير زيادة: إنك لا تخلف الميعاد أما هذه الزيادة فرواها البيهقي بإسناد حسن، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13268/حكم-اجابة-اكثر-من-موذن-في-الفرض-الواحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_638/nour_63806.mp3","categories":["الأذان والإقامة"]},{"id":14858,"question":"يسأل أيضًا ويقول: إذا أذن مؤذن في البلدة أذان الفجر الأول والثاني، وجاء في اليوم الثاني، فعندما أذن الأذان الأول قاموا برشقه بالحجارة أهل البلد، هل يجوز قطع الأذان ليدافع عن نفسه، أم ماذا يعمل؟","title":"حكم قطع الأذان للدفاع عن النفس","answer":"الجواب: يستحب أن يكون هناك أذان أول للصبح حتى ينتبه الناس، يقول النبي ﷺ في أذان بلال قبل الصبح: ليوقظ نائمكم، ويرجع قائمكم للتنبيه أن الصبح قريب.  أما الأذان الواجب فهو بعد الصبح هذا فرض كفاية إذا قام به من يكفي سقط عن الباقين، إذا طلع الفجر يؤذن حتى يعلم الناس طلوع الفجر، وحتى يحضروا لصلاة الجماعة في المساجد.  والذي يؤذي من يؤذن الأول هذا له حالان: إحداهما: أن يكون الأذى يمكن تلافيه بعد فراغ الأذان، فهذا لا يقطع يكمل أذانه، ولا بأس يشتكيهم وإلا..، أما إذا كانوا يؤذنه في الأذان ربما ناله الحجر ربما أصابوه فله أن يقطع الأذان، ويدافع عن نفسه، ولا حرج في ذلك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13382/حكم-قطع-الاذان-للدفاع-عن-النفس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_639/nour_63904.mp3","categories":["الأذان والإقامة"]},{"id":14860,"question":"كم يكون الوقت الفارق بين الأذان الأول والأذان الثاني سماحة الشيخ؟","title":"كم الوقت بين الأذان الأول والثاني في الفجر؟","answer":"الجواب: الأفضل أن يكون قريبًا، جاء في بعض الروايات أنه «ليس بينهما إلا أن يصعد هذا، وينزل هذا» يعني قريب.\nالمقدم: قريب جدًا. الشيخ: يكون الأذان قبل نصف ساعة، أو ما يشبه ذلك حتى ينتبه الناس أن الوقت قريب، والذي في الصلاة حتى يبادر بالإيتار، ونحو ذلك، نعم. المقدم: جزاكم الله خيرًا، أما الأذان في منتصف الليل أو في الواحدة ليلًا؟ الشيخ: ما ينبغي، لا، يكون قريبًا من الفجر. المقدم: يكون قريبًا من الفجر.\nالشيخ: حتى تحصل الفائدة من التنبيه. المقدم: بارك الله فيكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13384/كم-الوقت-بين-الاذان-الاول-والثاني-في-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_639/nour_63905.mp3","categories":["الأذان والإقامة"]},{"id":14881,"question":"المستمع بشير مرغني، بعث برسالة يقول فيها: لدينا في قريتنا جماعة أنصار السنة المحمدية، أخونا يبدو أنه من السودان، ولهم مسجد وفي أذان الفجر، يقولون: (الصلاة خير من النوم) في الأذان الأول. علمًا بأن المساجد تقولها في الأذان الثاني، وبسؤالنا لهم قالوا لنا: هذا هو الأصل، حيث أنهم قدموا لنا الدليل من كتاب زاد المعاد، وقلنا لهم: هذا رأي الإجماع كما قال العلماء، فقالوا: إذا كان الإجماع مخالف للأصل فلا يتبع، أرجو أن تفيدونا بالصواب. جزاكم الله خيرًا.","title":"في أي الأذانين تُقال: \"الصلاة خير من النوم\"؟","answer":"الجواب: ليس في المسألة إجماع فيما نعلم، وإذا فعلوا ذلك في الأول، أو في الثاني، فلا حرج -إن شاء الله-، المهم أنه لا يكون في الاثنين، يكون في أحدهما حتى لا تلتبس الأمور على الناس، والأفضل أن يكون في الأخير، هذا هو الأفضل؛ لأن الأحاديث الصحيحة تدل على أنه في الأخير، وهو الأذان بعد طلوع الفجر، وسمي في بعض الأحاديث الأول؛ لأنه أول بالنسبة إلى الإقامة، فلهذا ظن بعض إخواننا من أنصار السنة أن المراد بالأول الذي يكون قبل الفجر، وليس الأمر كذلك، الأول هو الذي بعد طلوع الفجر وسمي أولًا؛ لأنه بعده الأذان الثاني وهو الإقامة.  وهكذا جاء في حديث أبي محذورة الأول، وأبو محذورة يؤذن بعد الصبح، فسمي أولًا في أذانه، يعني: خلاف الأذان الأخير، وهو الإقامة، وهكذا أخبرت عائشة -رضي الله عنها- كما في البخاري -رحمه الله- في صحيح البخاري أن الأذان الأول هو الأذان الذي بعد طلوع الفجر، الذي بعده تصلى الراتبة، كان النبي ﷺ بعد الأذان الأول يصلي الراتبة، ثم يخرج إلى الصلاة، فسمته أولًا؛ لأن بعده الأذان الثاني، وهو الإقامة، فينبغي أن يفهم هذا جيدًا حتى يزول الإشكال، وحتى تجتمع الكلمة بين إخواننا في السودان، فيكون قول: (الصلاة خير من النوم) في الأذان الأخير عند الجميع؛ حتى لا يختلفوا، وهذا هو الأفضل والأولى. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13377/في-اي-الاذانين-تقال-الصلاة-خير-من-النوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_645/nour_64520.mp3","categories":["الأذان والإقامة"]},{"id":14940,"question":"سؤاله الثاني يقول: هل الأذان والرجل لابس للحذاء مكروه أم حرام؟نرجو الإفادة، ولكم من الله الشكر.","title":"حكم الأذان مع لبس النعلين","answer":"الجواب: الأذان والإنسان لابس النعلين ليس فيه بأس لا مكروه، ولا حرام، بل جائز، ولا بأس به، أن يصلي في نعليه كيف بالأذان؟! الرسول صلى في نعليه -عليه الصلاة والسلام-، الأذان غير الصلاة، فإذا كان جازت الصلاة في النعلين، فالأذان من باب أوْلى.  فالحاصل: أنه لا حرج في ذلك، نعم.","link":"https://binbaz.org.sa/fatwas/13439/حكم-الاذان-مع-لبس-النعلين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_647/nour_64707.mp3","categories":["الأذان والإقامة"]},{"id":15047,"question":"يقول: إذا كنت أصلي، وسمعت الأذان، هل أكمل صلاتي أم أعيدها أم أقف حتى انتهاء الأذان؟","title":"ماذا يفعل من أذن المؤذن وهو يصلي الفرض؟","answer":"الجواب: المصلي يستمر في صلاته، ولا يجيب المؤذن، المصلي مشغول بالصلاة، فإذا أذن المؤذن وأنت في الصلاة؛ تكمل الصلاة، ولا تجيب المؤذن، نعم. المقدم: ولكن لو كانت هذه فرضًا مثلًا، والأذان على أول الوقت؟ الشيخ: هذا شيء آخر، إذا كان في الفريضة، لا يصليها إلا بعد التحقق من دخول الوقت، إذا كان مريضًا في البيت مثلًا، أو له مانع من الصلاة مع المسلمين في المساجد؛ لخوف، أو مرض؛ فإنه يصلي بعد دخول الوقت، ولو ما بعد أذن؛ لأن بعض المؤذنين قد يؤخر، قد يؤخر الأذان، ويفوت بعض الوقت، فإذا تحقق أن الوقت دخل؛ ساغ له أن يصلي فريضته، وإن كان لم يسمع أذانًا، كالمريض في بيتٍ بعيد عن المؤذنين، أو الخائف، أو المسافر الذي لا يسمع الأذان، متى تحقق الوقت؛ صلى، لكن المسافر السنة له أن يؤذن قبل الصلاة، إذا تحقق الوقت يؤذن، ثم يقيم ويصلي، لكن من كان في البلد ليس له أن يصلي إلا بعد دخول الوقت، وإذا دخل الوقت وعلمه؛ جاز له أن يصلي، وإن لم يسمع الأذان، نعم.","link":"https://binbaz.org.sa/fatwas/13559/ماذا-يفعل-من-اذن-الموذن-وهو-يصلي-الفرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_654/nour_65404.mp3","categories":["وقت الصلاة","الأذان والإقامة"]},{"id":15050,"question":"يقول: إذا كنت أصلي، وسمعت الأذان، هل أكمل صلاتي أم أعيدها أم أقف حتى انتهاء الأذان؟","title":"ماذا يفعل من أذن المؤذن وهو يصلي الفرض؟","answer":"الجواب: المصلي يستمر في صلاته، ولا يجيب المؤذن، المصلي مشغول بالصلاة، فإذا أذن المؤذن وأنت في الصلاة؛ تكمل الصلاة، ولا تجيب المؤذن، نعم. المقدم: ولكن لو كانت هذه فرضًا مثلًا، والأذان على أول الوقت؟ الشيخ: هذا شيء آخر، إذا كان في الفريضة، لا يصليها إلا بعد التحقق من دخول الوقت، إذا كان مريضًا في البيت مثلًا، أو له مانع من الصلاة مع المسلمين في المساجد؛ لخوف، أو مرض؛ فإنه يصلي بعد دخول الوقت، ولو ما بعد أذن؛ لأن بعض المؤذنين قد يؤخر، قد يؤخر الأذان، ويفوت بعض الوقت، فإذا تحقق أن الوقت دخل؛ ساغ له أن يصلي فريضته، وإن كان لم يسمع أذانًا، كالمريض في بيتٍ بعيد عن المؤذنين، أو الخائف، أو المسافر الذي لا يسمع الأذان، متى تحقق الوقت؛ صلى، لكن المسافر السنة له أن يؤذن قبل الصلاة، إذا تحقق الوقت يؤذن، ثم يقيم ويصلي، لكن من كان في البلد ليس له أن يصلي إلا بعد دخول الوقت، وإذا دخل الوقت وعلمه؛ جاز له أن يصلي، وإن لم يسمع الأذان، نعم.","link":"https://binbaz.org.sa/fatwas/13559/ماذا-يفعل-من-اذن-الموذن-وهو-يصلي-الفرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_654/nour_65404.mp3","categories":["وقت الصلاة","الأذان والإقامة"]},{"id":15066,"question":"السائلة (أ. س) من جدة تقول: هل يشرع للنساء أذان وإقامة، سواء كن في الحضر أو السفر أو البرية؟","title":"هل يشرع للنساء الأذان والإقامة؟","answer":"الجواب: لا يشرع لهن أذان ولا إقامة، هذا من خصائص الرجال، الأذان والإقامة من خصائص الرجال، تصلي بدون أذان وبدون إقامة، والحمد لله، نعم.","link":"https://binbaz.org.sa/fatwas/13553/هل-يشرع-للنساء-الاذان-والاقامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_563/56315.mp3","categories":["الأذان والإقامة","قضايا المرأة"]},{"id":15090,"question":"سؤاله الأخير طويل جدًا، يقول فيه: إنه عرض علي تاجر العمل معه في محل، بقالة، واتفق معي على أن يعمل هو صباحًا، وأنا أعمل مساءً، وحدد لي المصروف اليومي على أساس أن يكون هناك جرد كل ثلاثة شهور، فإذا كان العمل رابحًا، وصار لي باقي؛ أخذته، وإذا كان عكس ذلك، خفض لي المصروف، أو أنهى العقد معي، يقول في ذلك -الرسالة طويلة، نستطيع أن نلخصها-:بأن صاحب المحل عرض على هذا العامل أن يفتح معه معرض، ويكون بالتساوي بينهما، وهو يريد أن يأخذ من المعرض خسارته في هذه النسبة، يقول هذا الذي بعث لنا بالرسالة: إنني أخفي عليه بعض الحاجات من النقود؛ لأن صديقًا لي قال: إن صاحب المتجر سيلعب عليك، ويأخذ خسارته في الشراكة الأولى، فأخفيت هذا المبلغ، وقلت في نفسي: أريد أن أعرف إذا كان يريد أن يلعب علي؛ أخذت نقودي، وإذا كان صادقًا؛ رجعت نقودي هذه إليه، وفعلًا أصبح يريد أن يلعب علي؛ ولذلك لم أرجع هذه النقود، التي أخذتها خفية، هل فيها شيء أم لا؟","title":"حكم إخفاء العامل بعض النقود لتلاعب رب العمل بحقوقه","answer":"الجواب: السؤال فيه إجمال، وفيه بعض الغموض، ولكن نجيبه على التفصيل:  إذا كان هذا السائل اتفق مع التاجر على راتبٍ معلوم شهريًا، في ثلاثة أشهر، أو أقل، أو أكثر، ثم بعد مضي المدة، ينظرون في البقالة، ويتأملون البقالة، فإن كانت البقالة رابحة، جدد معه العقد، وإلا فلا، هذا معناه صحيح. إذا اتفق معه على راتب معلوم، شهرين، أو ثلاثة، أو أربعة، أو خمسة، ثم بعد ذلك ينظرون في البقالة، ويصفون حسابها، فإن رأوا أنها رابحة، والعمل ناجح؛ جدد له العقد مرةً أخرى، بأقل أو بأكثر، وإن لم يروا ذلك؛ أمكنه فسخ العقد، فهذا لا بأس به؛ لأنه ليس فيه غرر. أما إن كان مراده غير ذلك، فليوضح مراده، نعم.","link":"https://binbaz.org.sa/fatwas/13587/حكم-اخفاء-العامل-بعض-النقود-لتلاعب-رب-العمل-بحقوقه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_655/nour_65505.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":15159,"question":"السؤال الآخر يقول: إذا كنا نصلي في مسجد صغير، ونسمع أذان مسجد كبير، فهل السنة أن يؤذن في هذا المسجد الصغير أم نكتفي بالأذان الذي سمعناه في المسجد الكبير؟","title":"هل تكتفي المساجد الصغيرة بأذان المساجد الكبيرة؟","answer":"الجواب: ما دام المسجد يصلى فيه، فالسنة أن يكون فيه أذان، ويكون فيه إقامة، ولو سمعتم أذان المسجد الآخر، فإن المساجد في البلد في الغالب ولا سيما مع هذه المكبرات يسمع بعضهم بعضًا، فالسنة أن كل مسجد يؤذن فيه، ويقام فيه، فقد يتعطل هذا، أو يتعطل هذا. فالحاصل: أن السنة أن يؤذن في كل مسجد، وأن تقام فيه الصلاة، ومن سمع الأذان في أي مسجد أجابه.","link":"https://binbaz.org.sa/fatwas/13663/هل-تكتفي-المساجد-الصغيرة-باذان-المساجد-الكبيرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_665/nour_66509.mp3","categories":["الأذان والإقامة"]},{"id":15186,"question":"من الرياض وردتنا رسالة من عبدالعزيز عبدالرحمن العبدالله، طويلة جدًا، لخصنا هذه الرسالة، ومجملها يقول: إننا نعيش في مؤسسة، وكثير من العاملين فيها من الأتراك المسلمين، جزاهم الله عنا خيرًا، هؤلاء الأتراك مسلمون بمعنى الكلمة، يحضوننا على الصلاة، ويؤذنون ويقيمون ويؤموننا في الصلاة، لكن المؤذن عندهم يقيم الصلاة كالأذان، أي: أنه يأتي بالإقامة كالأذان بالضبط، فهل هذا جائز أم لا؟وفقكم الله.","title":"حكم الإتيان بالإقامة مثل الأذان","answer":"الجواب: لا حرج في ذلك، فإن الأذان جاء على نوعين:\nنوع بالتكبير في أوله أربع، والشهادتين مرتين، الشهادة مرتين مرتين، والتكبير في آخره مرتين، والحيعلة كذلك مرتين، كل واحدة مرتين، وجاء في الإقامة على نحوه، جاءت الإقامة على نحوه، في حديث أبي محذورة.  وجاء في حديث أنس في أذان بلال الإيتار في الإقامة، فمن أوتر الإقامة فهو أفضل على حديث بلال، وإقامة بلال: الله أكبر، الله أكبر، أشهد أن لا إله إلا الله، أشهد أن محمدًا رسول الله، حي على الصلاة، حي على الفلاح، قد قامت الصلاة، قد قامت الصلاة، الله أكبر، الله أكبر، لا إله إلا الله. هذا هو الأفضل كما جاء في أذان بلال وفيما رواه عبدالله بن زيد لما أُرِي الأذان. ومن أتى بالإقامة على شبه الأذان فلا بأس؛ لأن هذا جاء في حديث أبي محذورة، وأنه علمه الإقامة كما علمه الأذان -عليه الصلاة والسلام-، فالأمر في هذا واسع، من باب اختلاف التنوع، نعم، والأذان كذلك تنوع، فإنه جاء فيه مثلما تقدم، وجاء فيه إعادة الشهادتين مرة أخرى، يأتي بها بصوت خفي ليس بجهوري، ليس برفيع جدًا، ثم يرفع الصوت بذلك مرة أخرى بالشهادتين أرفع من اللفظ الأول، وهذا يسمى الترجيع، نعم.","link":"https://binbaz.org.sa/fatwas/13687/حكم-الاتيان-بالاقامة-مثل-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_666/nour_66603.mp3","categories":["الأذان والإقامة"]},{"id":15213,"question":"سؤاله الثالث يقول: ما حكم من يؤذن للصلاة بدون وضوء؟","title":"حكم الأذان بدون وضوء","answer":"الجواب: الأذان ليس من شرطه الوضوء، إذا أذن وهو على غير وضوء أجزأ، حتى ولو كان على جنابة، ليس قرآنًا هو، الأذان ليس بقرآن، إنما هو ذكر، والنبي  كان يذكر الله على كل أحيانه. فالمسلم يذكر الله دائمًا، حتى ولو كان على جنابة، يذكر الله، حتى الحائض تذكر الله، والنفساء تذكر الله. والأذان من ذكر الله، فإذا أذن وهو على جنابة، أو أذن وهو على غير وضوء فأذانه صحيح، لكن الأفضل أن يكون على طهارة، هذا هو الأفضل. أما حديث: لا يؤذن إلا متوضئ فهو حديث ضعيف. فالسنة والأفضل أن يكون حين الأذان على طهارة كاملة من الحدثين، هذا هو الأفضل، ولكن لو أذن وهو على جنابة، أو أذن وهو على غير طهارة من الحدث الأصغر، فأذانه صحيح، ولا حرج في ذلك، نعم.","link":"https://binbaz.org.sa/fatwas/13714/حكم-الاذان-بدون-وضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_672/nour_67203.mp3","categories":["الأذان والإقامة"]},{"id":15300,"question":"هذه رسالة من المواطن (ص. س) من المدينة المنورة، يقول: أرجو إفادتي بالتفصيل عن صلة الرحم، وهل تشمل أهل الزوجة والزوج بالنسبة لبعضهم البعض أم لا؟ ومن هم الأرحام؟","title":"من هم الأرحام؟ وهل أقارب الزوج والزوجة منهم؟","answer":"الجواب: الأرحام: هم الأقارب من جهة الأم، ومن جهة الأب، فالآباء والأمهات والأجداد والجدات أرحام، والأولاد وأولادهم من ذكور وإناث وأولاد البنات كلهم أرحام، وهكذا الإخوة والأخوات وأولادهم أرحام، وهكذا الأعمام والعمات والأخوال والخالات وأولادهم أرحام، داخلون كلهم في قوله -جل وعلا-: وَأُوْلُوا الأَرْحَامِ بَعْضُهُمْ أَوْلَى بِبَعْضٍ [الأنفال:75] وداخلون في قوله  متوعدًا لأهل القطيعة بقوله : فَهَلْ عَسَيْتُمْ إِنْ تَوَلَّيْتُمْ أَنْ تُفْسِدُوا فِي الأَرْضِ وَتُقَطِّعُوا أَرْحَامَكُمْ ۝ أُوْلَئِكَ الَّذِينَ لَعَنَهُمُ اللَّهُ فَأَصَمَّهُمْ وَأَعْمَى أَبْصَارَهُمْ [محمد:22-23] وداخل في قول النبي ﷺ: لا يدخل الجنة قاطع رحم وداخلون في قول النبي ﷺ أيضًا: من أحب أن يبسط له في رزقه، وأن ينسأ له في أجله، فليصل رحمه وداخل في قوله -عليه الصلاة والسلام- لما خلق الله الخلق: قامت الرحم فقالت: يا رب، هذا مقام العائذ بك من القطيعة، فقال -جل وعلا-: ألا ترضين أن أصل من وصلك، وأن أقطع من قطعك؟ فقالت: بلى يا رب، فقال: ذلك لك وفي لفظ قال -جل وعلا-: من وصلها وصلته، ومن قطعها بتته. فالواجب على كل مسلم أن يعتني بالرحم، وأن يصل أرحامه، وأن يحسن إلى أرحامه وقراباته. أما أقارب الزوجة فهم أصهار، وليسوا بأرحام، وكذلك أقارب الزوج بالنسبة إلى المرأة أصهار، وليسوا بأرحام، وإنما الأرحام أقاربك من جهة أبيك، ومن جهة أمك، وهكذا أقارب المرأة من جهة أبيها وأمها، هؤلاء هم الأرحام، أما أقارب زوجتك فهم أصهار وليسوا بأرحام، وهكذا أقارب الزوج بالنسبة للزوجة أصهار وليسوا بأرحام، والإحسان إليهم وحسن الصلة بهم أمر مطلوب، ولكنهم ليسوا كالأرحام، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13802/من-هم-الارحام-وهل-اقارب-الزوج-والزوجة-منهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_676/nour_67602.mp3","categories":["الأذان والإقامة"]},{"id":15308,"question":"امرأة تجلس في انتظار دخول الوقت التالي تسبح وتهلل وتصلي ما يشاء الله لها، هل ينقص أجرها إذا قامت من مكانها لظرف ما كفتح الباب أو رد على التلفون، وغير ذلك؟","title":"هل يؤثر قيام المنتظرة للصلاة لحاجة على أجرها؟","answer":"الجواب: لا يضر -إن شاء الله-، إذا قامت لحاجة لا يضر -إن شاء الله-، تفتح الباب لضارب الباب، أو رد التلفون لا يضر -إن شاء الله-، فهي على خير عظيم، نعم.","link":"https://binbaz.org.sa/fatwas/13805/هل-يوثر-قيام-المنتظرة-للصلاة-لحاجة-على-اجرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_566/56603.mp3","categories":["الأذان والإقامة"]},{"id":15363,"question":"السائل يقول: سماحة الشيخ، إذا كنت في مدينة لا يؤذن فيها إلا مؤذن واحد، ويذاع ذلك الأذان من خلال المذياع، ومكبر الصوت في جميع مساجد تلك المدينة، فما حكم هذا الأذان؟ وهل أردد معه؟ وهل يجزئ أم لا بد أن يؤذن كل شخص لنفسه؟","title":"حكم اكتفاء بعض المساجد بأذان المذياع وحكم إجابته","answer":"الجواب: إذا كان يعم المساجد يُردد معه، يجاب، إذا كان يوجد سماعات في المساجد الأخرى، يُجاب فالذين يسمعونه يجيبونه ويكتفى به، ولكن الأفضل أن يكون كل مسجد له مؤذن ومقيم، لكن لو قُدّر أن قرية من القرى جعل مؤذن واحد في أحد مساجدها وجعلت مكبرات في مساجد أخرى يسمعون، شرع الإجابة لهذا المؤذن، بحيث يقول ما يقول؛ لقوله ﷺ في الحديث الصحيح: إذا سمعتم المؤذن فقولوا مثلما يقول هذا عام، ويقول ﷺ لما قالوا له: يا رسول الله، إن المؤذنين يغبنوننا، قال: قولوا كما يقولون، ثم صلوا علي فإن من صلى علي واحدة صلى الله عليه بها عشرًا، ثم سلوا الله لي الوسيلة، فإنها منزلة في الجنة لا تنبغي إلا لعبد من عباد الله، وأرجو أن أكون أن هو، فمن سأل لي الوسيلة حلت له الشفاعة. فالمقصود: أنه إذا كان الأذان يسمع من المساجد، فإنهم يجيبونه، ويصلون على النبي ﷺ بعد النهاية، ويدعون له بالوسيلة: اللهم رب هذه الدعوة التامة، والصلاة القائمة، آت محمدًا الوسيلة والفضيلة، وابعثه المقام المحمود الذي وعدته وهكذا من كان في البيوت أو في الطرقات يسمعون يجيبون مثلما قال ﷺ: إذا سمعتم المؤذن فقولوا مثلما يقول اللهم صل عليه وسلم، نعم. المقدم: اللهم صل على نبينا محمد.","link":"https://binbaz.org.sa/fatwas/13866/حكم-اكتفاء-بعض-المساجد-باذان-المذياع-وحكم-اجابته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_499/49906.mp3","categories":["الأذان والإقامة"]},{"id":15416,"question":"سؤاله الثاني يقول: أصلي الفروض أحيانًا كثيرة لوحدي؛ نظرًا لعدم وجود مسجد بالقرب مني، ولكن هل يلزمني الأذان والإقامة لكل صلاة، أم يجوز أن أصلي بدون أذان أو بدون إقامة؟","title":"حكم الأذان والإقامة لمن يصلي في بيته منفردًا","answer":"الجواب: السنة أن تؤذن وتقيم هذه السنة، أما الوجوب فيه خلاف بين أهل العلم، ولكن الأولى بك والأحوط لك أن تؤذن وتقيم لعموم الأدلة، ولكن يلزمك أن تصلي في الجماعة مهما أمكن إذا وجدت جماعة، أو سمعت النداء من مسجد بقربك، وجب عليك أن تجيب المؤذن، وأن تحضر مع الجماعة، فإن لم تسمع النداء، ولم يكن بقربك مسجد، فالسنة أن تؤذن أنت وأن تقيم، نعم.","link":"https://binbaz.org.sa/fatwas/13926/حكم-الاذان-والاقامة-لمن-يصلي-في-بيته-منفردا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_684/nour_68416.mp3","categories":["الأذان والإقامة"]},{"id":15428,"question":"هذه السائلة من محافظة شمال سيناء السائل (ج. م. ع) يقول: لدي هذا السؤال، يقول: أنا موظف، ولكن لا أذهب إلى عملي في كل يوم؛ لأن عملي لا يتطلب ذلك، بل أذهب في الأسبوع ثلاثة أيام، وباقي الأسبوع أجلس في البيت، ولكن عندما أذهب باقي الأسبوع لا أجد عملًا أقوم بعمله، بل نجلس نتجاذب الحديث بيننا دون عمل، فما حكم الإسلام في نظركم في المرتب الذي أتقاضاه، هل هو حرام أم حلال؟","title":"حكم تقاضي مرتب في وظيفة قليلة أعمالها","answer":"الجواب: الواجب عليك الحضور في محل العمل؛ لأنه قد يأتي عمل ويطرأ، فالواجب عليك الحضور، والاستعداد للعمل، وإن لم يأت عمل، ولا تجلس في بيتك، والراتب لا حرج فيه لأنك متأول، تقول: ما عندك عمل فأنت متأول، ولكن يجب عليك أن تذهب إلى محل العمل، وتقيم فيه وقت العمل، قد يطرأ شيء، قد تسأل عن شيء، فلا يجوز التساهل في هذا الأمر، فأنت مستعد، والحمد لله، تكون مستعدًا في محل العمل، ويكفي. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13944/حكم-تقاضي-مرتب-في-وظيفة-قليلة-اعمالها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_500/50009.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":15481,"question":"ورد من المستمع محمد علي الجمل من جمهورية مصر العربية -دمياط- في سؤاله الأول يقول: لاحظت في بلدكم المملكة العربية السعودية أنه يوجد أذانان للجمعة، وهذا غير صحيح؛ إذ أنه كان إذا صعد الإمام المنبر أذن بين يديه أذان واحد، وجميع كتب السنة تؤيد ذلك. فأرجو أن تحولوا هذا إلى الجهات المختصة كدار الإفتاء التي يرأسها سماحة الشيخ: عبدالعزيز بن باز ليحق الله الحق، ويبطل الباطل؟","title":"ما حكم الأذانين لصلاة الجمعة؟","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فنعم هو كما قال السائل، كان الأمر في عهد النبي ﷺ أذان واحد مع الإقامة، كان إذا دخل النبي ﷺ للخطبة والصلاة أذن المؤذن، ثم خطب النبي ﷺ الخطبتين، ثم يقام للصلاة، هذا هو الأمر المعلوم، وهو الذي جاءت به السنة، كما قال السائل، وهو أمر معروف عند أهل العلم والإيمان. ثم إن الناس كثروا في عهد الخليفة الراشد عثمان بن عفان -رضي الله تعالى عنه- في المدينة، فرأى أن يزاد الأذان الثالث، ويقال له: الأذان الأول؛ لأجل تنبيه الناس على أن اليوم يوم الجمعة، حتى يستعدوا ويبادروا إلى الصلاة قبل الأذان المعتاد المعروف بعد الزوال، وتابعه بهذا الصحابة في عهده، كان في عهده علي ، وعبد الرحمن بن عوف الزهري أحد العشرة، والزبير بن العوام أحد العشرة أيضًا، وطلحة بن عبيد الله، وغيرهم من أعيان الصحابة وكبارهم، وهكذا سار المسلمون على هذا في غالب الأمصار والبلدان تبعًا لما فعله الخليفة الراشد  عثمان، وتابعه عليه الخليفة الراشد أيضًا علي  وأرضاه، وهكذا بقية الصحابة. فالمقصود: أن هذا حدث في خلافة عثمان وبعده، واستمر عليه غالب المسلمين في الأمصار والأعصار إلى يومنا هذا؛ وذلك أخذًا بهذه السنة التي فعلها عثمان  وأرضاه لاجتهاد وقع له، ونصيحة للمسلمين، ولا حرج في ذلك؛ لأن الرسول  قال: عليكم بسنتي، وسنة الخلفاء الراشدين المهديين من بعدي، تمسكوا بها، وعضوا عليها بالنواجذ وهو من الخلفاء الراشدين ، والمصلحة ظاهرة في ذلك، فلهذا أخذ بها أهل السنة والجماعة، ولم يروا بهذا بأسًا، لكونها من سنة الخلفاء الراشدين عثمان وعلي ومن حضر من الصحابة ذلك الوقت  جميعًا، نعم.","link":"https://binbaz.org.sa/fatwas/14005/ما-حكم-الاذانين-لصلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_689/nour_68901.mp3","categories":["الأذان والإقامة"]},{"id":15626,"question":"هذا سائل للبرنامج الحقيقة من الأردن، يقول: سماحة الشيخ، ما حكم الأذان الموحد، ومثال ذلك: أن يوضع جهاز راديو يربط على مسجد ويؤذن ذلك المسجد، ويبث الأذان إلى أكثر من مائتي مسجد، هل يجوز ذلك؟ وحديث النبي ﷺ يقول: المؤذنون أطول أعناقًا يوم القيامة؟","title":"حكم الأذان الموحد باستخدام الراديو","answer":"الجواب: إذا دعت الحاجة إلى ذلك ما أعلم بأسًا، إذا دعت الحاجة إليه. أما إذا وجد المؤذنون فالسُّنة أن يكون لكل مسجد مؤذن، هذا هو السنة؛ لما في رفع الأذان من الخير والمصالح العظيمة، والأجر للمؤذنين للحديث المذكور وغيره.  فالسنة أن يكون لكل مسجد مؤذن معروف بالأمانة، وحسن الصوت؛ حتى هذا هو المشروع، وهذا هو المعروف في عهد النبي ﷺ وعهد من بعده من الخلفاء الراشدين والسلف الصالح إلى يومنا هذا، السنة أن يكون لكل مسجد مؤذن، لكن لو وجد حاجة لهذا بأن لم يوجد مؤذنون ودعت الحاجة إلى تسجيل الأذان لعدة مساجد للحاجة إلى هذا فلا أعلم به بأسًا، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14163/حكم-الاذان-الموحد-باستخدام-الراديو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_571/57109.mp3","categories":["الأذان والإقامة"]},{"id":15744,"question":"عندما يسمع الأذان نمسح العينين بباطن أنملة السبابتين بعد تقبيلهما، ما هو رأيكم في ذلك؟علمًا بأننا وجدنا في كتاب فقه السنة، وفي كتاب الحاشية حديثًا يحث فيه الرسول ﷺ أبا بكر الصديق على ذلك.","title":"حكم مسح العينين عند سماع الأذان","answer":"الجواب: هذا لا أصل له، لا أصل له، مسح العينين بأطراف السبابتين هذا لا أصل له عند الأذان، بل هذا من البدع، نعم. المقدم: جزاكم الله خيرًا، وما رأيكم في ذلكم الحديث الذي ذكر في فقه السنة؟\nالشيخ: لا صحة له، نعم.\nالمقدم: الحديث غير صحيح؟\nالشيخ: لا صحة له، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14331/حكم-مسح-العينين-عند-سماع-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_707/nour_70704.mp3","categories":["الأذان والإقامة","البدع والمحدثات"]},{"id":15819,"question":"السائل يقول -سماحة الشيخ- في هذا  هل صلوات السنة أو ركعات السنة؛ هل لهن إقامة؟","title":"هل تُشرع الإقامة لصلاة النافلة؟","answer":"الجواب: ليس لها إقامة؛ الإقامة للفرائض، أما النوافل ما لها إقامة، وصلاة الكسوف ما لها إقامة، وصلاة الاستسقاء ما لها إقامة، وصلاة العيد ما لها إقامة، نعم.\nالإقامة للصلوات الخمس، لها أذان وإقامة، الصلوات الخمس، نعم.","link":"https://binbaz.org.sa/fatwas/14408/هل-تشرع-الاقامة-لصلاة-النافلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_575/57511.mp3","categories":["الأذان والإقامة"]},{"id":15877,"question":"هذا سائل من اليمن، يقول -سماحة الشيخ-: البعض في المساجد يقوم القائمون عليها -وفي أذان الصبح- بأذانين، ما الدليل على ذلك بصحة هذا العمل؟ مأجورين.","title":"ما الدليل على الأذانين لصلاة الفجر؟","answer":"الجواب: يشرع للفجر أذانان؛ أذان قبل الصبح، وأذان بعد الصبح؛ لما ثبت في الصحيحين عن النبي ﷺ أنه قال: إن بلالًا يؤذن بليل، فكلوا واشربوا حتى ينادي ابن أم مكتوم وقال: إن بلالًا يؤذن ليرجع قائمكم، ويوقظ نائمكم كان بلال يؤذن في آخر الليل حتى ينتبه القائم، وأن الصبح قريب حتى يوتر، وحتى يوقظ النائم ليستعد لصلاة الفجر، فلا بأس أن يؤذن أذان أول قبل الفجر بوقت بنصف ساعة، أو نحوها أو ساعة حتى ينتبه الناس أن الفجر قريب، ليقوم الذي يريد الإيتار والتهجد؛ وليستعد لصلاة الفجر، ثم الأذان الأخير بعد طلوع الفجر، نعم.","link":"https://binbaz.org.sa/fatwas/14465/ما-الدليل-على-الاذانين-لصلاة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_577/57703.mp3","categories":["الأذان والإقامة"]},{"id":15959,"question":"هذا السائل (ص. ف. ح) يقول -سماحة الشيخ- يذكر بأنه شاب متزوج، وعنده أطفال، ويحمد الله على ذلك يقول: خرجت من بيت والدي منذ صغري، ولا أذكر ذلك اليوم، وفتحت عيني، وأنا في بيت خالي الذي رباني، وتعب علي، وصرف علي، ووجهني كثيرًا، عندما أجلس مع والدي لا أحس به أنه والدي، ولكن عندما أجلس مع خالي أحس به أنه هو والدي الحقيقي الذي يهتم بأمري، فهل لوالدي حقوق؟جزاكم الله خيرًا.","title":"الوالد له حقوق وإن قصر في حق أولاده","answer":"الجواب: نعم، لوالدك حقوق حق الأبوة، فالواجب بره، والإحسان إليه، وعدم إنكار أبوته، عليك أن تحسن إليه، وأن تبدأه بالسلام، وأن تجتهد في كل ما يرضيه من الأمور الطيبة بالمعروف.  وخالك له حق أيضًا، حق التربية والإحسان، جزاه الله خيرًا، فعليك أن تقوم بهذا وهذا، عليك أن تعرف قدر خالك الذي أحسن إليك، وتعرف بره وإحسانه، وتعرف -أيضًا- حق والدك، والله -جل وعلا- يقول: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا [الإسراء:23] فالوالد له حق عظيم، فالواجب عليك أن تفعل هذا وهذا؛ تبر والدك، وتعرف قدره، وتحسن إليه، وتجتهد في عدم ما يغضبه أو يؤذيه، وعليك أيضًا مع هذا أن تحسن إلى خالك، وتعرف قدره وإحسانه، وتقدر له ما فعله معك من الخير، هذا هو شأن الكرماء والأخيار، نعم. المقدم: أحسن الله إليكم، الآباء دائمًا يحرصون على أبنائهم، ويحرصون على تنشئتهم التنشئة الإسلامية، ولكن بعض الآباء -سماحة الشيخ- قد يقسو على أولاده، أو يخطي في التربية، هل من توجيه للآباء؟ الشيخ: الواجب على الآباء تقوى الله، وأن يحسنوا إلى أولادهم، ويربوهم التربية الإسلامية، وأن يرفقوا بهم، ويحسنوا إليهم، هذا هو الواجب على الآباء، وعلى الأمهات أن يتقوا الله، وأن يحسنوا في أولادهم، ويعلموهم، ويوجهوهم إلى الخير، وأن يكونوا قدوة صالحة لأولادهم: لا من جهة التربية، ولا من جهة الأخلاق التي يسمعها ويراها أولادهم من: العفو والصفح، وطيب الخلق، وكرم الجوار، وحسن الكلام، وغير هذا من الأفعال الطيبة، والمحافظة على الصلاة وغير هذا من وجوه الخير حتى يتأسى بهم الأولاد، فعلى الأم أن تجتهد في أن يتأسى بها بناتها وأولادها في الخير، وعلى الوالد كذلك. وعلى الولد أن يجتهد في بر والديه، والإحسان إليهما، وإذا رأى منهما ما يخالف الشرع نصحهما بالرفق، والكلام الطيب؛ حتى يحصل التعاون على البر والتقوى، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14564/الوالد-له-حقوق-وان-قصر-في-حق-اولاده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_578/57811.mp3","categories":["الأذان والإقامة"]},{"id":15988,"question":"السائل فواز له مجموعة من الأسئلة يقول في بداية أسئلته سماحة الشيخ: ما حكم أخذ الأجرة على السمسرة؟","title":"حكم أخذ الأجرة على الدلالة","answer":"الجواب: لا حرج، أخذ الأجرة كونه يكون دلالًا يبيع البيوت، يبيع الأراضي، يبيع الإبل، يبيع الغنم، يبيع الرقيق ويأخذ أجرة، لا بأس، أجرته، هذا عمله.","link":"https://binbaz.org.sa/fatwas/14592/حكم-اخذ-الاجرة-على-الدلالة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_578/57816.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":15998,"question":"يقول: هل من سالم شخصًا له عليه مال أو مظلمة أفضل أم من يطالب بحقه في الآخرة؟","title":"فضل العفو والمسامحة","answer":"الجواب: إذا سمح وعفا عن أخيه، ولا سيما إذا كان محتاج فقير، أو يدعي أن عليه مشقة إذا سامحه عن مال أو مظلمة عنده له مظلمة ضربه أو سبه وسامحه، فأجره عند الله -جل وعلا-، فهو أفضل له، يقول الله سبحانه: فَمَنْ عَفَا وَأَصْلَحَ فَأَجْرُهُ عَلَى اللَّهِ[الشورى:40] ويقول : وَأَنْ تَعْفُوا أَقْرَبُ لِلتَّقْوَى[البقرة:237] ويقول النبي ﷺ: ما زاد الله عبدًا بعفو إلا عزًا لكن إذا كان العفو يجر الشخص للشر والفساد ويعينه على الباطل، فالأفضل عدم العفو، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14618/فضل-العفو-والمسامحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_747/nour_74707.mp3","categories":["الأذان والإقامة"]},{"id":16146,"question":"على بركة الله نبدأ بهذا اللقاء الطيب المبارك من رسالة وصلت من الإمارات العربية المتحدة، السائل أبو إبراهيم يقول: سماحة الشيخ! ما هو أفضل شيء يتقرب فيه العبد إلى ربه غير الصلاة من الأعمال التي تنفع المسلم في أخراه ودنياه؟ جزاكم الله خيرًا.","title":"أفضل القربات بعد الصلاة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه. القربات كثيرة، والحمد لله، فالصلاة من أفضل القربات، والصيام من أفضل القربات تطوعًا، والصدقات بالمال من أفضل القربات، والحج من أفضل القربات، والعمرة من أفضل القربات، والاستغفار، وكثرة التسبيح والتهليل، وقراءة القرآن من أفضل القربات. فالمؤمن يجتهد في أنواع القربات، يقرأ القرآن، ويكثر من قراءة القرآن، يكثر من التسبيح والتهليل والتكبير، يكثر من نوافل الصدقة، نوافل الصلاة، نوافل الصوم، نوافل الحج حسب طاقته، وإذا جاء الجهاد شرع له أن يشارك في الجهاد في سبيل الله إذا يسر الله ذلك، كل هذه قربات، كلها، مثلما لما سئل النبي ﷺ سأله بعض الأعراب عما يلزمه، وعلمه بشرائع الإسلام: علمه الشهادتين، ثم علمه بالصلاة، قال: «هل علي غيرها؟ قال: لا إلا أن تطوع، ثم لما علمه الزكاة قال: هل علي غيرها؟ قال: إلا أن تطوع ثم لما علمه صوم رمضان قال: هل علي غيره؟ قال: لا إلا أن تطوع وهكذا الحج. فالمقصود: أن المؤمن يجتهد في أنواع القربات، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14800/افضل-القربات-بعد-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_580/58001.mp3","categories":["الأذان والإقامة"]},{"id":16217,"question":"سماحة الشيخ! يقول السائل -من فقراته-: هل هناك نص نبوي شريف يحث على قراءة سورة الكهف في يوم الجمعة؟","title":"هل هناك دليل على قراءة سورة الكهف يوم الجمعة؟","answer":"الجواب: جاء في أحاديث ضعيفة، ولكن ثبت من فعل بعض الصحابة، ثبتت قراءتها يوم الجمعة من فعل بعض الصحابة. فإذا قرأها الإنسان؛ فحسن -إن شاء الله- لأن فعل الصحابي يدل على أن لها أصلًا، فعل الصحابي لذلك يدل على أن لها أصلًا. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/14884/هل-هناك-دليل-على-قراءة-سورة-الكهف-يوم-الجمعة ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_580/58011.mp3","categories":["الأذان والإقامة"]},{"id":16246,"question":"من المستمع إسماعيل محمد موسى مقيم في مكة المكرمة رسالة يقول فيها: لنا في السودان أدوات تؤجر للمناسبات، كمكبرات الصوت، والكراسي، والصيوانات، ومفارش، وكوش لجلوس العروسين يوم الزفاف، علمًا بأن هذه الأشياء أحيانًا تؤجر للمآتم، والندوات الدينية، والثقافية، فهل هذا يجوز، أم لا؟ جزاكم الله خيرًا.","title":"حكم تأجير بعض الأدوات للمناسبات والمآتم","answer":"الجواب: تأجيرها في المناسبات المباحة، والمشروعة لا بأس بذلك، إذا أجرها صاحبها لوليمة العرس التي ليس فيها منكر، أو لمناسبات أخرى، ليس فيها منكر؛ مباحة لا بأس، أما تأجيرها على قوم يفعلون فيها المنكر، من إنشاد المآتم التي تعتبر بدعة، كإيجاد الوليمة من أهل الميت إذا مات الميت، هذا بدعة، ومن عمل الجاهلية، كونهم يقيمون وليمة عند موت ميتهم، هذا من البدع، ومن أمر الجاهلية، يقول جرير بن عبدالله البجلي : \"كنا نعد الاجتماع إلى أهل الميت، وصنعة الطعام بعد الدفن من النياحة\". فالمقصود: أن كون أهل الميت يعدون طعامًا للناس مأتمًا، وحزنًا، فهذا من عمل الجاهلية، لا يؤجر عليهم لا الكراسي، ولا غيرها. وهكذا إذا كان يقام في الاحتفال أمور منكرة من الملاهي، والعود، والسينما، وأشباه ذلك مما يعتبر محرمًا؛ فلا يجوز ذلك. فالخلاصة: أنها إن أجرت على من يستعملها في أمر مشروع، أو مباح؛ فلا بأس، وإن أجرت على من يستعمل فيها المنكر، أو يستعملها في بدعة؛ فلا يجوز، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14932/حكم-تاجير-بعض-الادوات-للمناسبات-والماتم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_807/nour_80705.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":16296,"question":"سماحة الشيخ! يختتم أسئلته في هذه الحلقة يقول: يحصل بين أمي وأبي نزاع ومخاصمة وشجار في كثير من الأحيان، وقد نصحتهما في ذلك كثيرًا، كيف توجهونني حيال هذا الأمر، وهو يؤلمني كثيرًا؟ جزاكم الله خيرًا.","title":"الوصية بالإصلاح بين الوالدين","answer":"الجواب: نوصيك بالاستمرار في النصيحة، وأنت مشكور ومأجور، نوصيك بالاستمرار بالنصيحة لوالديك جميعًا، بالكلام الطيب، والأسلوب الحسن، والرفق، المرأة الوالدة تنصح بالسمع والطاعة لزوجها، أن تعامله المعاملة الطيبة، وأن تتحمل بعض الأذى، وتوصي الوالد بالكلام الطيب، والأسلوب الحسن، وعدم ظلمها، وعدم التعدي عليها، والله يهديهما جميعًا، نسأل الله أن يهديهما جميعًا. المقصود: نوصيك بالاستمرار بالكلام الطيب، والأسلوب الحسن، وهكذا إخوتك، وأخواتك، كلكم استعينوا بالله في نصيحة الوالدين، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14982/الوصية-بالاصلاح-بين-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_753/nour_7530034.mp3","categories":["الأذان والإقامة"]},{"id":16320,"question":"من إحدى الأخوات المستمعات رمزت إلى اسمها بالحروف (م ص) تقول: إنني كثيرًا ما أتضايق من أولئك الذين يقولون: إنا لا نحفظ من القرآن شيئًا، فهل يجب على المسلم أن يحفظ القرآن، أو يظل جوفه خاليًا من كتاب الله؟","title":"حكم حفظ القرآن الكريم","answer":"الجواب: المشروع للمؤمن والمؤمنة العناية بالقرآن، والحرص على حفظ ما تيسر منه، لكن لا يجب على المكلف إلا الفاتحة، ركن الصلاة، هي الواجبة، ركن الصلاة الفاتحة (الحمد) يجب على كل مؤمن ومؤمنة أن يحفظها، وإذا تيسر له أن يحفظ سورًا من القرآن من المفصل حتى يقرأ مع الفاتحة؛ فهذا سنة مؤكدة، جزء عم، أو جزء عم، وجزء تبارك، أو ما تيسر من ذلك، هذا مطلوب سنة، مشروع له أن يعتني بهذا الشيء. لكن الواجب قراءة الفاتحة، فإذا تيسر له حفظ القرآن كله فهذه نعمة عظيمة، وسنة فيها خير كثير، لكن لا يلزم الناس، حفظ القرآن فرض كفاية، يجب أن يكون فيهم من يحفظه، لكن لا يلزم فلانًا، أو فلانًا حفظ القرآن، إنما يشرع له ذلك، أو ما تيسر منه، كجزء عم، أو المفصل، كله من ق إلى آخره، المفصل من ق إلى آخر القرآن، هذا يسمى المفصل، يشرع حفظ هذا المفصل إذا تيسر ذلك، أو حفظ ما تيسر منه، جزء عم، نصف جزء عم، ما تيسر من السور حتى يقرأ مع الفاتحة بعض السور. أما الواجب فالفاتحة وهي: الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ۝ الرَّحْمَنِ الرَّحِيمِ ۝ مَالِكِ يَوْمِ الدِّينِ ۝ إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ ۝ اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ ۝ صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلا الضَّالِّينَ [الفاتحة:2-7] هذه الفاتحة، يقرؤها المؤمن والمؤمنة في كل ركعة في النفل والفرض، لابد منها في الفريضة والنافلة في كل ركعة، وإذا تيسر معها زيادة؛ قرأ الزيادة، في الأولى والثانية من الظهر والعصر والمغرب والعشاء، ويقرؤها مع الفاتحة في الفجر أيضًا، وفي النوافل، لكن لا يجب ذلك، الواجب الفاتحة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15023/حكم-حفظ-القران-الكريم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_810/nour_81018.mp3","categories":["الأذان والإقامة"]},{"id":16334,"question":"من أحد الإخوة المستمعين سؤالان، في سؤاله الأول يقول: ما حكم الصلاة على النبي ﷺ بعد الأذان في مكبرات الصوت؟","title":"حكم الصلاة على النبي ﷺ بعد الأذان بمكبرات الصوت","answer":"الجواب: السنة بعد الأذان قفل المكبر، إذا قال: \"لا إله إلا الله\" انتهى الأذان، يقفل المكبر، وتكون الصلاة على النبي ﷺ بالصوت العادي بعد ذلك، من غير أن يكون في المكبر؛ لأن السنة أن المؤذن يجاب، يقول ﷺ: إذا سمعتم المؤذن فقولوا مثلما يقول يعني: يقول مثله: الله أكبر الله أكبر، الله أكبر الله أكبر، أشهد أن لا إله إلا الله.. إلى آخره، إلا عند الحيعلة، عند حي على الصلاة، يقول: لا حول ولا قوة إلا بالله، وعند حي على الفلاح يقول: لا حول ولا قوة إلا بالله.  ثم يقول بعد هذا: الله أكبر الله أكبر، لا إله إلا الله، ثم يصلي على النبي ﷺ إذا كان مؤذنًا بعد قفل المكبر؛ لا يصلي مع الأذان، انتهى الأذان، انتهى الأذان بقوله: لا إله إلا الله؛ فيقفل المكبر، ثم يصلي على النبي ﷺ بالصوت العادي الذي يسمعه من حوله، ثم يكمل اللهم صل على النبي، ثم يقول: اللهم رب هذه الدعوة التامة، والصلاة القائمة، آت محمدًا الوسيلة والفضيلة، وابعثه مقامًا محمودًا الذي وعدته، إنك لا تخلف الميعاد هكذا جاء في الحديث الصحيح، أن السنة للمؤمن أن يقول هذا بعد الأذان، رواه البخاري في صحيحه، لكن بغير زيادة: إنك لا تخلف الميعاد وهذه الزيادة رواها البيهقي بإسناد جيد. والمؤمن يصلي على النبي ﷺ المؤذن، والمستمع يصلي بعد الأذان، بعد فراغ الأذان، لكن المؤذن لا يقولها مع الأذان، بل يقفل المكبر، ثم يقولها بالصوت العادي، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15029/حكم-الصلاة-على-النبي-ﷺ-بعد-الاذان-بمكبرات-الصوت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_754/nour_75403.mp3","categories":["الأدعية والأذكار","الأذان والإقامة"]},{"id":16419,"question":"ننتقل بعد هذا إلى رسالة، وصلت إلى البرنامج من الدوحة -قطر- وباعث الرسالة المستمع: (ع. محمد) يقول في أحد أسئلته: بعد أن ينتهي المؤذن، وينهي الأذان بـ (لا إله إلا الله) يقول بعض الناس: حقًّا لا إله إلا الله، فما حكمها؟ وهل ذلكم القول صحيح في ذاته؟ جزاكم الله خيرًا.","title":"ما حكم قول (حقًّا لا إله إلا الله) بعد الأذان؟","answer":"الجواب: نعم إنه حق، كلام صحيح: فلا إله إلا الله أعظم الحق، فإنه سبحانه هو المستحق للعبادة، وليس هناك إله معبود بحق سواه -جل وعلا- كما قال سبحانه: وَإِلَهُكُمْ إِلَهٌ وَاحِدٌ لا إِلَهَ إِلَّا هُوَ الرَّحْمَنُ الرَّحِيمُ [البقرة:163] ويقول : إِنَّمَا إِلَهُكُمُ اللَّهُ الَّذِي لا إِلَهَ إِلَّا هُوَ وَسِعَ كُلَّ شَيْءٍ عِلْمًا [طه:98] ويقول سبحانه: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23]. فهو الإله الحق  ليس هناك إله آخر معبود بحق، بل جميع الآلهة كلها باطلة، كلها معبودة بالباطل، كما قال سبحانه: ذَلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِنْ دُونِهِ هُوَ الْبَاطِلُ [الحج:62] فجميع الآلهة التي يعبدها الناس كلها باطلة إلا الإله الحق  هو الله . لكن الرسول يقول -عليه الصلاة والسلام-: إذا سمعتم المؤذن فقولوا مثلما يقول يكفي أن يقول: لا إله إلا الله، ما بحاجة يقول حق، هو حق لا شك أنه حق، لكن يقول النبي ﷺ: قولوا مثلما يقول والمؤذن يقول: لا إله إلا الله، فأنت تقول مثله: لا إله إلا الله، ثم تصلي على النبي ﷺ، ثم تقول: اللهم رب هذه الدعوة التامة، والصلاة القائمة، آت محمدًا الوسيلة والفضيلة، وابعثه مقامًا محمودًا الذي وعدته، إنك لا تخلف الميعاد هذا هو المشروع، هذا هو المشروع للمستمع للآذان، ولا يزيد كلمة حق، الأفضل تركها، هي كلمة حق، لكن الأفضل تركها، لقوله ﷺ: قولوا مثلما يقول. يقول مثله: الله أكبر، الله أكبر، أشهد أن لا إله إلا الله، يقول: أشهد أن لا إله إلا الله، أشهد أن محمدًا رسول الله، يقول: أشهد أن محمدًا رسول الله، إلا الحيعلة يقول: لا حول ولا قوة إلا بالله، عند حي على الصلاة يقول: لا حول ولا قوة إلا بالله، حي على الفلاح يقول: لا حول ولا قوة إلا بالله، هكذا أرشد النبي ﷺ ثم يقول معه: الله أكبر، الله أكبر، لا إله إلا الله، ثم يصلي على النبي ﷺ ثم يقول: اللهم رب هذه الدعوة التامة والصلاة القائمة آت محمدًا الوسيلة والفضيلة، وابعثه مقامًا محمودًا الذي وعدته، إنك لا تخلف الميعاد نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15144/ما-حكم-قول-حقا-لا-اله-الا-الله-بعد-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_812/nour_81203.mp3","categories":["الأذان والإقامة"]},{"id":16494,"question":"في ثاني أسئلته يقول: هل تجوز صلة الرحم عبر التلفون؟","title":"هل تجوز صلة الرحم بالهاتف؟","answer":"الجواب: نعم، هذا من صلة الرحم، المكالمة الهاتفية، والمكاتبة بالقلم، كلها من الصلة، كونه يكتب إليه، لأخيه، أو عمه، أو قريبه يسأله عن صحته، وعن حاله، أو يكلمه بالهاتف، كله طيب، كله من الصلة.","link":"https://binbaz.org.sa/fatwas/15206/هل-تجوز-صلة-الرحم-بالهاتف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_582/58221.mp3","categories":["الأذان والإقامة"]},{"id":16497,"question":"لأختنا من الأردن سؤال تقول فيه: إن كثيرًا من المؤذنين بعد قولهم: لا إله إلا الله في نهاية الأذان، يصلون على النبي ﷺ، فهل هذا بدعة؟","title":"كيفية الصلاة على النبي ﷺ بعد الأذان","answer":"الجواب: إذا فرغ المؤذن من الأذان ينتهي، إذا قال: لا إله إلا الله، يقفل الميكرفون لا يزيد شيئًا، ثم يصلي على النبي ﷺ بلفظ عادي يسمعه من حوله؛ لأن الرسول ﷺ قال: إذا سمعتم المؤذن؛ فقولوا مثلما يقول، ثم صلوا علي، فإنه من صلى علي واحدة؛ صلى الله عليه بها عشرًا، ثم سلوا الله لي الوسيلة، فإنها منزلة في الجنة، لا تنبغي إلا لعبد من عباد الله، فأرجو أن أكون أنا هو، فمن سأل لي الوسيلة؛ حلت له الشفاعة. فالصلاة على النبي ﷺ ما هي من الأذان، ما هي من ألفاظ الأذان، الأذان ينتهي عند: لا إله إلا الله، والمجيب يقول: لا إله إلا الله، ثم يصلي على النبي ﷺ لكن من دون رفع صوت زيادة على العادة، صوته العادي، والمؤذن كذلك إذا فرغ يأتي بصوت عادي، ليس بصوت الأذان، بل بعدما يسكت يأتي بالصلاة على النبي ﷺ بصوت عادي، وإن كان في غير الميكرفون لا يرفع صوته، مع لا إله إلا الله؛ لئلا يظن أن هذا من الأذان، الأذان انتهى عند قوله: لا إله إلا الله، فالمجيب يقول: لا إله إلا الله، والأفضل لا يتمها، وحده لا شريك له، له الملك وله الحمد، لا، يقول: لا إله إلا الله مثلما قال المؤذن، الرسول ﷺ قال: إذا سمعتم المؤذن؛ فقولوا مثلما يقول. فإذا قال: لا إله إلا الله يتبعها بقوله: اللهم صل وسلم على رسول الله، اللهم صل على محمد، وعلى آل محمد، كما صليت على إبراهيم، وآل إبراهيم، إنك حميد مجيد، اللهم بارك على محمد، وعلى آل محمد، كما باركت على إبراهيم، وعلى آل إبراهيم، إنك حميد مجيد اللهم رب هذه الدعوة التامة، والصلاة القائمة، آت محمدًا الوسيلة والفضيلة، وابعثه مقامًا محمودًا الذي وعدته هكذا رواه البخاري في الصحيح، قال النبي ﷺ: من قال حين يسمع النداء: اللهم رب هذه الدعوة التامة، والصلاة القائمة، آت محمدًا الوسيلة والفضيلة، وابعثه مقامًا محمودًا الذي وعدته؛ حلت له شفاعتي يوم القيامة زاد البيهقي -رحمه الله- بإسناد جيد، إنك لا تخلف الميعاد.  فالمقصود: أن هذا هو المشروع بعد الأذان، للمؤذن والناس جميعًا يقولون بعد الأذان، إذا كملوا لا إله إلا الله، يصلون على النبي ﷺ ثم يقولون: اللهم رب هذه الدعوة بصوت عادي اللهم رب هذه الدعوة التامة الدعوة يعني: دعوة الأذان والصلاة القائمة يعني التي ستقوم قريبًا آت محمدًا يعني: نبينا محمد ﷺ الوسيلة والفضيلة، وابعثه مقامًا محمودًا الذي وعدته، إنك لا تخلف الميعاد هذه الزيادة تثبت من رواية البيهقي -رحمه الله- وبعضهم يزيد الدرجة الرفيعة وهذه ما لها أصل، ما هي في الحديث، الدرجة الرفيعة هي الوسيلة، هي نفس الوسيلة، آت محمدًا الوسيلة هي الدرجة الرفيعة، لكن ما هي في الحديث الدرجة الرفيعة اللهم رب هذه الدعوة التامة، والصلاة القائمة، آت محمدًا الوسيلة والفضيلة. الوسيلة والفضيلة هي الدرجة، يقول النبي ﷺ: إنها منزلة في الجنة، لا تنبغي إلا لعبد من عباد الله، فأرجو أن أكون أنا هو فهي الدرجة الرفيعة اللهم رب هذه الدعوة التامة، والصلاة القائمة، آت محمدًا الوسيلة والفضيلة، وابعثه مقامًا محمودًا الذي وعدته، إنك لا تخلف الميعاد هذا يقال بعد الأذان، وبعد الإقامة أيضًا، نعم. المقدم: جزاكم الله خيرًا، وبدون صوت مرتفع؟ الجواب: لا، عادي صوت عادي، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15242/كيفية-الصلاة-على-النبي-ﷺ-بعد-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_814/nour_81403.mp3","categories":["الأدعية والأذكار","الأذان والإقامة"]},{"id":16518,"question":"يقول: إذا فاتتني صلاة الفجر، ولم أستيقظ إلا في الثامنة صباحًا، فهل أؤذن وأقيم؟ أم أصلي بدون أذان، ولا إقامة؟ وما حكم الراتبة حينئذٍ؟ جزاكم الله خيرًا.","title":"حكم الأذان والإقامة لمن نام عن صلاة الفجر","answer":"الجواب: تصلي الراتبة، ثم تصلي الفريضة، وتقيم للفريضة، ولا حاجة إلى الأذان في هذا، تكفي الإقامة، تصلي، أما إذا كنتم جماعة تؤذنون، وتقيمون مثل أناس في السفر ناموا، فإنهم إذا استيقظوا؛ يؤذنون، ويقيمون، كما فعله النبي ﷺ أو كنت في السفر أنت وحدك كذلك، ونمت عن الفجر، ولم تستيقظ إلا بعد الشمس، أو قبل الشمس تؤذن وتقيم، وتصلي الراتبة. أما في الحضر بين الناس، فالأقرب -والله أعلم- أنه يكفيك الإقامة -إن شاء الله- ولا حاجة إلى الأذان؛ لأن الحضر قد أذنوا المساجد، قد أذنوا وصلوها في وقتها، فأنت تقيم فقط، وهذا يكفي -إن شاء الله- في الحضر، تقيم الصلاة بعدما تصلي الراتبة، تقيم، وتصلي الفريضة، ولعل هذا يكفي -إن شاء الله- عن الأذان، ولو أذنت أذانًا لا يسمع من الخارج، أذانًا لا يشوش على الناس، ولا يستنكر في محلك؛ فلا أعلم به بأسًا، كما فعله النبي ﷺ لما نام عن الصلاة في السفر، أمر بالأذان، وبالإقامة، وصلى الراتبة، وصلى الفريضة. لكن في الحضر، وبين الناس لعله يكفي الإقامة -إن شاء الله-لأن المساجد قد أذن أهلها، وصلوا الصلاة في وقتها، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15221/حكم-الاذان-والاقامة-لمن-نام-عن-صلاة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_756/nour_75608.mp3","categories":["الأذان والإقامة"]},{"id":16554,"question":"يقول: إن بالقرب من منزلنا مسجد من الطين أصلي فيه أنا وأبي وإخواني، لكننا لا نؤذن، بل نكتفي بما نسمع، هل يجب علينا الأذان؟ ذلك أن أحد أقاربنا قال: لابد من الأذان، ما هو توجيهكم؟ جزاكم الله خيرًا.","title":"حكم الأذان بمسجد صغير يُسمع الأذان من غيره","answer":"الجواب: الأفضل أن تؤذنوا فيه حتى يعلم من حولكم، ويحضر، ولا يجب مادام حولكم مؤذنون يسمعهم من حولكم، لا بأس، يحصل بهم الكفاية، لكن إذا أذنتم في المسجد هذا يكون أفضل، وأولى. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15295/حكم-الاذان-بمسجد-صغير-يسمع-الاذان-من-غيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_816/nour_81609.mp3","categories":["الأذان والإقامة"]},{"id":16573,"question":"يقول: إن بالقرب من منزلنا مسجد من الطين أصلي فيه أنا وأبي وإخواني، لكننا لا نؤذن، بل نكتفي بما نسمع، هل يجب علينا الأذان؟ ذلك أن أحد أقاربنا قال: لابد من الأذان، ما هو توجيهكم؟ جزاكم الله خيرًا.","title":"حكم الأذان بمسجد صغير يُسمع الأذان من غيره","answer":"الجواب: الأفضل أن تؤذنوا فيه حتى يعلم من حولكم، ويحضر، ولا يجب مادام حولكم مؤذنون يسمعهم من حولكم، لا بأس، يحصل بهم الكفاية، لكن إذا أذنتم في المسجد هذا يكون أفضل، وأولى. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15295/حكم-الاذان-بمسجد-صغير-يسمع-الاذان-من-غيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_816/nour_81609.mp3","categories":["الأذان والإقامة"]},{"id":16593,"question":"المستمع سريح القرني من رأس تنورة بعث يسأل ويقول: لدينا مزرعة، وعليها عمال، حيث نعطيهم رواتب شهرية حسب اتفاقية الاستقدام من دولتهم، ولكن بعض الأحيان يطلبوا منا إعطاءهم المزرعة بالنصيفة، بدون راتب، على أن نقوم نحن أصحاب المزرعة بإعداد متطلبات المزرعة من المضخات، والوقود، وكذلك آلات الحرث، ومقابل أن يقوم العمال بزراعة المزرعة، وبيعها في الأسواق في سياراتنا، وعند انتهاء الثمرة نقتسم بالنصف فيما بيننا فما الحكم في ذلك؟ وهل علينا شيء في هذا؟ وهل هذا يدخل في كراء الأرض المنهي عنه؟ لأنني قرأت أحاديث تدل على النهي عن كراء الأرض، مثاله: عن جابر بن عبدالله -رضي الله عنهما- أن النبي ﷺ قال: من كانت له أرض؛ فليزرعها، أو ليزرعها أخاه، ولا يكرها مختصر صحيح مسلم، جزاكم الله خيرًا.","title":"حكم تأجير الأرض على شيء معلوم","answer":"الجواب: عملكم هذا طيب، ولا بأس، هذه مزارعة، فإذا أعطيتم العمال النصف، أو الثلث، أو الربع على قيامهم على المزرعة، وسقيهم لها، وتعبهم فيها، وأنتم تعدون لهم كل شيء؛ فلا بأس بذلك، هذه مزارعة جائزة، ولا حرج فيها، ولا بأس بتأجير الأرض على الناس بأجر معلوم، كان هذا الذي ذكرت الحديث كان هذا في أول الإسلام، ثم نسخ، كان النبي ﷺ نهى عن تأجير الأرض، ثم رخص في ذلك عليه الصلاة والسلام.  فإذا زارع عليها بالنصف، أو بالثلث؛ فلا بأس، أو أجرها بشيء معلوم، والمستأجر يزرعها، أو يغرس فيها فلا بأس؛ لأن هذه أمور معلومة، أما الذي بقي النهي عنه، ولم يزل ينهى عنه الرسول ﷺ فهو تأجيرها بشيء مجهول، كأن يزارع على شيء مجهول من الزرع، بأن يعطيه ما أنبتت الجهة الفلانية، أو ما نبت على السواقي، فهذا خطر، قد يكون رديء، وقد يكون طيبًا، هذا منهي عنه، وأما الشيء المضمون بدراهم معلومة، أو آصع معلومة، أو بجزء مشاع، كالنصف، أو بالثلث هذا لا بأس به. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15324/حكم-تاجير-الارض-على-شيء-معلوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_817/nour_81707.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":16608,"question":"إذا أذن المؤذن، ولم أسمعه، وفاتتني صلاة الجماعة، هل يجب علي الأذان؟","title":"حكم الأذان لمن فاتته الجماعة ولم يسمع الأذان","answer":"الجواب: لا، يكفي أذان المسلمين، تقيم وتصلي فقط، ولا حاجة إلى الأذان، نعم.","link":"https://binbaz.org.sa/fatwas/15343/حكم-الاذان-لمن-فاتته-الجماعة-ولم-يسمع-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_758/nour_75813.mp3","categories":["الأذان والإقامة"]},{"id":16645,"question":"ما رأي سماحتكم فيمن يتقاضى أجرًا عما يقوم به من الدعوة إلى الله، وتحفيظ القرآن الكريم؟","title":"حكم أخذ الأجرة على تعليم القرآن والدعوة إلى الله","answer":"الجواب: لا حرج في ذلك، المعلم يعطى على تحفيظ القرآن، وتعليم القرآن، والدعوة إلى الله  لأن هذه الأمور تحتاج إلى أوقات، وكلفة ومشقة، فإذا أعطي من بيت المال، ومن أوقاف المسلمين، أو من بعض المحسنين ما يعينه على التعليم، والتحفيظ، والدعوة إلى الله، أو التدريس كله طيب، لا حرج فيه، والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15378/حكم-اخذ-الاجرة-على-تعليم-القران-والدعوة-الى-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_717/nour_71708.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":16694,"question":"رسالة وصلت إلى البرنامج من المستمع عباس صافي النور، يقول: نويت الحج لوالدي، هل أحج لوالدي، أم لوالدتي؟ جزاكم الله خيرًا، علمًا بأن الوالد متوفٍ؟","title":"حكم تقديم الأم في البر","answer":"الجواب: إذا كانا جميعًا قد توفيا، ولم يحجا، فالأم أفضل، البدء بها أفضل؛ لأن حقها أكبر، أما إذا كانت موجودة، أو قد حجت؛ فإنك تحج عن الوالد، وذلك من بره، والوالدة إذا كان ما حجت؛ فاستعن بالله إذا استطعت أن تحججها إذا كانت تقدر على الحج، أما إذا كانت عاجزة، لكبر سنها؛ فإنك تحج عنها والحمد لله، وأنت مأجور. والخلاصة: أن الأب، والأم إذا استويا؛ فالأم أفضل، تقدم في البر؛ لقوله ﷺ لما سئل قال له السائل: يا رسول الله! من أحق الناس بحسن الصحبة؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أبوك وفي الحديث الآخر يقول ﷺ لما سأله سائل: من أبر؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أمك قال ثم من؟ قال: أبوك، ثم الأقرب فالأقرب. فالأم مقدمة في البر حية وميتة، فإذا كانا لم يحجا، وقد ماتا؛ فحج عن الأم أولًا، ثم عن الأب، هذا هو الأفضل، وإن بدأت بالأب؛ فلا حرج، لكنك تركت الأفضل، فالأفضل البداءة بها، ثم بالأب. وهكذا إذا كانا موجودين، ويعجزان عن الحج، وأنت تستطيع تحجيجهما؛ فحججهما جميعًا، فإن لم تستطع؛ فابدأ بالأم، فإن حقها أكبر، وفق الله الجميع. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15477/حكم-تقديم-الام-في-البر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_820/nour_82017.mp3","categories":["الأذان والإقامة"]},{"id":16723,"question":"أنا مؤذن، هل يلزمني بعد الأذان الدعاء المأثور، أم أنه لا يجب على المؤذن؟","title":"حكم الذكر الذي يقال عقب الأذان للمؤذن","answer":"الجواب: الدعاء ما هو بواجب، سنة للمؤذن، وغير المؤذن، الدعاء سنة، مستحب، ليس واجبًا للمؤذن بعد فراغه من الأذان، ولغيره، فالمؤذن بعد الفراغ يقول: اللهم صل وسلم على رسول الله، أو اللهم صل على محمد، وعلى آل محمد، ثم يقول: اللهم رب هذه الدعوة التامة، والصلاة القائمة، آت محمدًا الوسيلة والفضيلة، وابعثه مقامًا محمودًا الذي وعدته إنك لا تخلف الميعاد. وهكذا كل مسلم سمع الأذان يقول هذا، وهكذا كل مسلمة يستحب أن يقول هذا، من سمع الأذان من رجل، أو امرأة يجيب المؤذن، يقول مثل قول المؤذن إلا عند الحيعلة، فيقول: لا حول ولا قوة إلا بالله، عند حي على الصلاة، حي على الفلاح يقول: لا حول ولا قوة إلا بالله، أما البقية فيقول مثله، إذا قال: الله أكبر، يقول: الله أكبر، أشهد أن لا إله إلا الله، يقول: أشهد أن لا إله إلا الله، وهكذا، ثم بعد الفراغ يصلي على النبي ﷺ ثم يقول: اللهم رب هذه الدعوة التامة، والصلاة القائمة، آت محمدًا الوسيلة والفضيلة، وابعثه المقام المحمود الذي وعدته. يقول النبي ﷺ في الحديث الصحيح: من قال حين يسمع النداء: اللهم رب هذه الدعوة التامة، والصلاة القائمة، آت محمدًا الوسيلة والفضيلة، وابعثه مقامًا محمودًا الذي وعدته؛ حلت له شفاعتي يوم القيامة رواه البخاري في صحيحه، زاد البيهقي في آخره: إنك لا تخلف الميعاد بإسناد حسن. وفي الحديث الآخر: قال بعض الناس: يا رسول الله! إن المؤذنين يفضلونا قال: قل مثل قولهم، ثم سل تعطه وفي اللفظ الآخر قال: إذا سمعتم المؤذن فقولوا مثلما يقول، ثم صلوا علي، فإنه من صلى علي واحدة؛ صلى الله عليه بها عشرًا، ثم سلوا الله لي الوسيلة فإنها منزلة في الجنة لا تنبغي إلا لعبد من عباد الله، فأرجو أن أكون أنا هو، فمن سأل لي الوسيلة؛ حلت له الشفاعة هذا فضل عظيم. فيستحب للمؤمن والمؤمنة إذا سمع المؤذن أن يجيب المؤذن مثل قول المؤذن سواء سواء، إلا عند قول: حي على الصلاة، حي على الفلاح يقول: لا حول ولا قوة إلا بالله، ثم بعد الفراغ يصلي على النبي ﷺ يقول: اللهم صل وسلم على رسول الله، أو اللهم صل على محمد، وعلى آل محمد، كما صليت على آل إبراهيم، وبارك على محمد، وعلى آل محمد، كما باركت على آل إبراهيم، إنك حميد مجيد، أي نوع من أنواع الصلاة الإبراهيمية تكفي. ثم يقول: اللهم رب هذه الدعوة التامة، والصلاة القائمة، آت محمدًا الوسيلة، والفضيلة، وابعثه مقامًا محمودًا الذي وعدته. والأفضل أن يزيد إنك لا تخلف الميعاد هذا هو الأفضل، وهو سنة، وليس بواجب. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15473/حكم-الذكر-الذي-يقال-عقب-الاذان-للموذن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_718/nour_71805.mp3","categories":["الأدعية والأذكار","الأذان والإقامة"]},{"id":16825,"question":"تقول: والدتي منعتنا من زيارة أقاربنا الذين ينتسبون لوالدي بسبب بعض الخلافات التي حدثت بينهما، ومنها عدم زيارتهم لنا، وانقطاعهم عن زيارتنا، إلا إذا دعوناهم نحن لمناسبة، فهل نأثم على ترك زيارتهم طاعة لوالدتي؛ لأن طاعة الوالدين واجبة؟ أفيدونا عن هذا الموضوع، جزاكم الله خيرًا.","title":"حكم طاعة الأم في منعها لزيارة أقارب الأب","answer":"الجواب: طاعة الوالدين واجبة في المعروف، وصلة الرحم واجبة أيضًا، صلة الرحم واجبة بالكلام الطيب، وبالزيارة، وبالصدقة وبالهدية، فالواجب على والدتك أن لا تمنع من زيارة الأقارب (مثل) كالأعمام.. أعمام الأب، وأخوال الأب، فإن أعمام الأب أعمام لكم، وأخواله أخوال لكم، وأبوه جد لكم، فليس لها أن تمنعكم من صلة الرحم التي ليس فيها محذور، ولا منكر، يقول النبي ﷺ: إنما الطاعة في المعروف لا طاعة لمخلوق في معصية الخالق.  فالواجب على الوالدة أن تسمح لكم، وأن لا تمنعكم من الصلة التي شرعها الله، وأوجبها، وعليكم أن تلتمسوا رضاها بالكلام الطيب، والأسلوب الحسن، وأن تحاولوا معها أن تسمح لكم؛ حتى تجمعوا بين المصلحتين، رزق الله الجميع التوفيق. المقدم: اللهم آمين.. سماحة الشيخ! ما هو توجيهكم للأقارب الذين لا يجتمعون إلا في المناسبات؟! الشيخ: على كل حال إذا كان الاجتماع في المناسبات يحصل الحمد لله؛ لأن الصله ليس من لازمها الزيارات، الصلة: عدم القطيعة، معناها عدم القطيعة بالكلام الطيب.. بالهاتف.. بالسلام عند اللقاء.. بالزيارة.. بإرسال الهدية.. كل ما يدل على سلامة القلوب يحصل به الصلة، ولو ما زاره ولو بالهاتف، ولو بالوصية، بالسلام مع بعض الأصحاب. على كل حال، الصلة هي ضد القطيعة، فقد يستطيع بعض الناس الزيارة، وقد لا يستطيع بعض الناس الزيارة، لكن إذا وصلهم بالكلام الطيب من طريق الهاتف، من طريق التلفون، أو من طريق المكاتبة، أو من طريق تحميل بعض الأصحاب السلام، أو من طريق الزيارة، أو من طريق الهدية، ونحو ذلك، كل هذا يسمى صلة، نعم. المقدم: جزاكم الله خيرًا.. إذًا الصلة البدنية لا تشترط ....؟ الشيخ: ما هو بلازم، ليس بلازم، قد يمنعها مانع، نعم. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15575/حكم-طاعة-الام-في-منعها-لزيارة-اقارب-الاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_763/nour_76311.mp3","categories":["الأذان والإقامة"]},{"id":16899,"question":"هل يجوز تأجير مطعم بكامل معداته، وأدواته، وعماله على شخص مستأجر، على أن يدفع المستأجر مبلغًا معينًا ثابتًا شهريًا للمؤجر، سواء ربح المطعم، أو خسر، مع العلم أن المستأجر يأخذ راتبًا شهريًا من المؤجر، وأيضًا المتبقي الصافي بعد خصم المبلغ المخصص للمؤجر، سواء كان قليلًا، أو كثيرًا؟","title":"حكم أخذ المستأجر أجرة من المؤجر","answer":"الجواب: .... على تأجير المطعم الأدوات التي فيه تأجيرها على زيد، أو عمرو لا بأس إذا كان بأجر معلوم لمدة معلومة، وهو يستعمل هذه الأشياء التي في المطعم من كراسي، ومن فرش، ومن أدوات، ومن أواني يستعملها في إطعام الناس، وفي صنع الولائم لهم، لا بأس بذلك، لكن كونه أجيرًا لصاحب المطعم، أي وجه لهذا مادام المطعم قد استأجره؟ كيف يكون أجيرًا له هو وهو استأجر المطعم؟ كيف يصير هذا وكونه مستأجرًا للمطعم يتصرف فيه..... يطعم الناس، ويأخذ الأجرة من الناس، فعلى أي وجه يأخذ أجرة هو وهو صاحب المطعم، وهو الذي استأجر المطعم، وصار يطعم الناس، ويأخذ منهم قيمة الطعام، والشراب؟ هذا غريب، محل نظر، نرى أن صاحب المطعم يتصل بي أحسن؛ حتى أشوف موضوعه، يتصل بي مشافهة حتى يدرس الموضوع معه؛ لأن السؤال فيه غرابة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15657/حكم-اخذ-المستاجر-اجرة-من-الموجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_719/nour_71906.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":16914,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: (س. ر) أخونا رسالته مطولة بعض الشيء يقول فيها: أنا طالب أدرس في إحدى الدول العربية، وخلال هذه الدراسة استأجرت غرفة عند حجة متقدمة -ربما يقصد امرأة كبيرة السن عند حجة متقدمة- في السن اعتادت أن تؤجر غرفًا من بيتها، وعند انتهاء تلك السنة الدراسية أردت أن أذهب لزيارة أهلي لمدة شهرين، ثم أعود..الشيخ: أعدالمقدم: تقول الرسالة: أنا طالبٌ أدرس في إحدى الدول العربية، وخلال هذه الدراسة استأجرت غرفة عند حجة متقدمة في السن اعتادت أن تؤجر غرفًا من بيتها، وعند انتهاء تلك السنة الدراسية أردت أن أذهب لزيارة أهلي لمدة شهرين، ثم أعود، فسألتها إن كانت تقبل أن أترك أغراضي في الغرفة حتى أعود، فأخذتها من عندها، فقبلت، وقالت: ضع ذلك تحت السرير بشكلٍ لا يظهر؛ ففعلت، وبقيت شنطة ثيابي فوضعتها على ظهر خزانة الثياب، وتركت للحجة المفتاح؛ لأنها كانت غائبة عن البيت تلك الساعة -المهم- عندما رجعت لأخذ الأغراض، قالت لي: أين ذهبت، وتركت أغراضك، ولم يرض أحد أن يستأجر الغرفة بسبب هذه الأغراض -هذا على حد قولها- وأنكرت إنكارًا شديدًا أنها سمحت لي بإبقاء ثيابي وملابسي عندها، وطالبتني بأجرة، فبماذا تنصحونني؟ جزاكم الله خيرًا.","title":"الرجوع عند المخاصمات إلى المحاكم","answer":"الجواب: هذه خصومة بينك وبينها، راجع المحكمة، والمحكمة فيها الكفاية، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، يقول: إذا كانت تلك خصومة بيني وبينها، وحكمت المحكمة علي بما تحكم من دفع المال، فهل يجب علي شرعًا أن أدفع؟ الشيخ: إن أعطيتها الأجرة ولم تخاصمها؛ فهو خير لك وأحسن، إن أعطيتها الأجرة ولم تخاصمها؛ فهو خير لك، وإلا فالمحكمة فيها الكفاية، إذا ألزمتك؛ عليك أن تلتزم بحكم الشرع، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15679/الرجوع-عند-المخاصمات-الى-المحاكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_826/nour_82603.mp3","categories":["الأذان والإقامة"]},{"id":17028,"question":"أيضًا يقول: عندنا في أغلب المساجد يقولون بعد الانتهاء من الأذان، وبعد قول: لا إله إلا الله، يقولون بصوت مرتفع، وفي الميكرفون: الصلاة والسلام عليك يا سيدي يا رسول الله.. إلى آخر ما يقولون، ما الحكم في مثل هذا العمل؟","title":"ما الصحيح من الأذكار الواردة بعد الأذان؟","answer":"الجواب: هذا غير مشروع بعد الأذان، لا في المكبر، ولا غيره، الأذان ينتهي عند لا إله إلا الله بس، ولا يزيد المؤذن شيئًا، لكن يصلي على النبي ﷺ بصوت آخر غير صوت الأذان، وهكذا من سمع الأذان يصلي على النبي ﷺ ويقول: اللهم رب هذه الدعوة التامة، والصلاة القائمة، آت محمدًا الوسيلة والفضيلة، وابعثه مقامًا محمودًا الذي وعدته؛ إنك لا تخلف الميعاد هذا هو المشروع، يقول ﷺ لما قيل له: «إن المؤذنين يفضلونها، قال -عليه الصلاة والسلام-: قولوا مثلما يقولون، ثم صلوا علي فإنه من صلى علي صلاة واحدة صلى الله عليه بها عشرًا، ثم سلوا الله لي الوسيلة؛ فإنها منزلة في الجنة، لا تنبغي إلا لعبد من عباد الله، وأرجو أن أكون أنا هو، فمن سأل لي الوسيلة؛ حلت له الشفاعة. وقال ﷺ: من قال حين يسمع النداء: اللهم رب هذه الدعوة التامة، والصلاة القائمة، آت محمدًا الوسيلة والفضيلة، وابعثه مقامًا محمودًا الذي وعدته؛ حلت له الشفاعة رواه البخاري في الصحيح، زاد البيهقي بإسناد جيد: إنك لا تخلف الميعاد. وقال -عليه الصلاة والسلام-: إذا سمعتم المؤذن فقولوا مثلما يقول هذه السنة، فالمؤذن يجاب نجيبه كما قال بصوت منخفض، وإذا فرغ نصلي على النبي ﷺ والمؤذن يصلي عليه، لكن بصوت منخفض غير صوت الأذان، ثم يأتي بـ اللهم رب هذه الدعوة .. إلى آخره. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15821/ما-الصحيح-من-الاذكار-الواردة-بعد-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_830/nour_83009.mp3","categories":["الأدعية والأذكار","الأذان والإقامة"]},{"id":17059,"question":"تقول سماحة الشيخ: إنها تقرأ القرآن الكريم، لكنها لا تفهم بعض الآيات، هل تكون آثمة حينئذ؟","title":"هل يأثم من يقرأ القرآن ولا يفهم بعض الآيات؟","answer":"الجواب: لا حرج في ذلك، الإنسان يقرأ القرآن .. يتفهم، يتدبر، يتعقل، فإن فهم فالحمد لله، وإلا لا حرج عليه ولو ما فهم يقرأ، ويكثر القراءة، والله  يفتح عليه، إذا أكثر القراءة يفتح الله عليه، ويراجع كتب التفسير إذا كان يقرأ، إذا كان يستطيع يطالع، يسأل أهل العلم عما أشكل عليه حتى يزداد علمه بكتاب الله. والمقصود: أن التلاوة عبادة قربة، وطاعة وإن لم يفهم، عبادة وقربة كل حرف بحسنة، والحسنة بعشر أمثالها، لكن يشرع للمؤمن، والمؤمنة العناية بالتدبر، والتعقل حتى يستفيد، حتى يفهم كلام الله؛ لأن الله أنزله للعمل والفهم، قال تعالى: كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُوْلُوا الأَلْبَابِ [ص:29]، قال سبحانه: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9] فلابد من التدبر، والتعقل حتى تفهم، حتى تستفيد.  وإذا قرأت آيات لم تفهمها فلا حرج عليك وأنت مأجور، ولك بكل حرف حسنة، والحسنة بعشر أمثالها، لكن يشرع لك التدبر، والتعقل، والتفهم دائمًا، ومراجعة كتب التفسير مثل البغوي، مثل تفسير ابن كثير، ابن جرير، تستفيد من هذه التفاسير وتنتفع وتعرف المعنى. نعم.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15851/هل-ياثم-من-يقرا-القران-ولا-يفهم-بعض-الايات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_721/nour_72105.mp3","categories":["الأذان والإقامة"]},{"id":17096,"question":"نعود في هذه الحلقة إلى رسالة المستمع أحمد عوض زائد حيث عرضنا بعضًا من أسئلته في حلقة مضت، وفي هذه الحلقة بقي له بعض الأسئلة، في أحدها يقول: هل متابعة القرآن الكريم من الراديو فيه أجر على ذلك؟ أم سماعه من القارئ شخصيًا؟جزاكم الله خيرًا.","title":"نيل الأجر من سماع القرآن من الراديو","answer":"الجواب: سماع القرآن فيه أجر عظيم، سواء من الشريط، أو من القارئ الحاضر، فيه خير عظيم بالإخلاص لله، وقصد الفائدة، وقصد العمل بقوله سبحانه: وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنصِتُوا [الأعراف:204] فأنت على خير عظيم، فاستماع القرآن من الأشرطة، ومن القارئ الذي يحضر بينكم في المجلس كله خير عظيم، وفيه فائدة عظيمة. ونوصي الجميع بسماع القرآن، نوصي الجميع بالاستماع لكتاب الله، من الشريط الذي فيه تسجيل القرآن لبعض أهل العلم، وبالقراءة الحسنة، وهكذا إذا كنتم جالسين يقرأ أحدكم، وتستمعون له، ولا سيما من كان حسن الصوت ففي هذا خير عظيم، كان النبي ﷺ إذا جلس بين أصحابه قرأ عليهم القرآن، وفسر لهم معانيه -عليه الصلاة والسلام- وربما أمر بعض الصحابة أن يقرأ وهو يستمع -عليه الصلاة والسلام- فالسنة للمؤمنين، والمؤمنات إذا جلسوا أن يستمعوا للقرآن من بعضهم، أو من شريط مسجل لقارئ طيب يستفيدون، ويتدبرون، ويتعقلون، ويعملون، وفق الله الجميع. نعم.  المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15939/نيل-الاجر-من-سماع-القران-من-الراديو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_831/nour_83109.mp3","categories":["الأذان والإقامة"]},{"id":17102,"question":"الحديث الثاني: \"إذا كنت في الصلاة فدعاك أبوك فأجبه، وإن دعتك أمك فأجبها\"؟","title":"حكم إجابة الوالدين أثناء الصلاة","answer":"الجواب: نعم. هذا من بر الوالدين، إذا دعاك وعرفت أنه لا يسمح، ولا يمهلك تجيبه إذا كانت الصلاة نافلة، أما إذا كانت فريضة لا، تكمل الفريضة، لكن إذا كانت نافلة، وتخشى أن يغضب عليك، أو تغضب عليك الوالدة إذا تأخرت فاقطعها لقصة حديث جريج؛ لأن النبي ﷺ أخبر عن جريج أن أمه دعته وهو يصلي، وهو فيمن كان قبلنا من بني إسرائيل، فقال: يا رب أمي وصلاتي، ولم يجبها، وكررت ثلاث مرات، ولم يجبها، وآثر صلاته، فدعت عليه، فقالت: اللهم لا تمته حتى تريه وجوه المومسات، فأجاب الله دعوتها. فهذا يدل على أنه ينبغي للمؤمن أن لا يترك جواب أمه وأبيه؛ لأن حقهما عظيم، أما إذا كان يعلم أنهما لا يغضبان، ويسمحان عنه حتى يكمل فلا بأس، لكن إذا خشي غضبهما فإنه يقطع الصلاة، ويجيبهما في النافلة فقط، أما الفريضة فأمرها عظيم، لا يجوز قطعها، بل يكملها، ثم يعتذر إليهما. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15946/حكم-اجابة-الوالدين-اثناء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_831/nour_83113.mp3","categories":["الأذان والإقامة"]},{"id":17122,"question":"هذا السائل سوداني، ومقيم يعمل بالمملكة، يقول: بالنسبة لصلاة المرأة هل تقيم الصلاة، أو تكبر وتصلي الأوقات المكتوبة عليها؟","title":"هل تقيم المرأة الصلاة، أم تكبر وتصلي؟","answer":"الجواب: المرأة ليس عليها أذان ولا إقامة، ولا يشرع لها أذان ولا إقامة، تصلي بدون أذان، وبدون إقامة، الأذان والإقامة من شأن الرجال، أما المرأة تصلي بحمد الله من غير أذان ولا إقامة، تدخل بالصلاة بالتكبير. نعم، تدخل فيها بالتكبير، والنية القلبية. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15934/هل-تقيم-المراة-الصلاة-ام-تكبر-وتصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_589/58918.mp3","categories":["الأذان والإقامة","قضايا المرأة"]},{"id":17178,"question":"رجل أذن وأثناء الأذان قام بمخاطبة رجل آخر ففصل بين الأذان، فما حكم ذلك؟","title":"حكم كلام المؤذن مع غيره أثناء الأذان","answer":"الجواب: إذا كان شيئًا يسيرًا يعفى عنه -إن شاء الله- إذا كان كلمات يسيرة يعفى عنها، ويتمم بعد ذلك. نعم. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15996/حكم-كلام-الموذن-مع-غيره-اثناء-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_590/59007.mp3","categories":["الأذان والإقامة"]},{"id":17222,"question":"إذا دخل الشخص المسجد، وقبل أن يشرع في أداء تحية المسجد أذن المؤذن، فهل يجلس حتى ينتهي الأذان، ثم يقوم ويصلي؟ أم يظل واقفًا؟ جزاكم الله خيرًا.","title":"ما يفعله من دخل المسجد والمؤذن يؤذن؟","answer":"الجواب: الأفضل أن يجمع بين السنتين، يجيب المؤذن وهو واقف، ثم يصلي الركعتين، فإن كان يشق عليه ذلك؛ صلى ركعتين، ولو كان يؤذن، لكن إذا تيسر له الوقوف حتى يجيب المؤذن، ثم يصلي ركعتين جمع بين السنتين. نعم. المقدم: جزاكم الله خيرًا، و أحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16048/ما-يفعله-من-دخل-المسجد-والموذن-يوذن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_723/nour_72318.mp3","categories":["الأذان والإقامة"]},{"id":17389,"question":"الرسالة التالية من إحدى الأخوات المستمعات تقول: إنني -ولله الحمد- مواظبة على أداء الصلوات في أوقاتها، ولكني لا أصلي صلاة الليل، ولا أصلي الضحى وأنا مستطيعة، فهل علي إثم؟","title":"حكم ترك صلاة النوافل مع الاستطاعة","answer":"الجواب: هذه من نعم الله العظيمة، المحافظة على الصلوات الخمس هذه من نعم الله العظيمة، وذلك من أوجب الواجبات، لقول الله سبحانه: حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى [البقرة:238] وقوله سبحانه: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ [البقرة:43]، وفي آيات كثيرات حث على المحافظة، والخشوع، والعناية بالصلاة، فاحمدي الله على ذلك، واسأليه الثبات. فالواجب على كل مؤمن ومؤمنة المحافظة على الصلوات الخمس في أوقاتها، والرجل يؤديها في الجماعة في مساجد الله، ولا يجوز له التساهل في أدائها في البيت، بل يجب على الرجل أن يصليها مع الجماعة في المساجد، وعلى المرأة أن تصليها في الوقت مع الخشوع، والطمأنينة، وعدم العجلة، لقوله سبحانه: قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلاتِهِمْ خَاشِعُونَ [المؤمنون:2] وقوله -جل وعلا-: وَأَقِمِ الصَّلاةَ إِنَّ الصَّلاةَ تَنْهَى عَنِ الْفَحْشَاءِ وَالْمُنْكَرِ [العنكبوت:45] . فالواجب على كل مؤمن، وعلى كل مؤمنة العناية بالصلاة، والمحافظة عليها في أوقاتها، مع العناية بالخشوع، والطمأنينة، وعدم العجلة، واستحضار القلب بين يدي الله  ويزيد الرجل الحضور في الجماعة، وأن الواجب عليه أن يحضر في الجماعة، وأن يصليها مع إخوانه في بيوت الله، لقول النبي ﷺ: من سمع النداء فلم يأت؛ فلا صلاة له إلا من عذر قيل لابن عباس: ما العذر؟ قال: خوف، أو مرض. وفي الصحيح أيضًا عن النبي ﷺ أنه قال لابن أم مكتوم -وهو أعمى- لما سأله قال: يا رسول الله! ليس لي قائد يقودني إلى المسجد، فهل لي من رخصة أن أصلي في بيتي؟ فقال له ﷺ: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب هذا أعمى ليس له قائد يقوده، ومع ذلك يقول له النبي ﷺ: أجب يعني: إلى أدائها في الجماعة في بيوت الله. نعم. أما صلاة الضحى، والتهجد بالليل فهذا مستحب، من تيسر له التهجد بالليل فهو قربة عظيمة، وعبادة مؤكدة، ولو ركعة واحدة في الليل، ولو ركعات ثلاث، أقلها ركعة واحدة، الوتر، وإن صلى ثلاثًا، أو أكثر فهو أفضل، والضحى سنة أيضًا، ولو ركعتين، النبي ﷺ أوصى بذلك جماعة من الصحابة ركعتين ركعتي الضحى، لكن ليست واجبة، لا صلاة الليل، ولا الضحى، إنما هي مستحبة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16268/حكم-ترك-صلاة-النوافل-مع-الاستطاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_835/nour_83505.mp3","categories":["الأذان والإقامة"]},{"id":17441,"question":"ننتقل إلى قضية أخرى عبر رسالة وصلت إلينا من القصيم، وباعثها مستمع رمز إلى اسمه بالحروف (ر. غ. ش) يقول: تعينت في وظيفة، وولدي في وظيفة أخرى، والراتب ما يقرب من ألفي ريال، ثم حصلت على وظيفة تبعد عن القرية التي أنا فيها، والتي أيضًا الوظيفة فيها مسافة أربعين كيلو مترًا، فاستقدمت إنسانًا براتب سبعمائة ريال ليقوم بوظيفتي، ووظيفة ابني، لكن ذلك الشخص غير راضٍ، فما حكم ما فعلت؟ جزاكم الله خيرًا.","title":"حكم النيابة في العمل مقابل جزء من الراتب","answer":"الجواب: إذا لم يكن راضيًا؛ فليس لك إجباره أنت، ولا غيرك، وإذا رضي؛ فلابد من استئذان مرجعك في الوظيفة: هل يرضى بهذا النائب عنك، أم لا يرضى؟ فلا بد من رضا المرجع في الوظيفة الأولى، ولابد من رضا النائب عنك الذي استأجرته؛ ليقوم بعملك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16298/حكم-النيابة-في-العمل-مقابل-جزء-من-الراتب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_836/nour_83602.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":17460,"question":"هذه السائلة تقول: إذا أخطأت في آية من آيات القرآن الكريم، وأنا أصلي مثلًا، لو قلت: آلم ۝ ذلك الكتاب لا ريب فيه هدى للمؤمنين، بدلًا من المتقين، فما الحكم في ذلك، هل أعيد الصلاة؟ أم أسجد للسهو؟","title":"حكم خطأ المصلي في قراءة القرآن","answer":"الجواب: لا حرج في ذلك، لا يضر -إن شاء الله- ولا تعيد، الصلاة صحيحة، ولا .... تسجد للسهو الحمد لله؛ لأن هذا غلط في اللفظ والمعنى صحيح، نعم.  المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16328/حكم-خطا-المصلي-في-قراءة-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_772/nour_77216.mp3","categories":["الأذان والإقامة"]},{"id":17527,"question":"بعض الناس عند إقامة الصلاة يقول: أقامها الله وأدامها، هل ورد ذلك؟","title":"حكم قول: (أقامها الله وأدامها) عند إقامة الصلاة","answer":"الجواب: ورد حديث ضعيف، والصواب أن يقول مثله: قد قامت الصلاة قد قامت الصلاة، لقوله ﷺ: إذا سمعتم المؤذن فقولوا مثلما يقول والإقامة أذان، لقوله ﷺ: بين كل أذانين صلاة، بين كل أذانين صلاة، فسمى الإقامة أذانًا، فيقول إذا قال المؤذن: قد قامت الصلاة يقول مثله: قد قامت الصلاة قد قامت الصلاة، هذا هو الصواب، أما حديث أقامها الله وأدامها فهو حديث ضعيف عند أهل العلم. نعم.\nالمقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16447/حكم-قول-اقامها-الله-وادامها-عند-اقامة-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_775/nour_77505.mp3","categories":["الأذان والإقامة"]},{"id":17528,"question":"هذا سائل يقول للبرنامج يقول في سؤاله: هل ورد عند قولنا عندما يقول المؤذن: الصلاة خير من النوم، صدقت وبررت وبالحق نطقت؟","title":"ما يقال عند قول المؤذن: الصلاة خير من النوم؟","answer":"الجواب: هذا يقوله بعض الفقهاء، والصواب أنه يقول مثله: الصلاة خير من النوم؛ لقول النبي ﷺ: إذا سمعتم المؤذن فقولوا مثلما يقول، هذا يعم كلمة الصلاة خير من النوم، الصلاة خير من النوم، ولا يقول: صدقت وبررت، ولا غير هذا، بل يقول: الصلاة خير من النوم؛ عملًا بقول النبي ﷺ: إذا سمعتم المؤذن فقولوا مثلما يقول هذا هو المشروع إلا الحيعلة، فيقول: لا حول ولا قوة إلا بالله عند قوله: حي على الصلاة، حي على الفلاح، يقول: لا حول ولا قوة إلا بالله؛ لأنه صح عن النبي ﷺ أنه كان يقول ذلك عند الحيعلة كما رواه مسلم من حديث عمر . نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16442/ما-يقال-عند-قول-الموذن-الصلاة-خير-من-النوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_775/nour_77502.mp3","categories":["الأذان والإقامة"]},{"id":17577,"question":"رسالة وصلت إلى البرنامج من أحد المستمعين من القصيم رمز إلى اسمه بالحروف ( س. ف ) يقول: صاحب مزرعة عنده عامل لغرض المزرعة فقط، وصاحب المزرعة يشتغل فراش في مسجد، وبعض الأوقات يأخذ العامل إلى المسجد لكي يقوم العامل بنظافة المسجد، والمرتب لصاحب المزرعة، هل يحق له ذلك أو لا؟","title":"حكم تكليف العامل بأعمال أخرى بدون أجر","answer":"الجواب: إذا سمح العامل فلا بأس، إذا سمح أن يذهب إلى المسجد ويقوم بخدمة المسجد فلا بأس، أما إذا لم يسمح فليس له إلزامه؛ لأن العمل اللي عنده في المزرعة، استأجره ليعمل في المزرعة، أما إذا سمح العامل أنه يخدم المسجد فهذا قربة وطاعة لا بأس الحمد لله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16503/حكم-تكليف-العامل-باعمال-اخرى-بدون-اجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_839/nour_83904.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":17635,"question":"تقول: إنها متزوجة من رجل ملتزم بتعاليم الدين لكن هذا الرجل يواجه بعض العقوق من أقربائه وأصدقائه لكونه متمسكًا بدين الإسلام وبتعاليم رسول الله ﷺ، وتسأل سماحتكم التوجيه كيف تتصرف مع هؤلاء؟ وكيف تنصح زوجها؟ جزاكم الله خيرًا.","title":"توجيه لمن قاطعه أقاربه وأصدقاؤه لتمسكه بالدين","answer":"الجواب: ما دام متمسكًا بدينه فالحمد لله، عليه الصبر والاستمرار والاستقامة ولو قاطعه بعض الأقارب، حق الله مقدم على الأقارب، فليثبت وليستقم وليعاملهم بالتي هي أحسن، ويصلهم إذا قطعوه، ويحسن إليهم إذا أساءوا إليه، وله البشرى والعاقبة الحميدة، يقول الله جل وعلا في كتابه العظيم: إِنَّ الَّذِينَ قَالُوا رَبُّنَا اللَّهُ ثُمَّ اسْتَقَامُوا [فصلت:30] يعني: على طاعته تَتَنَزَّلُ عَلَيْهِمُ الْمَلائِكَةُ أَلَّا تَخَافُوا وَلا تَحْزَنُوا وَأَبْشِرُوا بِالْجَنَّةِ الَّتِي كُنْتُمْ تُوعَدُونَ ۝ نَحْنُ أَوْلِيَاؤُكُمْ فِي الْحَيَاةِ الدُّنْيَا وَفِي الآخِرَةِ وَلَكُمْ فِيهَا مَا تَشْتَهِي أَنفُسُكُمْ وَلَكُمْ فِيهَا مَا تَدَّعُونَ ۝ نُزُلًا مِنْ غَفُورٍ رَحِيمٍ [فصلت:30-32].\nفالمؤمن يستقيم على طاعة الله ويجتهد في ذلك، وهكذا المؤمنة، ولو كره بعض أقاربه، ولو قاطعه بعض أقاربه، فإذا كان بعض أقاربه لا يصلون وهو يصلي فليحمد الله وليدعو الله لهم بالهداية، وإذا كانوا أهل خمر وهو ينهاهم عن الخمر فليحمد الله ويسأل ربه لهم الهداية، وإذا كانوا على قطيعة وعقوق فليجتنب ذلك ولا يكن مثلهم في العقوق والقطيعة وليسأل الله لهم الهداية، وهكذا إذا كانوا أهل غيبة ونميمة لا يوافقهم على ذلك وينكر عليهم بالكلام الطيب والحكمة ولا يضره قطيعتهم. يقول النبي ﷺ: ليس الواصل بالمكافي، وإنما الواصل الذي إذا قطعت رحمه وصلها، هذا الواصل الحقيقي الكامل، أما اللي يصلهم إن وصلوا ويقطعهم إن قطعوا هذا مكافي لكن الواصل على الحقيقة الذي يصلهم وإن قطعوا، ويحسن إليهم وإن أساءوا، هذا هو الواصل الكامل، ولهذا في الحديث الآخر: \"أن رجلًا قال: يا رسول الله! إن لي قرابة أصلهم ويقطعونني وأحسن إليهم ويسيئون إلي وأحلم عنهم ويجهلون علي، فقال له النبي ﷺ: لئن كنت كما قلت لكأنما تسفهم المل، يعني: الرماد الحامي ولا يزال معك من الله ظهير يعني: عليهم ما دمت على ذلك. فالله يعينه عليهم، ويمكنه منهم، وهو المصيب، وهم المخطئون، وليصبر وليحتسب ويسأل الله لهم الهداية، ولا يضره قطيعتهم، الإثم عليهم، ولكن هو يصلهم بما يستطيع إذا كانوا فقراء يحسن إليهم، إذا مروا سلم عليهم، إذا وافقهم سلم عليهم، وإن لم يردوا، إذا رأى منهم ما لا ينبغي أمرهم بالمعروف ونهاهم عن المنكر وإن لم يستجيبوا، إذا ظلموا ينصرهم على من ظلمهم يساعدهم على ترك الظلم وعلى رد الظلمة إليهم، يكون خيرًا منهم، يشفع لهم في الخير الذي ينفعهم ويكون سببًا لهدايتهم.\nفالمقصود أنه يعاملهم بما يرضي الله فيهم ويجتهد في نفعهم والدعاء لهم بالهداية وإن قطعوه، هذا هو طريق أهل الخير والهدى. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16559/توجيه-لمن-قاطعه-اقاربه-واصدقاوه-لتمسكه-بالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_844/nour_84404.mp3","categories":["الأذان والإقامة"]},{"id":17724,"question":"كثير من الإخوان يسألون هذا السؤال، وهو: الدعاء الوارد بعد الأذان، وهل هناك أدعية بعد أن يتم المؤذن أذانه؟","title":"ما الدعاء المشروع بعد الأذان؟","answer":"الجواب: النبي ﷺ أوصى بذلك قال: إذا سمعتم المؤذن فقولوا مثلما يقول ثم صلوا علي فإنه من صلى علي واحدة صلى الله عليه بها عشرًا ثم سلوا الله لي الوسيلة؛ فإنها منزلة في الجنة لا تنبغي إلا لعبد من عباد الله وأرجو أن أكون أنا هو، فمن سأل الله لي الوسيلة حلت له الشفاعة هذا السنة، وقال: من قال حين يسمع النداء: اللهم رب هذه الدعوة التامة والصلاة القائمة، آت محمدًا الوسيلة والفضيلة، وابعثه مقام محمودًا الذي وعدته؛ حلت له شفاعتي يوم القيامة. فينبغي للمؤمن إذا سمع النداء أن يجيب المؤذن مثله: الله أكبر الله أكبر، أشهد أن لا إله إلا الله أشهد أن لا إله إلا الله، أشهد أن محمدًا رسول الله كذلك، حي على الصلاة: لا حول ولا قوة إلا بالله، حي على الفلاح: لا حول ولا قوة إلا بالله، الصلاة خير من النوم يقول مثلها: الصلاة خير من النوم، الله أكبر الله أكبر، لا إله إلا الله مثله سواء سواء، وهكذا في قد قامت الصلاة يقول مثله: قد قامت الصلاة- في الإقامة- ثم يقول بعده يصلي على النبي ﷺ بعد ذلك، ثم يقول: اللهم رب هذه الدعوة التامة والصلاة القائمة، آت محمدًا الوسيلة والفضيلة وابعثه مقامًا محمودًا الذي وعدته، زاد البيهقي بإسناد جيد: إنك لا تخلف الميعاد نعم.\nالمقدم: في لفظ: ثم صلوا علي الصلاة الواردة يا شيخ؟\nالشيخ: اللهم صل على محمد وعلى آل محمد، كما صليت على إبراهيم وعلى آل إبراهيم ، إنك حميد مجيد، اللهم بارك على محمد وعلى آل محمد كما باركت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد هذه أفضل ما ورد.. أكمل ما ورد.\nوإن قال: اللهم صل على محمد وعلى أزواجه وذريته كما صليت على آل إبراهيم، وبارك على محمد وعلى أزواجه وذريته كما باركت على آل إبراهيم إنك حميد مجيد فهو صحيح ثابت عن النبي أيضًا، فإذا صلى على النبي ﷺ بأي نوع من الصفات الواردة فقد فعل السنة.\nالمقدم: لو قال: (اللهم صل على نبينا محمد) فقط (اللهم رب هذه الدعوة التامة ...)؟\nالشيخ: لا بأس، لكن إذا كملها أفضل، إذا كمل أفضل.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16682/ما-الدعاء-المشروع-بعد-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_595/59530.mp3","categories":["الأدعية والأذكار","الأذان والإقامة"]},{"id":17757,"question":"تقول السائلة في هذا  نعيش في بلدة نائية بها مسجد لا يصلي به أحد..الشيخ: أيش؟المقدم: تقول السائلة: نعيش في بلدة نائية بها مسجد لا يصلي به أحد إلا المارة ليس لهذا المسجد مؤذن؛ لأنه مسجد خاص بناه أحد الناس، لا تصلى فيه التراويح في رمضان ويذهب أحيانًا زوجي يؤذن ويقيم ويصلي وحده وقد نصحنا بعض الإخوان بالصلاة فيه ولكن دون فائدة، هل يستمر زوجي في الصلاة فيه لوحده أم ماذا علينا؟ وهل يجب أن يصلي في المنزل بمفرده؟","title":"حكم إقامة الصلاة بمسجد لا يغشاه الناس إلا نادرًا","answer":"الجواب: هذا الذي عمله زوج السائلة عمل طيب، وهو مشكور عليه، ونوصيه بالاستمرار بأن يذهب إلى المسجد، ويؤذن؛ لعل الله يأتي بمن يصلي معه من المارة، أو من السكان، وإن لم يأت صلى وحده، والحمد لله، نوصيه بأن يستمر، وأن لا يصلي في البيت؛ لأن المساجد عمرت لهذا، وعلى المؤمن أن يذهب إلى المسجد فإن وجد أحدًا وإلا صلى وحده والحمد لله، لا يجوز الصلاة في البيت والمساجد موجودة، وكونه قد لا يصلي مع أحد لا يضره ذلك، يكون له الأجر العظيم، فليؤذن وله فضل الأذان، يقول النبي ﷺ: لا يسمع صوت المؤذن جن ولا إنس، ولا شجر ولا حجر، ولا شيء؛ إلا شهد له يوم القيامة فضل عظيم، ثم هو بهذا يدعو الناس إلى إقامة صلاة الجماعة يكون له مثل أجورهم؛ لأنه دعاهم إلى الخير فيكون له مثل أجور من صلى معه: من دل على خير فله مثل أجر فاعله فنوصي زوجك بالاستمرار، والعمل الطيب، والذهاب إلى المسجد، وأن هذا هو الواجب عليه وإن تخلف عنه الجيران أو غيرهم. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16730/حكم-اقامة-الصلاة-بمسجد-لا-يغشاه-الناس-الا-نادرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_777/nour_77712.mp3","categories":["الأذان والإقامة","المساجد ومواضع السجود"]},{"id":17761,"question":"سماحة الشيخ! هذا سائل رمز لاسمه بـ (ع.ع. ل) يقول في هذا  قال الرسول صلى الله عليه وآله وسلم: أنا وكافل اليتيم كهاتين في الجنة وأشار بالسبابة والوسطى، و هل كافل اليتيم المذكور في الحديث هو الذي يكفل اليتيم منذ صغره وحتى البلوغ، أو أنه الذي يكفل اليتيم لأي مدة مثلًا يكفل اليتيم لمدة سنة سنتين أكثر؟","title":"كيفية تحقق الأجر بكفالة اليتيم","answer":"الجواب: الحديث عام يرجى لكافل اليتيم هذا الخير العظيم، كلما طالت المدة صار الأجر أكثر، فإذا كفله سنة أو شهر أو سنتين أو أكثر فله أجره العظيم، وإذا كفله من صغره إلى أن يبلغ ويرشد صار أجره أعظم مع النية الصالحة والإخلاص لله .\nفعلى كل حال: كفالة اليتيم قربة وطاعة قلت أو كثرت، والوعد صادر من النبي عليه الصلاة والسلام، فالمؤمن يقصد الخير، ويرجو هذا الخير، ويعمل ما يستطيع للإحسان إلى الأيتام والمساكين، ورحمة حالهم، وكفالتهم، وهكذا غيرهم من الفقراء. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16736/كيفية-تحقق-الاجر-بكفالة-اليتيم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_777/nour_77716.mp3","categories":["الأذان والإقامة"]},{"id":17787,"question":"هذا سائل أرسل بمجموعة من الأسئلة السائل حميدان الصبحي يقول: ما حكم من نسي إقامة الصلاة ولم يذكر إلا بعد قطع التكبيرة هل يكمل الصلاة؟ أم ماذا يفعل؟ وما حكم الصلاة التي صلاها بدون إقامة؟ وجهونا سماحة الشيخ.","title":"حكم ترك إقامة الصلاة","answer":"الجواب: لا حرج عليه في ذلك تسقط والحمد لله؛ لأنها فرض كفاية فإذا لم يقم الصلاة فلا حرج عليه وصلاته صحيحة ولا ينقضها لأجل الإقامة بل يستمر ويكملها والحمد لله. نعم.","link":"https://binbaz.org.sa/fatwas/16788/حكم-ترك-اقامة-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_778/nour_77814.mp3","categories":["الأذان والإقامة"]},{"id":17789,"question":"يقول السائل: أنا في بعض المرات أنسى في أذان الفجر قول: الصلاة خير من النوم، أذكر بعد أن أنتهي من الأذان ماذا علي في ذلك؟","title":"حكم نسيان المؤذن قول: الصلاة خير من النوم","answer":"الجواب: سنة، .... في أذان الفجر فإن ذكرتها قريبًا فأت بها ثم أعد الله أكبر الله أكبر لا إله إلا الله، وإن أعدت الأذان كله فهو طيب وحسن؛ لأنها سنة مهمة يعرف بها أذان الفجر وطلوع الفجر، والنبي ﷺ أمر أن تجعل في أذان الفجر، الصلاة خير من النوم. نعم.","link":"https://binbaz.org.sa/fatwas/16790/حكم-نسيان-الموذن-قول-الصلاة-خير-من-النوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_778/nour_77815.mp3","categories":["الأذان والإقامة"]},{"id":17906,"question":"من فقراته يقول يا سماحة الشيخ: كيف يكون التحدث بنعم الله ؟","title":"كيفية التحدث بنعم الله","answer":"الجواب: يتحدث بنعم الله التي أنعم عليه: أنه رزق مالًا حلالًا، أنه بحمد الله يحافظ على الصلاة في الجماعة، أنه بحمد الله بار بوالديه، أنه بحمد الله يؤدي الزكاة، ليس على قصد الرياء، بل على سبيل التحدث بنعم الله جل وعلا، أنه بحمد الله قد صبر واحتسب على مصيبته. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16909/كيفية-التحدث-بنعم-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_598/59819.mp3","categories":["الأذان والإقامة"]},{"id":17909,"question":"سؤاله الثاني يقول: هل للجمعة أذانان؟ أم أذان واحد؟","title":"ما حكم الأذان الأول لصلاة الجمعة؟","answer":"الشيخ: نعم، لها أذانان، الأذن الأول هذا رآه عثمان  وأرضاه في خلافته، عثمان بن عفان رأى إحداث أذان جديد حتى ينتبه الناس للجمعة، ويستعدوا لها، ويأتوا إليها، وكان هذا في عهد عثمان، وأما في عهد النبي ﷺ، وعهد الصديق، وعمر؛ لم يكن هناك إلا أذانًا واحدًا عند دخول الخطيب، عند دخول الخطيب بعد الزوال، لكن رأى عثمان  وأرضاه هذا الأذان الثاني، وهو الأول، يسمى الأول، لهذه المصلحة، وهو أحد الخلفاء الراشدين ، الذي قال فيهم النبي ﷺ: عليكم بسنتي، وسنة الخلفاء الراشدين من بعدي فلهذا عمل به المسلمون من ذاك الوقت إلى وقتنا هذا، وهو أفضل. نعم، الأفضل أن يكون له أذانين، أول وهو يسمى الأذان الثاني، وهو الأول، لمصلحة المسلمين حتى ينتبهوا للجمعة، وحتى يحضروا. نعم.\nالمقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16914/ما-حكم-الاذان-الاول-لصلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_728/nour_72814.mp3","categories":["الأذان والإقامة"]},{"id":17910,"question":"سماحة الشيخ! هل ترشدون الناس إلى الفرق بين وقت الأذان الأول، ووقت الأذان الثاني؟","title":"متى وقت الأذان الأول في يوم الجمعة؟","answer":"الجواب: الأذان الثاني هذا بعد دخول الخطيب، وهو الموجود في عهد النبي ﷺ، وفي عهد الصديق و عمر ، هذا يقال له: الأذان الأخير -الآن- لم يكن في عهد النبي ﷺ إلا هو، بعد الزوال، هذا هو المشروع.\nأما الأذان الأول مثل ما تقدم، أحدثه عثمان للمصلحة الشرعية، والأفضل أن لا يكون بعيدًا عن الأخير، الأفضل أن لا يكون بعيدًا حتى ينتبه الناس، ويحضروا قبل دخول الخطيب، فإذا كان قبل الصلاة، قبل الأذان بنصف ساعة، أو نحوها، أو ثلثي ساعة؛ فهذا حسن إن شاء الله. أما كونهم يتخذون الأذان الأخير فالفائدة تكون قليلة، فالأفضل أن يكون قبل الأذان بوقت ينتفع به الناس، يغتسلون، ويتقدمون للصلاة قبل الأذان الأخير، وحتى تحصل الفائدة المطلوبة. نعم.\nالمقدم: جزاكم الله خيرًا، وأحسن إليكم، إذا كان قبل دخول الخطيب بساعة مثلاً، هل تستحسنون هذا؟\nالشيخ: لا حرج، ساعة أو أقل منها، أو نص ساعة؛ لا حرج، المقصود ما يفعل ببعض المساجد من كونه يؤذن هذا، ثم يؤذن الثاني، تركه أولى؛ لأن الفائدة ما تحصل بهذا، لو يكون بينهما وقت، يكون بين الأذانين وقتٌ يتسع للمسلمين، ينتفعون في الغسل، وفي التقدم للصلاة قبل دخول الخطيب بوقت؛ حتى يحضروا للمسجد، ويصلوا ما كتب الله لهم، ثم يستعدوا لسماع الخطيب. نعم، هذا هو الأولى والأفضل.نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16916/متى-وقت-الاذان-الاول-في-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_728/nour_72815.mp3","categories":["الأذان والإقامة"]},{"id":17925,"question":"يقول هذا السائل: في رمضان سماحة الشيخ أيهما أفضل للمسلم في مكة: قراءة القرآن، أو الطواف، أو التنفل بركعات، أو التسبيح؟","title":"أفضل الأعمال لمن وافق رمضان في مكة","answer":"الجواب: يفعل ما تيسر من هذا، يقرأ تارة، ويطوف تارة، ويصلي تارة، يعني: يفعل كل ما يستطيع من هذا، الصلاة والطواف والقراءة والدعاء والتسبيح والتهليل، يكون مجتهدًا فيها كلها، تارة كذا وتارة كذا، يساهم في كل نوع من الخير، تارة يطوف .. تارة يصلي .. تارة يقرأ. نعم.\nالمقدم: حفظكم الله سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16945/افضل-الاعمال-لمن-وافق-رمضان-في-مكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_598/59825.mp3","categories":["الأذان والإقامة"]},{"id":17966,"question":"تقول في سؤال آخر: لي بنات عمتي لا يزورونا ولا نزورهم، وهم يسكنون بعيدًا عنا، هل تجب علينا زيارتهم؟ وهل أكون آثمة إذا قطعتهم؟ وهل يكفي أن أتصل بهم بالتلفون وأسأل عنهم أم لا يكفي؟","title":"حكم زيارة الأقارب البعيدين","answer":"الجواب: لا تجب الزيارة ولكن تستحب إذا تيسرت الزيارة على وجه شرعي، ويكفي التلفون والمكاتبة والحمد لله، المحرم القطيعة، فإذا حصلت الصلة بالمكاتبة أو بالهاتف أو بإرسال السلام مع الأصحاب والإخوان والأخيار كل هذا يكفي والحمد لله.\nوإذا كان الأقارب فقراء فمن الصلة وصلهم بالمال والإحسان إذا كان القريب قادرًا يصلهم بما يسر الله له من المال أو الزكاة حتى يجمع بين الأمرين: بين الكلام الطيب والسلام، وبين المواساة والإحسان بالمال. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17007/حكم-زيارة-الاقارب-البعيدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_848/nour_84814.mp3","categories":["الأذان والإقامة"]},{"id":17985,"question":"يقول: لي جار في السكن وأنا لا أقطع زيارته إنما هو لم يزرني إطلاقًا فكيف توجهونني؟","title":"الحث على زيارة الإخوان وإن قطعوا","answer":"الجواب: أنت قد فعلت المعروف، قد فعلت الخير وأحسنت والحمد لله، وإذا دعوته أنت للزيارة وتحببت إليه يحصل التزاور طيب، التزاور بين الإخوان طيب، وإذا فعلت أنت الزيارة ولم يزر هو فزت بالأجر. نعم.\nالمقدم: جزاكم الله خيرًا.\nالشيخ: إذا كانت الزيارة فيها مصلحة ودين وخير، أما إن كانت الزيارة يترتب عليها شر وحضور المنكرات فهذا لا يجوز لك، أما إذا كانت الزيارة لله وفي الله محبة وموانسة، ولا فيها منكر فأنت تفوز بالأجر. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17034/الحث-على-زيارة-الاخوان-وان-قطعوا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_849/nour_84918.mp3","categories":["الأذان والإقامة"]},{"id":17988,"question":"من الأخت المستمعة أمل عبد العاطي من الرياض رسالة وضمنتها جمعًا من الأسئلة، في أحدها تقول: هل يجوز الكلام أثناء الأذان أو بعد الأذان؟","title":"حكم الكلام أثناء الأذان وبعده","answer":"الجواب: نعم، يجوز الكلام في الأذان وبعد الأذان لا بأس لكن السنة الإنصات للمؤذن وإجابته، وإذا تكلم مع ذلك في حاجة من الحاجات فلا حرج في ذلك يجيب المؤذن وإذا رد السلام أو شمت عاطس أو طلب حاجة فلا حرج في ذلك، الحمد لله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17023/حكم-الكلام-اثناء-الاذان-وبعده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_849/nour_84910.mp3","categories":["الأذان والإقامة"]},{"id":18009,"question":"يقول: لي جار في السكن وأنا لا أقطع زيارته إنما هو لم يزرني إطلاقًا فكيف توجهونني؟","title":"الحث على زيارة الإخوان وإن قطعوا","answer":"الجواب: أنت قد فعلت المعروف، قد فعلت الخير وأحسنت والحمد لله، وإذا دعوته أنت للزيارة وتحببت إليه يحصل التزاور طيب، التزاور بين الإخوان طيب، وإذا فعلت أنت الزيارة ولم يزر هو فزت بالأجر. نعم.\nالمقدم: جزاكم الله خيرًا.\nالشيخ: إذا كانت الزيارة فيها مصلحة ودين وخير، أما إن كانت الزيارة يترتب عليها شر وحضور المنكرات فهذا لا يجوز لك، أما إذا كانت الزيارة لله وفي الله محبة وموانسة، ولا فيها منكر فأنت تفوز بالأجر. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17034/الحث-على-زيارة-الاخوان-وان-قطعوا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_849/nour_84918.mp3","categories":["الأذان والإقامة"]},{"id":18208,"question":"من المستمع محمد إدريس محمد سوداني بعث برسالة بدأها بقوله: إلى حضرة مولاي الموجه والمجيب على أسئلة المستمعين وفقه الله:لقد حصل في يوم من الأيام أن أقسمت بالله ثلاثًا ألا أعمل هذا الشيء، لكن والدي أصر علي بالعمل ففعلت، ماذا يجب علي؟ جزاكم الله خيرًا.","title":"حكم من حنث في يمينه لأمر أبيه، وحكم كلمة \"يا مولاي\"","answer":"الجواب: عليك كفارة اليمين، إذا حلفت أنك لا تفعل هذا الشيء وهو مباح في نفسه، كأن حلفت أنك لا تكلم فلان أو لا تزور فلان، أو لا تأكل طعام فلان، وليس هناك مانع شرعي من زيارته ولا أكل طعامه، ثم رأيت أن تزوره وتأكل طعامه، أو أكد عليك والدك في ذلك؛ فإنك تكفر عن يمينك، وهي إطعام عشرة مساكين أو كسوتهم أو عتق رقبة، فمن عجز صام ثلاثة أيام، كما بينه الله في كتابه العظيم في سورة المائدة. وهكذا لو ما ألزم عليك والدك يقول النبي ﷺ في الحديث الصحيح لـعبد الرحمن بن سمرة: إذا حلفت على يمين فرأيت غيرها خيرًا منها فكفر عن يمينك وائت الذي هو خير، ويقول ﷺ: والله! إني إن شاء الله لا أحلف على يمين فأرى غيرها خيرًا منها إلا كفرت عن يميني وأتيت الذي هو خير هذه السنة، إذا حلفت على شيء ثم رأيت المصلحة في الحنث؛ فإنك تحنث وتكفر عن يمينك، بما شرع الله  في قوله سبحانه في سورة المائدة: لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلاثَةِ أَيَّامٍ ذَلِكَ كَفَّارَةُ أَيْمَانِكُمْ إِذَا حَلَفْتُمْ وَاحْفَظُوا أَيْمَانَكُمْ [المائدة:89] الآية. فبين  أن الكفارة هي ما بينه جل وعلا من إطعام عشرة مساكين أو كسوتهم أو تحرير رقبة يعني: عتق رقبة، فمن عجز عن هذا ولم يستطع صام ثلاثة أيام، والناس أعلم بأحوالهم فإذا رأى أن يمينه تشق عليه أو فيها ضرر عليه، أو فيها إغضاب لوالده أو لأمه أو نحو ذلك أو رأى المصلحة في الحنث فيها لأمر آخر كفر عن يمينه وأتى ما هو الأفضل والأصلح. إلا أن يكون إثمًا فعليه أن يحذر الإثم كما لو قال: والله! لا أشرب الخمر، والله! لا أدخن، فإنه في هذه اليمين قد أحسن في هذه اليمين، فالواجب عليه تنفيذها وعدم الحنث، ولو قال له والده: احنث. ليس له أن يطيع والده ولا غير والده؛ لأن التدخين محرم وفيه مضار كثيرة، وشرب الخمر كذلك محرم بالنص من القرآن والسنة، فلا يجوز له أن يعود إليه، حتى ولو ما حلف، الواجب عليه أن يحذر التدخين ويحذر الخمر ولو لم يحلف، فإذا حلف صار تأكيدًا لذلك، فليس له أن يحنث، ولو حنث وفعل فعليه كفارة يمين مع الإثم ومع التوبة إلى الله . وقد قلت في أول السؤال: يا مولاي وهذه كلمة ينبغي تركها؛ لأن الرسول ﷺ صح عنه أنه قال: لا يقولن أحدكم مولاي؛ فإن مولاكم الله وقال في العبد: لا يقل: ربي، وليقل: سيدي ومولاي يقول: في سيده الذي هو المالك فأخذ بعض العلماء أن النهي ليس للتحريم في لا يقل: مولاي لأنه ﷺ أذن للعبد أن يقول: سيدي ومولاي، فالعبد له شأن والناس لهم شأن. فالأولى ترك هذه الكلمة والأحوط تركها، أما المملوك فله أن يقولها لسيده: يا مولاي أو يا سيدي لا بأس أن يقولها، أو يا عمي كما يقول الناس اليوم، أما أنت وأنت لست مملوكًا فتخاطب الناس بغيرها تقول: يا فلان أو يا أبا فلان أو يا شيخ فلان، أو القاضي فلان.. أو ما أشبه ذلك، تخاطبه بالألقاب المعروفة، غير مولاي وغير سيدي، حتى سيدي تركها أولى؛ لأن الرسول ﷺ قال لما قيل له: يا سيدنا قال: السيد الله تبارك وتعالى، كره أن يخاطب بهذا، وإن كان هو سيد ولد آدم عليه الصلاة والسلام، وأفضل الناس لكن خاف أن يغلوا فيه، خشي عليهم من الغلو فقال: السيد الله قولوا بقولكم أو بعض قولكم ولا يستهوينكم الشيطان أنا محمد عبد الله ورسوله عليه الصلاة والسلام، ما أحب أن ترفعوني فوق منزلتي التي أنزلني الله ، يعني: عبد الله ورسوله، مع أنه سيد ولد آدم كما قال ﷺ: أنا سيد ولد آدم يوم القيامة ولا فخر وأفضل الخلق ولكن تواضعًا منه عليه الصلاة والسلام وخوفًا على أمته من الغلو أرشدهم إلى ألا يخاطبوه بقول: يا سيدنا. أما إذا قيل: هو سيد ولد آدم، أو قيل: هو سيدنا فلا بأس من غير خطاب له؛ لأنه قد توفي عليه الصلاة والسلام وكره هذا في حياته أن يخاطب بهذا عليه الصلاة والسلام. أما إذا قاله واحد منا اليوم: سيدنا محمد، أو اللهم صل على سيدنا؛ فهذا لا بأس به؛ لأنه حق ليس فيه محذور، لكن لا يقال في الأشياء التي وردت وليس فيها ذكر، لا يحدث في أشياء شرعها الله ليس فيها أجر السيادة بل يقتصر على الوارد، فلا يقال في الأذان: نشهد أن سيدنا محمدًا رسول الله، ولا يقال في الإقامة كذلك؛ لأن هذا لم يرد في الأذان ولا في الإقامة، فيقتصر على ما ورد يقال: أشهد أن محمدًا رسول الله في الأذان والإقامة. وهكذا في التحيات، اللهم صل على محمد، وهكذا أشهد أن لا إله إلا الله وأشهد أن محمدًا عبده ورسوله في التحيات في التشهد؛ لأن هذا هو الوارد، فالأفضل ألا يقول ذلك، وهكذا في الأذان؛ لأنه ورد بغير ذكر السيادة فيقول كما كان المؤذن يقول: أشهد أن محمدًا رسول الله، هكذا كان المؤذنون في عهده ﷺ وعهد أصحابه، فعلينا أن نسير على نهجهم في ذلك، هذا هو المشروع لنا، لكن في عرض كلامنا العادي عند ذكر الحديث، وعند ذكره ﷺ، اللهم صل على سيدنا محمد أو في الخطبة لا بأس بذلك ولا حرج في ذلك، من قالها فلا حرج ومن تركها فلا حرج. ولا ينبغي أن يظن في حق من تركها أنه جافي هذا غلط، فمن قالها فلا بأس ومن تركها فلا بأس، فإذا قال: اللهم صل على نبينا محمد أو على عبدك ورسولك محمد فكله حق كله صحيح وكله طيب، ولو لم يقل: سيدنا، وإن قال: اللهم صل على سيدنا محمد أو سيد ولد آدم فكله حق لا بأس بذلك كله حق ومشروع، صلى الله وسلم عليه وعلى آله وأصحابه. نعم. المقدم: اللهم صل وسلم وبارك على سيدنا محمد.","link":"https://binbaz.org.sa/fatwas/17267/حكم-من-حنث-في-يمينه-لامر-ابيه-وحكم-كلمة-يا-مولاي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_856/nour_85605.mp3","categories":["الأذان والإقامة"]},{"id":18291,"question":"هل صلة الأرحام تلزم الرجال دون النساء؟","title":"عموم الأمر بصلة الرحم للرجال والنساء","answer":"الجواب: صلة الرحم مشتركة بين الرجال والنساء؛ لأن الله جل وعلا يقول في كتابه العظيم: فَهَلْ عَسَيْتُمْ إِنْ تَوَلَّيْتُمْ أَنْ تُفْسِدُوا فِي الأَرْضِ وَتُقَطِّعُوا أَرْحَامَكُمْ ۝ أُوْلَئِكَ الَّذِينَ لَعَنَهُمُ اللَّهُ فَأَصَمَّهُمْ وَأَعْمَى أَبْصَارَهُمْ [محمد:22-23]، هذا خطاب للجميع للرجال والنساء. وهكذا قوله ﷺ: لا يدخل الجنة قاطع رحم يعم الرجال والنساء، وقوله ﷺ: من أحب أن يفسح له في أجله وأن يبسط له في رزقه، فليصل رحمه يعم الرجال والنساء، فوصل الرحم مطلوب من الرجال والنساء، بل واجب على الجميع، ولا يختص بالرجال. نعم.","link":"https://binbaz.org.sa/fatwas/17342/عموم-الامر-بصلة-الرحم-للرجال-والنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_912/nour_91206.mp3","categories":["الأذان والإقامة"]},{"id":18491,"question":"أخونا يسأل ويقول: أرجو أن توجهوا أصحاب المؤسسات كي ما يكثروا من العمال المسلمين؛ لأني ألاحظ أن معظم عمال المؤسسات من غير المسلمين، بل ومن غير الكتابيين أيضًا فهم يصلون إلى نسبة تسعين في المائة؟","title":"الحث على استقدام العمال المسلمين","answer":"الجواب: قد سبق منا غير مرة التنبيه على هذا، وأن الواجب على المؤسسات والشركات وعلى غيرهم ممن يستورد العمال ألا يستورد إلا المسلمين في هذه الجزيرة بوجه أخص؛ لأن هذه الجزيرة مهد الإسلام ومطلع شمس الرسالة، ومرجع المسلمين، وفيها الحرمان الشريفان، ولهذا أمر النبي ﷺ بإخراج المشركين منها وأوصى بذلك عند وفاته أن يخرجوا من هذه الجزيرة سواء كانوا يهودًا أو نصارى أو وثنيين أو شيوعيين .. جميع أنواع الكفرة يجب إخراجهم من هذه الجزيرة وأن لا يبقى فيها إلا مسلم، ونهى أن يجتمع بها دينان، فلا يجوز بقاء دين آخر غير الإسلام في هذه الجزيرة، لا من العمال ولا من السكان بل يجب إخراجهم إلا من وردها لحاجة عارضة كالبريد والتاجر الذي يبيع حاجته وينصرف ونحو ذلك بصفة مؤقتة وأيام معدودة. فعلى المؤسسات والشركات والأفراد وعلى الدولة وفقها الله أن تعنى بهذا الأمر وأن تأخذ على أيدي الناس وأن تمنع من استيراد الكفار إلا عند الضرورة القصوى في مصلحة المسلمين فيما يتعلق بالدولة إذا احتيج إلى بعض الكفرة لمصلحة المسلمين ولم يتيسر من يقوم بعمله غيره. أما عموم الناس فالواجب منعهم من استيراد الكفرة وألا يستوردوا إلا مسلمين في عمل البناء وفي غير ذلك من الأعمال، هذا هو الواجب على المسلمين جميعًا، وأن يعملوا بما أوصى به نبيهم عليه الصلاة والسلام من إخراج الكفار من هذه الجزيرة وعدم استيرادهم لها، لما في اختلاطهم بالمسلمين من الأضرار العظيمة والأخطار الكثيرة. نسأل الله أن يوفق المسلمين لما يرضيه، وأن يوفق الدولة لتنفيذ أوامر الله ورسوله في كل شيء، وأن يعينها على ذلك إنه خير مسئول. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17596/الحث-على-استقدام-العمال-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_867/nour_86707.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":18502,"question":"السائلة يا شيخ عبد العزيز حفظكم الله تقول: أحس وأشعر بضيق شديد عندما يأتي إلي والدي هذا، وحتى أنني لا أريده أن يقوم بزيارتي، فهل أأثم على ذلك أيضًا؟","title":"حكم تضايق المرأة من زيارة والدها","answer":"الجواب: عليك أن تجتهدي في الترحيب به، والكلام الطيب معه، والسلام الحسن، ولا يضرك إن شاء الله؛ لأنك إنما كرهت ذلك لأجل المال الذي تعطينه من مال زوجك تتحرجين من ذلك، لكن أليني القول، ورحبي به، ويجب عليك أن ترحبي به، وأن تشرحي صدرك له لأن حقه عظيم، لكن اعتذري قولي: ما عندي مال إلا مال زوجي، ولا يجوز لي أن أعطيك من مال زوجي، وتكلمي معه بالكلام الطيب؛ لأن حقه عظيم، جاء عنه ﷺ أنه قال: رضا الله في رضا الوالدين، وسخط الله في سخط الوالدين، والله يقول سبحانه: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا[الإسراء:23]، ويقول : وَاعْبُدُوا اللَّهَ وَلا تُشْرِكُوا بِهِ شَيْئًا وَبِالْوَالِدَيْنِ إِحْسَانًا[النساء:36] فحق الوالدين عظيم. فالواجب عليك الانبساط للوالد، والترحيب به، والإحسان إليه حسب طاقتك، لكن لا تأخذي من مال زوجك شيئًا لأجل والدك إلا بإذنه. المقدم: أحسن الله إليكم وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17608/حكم-تضايق-المراة-من-زيارة-والدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_786/nour_78610.mp3","categories":["الأذان والإقامة"]},{"id":18540,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين في قريةالمظيلف، يقول محمد عبده العجلاني، الأخ محمد له جمع من الأسئلة في أحدها يقول: هل على المرأة أذان وإقامة حين تريد الشروع في الصلاة؟ أم تكفيها الإقامة بنفسها، أو إقامة المسجد المجاور؟جزاكم الله خيرًا.","title":"هل على المرأة أذان وإقامة للصلاة؟","answer":"الجواب: ليس على المرأة أذان ولا إقامة، إنما هذا من شأن الرجال، أما المرأة تصلي بدون أذان ولا إقامة، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17641/هل-على-المراة-اذان-واقامة-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_733/nour_73313.mp3","categories":["الأذان والإقامة"]},{"id":18607,"question":"إذا قال المؤذن: الصلاة خير من النوم، فماذا نقول؟","title":"ما يقال عند قول المؤذن: \"الصلاة خير من النوم\"","answer":"الجواب: السنة أن تقول: الصلاة خير من النوم، وهكذا إذا قال: قد قامت الصلاة، المؤذن في الإقامة تقول: قد قامت الصلاة، قد قامت الصلاة، هذا هو الصواب، تقول مثله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17712/ما-يقال-عند-قول-الموذن-الصلاة-خير-من-النوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_734/nour_73409.mp3","categories":["الأذان والإقامة"]},{"id":18666,"question":"يقول السائل في ثاني أسئلته: البعض من المؤذنين في المساجد، وبعد الانتهاء من الأذان يقول: صل اللهم على سيدنا محمد، وعلى آله وصحبه وسلم، ما حكم الشرع في نظركم في ذلك؟","title":"حكم الصلاة على النبي ﷺ بعد الأذان","answer":"الجواب: المشروع للمؤمن بعد الفراغ من الأذان أن يصلي على النبي ﷺ، وهكذا المستمع بعد الفراغ يجيب المؤذن، وبعد الإجابة يصلي على النبي ﷺ ثم يقول: اللهم رب هذه الدعوة التامة، والصلاة القائمة؛ آت محمدًا الوسيلة والفضيلة، وابعثه مقامًا محمودًا الذي وعدته هكذا جاء في الأحاديث الصحيحة، يقول ﷺ: إذا سمعتم المؤذن فقولوا مثلما يقول، ثم صلوا عليّ، فإنه من صلى عليّ واحدة صلى الله عليه بها عشرًا، ثم سلوا الله لي الوسيلة، فإنها منزلة في الجنة، لا تنبغي إلا لعبد من عباد الله، وأرجو أن أكون أنا هو، فمن سأل لي الوسيلة حلت له الشفاعة. وفي الحديث الآخر يقول ﷺ: من قال حين يسمع النداء: اللهم رب هذه الدعوة التامة، والصلاة القائمة؛ آت محمدًا الوسيلة، والفضيلة، وابعثه مقامًا محمودًا الذي وعدته؛ حلت له شفاعتي يوم القيامة زاد البيهقي -رحمه الله- بإسناد جيد: إنك لا تخلف الميعاد هذا مستحب بعد الأذان في حق المؤذن، وفي حق من يجيب المؤذن. كل من سمع الأذان يقول مثلما يقول المؤذن: الله أكبر، الله أكبر، أشهد أن لا إله إلا الله، أشهد أن لا إله إلا الله، أشهد أن محمدًا رسول الله، مثله، حي على الصلاة، يقول: لا حول ولا قوة إلا بالله، هكذا عند حي على الفلاح يقول: لا حول ولا قوة إلا بالله، وعندما يقول: الله أكبر، هو يقول: الله أكبر، الله أكبر، ثم يقول: لا إله إلا الله. وفي الحديث الآخر الصحيح: إذا قالها من قلبه دخل الجنة هذا هو المشروع لكل مسلم، على الرجل والمرأة، إذا سمعوا الأذان أن يقولوا هكذا، أن يقولوا مثل قول المؤذن إلا عند الحيعلة يقول: لا حول ولا قوة إلا بالله.  ويستحب عند الشهادتين أن يقول: رضيت بالله ربًا، وبالإسلام دينًا، وبمحمد رسولًا، جاء في الحديث أنه قال: إذا قال هذا عند اثنتين غفر له ذنبه لكن لا يقولها مع أذان المؤذن إذا انتهى من: لا إله إلا الله، سكر السماعة، ويقولها بينه وبين نفسه، يسمعه من حوله لا بأس، لكن لا يقولها مع الأذان إنما ينتهي الأذان عند: لا إله إلا الله، ثم بعد ذلك يسكر السماعة، ويصلي على النبي ﷺ بعد ذلك بينه وبين نفسه من دون أن يكون ذلك في المكبر، هذا هو المشروع، نعم. المقدم: زيادة الأدعية بعد الأذان مثل يا سماحة الشيخ؟ الشيخ: يستحب الدعاء بين الأذان والإقامة الدعاء بين الأذان والإقامة لا يرد يقول ﷺ: الدعاء بين الأذان والإقامة لا يرد يستحب الإكثار من الدعاء بين الأذان والإقامة، وهو ينتظر الصلاة. السؤال: هناك أدعية محددة يا سماحة الشيخ؟ الجواب: لكن يدعو الله بما تيسر، يدعو الله بما أحب من الدعوات الطيبة. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17781/حكم-الصلاة-على-النبي-ﷺ-بعد-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_788/nour_78802.mp3","categories":["الأدعية والأذكار","الأذان والإقامة"]},{"id":18729,"question":"سماحة الشيخ يشاع أنكم رأيتم في المنام رسول الله ﷺ وأنه أوصاكم بإغلاق مدارس البنات، وقد كثر التساؤل عن صحة هذه الإشاعة، أرجو أن تتفضلوا بالإجابة، وتوجيه الناس حيال الإشاعات، جزاكم الله خيرًا.","title":"صحة رؤيا الشيخ ابن باز لرسول ﷺ ووصيته له","answer":"الجواب: نعم سمعنا هذه الإشاعة، وسألنا عنها أناس كثير من طريق الهاتف وغير الهاتف، وهي إشاعة كاذبة باطلة لا أساس لها من الصحة، فلم أر النبي ﷺ ولم يقل لي هذا الكلام، بل كل هذا باطل، ومن إشاعة الشياطين، شياطين الإنس والجن، وهذه الإشاعة يقولون فيها: إني رأيت النبي ﷺ مرتين، وأنه أوصاني أن أبلغ المسؤولين إغلاق مدارس البنات، وهذا كله باطل، ولا أساس له، بل هو كذب. فأرجو ممن سمع كلمتي هذه أن يبلغها غيره، وأن ينشرها بين إخوانه حتى يعلم الناس أن هذا الكلام باطل، وأن هذه الرؤيا لا وجود لها، ونسأل الله أن يجازي من كذب ما يستحق. المقدم: اللهم آمين جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17848/صحة-رويا-الشيخ-ابن-باز-لرسول-ﷺ-ووصيته-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_874/nour_87402.mp3","categories":["الأذان والإقامة"]},{"id":18811,"question":"يوجد عندنا من يقول: الذي يؤذن هو الذي يقيم الصلاة، وتوجد عندنا ظاهرة قراءة آية الكرسي قبل التسبيح الذي بعد الصلاة، ما رأيكم في هذا أفتونا؟جزاكم الله خيرًا.","title":"حكم إقامة غير المؤذن وتقديم آية الكرسي على أذكار الصلاة","answer":"الجواب: الأفضل أنه يتولى الإقامة من يتولى الأذان، هذا هو الأفضل، ولو أقام غيره فلا حرج، لو أقام غيره فلا حرج، ولكن الأفضل هو أن المؤذن هو الذي يقيم، كما كان بلال يؤذن ويقيم  لكن لو أقام غيره بأن شغل المؤذن، أو سمح بأن يقيم غيره، فلا بأس بذلك. وكذلك ظاهرة قراءة آية الكرسي قبل التسبيح لا حرج في ذلك، الرسول ﷺ ندب إلى قراءة آية الكرسي بعد الصلاة، فإن قرأها قبل الذكر فلا بأس، لكن الأفضل أن تكون بعد الذكر؛ لأن الرسول ﷺ كان يذكر الله بعد السلام، فالأفضل أن يبدأ بالذكر ثم يأتي بها سرًّا بعد الأذكار، هذا هو الأفضل. المقدم: جزاكم الله خيرًا، وإن كانت قراءة آية الكرسي جماعية سماحة الشيخ؟ الشيخ: لا، يقرأها سرًا بينه وبين نفسه لا جماعية، يقرأها الإنسان بعد السلام، وبعد الذكر سرًا بينه وبين نفسه، ولا يقرأها جماعية مع الناس، نعم. المقدم: بارك الله فيكم، أعتقد أن أخانا يسأل عن كونها مقروءة جماعة؟ الشيخ: لا، جماعية لا تصلح، بدعة لا يجوز قراءتها جماعية، ولكن تقرأ بينه وبين نفسه بعد الأذكار الشرعية، هذا هو الأفضل. المقدم: كل مصل يقرؤها بينه وبين نفسه. الشيخ: بعدما يفرغ من الأذكار، نعم، وهكذا قراءة قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص: 1] والمعوذتين يقرأها بينه وبين نفسه بعد كل صلاة، وبعد الفجر ثلاثًا، وبعد المغرب ثلاثًا، قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص: 1] والمعوذتين ثلاثًا بعد المغرب، ثلاثًا بعد الفجر، أما بعد الظهر والعصر والعشاء فمرة واحدة بينه وبين نفسه، نعم. المقدم: نفع الله بكم.","link":"https://binbaz.org.sa/fatwas/17933/حكم-اقامة-غير-الموذن-وتقديم-اية-الكرسي-على-اذكار-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_876/nour_87608.mp3","categories":["الأذان والإقامة","البدع والمحدثات","الأدعية والأذكار"]},{"id":18873,"question":"أخونا يسأل ويقول: أرجو أن توجهوا أصحاب المؤسسات؛ كي يكثروا من العمال المسلمين؛ لأني ألاحظ أن معظم عمال المؤسسات من غير المسلمين، بل ومن غير الكتابيين أيضًا، فهم يصلون إلى نسبة تسعين بالمائة.","title":"حكم استقدام الكفرة إلى جزيرة العرب للعمل وغيره","answer":"الجواب: قد سبق منا غير مرة التنبيه على هذا، وأن الواجب على المؤسسات والشركات -وعلى غيرهم ممن يستورد العمال- أن لا يستورد إلا المسلمين، في هذه الجزيرة بوجه أخص؛ لأن هذه الجزيرة مهد الإسلام، ومطلع شمس الرسالة، ومرجع المسلمين، وفيها الحرمان الشريفان؛ ولهذا أمر النبي ﷺ بإخراج المشركين منها، وأوصى بذلك عند وفاته أن يخرجوا من هذه الجزيرة، سواء كانوا يهودًا أو نصارى أو وثنيين أو شيوعيين. جميع أنواع الكفرة، يجب إخراجهم من هذه الجزيرة، وألا يبقى فيها إلا مسلم، ونهى أن يجتمع فيها دينان، فلا يجوز بقاء دين آخر غير الإسلام في هذه الجزيرة، لا من العمال، ولا من السكان، بل يجب إخراجهم، إلا من وردها لحاجة عارضة: كالبريد، والتاجر الذي يبيع حاجته وينصرف، ونحو ذلك، بصفة مؤقتة وأيام معدودة. فعلى المؤسسات والشركات والأفراد، وعلى الدولة -وفقها الله- أن تعنى بهذا الأمر، وأن تأخذ على أيدي الناس، وأن تمنع من استيراد الكفار إلا عند الضرورة القصوى في مصلحة المسلمين، فيما يتعلق بالدولة، إذا احتيج إلى بعض الكفرة لمصلحة للمسلمين، ومن لم يتيسر من يقوم بعمله غيره. أما عموم الناس فالواجب منعهم من استيراد الكفرة، وأن لا يستوردوا إلا مسلمين: في عمل البناء، وفي غير ذلك من الأعمال، هذا هو الواجب على المسلمين جميعًا، وأن يعملوا بما أوصى به نبيهم -عليه الصلاة والسلام- من إخراج الكفار من هذه الجزيرة، وعدم استيرادهم لها، لما في اختلاطهم بالمسلمين من الأضرار العظيمة، والأخطار الكبيرة. نسأل الله أن يوفق المسلمين لما يرضيه، وأن يوفق الدولة لتنفيذ أوامر الله ورسوله في كل شيء، وأن يعينها على ذلك إنه خير مسؤول. المقدم: جزاكم الله خيرًا، معي في المؤسسة عمال غير المسلمين، ولا حتى من أهل الكتاب، كلما علمتهم شيئًا استعملوه ضدي، فهل أمتنع عن تعليمهم أي شيء، ويكون هذا حلال أم حرام؟ الشيخ: الواجب عليك ألا تستورد كفارًا، وأن تبعدهم إلى بلادهم، وأن تنهي عقودهم، وأن لا تخبرهم بشيء يضرك، وإنما تنصحهم، تدعوهم إلى الإسلام، وتعلمهم ما ينفعهم، أما أن تعلمهم شيء يضرك، فلا تعلمهم شيء يضرك، بل أبعدهم وأنه عقودهم، واتق الله، واتبع رسوله -عليه الصلاة والسلام- نعم.","link":"https://binbaz.org.sa/fatwas/18034/حكم-استقدام-الكفرة-الى-جزيرة-العرب-للعمل-وغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_880/nour_88007.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":18926,"question":"السائل (م. م) يقول في هذا  ماذا يجب على الشخص إذا كان في الخلاء، وسمع الأذان، هل يردد في قلبه، ثم يدعو بعد انتهاء المؤذن دعاء: اللهم رب هذه الدعوة التامة؟","title":"حكم الترديد بعد المؤذن لمن كان في الخلاء","answer":"الجواب: إذا كان في قضاء الحاجة لا يردد، لا يجيب المؤذن، وإذا خرج من الخلاء من الغائط، وأتى بالأذكار الشرعية لا بأس، نعم.","link":"https://binbaz.org.sa/fatwas/18072/حكم-الترديد-بعد-الموذن-لمن-كان-في-الخلاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_882/nour_88209.mp3","categories":["الأذان والإقامة"]},{"id":18949,"question":"يقول هذا السائل يا سماحة الشيخ: العبد المسلم الذي اتجه إلى الله  بالعبادات، ما أفضل شيء يتقرب به إلى ربه ؟","title":"أفضل القرب والعبادات","answer":"الجواب: يتقرب بكل عبادة، يصوم ما تيسر ثلاثة أيام من كل شهر، يصوم الإثنين والخميس، يكثر من الصلاة في الضحى، وفي الليل ما تيسر له من الصلوات، يكثر من ذكر الله، ومن قراءة القرآن، يكثر من الصدقة إن كان عنده مال، يتوسع في الخير. المقدم: أحسن الله إليكم، وبارك فيكم يا فضيلة الشيخ.","link":"https://binbaz.org.sa/fatwas/18123/افضل-القرب-والعبادات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_882/nour_88236.mp3","categories":["الأذان والإقامة"]},{"id":18959,"question":"سورة الملك إذا قرأها المسلم بعد صلاة المغرب أو بعد صلاة العشاء، هل يحصل له فضل في ذلك؟","title":"حكم قراءة سورة الملك بعد صلاة المغرب أو العشاء","answer":"الجواب: وردت فيها بعض الأحاديث، فإذا قرأها يحتسب الأجر فيها فضل، لكن ينبغي له أن يكون له راتب من القرآن كله من أوله إلى آخره، كلما كمله عاده هذا هو الأفضل، كما فعل الصحابة  وأرضاهم، يبدأ من الفاتحة والبقرة إلى أن يكمل ثم يعود وهكذا، هذا هو الأفضل أن يكون له راتب في ليله ونهاره كلما ختم عود. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18108/حكم-قراءة-سورة-الملك-بعد-صلاة-المغرب-او-العشاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_882/nour_88228.mp3","categories":["الأذان والإقامة"]},{"id":19096,"question":"يسأل أيضًا ويقول: عندما يقرأ المسلم أي سورة من القرآن، أو من الأحاديث النبوية الشريفة هل يلزمه أن يحفظها؟ وهل من حفظ ونسي يكون آثمًا؟ جزاكم الله خيرًا وأحسن إليكم.","title":"حكم حفظ القرآن الكريم والأحاديث النبوية","answer":"الجواب: لا يلزمه الحفظ، إنما يتدبر القرآن، ويكثر من تلاوته حتى يستفيد، لأن قراءة القرآن فيها الخير العظيم، والله يقول سبحانه: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ[الإسراء:9] ، ويقول سبحانه: قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ[فصلت:44] ويقول : كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُوْلُوا الأَلْبَابِ[ص:29]. فالمشروع للرجال والنساء جميعًا لكل مسلم أن يدرس هذا القرآن الكريم، ويتدبره، ويكثر من تلاوته، ويعمل بما فيه، ويسأل عما أشكل عليه أهل العلم، يسأل أهل العلم عما أشكل عليه من طريق الهاتف - التلفون -، من طريق المكاتبة، من طريق المشافهة، هذا هو المشروع لكل مسلم. ولكن لا يلزمه الحفظ إن حفظ فهو أفضل، إن حفظ فهو خير عظيم، ولكن لا يلزمه الحفظ، إنما يجتهد في كثرة التلاوة، والتدبر والعمل، لأن المقصود من التلاوة هو العمل في أداء الواجبات، وترك المحرمات، وفي قراءة القرآن تذكر الجنة والنار، ومعرفة أحوال الماضين، والاعتبار بما جرى عليهم، كل هذه موجودة في القرآن الكريم. وهكذا الأحاديث يجتهد المؤمن والمؤمنة في مراجعتها، وقراءتها، والاستفادة منها مثل: الصحيحين البخاري ومسلم، ومثل كتب السنن الأربع، مثل رياض الصالحين، مثل المنتقى، مثل بلوغ المرام، مثل عمدة الحديث، جامع الأصول. المؤمن والمؤمنة إذا كانا من طلبة العلم يستفيدا من هذه الكتب، وإذا تيسر الحفظ كونه يحفظ ما تيسر من الأحاديث مثل بلوغ المرام، مثل عمدة الحديث، مثل الأربعين النووية وتتمتها لابن رجب هذه فيها فائدة كبيرة عظيمة، ولكن بكل حال متى أكثر المراجعة والقراءة سوف يستفيد، وسوف يحفظ بعض الشيء، وهذا خير عظيم ينبغي لكل طالب علم وطالبة علم العناية بهذا الأمر من جهة القرآن، ومن جهة السنة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18307/حكم-حفظ-القران-الكريم-والاحاديث-النبوية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_797/nour_79710.mp3","categories":["الأذان والإقامة"]},{"id":19112,"question":"تسأل أختنا فتقول: كم يومًا يحتاج الإنسان إلى ختم القرآن بالفهم والتدبر؟ وهل إذا ختم الإنسان القرآن في شهرين؛ يكون قد تأخر في قراءته؟ أفيدونا أفادكم الله.","title":"ختم قراءة القرآن في شهرين","answer":"الجواب: النبي ﷺ قال لـعبد الله بن عمرو: اقرأه كل شهر، فلم يزل يقول: زدني يا رسول الله.. حتى قال: \"اقرأه في أسبوع\"، ثم طلب الزيادة إلى ثلاث، وكان الصحابة يقرءونه في أسبوع. فالأفضل في أسبوع، وإذا تيسر في الثلاثة الأيام فلا بأس، لكن مع العناية بالتدبر والتعقل والخشوع، وإذا قرأ الإنسان القرآن في شهر أو شهرين؛ فلا حرج لكن مع التدبر، وإذا رتب القراءة كل شهر يقرأ كل يوم جزءًا؛ فهذا حسن كما قال النبي ﷺ لـعبد الله بن عمرو: اقرأه كل شهر، فإن الحسنة بعشر أمثالها. فالمقصود: أن الإنسان يتحرى في قراءته الخشوع والتدبر والتعقل والاستفادة، سواءً قرأه في شهر أو شهرين أو أقل أو أكثر، لكن يكره أن يكون أقل من ثلاث، أقل شيء ثلاثة أيام يقرأه في ثلاثة أيام ولياليها في كل يوم وليلة عشرة أجزاء، هذا أقل ما ورد. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18283/ختم-قراءة-القران-في-شهرين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_737/nour_73704.mp3","categories":["الأذان والإقامة"]},{"id":19268,"question":"أختنا تقول: إن لها أقارب يحتاج السفر إليهم ما يقرب من أربع إلى خمس ساعات، وذلكم يتعبها كثيرًا، هل عليها من إثم إذا تأخرت عن زيارتهم، ترجو التوجيه؟","title":"حكم التأخر عن زيارة الأقارب لبعد المسافة","answer":"الجواب: لا إثم عليها، ولا يجب السفر -الحمد لله- صلة الرحم تكون بالمكاتبة، وبالهاتف من طريق الهاتف -التلفون- ومن طريق البرقية، والتلكس الذي حدث أخيرًا وعرفه الناس، الأمر في هذا واسع والحمد لله، الواجب الحذر من القطيعة، ووجوب صلة الرحم بالمستطاع وبالميسور وبالمتعارف، والحمد لله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18464/حكم-التاخر-عن-زيارة-الاقارب-لبعد-المسافة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_892/nour_89209.mp3","categories":["الأذان والإقامة"]},{"id":19286,"question":"تسأل أختنا وتقول: هل يجوز عدم دفع أجرة الخياط كاملة؛ لأنه مرتفع الثمن؟","title":"حكم عدم دفع أجرة الخياط كاملة بسبب الأجرة المرتفعة","answer":"الجواب: يقول النبي ﷺ: المسلمون على شروطهم والله يقول فوق ذلك: يَا أَيُّهَا الَّذِينَ آمَنُوا أَوْفُوا بِالْعُقُودِ [المائدة:1]، فإذا تعاقدت المرأة أو الرجل مع الخياط على شيء معلوم، وجب عليهم أداؤه مرتفعًا أو غير مرتفع، المسلمون على شروطهم، ويقول عمر : مقاطع الحقوق عند الشروط، فإذا اتفقا على أنه يخيط هذا الثوب بعشرة أريل.. بعشرين.. بثلاثين، واتفقا على هذا، وسلموا له الثوب، وجب عليهم أن يؤدوا له الأجرة . نعم . المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18489/حكم-عدم-دفع-اجرة-الخياط-كاملة-بسبب-الاجرة-المرتفعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_893/nour_89306.mp3","categories":["الأذان والإقامة","الإجارة"]},{"id":19407,"question":"يسأل سماحتكم فيقول: هل يجوز تأخير الأذان بخمس دقائق لعذر؟","title":"حكم تأخير الأذان خمس دقائق لعذر","answer":"الجواب: الأمر واسع الخمس الدقائق قليلة لا يضر إذا شغل بشيء، ولكن الأحوط والأولى للمؤمن أن يحافظ حتى يؤذن مع الناس، والتأخير خمس دقائق أو ثلاث دقائق لا يضر إن شاء الله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18635/حكم-تاخير-الاذان-خمس-دقاىق-لعذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_740/nour_74009.mp3","categories":["الأذان والإقامة"]},{"id":19488,"question":"يقول السائل من اليمن: الإسلام أمر بصلة الرحم، لكن ما هي الرحم المأمور بصلتها، هل هم الأقارب كالعمة والجدة والخال مثلًا، أم كل من يمت للإنسان بصلة؟","title":"الرحم المأمور بصلتها","answer":"الجواب: الأقارب هم الرحم، أبوك وأمك وأجدادك وأولادك وأولادهم والإخوان وأولادهم والأعمام وأولادهم والأخوال وأولادهم الأقرب فالأقرب، «قيل: يا رسول الله! من أبر؟ قال: أمك، قال: ثم من؟ قال: أمك، قال: ثم من؟ قال: أمك، قال: ثم من؟ قال: أباك ثم الأقرب فالأقرب كل من كان قريب هو أولى بالصلة، ومنهم الأخوال والأعمام وأولادهم. نعم.","link":"https://binbaz.org.sa/fatwas/18735/الرحم-المامور-بصلتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93920.mp3","categories":["الأذان والإقامة"]},{"id":19503,"question":"من أسئلة هذا السائل يقول يا سماحة الشيخ: ما حكم الصلاة عند المطر؟ هل يقول المؤذن: صلوا في رحالكم؟ وهل يجمعون؟","title":"حكم قول (صلوا في رحالكم) وجمع الصلاة في المطر","answer":"الجواب: إذا كان فيه مشقة قال: (صلوا في رحالكم) لا بأس، وإن جمعوا فلا بأس، الظهر والعصر والمغرب والعشاء إذا كان فيه مشقة، مطر فيه مشقة، أو دحض في الأسواق ومشقة في الأسواق. نعم.\nكل هذا جاءت به السنة عن النبي ﷺ. نعم.","link":"https://binbaz.org.sa/fatwas/18747/حكم-قول-صلوا-في-رحالكم-وجمع-الصلاة-في-المطر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93927.mp3","categories":["الأذان والإقامة"]}]
